\section{Preliminaries}
%=====================================



\begin{theorem}(\,Douglas' factorization theorem\,)\,{\cite{Douglas}}\label{th1}
Let \,$U,\, V \,\in\, \mathcal{B}\,(\,H\,)$.\;Then the following conditions are equivalent:
\begin{itemize}
\item[$(\,i\,)$]\;\;$\mathcal{R}\,(\,U\,) \,\subseteq\, \mathcal{R}\,(\,V\,)$.
\item[$(\,ii\,)$]\;\;$U\,U^{\,\ast} \,\leq\, \lambda^{\,2}\; V\,V^{\,\ast}$\, for some \,$\lambda \,>\, 0$.
\item[$(\,iii\,)$]\;\;$U \,=\, V\,W$\, for some \,$W \,\in\, \mathcal{B}\,(\,H\,)$.
\end{itemize}
\end{theorem}

\begin{theorem}(\cite{Christensen})\label{thm1.1}
Let \,$H_{\,1},\, H_{\,2}$\; be two Hilbert spaces and \;$U \,:\, H_{\,1} \,\to\, H_{\,2}$\; be a bounded linear operator with closed range \;$\mathcal{R}_{\,U}$.\;Then there exists a bounded linear operator \,$U^{\dagger} \,:\, H_{\,2} \,\to\, H_{\,1}$\, such that \,$U\,U^{\dagger}\,x \,=\, x\; \;\forall\; x \,\in\, \mathcal{R}_{\,U}$.
\end{theorem}

\begin{note}
The operator \,$U^{\dagger}$\, defined in Theorem (\ref{thm1.1}), is called the pseudo-inverse of \,$U$.
\end{note}


\begin{definition}{\cite{Gavruta}}
Let \,$K \,\in\, \mathcal{B}\,(\,H\,)$.\;Then a sequence \,$\{\,f_{\,i}\,\}_{i \,=\, 1}^{\infty}$\, in \,$H$\, is said to be a \,$K$-frame for \,$H$\, if there exist constants \,$0 \,<\, A \,\leq\, B \,<\, \infty$\, such that
\[A \,\left \|\,K^{\,\ast}\,f\, \right \|^{\,2} \,\leq\, \sum\limits^{\infty}_{i \,=\, 1}\, \left |\,\left <\,f \,,\, f_{\,i}\,\right >\,\right|^{\,2} \,\leq\, B\;\left\|\,f\,\right\|^{\,2}\; \;\forall\; f \,\in\, H.\]
\end{definition}

\begin{definition}\cite{TB}
Let \,$U$\, be a linear space over the filed \,$F$.\,A fuzzy subset \,$N$\,of \,$U \,\times\, \mathbb{R}$\, is called a fuzzy norm on \,$U$\, if for all \,$x,\, u \,\in\, U$\, and \,$c \,\in\, F$, the following conditions are satisfied:
\begin{itemize}
\item[$(\,N1\,)$]\,\,$\forall\, t \,\in\, \mathbb{R}$\, with \,$t \,\leq\, 0$, \,$N\,(\,x,\, t\,) \,=\, 0$;
\item[$(\,N2\,)$]\,\,$\forall\, t \,\in\, \mathbb{R}$, \,$t \,>\, 0$, \,$N\,(\,x,\, t\,) \,=\, 1$\, if and only if \,$x \,=\, \theta$;
\item[$(\,N3\,)$]\,\,$\forall\, t \,\in\, \mathbb{R}$, \,$t \,>\, 0$, \,$N\,(\,c\,x,\, t\,) \,=\, N\left(\,x,\,\dfrac{t}{|\,c\,|}\,\right)$\, if \,$c \,\neq\, 0$;
\item[$(\,N4\,)$]\,\,$\forall\, s,\, t \,\in\, \mathbb{R}$, \,$x,\, u \,\in\, U$, \,$N\left(\,x \,+\, u,\, s \,+\, t\,\right) \,\geq\, \min\left\{\,N\left(\,x,\, s \,\right),\, N\left(\,u,\, t\,\right)\,\right\}$;
\item[$(\,N5\,)$]\,\,$N\left(\,x,\, \cdot\,\right)$\, is a non-decreasing function on \,$\mathbb{R}$\, and \,$\lim\limits_{t \,\to\, \infty}\,N\,(\,x,\, t\,) \,=\, 1$.
\end{itemize}
The pair \,$\left(\,U,\, N\,\right)$\, is called a fuzzy normed linear space.
\end{definition}

\begin{theorem}\cite{TB}
Let \,$\left(\,U,\, N\,\right)$\, be a fuzzy normed linear space.\,Assume further that,
\begin{itemize}
\item[$(\,N6\,)$]\,\,$\forall\, t \,>\, 0,\, \,N\,(\,x,\, t\,) \,>\, 0\, \,\Rightarrow\, x \,=\, \theta$.
\end{itemize}
\end{theorem}

Define \,$\left\|\,x\,\right\|_{\alpha} \,=\, \bigwedge\left\{\,t \,>\, 0 \,:\, N\left(\,x,\, t\,\right) \,\geq\, \alpha\,\right\},\, \,\alpha \,\in\, (\,0,\, 1\,)$.\,Then \,$\left\{\,\left\|\,\cdot\,\right\|_{\alpha}\,\right\} \,:\, \alpha \,\in\, (\,0,\, 1\,)$\, is an ascending family of norms on \,$U$\, and they are called \,$\alpha$-norms on \,$U$\, corresponding to the fuzzy norm \,$N$\, on \,$U$.

\begin{definition}\cite{TBS}
Let \,$\left(\,U,\, N\,\right)$\, be a fuzzy normed linear space.\,Let \,$\left\{\,x_{n}\,\right\}$\, be a sequence in \,$U$.\,Then \,$\left\{\,x_{n}\,\right\}$\,is said to be convergent if there exists \,$x \,\in\, U$\, such that \,$\lim\limits_{n \,\to\, \infty}\,N\left(\,x_{n} \,-\, x,\, t\,\right) \,=\, 1$, for all \,$t \,>\, 0$. 
\end{definition}

\begin{theorem}\cite{SCC}
Let \,$\left(\,U,\, N\,\right)$\, be a fuzzy normed linear space satisfying \,$(\,N6\,)$\,and \,$\left\{\,x_{n}\,\right\}$\, be a sequence in \,$U$.\,Then \,$\left\{\,x_{n}\,\right\}$\, converges to \,$x$\, if and only if \,$x_{n} \,\to\, x$\, with respect to \,$\left\|\,\cdot\,\right\|_{\alpha}$\, for all \,$\alpha \,\in\, (\,0,\, 1\,)$.  
\end{theorem}

\begin{definition}\cite{TBS}
Let \,$\left(\,U,\, N\,\right)$\, be a fuzzy normed linear space and \,$\alpha \,\in\, (\,0,\, 1\,)$.\,A sequence \,$\left\{\,x_{n}\,\right\}$\, is said to be \,$\alpha$-convergent in \,$U$\, if there exists \,$x \,\in\, U$\, such that \,$\lim\limits_{n \,\to\, \infty}\,N\left(\,x_{n} \,-\, x,\, t\,\right) \,>\, \alpha$, for all \,$t \,>\, 0$.  
\end{definition}

\begin{theorem}\cite{PMS}
Let \,$\left(\,U,\, N\,\right)$\, be a fuzzy normed linear space satisfying \,$(\,N6\,)$.\,If a sequence \,$\left\{\,x_{n}\,\right\}$\,is an \,$\alpha$-convergent in \,$\left(\,U,\, N\,\right)$, then \,$\left\|\,x_{n} \,-\, x\,\right\|_{\alpha} \,\to\, 0$\, as \,$n \,\to\, \infty$.
\end{theorem}

\begin{definition}\cite{PM}
Let \,$U$\, be a linear space over the field \,$\mathbb{C}$\, of complex numbers.\,Let \,$\mu \,:\, U \,\times\, U \,\times\, \mathbb{C} \,\to\, I \,=\, [\,0,\,1\,]$\, be a mapping such that the following conditions and statements hold:
\begin{itemize}
\item[(\,FIP1\,)]\, for \,$s,\, t \,\in\, \mathbb{C}$, \,$\mu\left(\,x \,+\, y,\, z,\, |\,t\,| \,+\, |\,s\,|\,\right) \,\geq\, \min\left\{\,\mu\left(\,x,\, z,\, |\,t\,|\,\right),\, \mu\left(\,y,\, z,\, |\,s\,|\,\right)\,\right\}$;
\item[(\,FIP2\,)]\, for \,$s,\, t \,\in\, \mathbb{C}$, \,$\mu\left(\,x,\, y,\, |\,s\,t\,|\,\right) \,\geq\, \min\left\{\,\mu\left(\,x,\, x,\, |\,s\,|^{2}\,\right),\, \mu\left(\,y,\, y,\, |\,t\,|^{2}\,\right)\,\right\}$;
\item[(\,FIP3\,)]\, for \,$t \,\in\, \mathbb{C}$, \,$\mu\left(\,x,\, y,\, t\,\right) \,=\, \mu\left(\,y,\, x,\, \overline{t}\,\right)$;
\item[(\,FIP4\,)]\, for \,$\alpha\,(\,\neq\, 0\,),\, t \,\in\, \mathbb{C}$, \,$\mu\left(\,\alpha\,x,\, y,\, t\,\right) \,=\, \mu\left(\,x,\, y,\,  \dfrac{t}{|\,\alpha\,|}\,\right)$;
\item[(\,FIP5\,)]\,\,$\mu\left(\,x,\, x,\, t\,\right) \,=\, 0$,\, for all \,$t \,\in\, \mathbb{C} \,/\, \mathbb{R}^{+}$; 
\item[(\,FIP6\,)]\,\,$\mu\left(\,x,\, x,\, t\,\right) \,=\, 1$, for all \,$t \,>\, 0$\, if and only if \,$x \,=\, \theta$;
\item[(\,FIP7\,)]\,\,$\mu\left(\,x,\, x,\, \cdot\,\right) \,:\, \mathbb{R} \,\to\, I$\, is a monotonic non-decreasing function on \,$\mathbb{R}$\, and \,$\lim\limits_{t \,\to\, \infty}\,\mu\left(\,\alpha\,x,\, x,\, t\,\right) \,=\, 1$.
\end{itemize}
Then \,$\mu$\, is called fuzzy inner product on \,$U$\, and \,$\left(\,U,\, \mu\,\right)$\, is called fuzzy inner product space (\,FIP\,) space.
\end{definition}

\begin{theorem}\cite{PM}
Let \,$\left(\,U,\, \mu\,\right)$\, be a FIP.\,Then
\[N\left(\,x,\, t\,\right)\,=\, \begin{cases}
\mu\left(\,x,\, x,\, t^{2}\,\right) & \text{if}\; \,t \,\in\, \mathbb{R},\, \,t \,>\, 0 \\ 0 & \text{if}\; \,t \,\leq\, 0. \end{cases}\]
is a fuzzy norm on \,$U$.
\end{theorem}
Now if \,$\mu$\, satisfies the following conditions:
\begin{itemize}
\item[(\,FIP8\,)]\,\,$\mu\left(\,x,\, x,\, t^{2}\,\right) \,>\, 0,\, \,\forall\, t \,>\, 0 \,\Rightarrow\, x\,=\, \theta$\, and 
\item[(\,FIP9\,)]\,\,for all \,$x,\, y \,\in\, U$\, and \,$p,\, q \,\in\, \mathbb{R}$,
\[\mu\left(x + y,\, x + y,\, 2q^{2}\right) \bigwedge \mu\left(x - y,\, x - y,\, 2p^{2}\right) \geq \mu\left(x,\, x,\, p^{2}\right)\bigwedge\mu\left(y,\, y,\, q^{2}\right),\]
\end{itemize}
then \,$\left\|\,x\,\right\|_{\alpha} \,=\, \bigwedge\left\{\,t \,>\, 0 \,:\, N\left(\,x,\, t\,\right) \,\geq\, \alpha\,\right\},\, \,\alpha \,\in\, (\,0,\, 1\,)$\, is an ordinary norm satisfying the parallelogram law.\,By using polarization identity, we can get ordinary inner product, called the \,$\left<\,\cdot,\, \cdot\,\right>_{\alpha}$-inner product, as follows:
\[\left<\,x,\, y\,\right>_{\alpha} \,=\, \dfrac{1}{4}\left(\,\left\|\,x \,+\, y\,\right\|^{2}_{\alpha} \,-\, \left\|\,x \,-\, y\,\right\|^{2}_{\alpha}\,\right) \,+\, \dfrac{i}{4}\left(\,\left\|\,x \,+\, i\,y\,\right\|^{2}_{\alpha} \,-\, \left\|\,x \,-\, i\,y\,\right\|^{2}_{\alpha}\,\right),\]for all \,$\alpha \,\in\, (\,0,\, 1\,)$. 

\begin{example}\cite{BDF} 
Let \,$\left(\,U,\, \mu\,\right)$\, be a real inner product space.\,Then the function \,$\mu \,:\, U \,\times\, U \,\times\, \mathbb{C} \,\to\, I \,=\, [\,0,\,1\,]$\, defined by 
\[\mu\left(\,x,\, y,\, t\,\right)\,=\, \begin{cases}
\dfrac{|\,t\,|}{|\,t\,| \,+\, \|\,x\,\|\,\|\,y\,\|} & \text{if}\; \,t \,>\,  \|\,x\,\|\,\|\,y\,\|,\\ 0 & \text{if}\; t \,\leq\,  \|\,x\,\|\,\|\,y\,\|,\\0 & \text{if}\; t \,\in\, \mathbb{C} \,\setminus\, \mathbb{R}^{+}
. \end{cases}\]
is a fuzzy inner product.\,Therefore, every classic inner product induces the fuzzy inner product space.\,Here, \,$\mu$\, satisfies (\,FIP8\,) and (\,FIP9\,).\,Also, it follows that
\[\left\|\,x \,+\, y\,\right\|^{2}_{\alpha} \,+\, \left\|\,x \,-\, y\,\right\|^{2}_{\alpha} \,=\, \dfrac{\alpha}{1 \,-\, \alpha}\left(\,2\,\|\,x\,\|^{2} \,+\, 2\,\|\,y\,\|^{2}\,\right),\, \left<\,x,\, y\,\right>_{\alpha} \,=\, \dfrac{\alpha}{1 \,-\, \alpha}\left<\,x,\, y\,\right>\] and \,$\|\,x\,\|_{\alpha} \,=\, \sqrt{\dfrac{\alpha}{1 - \alpha}}\,\|\,x\,\|$. 
\end{example}

Define \,$l^{2}(\mathbb{N}) \,=\, \left\{\,\left\{\,\beta_{i}\,\right\}_{i = 1}^{\infty} \,:\, \sum\limits_{i \,=\, 1}^{\,\infty}|\,\beta_{i}\,|^{2} \,<\, \infty\,\right\}$\, and the consider fuzzy inner product
\[\mu\left(\,x,\, y,\, t\,\right)\,=\, \begin{cases}
1 & \text{if}\; \,t \,>\,  \|\,x\,\|_{l^{2}(\mathbb{N})}\,\|\,y\,\|_{l^{2}(\mathbb{N})},\\ 0 & \text{if}\; t \,\leq\,  \|\,x\,\|_{l^{2}(\mathbb{N})}\,\|\,y\,\|_{l^{2}(\mathbb{N})}
. \end{cases}\]
Now, it can be easily verified that \,$\left\|\,x\,\right\|_{\alpha} \,=\, \|\,x\,\|_{l^{2}(\mathbb{N})}$, for all \,$\alpha \,\in\, (\,0,\,1\,)$
\begin{definition}\cite{PM}
Let \,$\left(\,U,\, \mu\,\right)$\, be a FIP satisfying (\,FIP8\,).\,The linear space \,$U$\, is said to be level complete if for any \,$\alpha \,\in\, (\,0,\, 1\,)$, every Cauchy sequence converges with respect to \,$\left\|\,\cdot\,\right\|_{\alpha}$\, and it is said to be fuzzy Hilbert space it is level complete. 
\end{definition}

\begin{definition}\cite{TBS}
Let \,$\left(\,U,\, N_{1}\,\right)$\, and \,$\left(\,V,\, N_{2}\,\right)$\, be fuzzy normed linear spaces.\,The mapping \,$T \,:\, U \,\to\, V$\, is said to be strongly fuzzy bounded if and only if there exists a positive real number \,$M$\, such that
\[N_{2}\left(\,T(x),\, s\,\right) \,\geq\, N_{1}\left(\,x,\, \dfrac{s}{M}\,\right),\, \,\forall\, x \,\in\, U,\, \forall\, s \,\in\, \mathbb{R}.\] 
\end{definition}

\begin{definition}\cite{TBS}
Let \,$\left(\,U,\, N_{1}\,\right)$\, and \,$\left(\,V,\, N_{2}\,\right)$\, be fuzzy normed linear spaces.\,The mapping \,$T \,:\, U \,\to\, V$\, is said to be uniformly bounded if there exists a positive real number \,$M$\, such that \,$\left\|\,T\,x\,\right\|^{2}_{\alpha} \,\leq\, M\,\left\|\,x\,\right\|^{1}_{\alpha}$\, for all \,$\alpha \,\in\, (\,0,\, 1\,)$, where  \,$\left\|\,\cdot\,\right\|^{1}_{\alpha}$\, and  \,$\left\|\,\cdot\,\right\|^{2}_{\alpha}$\, are \,$\alpha$-norms on \,$N_{1}$\, and \,$N_{2}$, respectively.  
\end{definition}

\,$\mathcal{B}\,(\,U,\, V\,)$\, denotes the set of all strongly fuzzy bounded linear operators from a fuzzy normed linear spaces \,$\left(\,U,\, N_{1}\,\right)$\, to \,$\left(\,V,\, N_{2}\,\right)$.

\begin{theorem}\cite{TBS}
Let \,$\left(\,U,\, N_{1}\,\right)$\, and \,$\left(\,V,\, N_{2}\,\right)$\, be fuzzy normed linear spaces satisfying \,$(\,N_{6}\,)$.\,The mapping \,$T \,:\, U \,\to\, V$\, is strongly fuzzy bounded if and only if it is uniformly bounded with respect to \,$\alpha$-norms on \,$N_{1}$\, and \,$N_{2}$.  
\end{theorem} 

\begin{definition}\cite{TBS}
Let \,$\left(\,U,\, N_{1}\,\right)$\, and \,$\left(\,V,\, N_{2}\,\right)$\, be fuzzy normed linear spaces satisfying \,$(\,N_{6}\,)$.\,For \,$T \,\in\, \mathcal{B}\,(\,U,\, V\,)$, let 
\[\,\left\|\,T\,\right\|^{'}_{\beta} \,=\, \bigvee\limits_{x \in U, x \neq \theta}\dfrac{\left\|\,T\,x\,\right\|^{2}_{\beta}}{\left\|\,x\,\right\|^{1}_{\beta}},\, \beta \in  (\,0,\, 1\,),\]
and \,$\left\|\,T\,\right\|_{\alpha} \,=\, \bigvee\limits_{\beta \,\leq \alpha}\left\|\,T\,\right\|^{'}_{\beta},\, \alpha \in  (\,0,\, 1\,)$.\,Then \,$\left\{\,\left\|\,\cdot\,\right\|_{\alpha}\,:\, \alpha \in  (\,0,\, 1\,)\,\right\}$\, is an ascending family of norms in \,$ \mathcal{B}\,(\,U,\, V\,)$.
\end{definition}

\begin{definition}\cite{PM}
Let \,$\left(\,U,\, \mu\,\right)$\, be a FIP satisfying (\,FIP8\,) and (\,FIP9\,).\,Now, if \,$x,\, y \,\in\, U$\,are such that \,$\left<\,x,\, y\,\right>_{\alpha} \,=\, 0,\, \,\alpha \in  (\,0,\, 1\,)$, then we say that \,$x,\, y$\, are \,$\alpha$-fuzzy orthogonal to each other and denote it by \,$x \,\perp_{\alpha}\, y$.\,Let \,$M$\, be a subset of \,$U$\, and \,$x \,\in\, U$.\,Now, if  \,$\left<\,x,\, y\,\right>_{\alpha} \,=\, 0$\, for all \,$y \,\in\, M$, then we say that \,$x$\, is \,$\alpha$-fuzzy orthogonal to \,$M$\, and denote it by \,$x \,\perp_{\alpha}\, M$.\,The set of all \,$\alpha$-fuzzy orthogonal elements to \,$M$\, is called \,$\alpha$-fuzzy orthogonal set.    
\end{definition}

\begin{definition}\cite{PM}
Let \,$\left(\,U,\, \mu\,\right)$\, be a FIP satisfying (\,FIP8\,) and (\,FIP9\,).\,Now, if \,$x,\, y \,\in\, U$\,are such that \,$\left<\,x,\, y\,\right>_{\alpha} \,=\, 0$, for all \,$\alpha \in  (\,0,\, 1\,)$, then we say that \,$x,\, y$\, are fuzzy orthogonal to each other and denote it by \,$x \,\perp\, y$.\,Thus \,$x \,\perp\, y$\, if and only if \,$x \,\perp_{\alpha}\, y$, for all \,$\alpha \in  (\,0,\, 1\,)$.\,The set of all elements fuzzy orthogonal to each other is called fuzzy orthogonal set.    
\end{definition}
\begin{definition}\cite{PMS}
Let \,$\left(\,U,\, \mu\,\right)$\, be a FIP satisfying (\,FIP8\,) and (\,FIP9\,).\,An \,$\alpha$-fuzzy orthogonal set \,$M$\, in \,$U$\, is said to be \,$\alpha$-fuzzy orthonormal if for all \,$x,\, y \,\in\, M$ 
\[\left<\,x,\, y\,\right>_{\alpha}\,=\, \begin{cases}
1 & \text{if}\; \,x \,=\, y \\ 0 & \text{if}\; \,x \,\neq\, y, \end{cases}\] 
where \,$\left<\,\cdot,\, \cdot\,\right>_{\alpha}$\, is an inner product induced by \,$\mu$.  
\end{definition}

\begin{definition}\cite{PMS}
Let \,$\left(\,U,\, \mu\,\right)$\, be a FIP satisfying (\,FIP8\,) and (\,FIP9\,).\,An fuzzy orthogonal set \,$M$\, in \,$U$\, is said to be fuzzy orthonormal if for all \,$x,\, y \,\in\, M$\,and for all \,$\alpha \in  (\,0,\, 1\,)$, we have  
\[\left<\,x,\, y\,\right>_{\alpha}\,=\, \begin{cases}
1 & \text{if}\; \,x \,=\, y \\ 0 & \text{if}\; \,x \,\neq\, y, \end{cases}\] 
where \,$\left<\,\cdot,\, \cdot\,\right>_{\alpha}$\, is an inner product induced by \,$\mu$.  
\end{definition}

\begin{theorem}\cite{PMS}
Let \,$\left(\,U,\, \mu\,\right)$\, be a FIP satisfying (\,FIP8\,) and (\,FIP9\,) and \,$\left\{\,e_{\,k}\,\right\}_{k \,=\, 1}^{\,\infty}$\, be a fuzzy orthonormal sequence in \,$U$.\,Then the following statements are equivalent:
\begin{itemize}
\item[(i)]\,$\left\{\,e_{\,k}\,\right\}_{k \,=\, 1}^{\,\infty}$\, is complete fuzzy orthonormal;
\item[(ii)]if \,$x \,\perp\, e_{k}$\, for \,$k \,=\, 1,\, 2,\, \cdots$, then \,$x \,=\, \theta$;
\item[(iii)]For every \,$x \,\in\, U$, \,$x \,=\, \sum\limits_{i \,=\, 1}^{\,\infty}\,\left <\,x,\, e_{\,k}\,\right>_{\alpha}\,e_{k}$, for all \,$\alpha \in  (\,0,\, 1\,)$,\ and hence \,$\left <\,x,\, e_{\,k}\,\right>_{\alpha} \,=\, \left <\,x,\, e_{\,k}\,\right>_{\beta}$, for all \,$\alpha,\, \beta \in  (\,0,\, 1\,)$, i.\,e., \,$x$\, is independent of \,$\alpha$. 
\item[(iv)]For every \,$x \,\in\, U$, \,$\|\,x\,\|^{2}_{\alpha} \,=\, \sum\limits_{i \,=\, 1}^{\,\infty}\,\left|\,\left <\,x,\, e_{\,k}\,\right>_{\alpha}\,\right|$, for all \,$\alpha \in  (\,0,\, 1\,)$,\ and hence \,$\|\,x\,\|^{2}_{\alpha} \,=\, \|\,x\,\|^{2}_{\beta}$, for all \,$\alpha,\, \beta \in  (\,0,\, 1\,)$. 
\end{itemize}
\end{theorem}

\begin{theorem}\cite{BDF}
Let \,$\left(\,U,\, \mu\,\right)$\, be a fuzzy Hilbert space satisfying \,$\left(\,\textit{FIP}\,8\,\right)$\, and \,$\left(\,\textit{FIP}\,9\,\right)$.\,Suppose \,$T$\, be a strongly fuzzy bounded linear operator on \,$U$.\,Then there exists a strongly fuzzy bounded linear operator \,$T^{\ast}$\, on \,$U$\, such that \,$\left <\,x,\, T\,y\,\right>_{\alpha} = \left <\,T^{\ast} x,\,y\,\right>_{\alpha}$, for all \,$x,\,y \in U$ and \,$\alpha \in  (\,0,\, 1\,)$. 
\end{theorem}

$T^{\ast}$ is called the adjoint of \,$T$ which satisfies the following:
\begin{itemize}
\item[(i)]$\left(\,T^{\ast}\,\right)^{\ast} \,=\, T$;\,\,$(ii)$\,\,$\left(\,T_{1} + T_{2}\,\right)^{\ast} = T_{1}^{\ast} + T_{2}^{\ast}$;\,\,$(iii)$\,\,$\left(\,\lambda\,T\,\right)^{\ast} = \overline{\lambda}\,T^{\ast}$, for all \,$\lambda \in \mathbb{C}$
\end{itemize}

\begin{definition}\cite{BDF}
Let \,$\left(\,U,\, \mu\,\right)$\, be a fuzzy Hilbert space satisfying \,$\left(\,\textit{FIP}\,8\,\right)$\, and \,$\left(\,\textit{FIP}\,9\,\right)$.\,A countable family of elements \,$\left\{\,f_{\,i}\,\right\}_{i \,=\, 1}^{\,\infty}$\, in \,$U$\, is said to be a fuzzy frame for \,$U$\, if there exist constants \,$0 \,<\, A \,\leq\, B \,<\, \infty$\, such that
\begin{align}
&A\,\left \|\,f\,\right \|_{\alpha}^{\,2} \,\leq\, \sum\limits_{i \,=\, 1}^{\infty}\, \left|\,\left <\,f,\,  f_{\,i}\,\right >_{\alpha}\,\right|^{\,2} \,\leq\, B\,\left\|\,f\,\right\|_{\alpha}^{\,2},\label{2.em2.11}
\end{align}
for all \,$f \,\in\, U$\, and \,$\alpha \in  (\,0,\, 1\,)$.\,The constants \,$A$\, and \,$B$\, are called fuzzy frame bounds.\,If \,$A \,=\, B$, then it is called a tight fuzzy frame for \,$U$.\,If \,$A \,=\, B \,=\, 1$, then it is called a Parseval fuzzy frame for \,$U$.\,If the right inequality of (\ref{2.em2.11}) is satisfied then\,$\left\{\,f_{\,i}\,\right\}_{i \,=\, 1}^{\,\infty}$\, is called a fuzzy Bessel sequence in \,$U$.
\end{definition}

Let \,$\left\{\,f_{\,i}\,\right\}_{i \,=\, 1}^{\,\infty}$\, be a fuzzy frame for \,$U$.\,Then the strongly fuzzy bounded linear operator \,$T_{F} \,:\, l^{2}(\mathbb{N}) \,\to\, U$\, defined by \,$T_{F}\,\left\{\,\beta_{\,k}\,\right\} \,=\, \sum\limits_{i \,=\, 1}^{\,\infty}\,\beta_{\,i}\,f_{\,i}$\, is called the fuzzy pre-frame operator or fuzzy synthesis operator and its adjoint operator 
\,$T^{\ast}_{F} \,:\, U \,\to\, l^{2}(\mathbb{N})$\, given by \,$T_{F}^{\ast}\,f \,=\, \left\{\,\left <\,f,\,  f_{\,i}\,\right >_{\alpha}\,\right\}_{i \,=\, 1}^{\,\infty}$\, is called the fuzzy analysis operator.\,The operator \,$S_{F} \,:\, U \,\to\, U$\, defined by \,$S_{F}\,f \,=\, T_{F}\,T_{F}^{\ast}\,f \,=\, \sum\limits_{i \,=\, 1}^{\,\infty}\,\left <\,f,\,  f_{\,i}\,\right >_{\alpha}\,f_{i}$\, is called the fuzzy frame operator.\,It is easy to verify that \,$\left <\,S_{F}\,f,\,  f\,\right >_{\alpha} \,=\, \sum\limits_{i \,=\, 1}^{\infty}\, \left|\,\left <\,f,\,  f_{\,i}\,\right >_{\alpha}\,\right|^{\,2}$, for all \,$f \,\in\, U$.\,The fuzzy frame operator \,$S_{F}$\, is strongly fuzzy bounded, invertible and self-adjoint. 




