\section{Stochastic dominance and a class of distributions }\label{sec:2}
\subsection{A stochastic dominance relation}
We first recall the notion of majorization order.
\begin{definition}\label{maj}
For two vectors $ \overline{\theta} := \(\theta_1,\dots,\theta_n\)$ and $ \overline{\eta} :=  \(\eta_1,\dots,\eta_n\)$ in $\R^n$,  $ \overline{\theta}$ is dominated by $ \overline{\eta}$ in \emph{majorization order}, denoted by $ \overline{\theta} \preceq  \overline{\eta}$ if 
$$
\sum^n_{i=1}\theta_i =\sum^n_{i=1}\eta_i \mbox{~~~and~~~}
\sum^k_{i=1} \theta_{(i)} \ge \sum^k_{i=1} \eta_{(i)}\ \ \mbox{for}\ k\in [n-1],
$$
where $\theta_{(i)}$ and $\eta_{(i)}$ represent the $i$th smallest order statistics of $\overline{\theta}$ and $\overline{\eta}$, respectively.
\end{definition}


The main focus of the paper is on studying the following stochastic dominance relation

\begin{equation} \label{eq:SD}
\sum_{i=1}^n\eta_i X_i  \le_{\rm st} \sum_{i=1}^n\theta_i X_i\mbox{  for all $\overline \theta,\overline \eta\in\R^n_+$ such that $\overline \theta \preceq \overline \eta$,}\tag{SD}
\end{equation}
where $ X_1, \dots, X_n$ are iid random variables. Let $X$ be a copy of $ X_1, \dots, X_n$. If $X_1, \dots, X_n\sim F$ satisfy \eqref{eq:SD}, we also say $X$ or $F$ satisfies \eqref{eq:SD}. 
For some $x\in\R$, let
$$
g(\theta_1,\dots,\theta_n) = \p\(\sum_{i=1}^n \theta_i X_i > x\),~~\overline \theta\in\R^n_+.
$$ 
Then  \eqref{eq:SD} holds if and only if 
$g$ is Schur-concave on  $\mathbb{R}^n_+$ for all $x \in \R$; recall that a function $f$ on $\R^n$ is \emph{Schur-concave} if  $f(\overline x)\ge f(\overline y) $ for $\overline x \preceq  \overline y$.



We present below some elementary properties of \eqref{eq:SD}.


\begin{proposition}\label{prop:trivial}
The following statements hold.
\begin{enumerate}[{\rm (i)}]
\item If random variable $X$ satisfies \eqref{eq:SD}, then either $X$ is a constant, or $\E[|X|]$ is infinite.
\item If  two independent random variables $X$ and $Y$ satisfy \eqref{eq:SD}, then $X+Y$ satisfies \eqref{eq:SD}.
\item If  random variable $X$  satisfies \eqref{eq:SD}, then $(X+a)/b$ satisfies \eqref{eq:SD} for all $a\in\R$ and $b \in \R_{++}$.
\item If $Y_k$ with $k=1, 2, \dots$ satisfies \eqref{eq:SD} and $Y_k\xrightarrow{\d}X$, then $X$ satisfies \eqref{eq:SD}.
\end{enumerate}
\end{proposition}
\begin{proof}
If $X$ is a constant, \eqref{eq:SD} clearly holds. For a non-degenerate random variable $X$, as
 \eqref{eq:SD} implies  $(\sum_{i=1}^n\theta_i) X  \le_{\rm st} \sum_{i=1}^n\theta_i X_i$, by Theorem 2.3 (b) of \cite{muller2024some}, $\E[|X|]=\infty$.
% Statement (i) was shown in Proposition 1 of \cite{CHWZ25}; it is also implied by Proposition 3.2 of  \cite{arab2024convex} or  Theorem 2.3 (b) of \cite{muller2024some}.
Statement (ii) is because usual stochastic order is preserved under convolution (see, e.g., Theorem 1.A.3 (b) of \cite{SS07}). Statement (iii) is trivial. Statement (iv)  holds as usual stochastic order is preserved under convergence in distribution (Theorem 1.2.14 of \cite{MS02}).
\end{proof}

\begin{remark}
Property \eqref{eq:SD} implies that 
$
(X_1+\dots+X_n)/n
$
is increasing in usual stochastic order as $n$ increases, since  $(1/n,\dots,1/n,0)$ dominates  $(1/(n+1),\dots,1/(n+1))$ in majorization order for all $n$. By Proposition \ref{prop:trivial}, if $X_1$ satisfies \eqref{eq:SD} and  $X_1$ is bounded from below, we have $\E[X_1]=\infty$. Then by the law of large numbers,  $(X_1+\dots+X_n)/n\rightarrow \infty$ almost surely as $n$ goes to infinity (see, e.g., Theorem 2.4.5 of \cite{D19}).
\end{remark}

\subsection{A new class of distributions}

Next, we introduce a class of distributions of non-negative random variables, denoted by $\H$. We will show later that this rather large class of distributions satisfies property \eqref{eq:SD} and thus, by Proposition \ref{prop:trivial}, the distributions in $\H$ have infinite mean.
\begin{definition}
Let $F$ be a distribution function with $\essinf F=0$. We say  $F\in \H$ if the function
\begin{equation*} 
\phi(x_1,x_2)= \overline{F} \left(\frac{1}{x_1}\right)+\overline{F} \left(\frac{1}{x_2}\right),~~(x_1,x_2)\in \R_{++}^2
\end{equation*}
is Schur-concave. For $X\sim F$ where $F\in\H$, we also write $X\in\H$.
\end{definition}

The following result characterizes distributions in class $\H$.
\begin{proposition}\label{prop:Hcont}
The following statements hold.
\begin{enumerate}[{\rm (i)}]
\item
A distribution function $F\in\H$ if and only if $\overline F(1/x)=c(x)+a(x)$ where $c:\R_{++} \rightarrow \R$ is concave and $a:\R_{++}\rightarrow \R$ is additive.
\item
Let $F$ be a continuous distribution on $\R_+$. Then $F\in\H$ if and only if $\overline F(1/x)$ is concave in $x\in\R_{++}$. In addition, if $F$ has density $f$, then $F\in\H$ if and only if $x^2f(x)$ is increasing in $x\in\R_{++}$.
\end{enumerate}
\end{proposition}
\begin{proof}
\begin{enumerate}[(i)]
\item 
This follows from Theorem 3 of \cite{ng1987functions}.


\item
By 3.C.1 of \cite{MOA11}, if $g:\R_+\rightarrow \R_+$ is concave, then   $\phi(x_1,\dots,x_n)=\sum_{i=1}^n g(x_i)$ is Schur-concave in $(x_1,\dots,x_n)\in\R_+^n$.
Thus, we have the ``$\Leftarrow$" direction.  By  3.C.1.c of \cite{MOA11}, for a continuous function $g$ on an interval $I$, if    $\psi(x_1,x_2)=g(x_1)+g(x_2)$ is Schur-concave on $I^2$, then $g$ is concave. Then the ``$\Rightarrow$'' direction follows. \qedhere
\end{enumerate}
\end{proof}
\begin{remark}\label{rem:RV}
If distributions have densities of the form
$
f(x) = x^{-\alpha-1} l(x)
$
where function $l$ is increasing and $\alpha \in (0,1]$, the distributions are in $\H$ by Proposition \ref{prop:Hcont}. In addition, if $l$ is a slowly-varying function, by the Karamata representation (see Theorem B.1.6 of \cite{DF06}), it may be written as
$$
l(x) = \exp\left(c(x) + \int_0^x \frac{\varepsilon(t)}{t} \d t\right),
$$
where $c(x) \to c$ as $x \to \infty$ and $\varepsilon(x) \to 0$ as $x \to \infty$. If $c$ is increasing and $\varepsilon$ is non-negative, the distributions are in $\H$.
\end{remark}

One can use Proposition \ref{prop:Hcont} (ii) together with Remark \ref{rem:RV} to show that many commonly used heavy-tailed distributions are in $\H$. We present some examples below. Additional examples are collected in Table \ref{t1}; see Appendix \ref{sec:SHex} for more details of Table \ref{t1}. Some closure properties of $\H$ are collected in Section \ref{sec:closure}.

\begin{example}[Fr\'echet distribution]
 The Fr\'echet distribution function is $F(x)=\exp\(-x^{-\alpha}\)$, $x \in \R_{++}$. As its density function is $f(x)=\alpha x^{-\alpha-1}\exp\(-x^{-\alpha}\)$ for $x \in \R_{++}$, by Remark \ref{rem:RV}, $F\in\H$ if $\alpha\le 1$.
\end{example}
\begin{example}[Absolute Cauchy distribution]\label{ex:absCauchy}
The absolute Cauchy distribution is defined as
$F(x)=(2/\pi)\arctan(x)$ for  $x \in \R_{++}$. As
the density function is $f(x)=2/(\pi(x^2+1))=x^{-2}(2x^2/(\pi(x^2+1)))$ for $x \in \R_{++}$, by Remark \ref{rem:RV},  we have $F \in \H$. \end{example}
\begin{example}[Inverse Gamma distribution]\label{ex:IG}
The density function of the inverse Gamma distribution with parameters $\alpha,\beta \in \R_{++}$ is $f(x)= \beta^\alpha x^{-\alpha-1}\exp\(-\beta/x\)/\Gamma(\alpha)$, $x \in \R_{++}$. By Remark \ref{rem:RV}, if $\alpha\le 1$ and $\beta \in \R_{++}$, we have $F \in \H$. The inverse Gamma distribution with $\alpha=0.5$ is the L{\'e}vy distribution, which also belongs to the class of stable distributions.
\end{example}
% \begin{example}[L{\'e}vy distribution]
