\subsection{Main result}

Let $\overline {\theta}$ and $\overline {\eta}$ be two vectors in $\R^n$.  Then $\overline {\theta}$ is a \emph{$T$-transform} of $\overline {\eta}$ if for some $\lambda \in [0,1]$ and $i,j\in [n]$ with $i \neq j$,
\begin{equation*}\label{eq:t-tran}
\theta_i=\lambda \eta_i + (1-\lambda)\eta_j,~\theta_j= (1-\lambda)\eta_i+\lambda \eta_j,
\end{equation*}
and $\theta_k=\eta_k$ for $k\in [n]\setminus \{i,j\}$. The following lemma will be useful in our proof.

\begin{lemma}
\label{lem:maj}
{\rm \citep[][Section 1.A.3]{MOA11}}\ \
For $\overline \theta, \overline \eta\in \R^n$, $\overline \th\preceq \overline \eta$ if and only if $\overline \theta$ can be obtained from $\overline\eta$ by a finite number of $T$-transforms.
\end{lemma}



\begin{theorem}\label{thm:main}
If $F\in \H$, then $F$ satisfies \eqref{eq:SD}.
\end{theorem}
\begin{proof}
We first show that it is sufficient to prove the theorem for the case of two random variables. 
By Lemma \ref{lem:maj}, it suffices to assume that $\overline \theta$ is obtained from $\overline \eta$ by a $T$-transform, i.e., only two components in $\overline \theta$ and $\overline \eta$ are different. Write $\overline \theta=(\lambda \eta_1 + (1-\lambda) \eta_2,(1-\lambda) \eta_1 + \lambda \eta_2, \eta_3,\dots,\eta_n)$ for some $\lambda\in[0,1]$. If the statement of the theorem is correct for two random variables, then
$$
\theta_1 X_1 + \theta_2 X_2=(\lambda \eta_1 + (1-\lambda) \eta_2) X_1 + ((1-\lambda) \eta_1 + \lambda \eta_2) X_2 \ge_{\rm st} \eta_1 X_1 + \eta_2 X_2. 
$$
Then, as $X_1,\dots,X_n$ are independent and  usual stochastic order is closed under convolution (see, e.g., Theorem 1.A.3 (b) of \cite{SS07}),
\begin{align*}
\sum_{i=1}^n \theta_i X_i&=(\lambda \eta_1 + (1-\lambda) \eta_2) X_1 + ((1-\lambda) \eta_1 + \lambda \eta_2) X_2 + \sum_{i=3}^n \eta_i X_i\\
& \ge_{\rm st} \eta_1 X_1 + \eta_2 X_2 + \sum_{i=3}^n \eta_i X_i=\sum_{i=1}^n \eta_i X_i.
\end{align*}

It therefore remains to prove the theorem in the case $n=2$. It is clear that we can restrict ourselves to the case $\theta_1+\theta_2=1$. It is also clear that, due to symmetries, it is sufficient to show that
\begin{equation} \label{eq:aux_1}
\p(\theta X_1 + (1-\theta) X_2 > x) \ge \p(\eta X_1 + (1-\eta) X_2 > x)
\end{equation}
holds for all $0 \le \eta \le \theta \le 1/2$ and for all $x\in\R$. To this end, for $a \in (0,1)$, write
\begin{align}\label{eq:remark}
 & \p(a X_1 + (1-a) X_2 > x) \nonumber\\
& = \p(X_1>x,X_2>x) + \p(X_1\le x, a X_1 + (1-a) X_2 > x) + \p(X_2\le x, a X_1 + (1-a) X_2 > x) \nonumber\\
& = \p(X_1>x,X_2>x) + \int_{y=0}^x  \overline{F}\left(\frac{x-a y}{1-a}\right)\d F(y) + \int_{y=0}^x  \overline{F}\left(\frac{x-(1-a) y}{a}\right)\d F(y).
\end{align}
From the above, it is now clear that, in order to show \eqref{eq:aux_1} holds for all $0 < \eta \le \theta \le 1/2$ and for all $x\in\R$, it is sufficient to show that
\begin{equation*} \label{eq:aux_2}
\overline{F}\left(\frac{x-\theta y}{1-\theta}\right) + \overline{F}\left(\frac{x-(1-\theta) y}{\theta}\right) \ge
\overline{F}\left(\frac{x-\eta y}{1-\eta}\right) + \overline{F}\left(\frac{x-(1-\eta) y}{\eta}\right)
\end{equation*}
for all $y \le x$ and for all $0 < \eta \le \theta \le 1/2$. This can be rewritten as
\begin{equation}\label{eq}
\overline{F}\left(y + \frac{x-y}{1-\theta}\right) + \overline{F}\left(y+\frac{x-y}{\theta}\right) \ge
\overline{F}\left(y+\frac{x-y}{1-\eta}\right) + \overline{F}\left(y+\frac{x-y}{\eta}\right)
\end{equation}
and, with conditions above,  \eqref{eq} can also be stated as
\begin{equation} \label{eq:suff_1}
\overline{F}\left(y + \frac{z}{1-\theta}\right) + \overline{F}\left(y+\frac{z}{\theta}\right) \ge
\overline{F}\left(y+\frac{z}{1-\eta}\right) + \overline{F}\left(y+\frac{z}{\eta}\right)
\end{equation}
for all $y, z \in \R_+$ and for all $0 < \eta \le \theta \le 1/2$. The above holds if $z=0$ and thus we only need to consider the case $ z\in \R_{++}$.
 Let $h(x)=\overline F(1/x)$ for $x\in\R_{++}$ and $l(w)=1/(y+z/w)$ for $w\in \R_{++}$, where $ y\in \R_{+}$ and $ z\in \R_{++}$.
Since $F\in\H$, by Proposition \ref{prop:Hcont} (ii), $h$ is concave. It is easy to check that $l$ is also concave. By Lemma \ref{lem:maj}, there exists some $\lambda\in[0,1]$ such that $\theta=(1-\lambda) (1-\eta) + \lambda \eta$ and  $1-\theta=\lambda (1-\eta) + (1-\lambda) \eta$. Therefore, we have 
\begin{align*}
\overline{F}\left(y + \frac{z}{1-\theta}\right) + \overline{F}\left(y+\frac{z}{\theta}\right) &= h(l(1-\theta))+h(l(\theta))\\
&=h(l(\lambda (1-\eta) + (1-\lambda) \eta))+h(l((1-\lambda) (1-\eta) + \lambda \eta))\\
&\ge h(\lambda l(1-\eta)+ (1-\lambda) l (\eta))+h((1-\lambda) l (1-\eta)+ \lambda l(\eta))\\
&\ge h(l(1-\eta))+h(l(\eta)) =
\overline{F}\left(y+\frac{z}{1-\eta}\right) + \overline{F}\left(y+\frac{z}{\eta}\right).
\end{align*}
Hence, \eqref{eq:aux_1} holds for $0 < \eta \le \theta \le 1/2$. Moreover, for any $a\in(0,1)$, we have 
\begin{align}\label{eq:proofSD*}
& \p(a X_1 + (1-a) X_2 > x)   \nonumber\\
% & = \p(X_1>x,X_2>x) + \p(X_1\le x, a X_1 + (1-a) X_2 > x) + \p(X_2\le x, a X_1 + (1-a) X_2 > x)  \\
& = \p(X_1>x,X_2>x) + \int_{y=0}^x  \overline{F}\left(\frac{x-a y}{1-a}\right)\d F(y) + \int_{y=0}^x  \overline{F}\left(\frac{x-(1-a) y}{a}\right)\d F(y)  \nonumber\\
& \ge \p(X_1 > x, X_2 > x) + \int_{y=0}^x  \overline{F}\left(\frac{x}{1-a}\right)\d F(y) + \int_{y=0}^x  \overline{F}\left(\frac{x}{a}\right)\d F(y) \nonumber\\
&\ge \p(X_1>x,X_2>x) + \int_{y=0}^x  \overline{F}\left(x\right)\d F(y)  \\
&=\p(X_1>x,X_2>x)+ \p(X_1>x,X_2\le x)= \p(X_1>x). \nonumber 
\end{align}
Inequality \eqref{eq:proofSD*} is due to $F\in\H$ and right-continuity of $\overline F$. Hence, \eqref{eq:aux_1} holds for $\eta=0$. 
The proof is complete.
\end{proof}

The proof of Theorem \ref{thm:main} is significantly 
%\seva{maybe significantly instead of quite?} 
different from \cite{CHWZ25} who established \eqref{eq:SD} for infinite-mean Pareto distributions. Their techniques depend on the assumption of Pareto distributions and have been used to derive a more general version of \eqref{eq:SD} for non-identically distributed Pareto random variables. On the other hand, our proof utilizes the symmetry property of functions and thus does not seem to work for non-identical distributions.

\begin{remark}\label{rem:unbounded}
We note that \eqref{eq:SD} can also hold for random variables that are not bounded from below. A classic example is the standard Cauchy distribution, with the distribution function given by 
$$F(x)=\frac{1}{\pi}\arctan(x)+\frac{1}{2},~~x\in\R.$$
It is well known that for iid standard Cauchy random variables $X_1,\dots,X_n$ and for any $\overline \theta\in\R_+^n$, $\sum_{i=1}^n\theta_iX_i\simeq_{\rm st} (\sum_{i=1}^n\theta_i)X_1$ and thus \eqref{eq:SD} holds. A question is whether the proof of  Theorem \ref{thm:main} can be generalized to incorporate distributions like the standard Cauchy distribution. This does not seem to be easy as \eqref{eq:suff_1} may flip for some negative $y$.
Indeed, from \eqref{eq:remark}, we can see that to let \eqref{eq:SD} hold for an arbitrary distribution $F$,  a sufficient and necessary condition is that
$$\int_{y=\essinf F}^x  \overline{F}\left(\frac{x-a y}{1-a}\right)\d F(y) + \int_{y=\essinf F}^x  \overline{F}\left(\frac{x-(1-a) y}{a}\right)\d F(y)$$
is increasing in $a\in[0,1/2]$ for all $x\in\R$. This condition can still hold if \eqref{eq:suff_1} does not hold for some values of $y$.
\end{remark}

A particularly interesting case of \eqref{eq:SD} relevant to risk sharing  is 
\begin{equation}\label{eq:SD*}
\(\sum_{i=1}^n \theta_i\) X_1 \le_{\rm st} \sum_{i=1}^n \theta_i X_i \mbox{~for all~} \overline\theta\in\R_+^n, \tag{SD*}
\end{equation}
where $X_1,\dots,X_n$ are iid random variables.  
Inequality \eqref{eq:SD*} implies that any rational decision makers will not share infinite-mean losses; we say a decision maker is rational if they prefer loss $X$ to loss $Y$ for $X\le_{\rm st}Y$.  \cite{CEW22} recently showed that \eqref{eq:SD*} holds if $X_1$ is an increasing and convex transformation of a Pareto random variable with tail parameter 1; such a random variable is called super-Pareto. Subsequently, this result was studied for more general classes of infinite-mean distributions by \cite{arab2024convex}, \cite{CS24}, and \cite{muller2024some}.

\begin{definition}
Let $F$ be a distribution function with $\essinf F=0$. We say  $F\in \H^*$ if
\begin{equation*} 
\overline{F} \left(\frac{1}{x_1}\right)+ \overline{F} \left(\frac{1}{x_2}\right)\ge  \overline{F} \left(\frac{1}{x_1+x_2}\right),~\mbox{for all}~(x_1,x_2)\in \R_{++}^2.\end{equation*}
\end{definition}
The distributions in $\H^*$ are called InvSub by \cite{arab2024convex} who also showed that $\H^*$ is more general than the class of super-Pareto distributions. Clearly, $\H\subseteq\H^*$. \cite{arab2024convex} has shown \eqref{eq:SD*} for the distributions in $\H^*$ (Theorem 3.1 of \cite{arab2024convex}).  This result is also implied by the last part of the proof of Theorem \ref{thm:main} (i.e., the inequality chain containing \eqref{eq:proofSD*}). 
% We can slightly modify the arguments in the proof of Theorem \ref{thm:main} to present  another proof. 

\begin{theorem}\label{thm:main2}
If $F\in \H^*$, then $F$ satisfies \eqref{eq:SD*}.
\end{theorem}
% \begin{proof}
% It suffices to show the statement for two risks as in the proof of  Theorem \ref{thm:main}.  For $a \in [0,1]$ and $x\ge0$, we have

% The last inequality follows from $F\in\H^*$. The proof is complete.
% \end{proof}
The studies mentioned on \eqref{eq:SD*} are closely related to each other and we refer to \cite{arab2024convex}, \cite{CS24}, and \cite{muller2024some} for discussions. Variations of \eqref{eq:SD*} were studied by \cite{CEW22} and \cite{CS24} for random variables that are possibly negatively dependent or non-identically distributed.

\subsection{Some closure properties of $\H$}\label{sec:closure}

 This section presents some closure properties of $\H$, which can be used to construct more distributions satisfying \eqref{eq:SD}. 
For random variables $X$ and $Y$ with respective densities $f$ and $g$,  we say $X$ is smaller than $Y$ in \emph{likelihood ratio order}, denoted by $X\le_{\rm lr}Y$, if $g(x)/f(x)$ is increasing in $x$ over the union of the supports of $X$ and $Y$.  See, e.g.,  \cite{SS07} for properties of likelihood ratio order.

\begin{proposition}\label{prop:Hproperty}
Let $X\sim F$ where $F$ is continuous and $F\in \H$. Then 
\begin{enumerate}[{\rm (i)}]
\item 
$F^\beta\in \H$ where $\beta\ge 1$;
\item
$\phi(X)\in\H$ where $\phi$ is strictly increasing and convex with $\phi(0)=0$ and $1/\phi^{-1}(1/x)$ being concave in $x\in\R_+$;
\item 
if $Y\sim G$ where $G\in\H$ is continuous and $Y$ is independent of $X$, then $\max\{X,Y\}\in\H$;
\item 
if in addition $X$ and another  random variable $Y$ have densities and $X\le_{\rm lr}Y$, then $Y\in\H$.
\end{enumerate}
\end{proposition}
\begin{proof}
\begin{enumerate}[(i)]
\item 
Let $G=F^\beta$. Then $\overline G(1/x)=1-(1-\overline F(1/x))^\beta$, $x \in \R_{++}$. As $\beta\ge 1$, $1-(1-x)^\beta$ is increasing and concave in $x\in(0,1)$. Moreover,  since $F\in\H$, $\overline G(1/x)$ is concave and the desired result follows from Proposition \ref{prop:Hcont}.
\item
Denote by $G$ the distribution function of $\phi(X)$. Then for $x\in \R_{++}$,
$$\overline G\(1/x\)=\p\(\phi(X)\ge 1/x\)=\overline F\(\phi^{-1}\(1/x\)\).$$
As $1/\phi^{-1}(1/x)$ is concave,  $\overline G(1/\cdot)$ is also concave. By Proposition \ref{prop:Hcont}, we have the desired result.
\item
Denote the distribution function of $\max\{X,Y\}$ by $H$. By Proposition \ref{prop:Hcont}, it suffices to show that $\overline H(1/x)$ is concave in $x\in\R_{++}$. We have for $x\in \R_{++}$,
$$\overline H(1/x)=1-(1-\overline F(1/x))(1-\overline G(1/x)).$$
As both $1-\overline F(1/x)$ and $1-\overline G(1/x)$ are convex, positive, and decreasing in $x\in \R_+$, then $(1-\overline F(1/x))(1-\overline G(1/x))$ is convex in $x\in \R_+$ (see Exercise 3.32 of \cite{boyd2004convex}) and $\overline H(1/\cdot)$ is concave.
\item
Let $Y$ have density $g$.
We have 
$x^2g(x)=x^2f(x)(g(x)/f(x))$. As $x^2f(x)$ and $g(x)/f(x)$ are both increasing in $x$ and are positive, $x^2g(x)$ is increasing in $x$. By Proposition \ref{prop:Hcont}, we have the desired result. \qedhere
\end{enumerate}
% Thus, we complete the proof of this proposition.
\end{proof}
Proposition \ref{prop:Hproperty} (ii) states that some increasing and convex transforms on random variables preserve property $\H$. The conditions on $\phi$ in Proposition \ref{prop:Hproperty} (ii) can be satisfied by commonly used convex functions, e.g., $\phi(x)=x^p$ with $p\ge 1$ and $\phi(x)=e^x-1$. For random variables $X$ and $Y$, $Y$ is said to be more \emph{skewed} than $X$ if there exists some increasing and convex function $\phi$ such that $Y\simeq_{\rm st}\phi(X)$; intuitively $Y$ is more ``heavy-tailed" than $X$.  See \cite{van1964convex} for more details.
 \begin{proposition}\label{prop:mixture}
  For $w_1,\dots,w_n\in \R_+$ such that $\sum_{i=1}^n w_i=1$, if distribution functions $F_1,\dots,F_n\in\H$, then
  $\sum_{i=1}^n w_iF_i\in\H$.  
  \end{proposition}
  \begin{proof}
  Let $G=\sum_{i=1}^n w_iF_i$. Then for $x_1,x_2\in\R_{++}$,
  \begin{align*}
  \phi(x_1,x_2)&=\overline{G} \left(\frac{1}{x_1}\right)+\overline{G} \left(\frac{1}{x_2}\right)\\
  &=\sum_{i=1}^n w_i\overline{F_i} \left(\frac{1}{x_1}\right)+\sum_{i=1}^n w_i\overline{F_i} \left(\frac{1}{x_2}\right)=\sum_{i=1}^n w_i\(\overline{F_i} \left(\frac{1}{x_1}\right)+\overline{F_i} \left(\frac{1}{x_2}\right)\).
  \end{align*}
 Since $F_1,\dots,F_n\in\H$, $\phi$ is Schur-concave and thus $G\in\H$.
  \end{proof}
  \begin{proposition}\label{prop:insurance}
  If $X\in \H$, then $\max(X-c,0)\in\H$ where $c\in \R_{++}$.
  \end{proposition}
  \begin{proof}
  Denote by $F$ and $G$ the distribution functions of $X$ and $\max(X-c,0)$. For $x_1,x_2\in \R_{++}$, let 
 \begin{align*}
 \phi(x_1,x_2)&= \overline{G} \left(\frac{1}{x_1}\right)+\overline{G} \left(\frac{1}{x_2}\right)\\
 &=\overline{F} \left(c+\frac{1}{x_1}\right)+\overline{F} \left(c+\frac{1}{x_2}\right).
 \end{align*}
 With a similar argument for \eqref{eq:suff_1}, we can show that $\phi$ is Schur-concave and hence we have the desired result.
  \end{proof}
  Proposition \ref{prop:mixture} says that $\H$ is closed under distribution mixture. Proposition \ref{prop:insurance} is relevant in an insurance context: $X$ is the actual claim amount and $c$ is the deductible, i.e., $\max(X-c,0)$ is the payout by the insurer.

\section{Compound Poisson distributions}\label{sec:3}

In this section, we assume each random variable in \eqref{eq:SD} is a compound sum of random losses. 
%Denote the risks by $S_1,\dots,S_n$.
More precisely, for each  $i\in[n]$, let   $X_i=\sum_{j=1}^{N_i}Y_{i,j}$, where $\{Y_{i,j}\}_{j\in\N}$ are iid random losses and $N_i$ is the number of losses,  which is independent of $\{Y_{i,j}\}_{j\in\N}$. The distribution of $X_i$ is referred to as \emph{compound distribution}. 
One classic example of compound distributions is the compound Poisson distribution. 
\begin{definition}
Let random variables $Y_1,Y_2,\dots$ be iid with distribution $F$ and $N$ follow a Poisson distribution with mean $\lambda\in \R_{++}$, i.e., $\p(N=j)=\lambda^je^{-\lambda}/j!$, $j\in\N_0$. Then we say that $X=\sum_{i=1}^NY_i$ follows a \emph{compound Poisson distribution} with Poisson parameter $\lambda$ and distribution $F$, denoted by ${\rm CP}(\lambda,F)$. 
\end{definition}

We first note that if a distribution $F$ satisfies \eqref{eq:SD}, \eqref{eq:SD} may not hold for ${\rm CP}(\lambda,F)$. For instance, if $F$ is a degenerate distribution at 1, then ${\rm CP}(\lambda,F)$ becomes a Poisson distribution, which clearly does not satisfy \eqref{eq:SD} by Proposition \ref{prop:trivial}. We give below a sufficient and necessary condition for \eqref{eq:SD} to hold for ${\rm CP}(\lambda,F)$.

\begin{theorem}\label{thm:CP}
Let $\lambda\in \R_{++}$ and $F$ be a distribution function with $\essinf F=0$. Then ${\rm CP}(\lambda,F)$ satisfies  \eqref{eq:SD} if and only if $F\in\H$.
\end{theorem}
\begin{proof}
We first show the ``$\Longleftarrow$" direction. Using an argument similar to the proof of Theorem \ref{thm:main}, it is sufficient to establish the result for the case of two random variables.  Let $X_1,X_2\sim {\rm CP}(\lambda,F)$ be independent and $\overline a=(a_1,a_2)\in(0,1)^2$ such that $a_1+a_2=1$. It is well known that  $\sum_{i=1}^2a_iX_i\sim {\rm CP}(2\lambda,H_{\overline a})$ where
$$H_{\overline a}(x)=\sum_{i=1}^2\frac{1}{2}F(x/a_i).$$
We give a proof for this result here for completeness. The characteristic function of $\sum_{i=1}^2a_iX_i$  is 
\begin{align*}
\varphi_{\sum_{i=1}^2a_i X_i}(t) =\exp\left\{\lambda\(\sum_{i=1}^2\varphi_{X_1}(a_it)-2\)\right\} =\exp\left\{2\lambda\(\frac{1}{2}\sum_{i=1}^2\varphi_{X_1}(a_it)-1\)\right\}.
\end{align*}
As $\sum_{i=1}^2\varphi_{X_1}(a_it)/2$ is the characteristic function of $H_{\overline a}$, $\sum_{i=1}^2a_iX_i\sim {\rm CP}(2\lambda,H_{\overline a})$.

% Write $\overline \theta=(\theta_1\dots,\theta_n)$ and $\overline \eta=(\eta_1\dots,\eta_n)$ (this has been defined). 
Let $\overline \theta\preceq \overline \eta$ such that $\overline \theta, \overline \eta\in (0,1)^2$ and $\sum_{i=1}^2\theta_i = \sum_{i=1}^2\eta_i = 1$.  We need to show 
$$\sum_{i=1}^2\eta_iX_i\le_{\rm st}\sum_{i=1}^2\theta_iX_i.$$
Since $\sum_{i=1}^2\theta_iX_i\sim {\rm CP}(2\lambda,H_{\overline \theta})$ and $\sum_{i=1}^2\eta_iX_i\sim {\rm CP}(2\lambda,H_{\overline \eta})$,  it suffices to show 
$$\sum_{i=1}^NV_i\le_{\rm st}\sum_{i=1}^NU_i,$$ 
where
$N\sim {\rm Poi}(2\lambda)$,  $V_1,V_2,\dots\sim  H_{\overline \eta}$ and $U_1,U_2,\dots\sim  H_{\overline \theta}$ are mutually independent.  As $F\in\H$, we have $H_{\overline \theta}(x)\le H_{\overline \eta}(x)$ for all $x\in \R_+$, i.e., $H_{\overline \eta}\le_{\rm st}H_{\overline \theta}$. Moreover, As usual stochastic order is preserved under convolution,   for $x\in \R_+$, 
\begin{eqnarray*}
\p\(\sum_{i=1}^NV_i\le x\) &=& \sum_{m=1}^\infty \p\(\sum_{i=1}^mV_i\le x\)\p(N=m) \\ 
&\ge& \sum_{m=1}^\infty \p\(\sum_{i=1}^mU_i\le x\)\p(N=m)=\p\(\sum_{i=1}^NU_i\le x\).
\end{eqnarray*}
Hence, $\sum_{i=1}^2\eta_iX_i\le_{\rm st}\sum_{i=1}^2\theta_iX_i$ holds for $\overline \theta, \overline \eta\in (0,1)^2$. Moreover, if $\overline \eta=(0,1)$, $\sum_{i=1}^2\eta_iX_i\sim {\rm CP}(2\lambda,H^*_{\overline \eta})$ where 
$$H^*_{\overline \eta}(x)=\frac{1}{2}\(F(x)+\id_{\{x\ge 0\}}\).$$
Clearly, we have $H^*_{\overline \eta}\le_{\rm st}H_{\overline \theta}$ by the definition of $F$. The  ``$\Longleftarrow$" direction is done. 

Next, we show the ``$\Longrightarrow$" direction. 
We have that, if $(\theta_1,\theta_2) \preceq (\eta_1,\eta_2)$ where $(\eta_1,\eta_2)\in(0,1)^2$,
 then for all $x\in \R$ and for some $\lambda\in\R_{++}$,
\begin{equation} \label{eq:aux_5}
\p(\theta_1 X_1 + \theta_2 X_2 > x) \ge \p(\eta_1 X_1 + \eta_2 X_2 > x),
\end{equation}
where $X_1,X_2\sim {\rm CP}(\lambda/2,F)$ are independent. Thus, by the previous arguments, \eqref{eq:aux_5} may be rewritten as
\begin{equation} \label{eq:aux_6}
 0 \le \lambda e^{-\lambda} [\p(U_1 > x) - \p(V_1 > x)] + \sum_{k = 2}^{\oo} \p(N=k) \[\p\left(\sum_{i=1}^k U_i > x\right) - \p\left(\sum_{i=1}^k V_i > x\right)\],
\end{equation}
where  $N\sim {\rm Poi}(\lambda)$, $V_1,V_2,\dots\sim  H_{\overline \eta}$ and $U_1,U_2,\dots\sim  H_{\overline \theta}$ are mutually independent.
Assume now that $F$ is not in $\H$, i.e., there exist vectors $(\theta_1,\theta_2) \preceq (\eta_1,\eta_2)$ and a value $x$ such that
$$
\[\overline{F}\left(\frac{x}{\theta_1}\right) + \overline{F}\left(\frac{x}{\theta_2}\right)\] - \[\overline{F}\left(\frac{x}{\eta_1}\right) + \overline{F}\left(\frac{x}{\eta_2}\right)\] = - \varepsilon,
$$
where $\varepsilon \in \R_{++}$. Let us now turn our attention back to \eqref{eq:aux_6}. The second term on the RHS may be bounded by
$$
\left|\sum_{k=2}^\oo \p(N=k) \[\p\left(\sum_{i=1}^k U_i > x\right) - \p\left(\sum_{i=1}^k V_i > x\right)\]\right| \le \p(N\ge 2) \le \lambda^2,
$$
while the first term is
$$
\lambda e^{-\lambda} (\p(U_1 > x) - \p(V_1 > x))  = - \frac{1}{2} \varepsilon \lambda e^{-\lambda} \le -\frac{1}{2} \varepsilon \lambda(1-\lambda).
$$
We have from \eqref{eq:aux_6} that, for all $\lambda\in \R_{++}$,
$$
0 \le -\frac12\varepsilon \lambda(1-\lambda) +  \lambda^2,
$$
which is clearly false for sufficiently small values of $\lambda$. Therefore, we have a contradiction and the proof is complete.
\end{proof}


\begin{remark}
By Theorem \ref{thm:CP}, if $F\in \H$,  CP$(\lambda, F)$ satisfies \eqref{eq:SD} for any $\lambda\in \R_{++}$. As usual stochastic order is preserved under mixtures (see, e.g., Theorem 1.A.3 (d) of \cite{SS07}), if $F\in\H$, \eqref{eq:SD} holds for the compound mixed Poisson distribution CP$(\Lambda,F)$ where $\Lambda$ is a random variable.
\end{remark}

In the following, we give a sufficient and necessary condition for \eqref{eq:SD*} to hold for ${\rm CP}(\lambda,F)$.  As this result can be shown by a slight modification to the proof of Theorem \ref{thm:CP},   its proof is omitted.
\begin{theorem}
Let $\lambda\in \R_{++}$ and $F$ be a distribution function with $\essinf F=0$. Then ${\rm CP}(\lambda,F)$ satisfies  \eqref{eq:SD*} if and only if $F\in\H^*$.
\end{theorem}


\section{Stable distributions}\label{sec:4}


In this section, we present a discussion of \eqref{eq:SD} for stable random variables to complement the findings of \cite{ibragimov2005new}, who focused on the peakedness property of linear combinations of stable random variables. Denote by  $S_\alpha(\sigma,\beta,\mu)$  the stable distributions with stability parameter $\alpha \in (0,2]$, skewness parameter $\beta\in[-1,1]$, scale parameter $\sigma\in \R_{++}$, and shift parameter $\mu\in\R$. We say $S_\alpha(1,\beta,0)$ is a standard stable distribution.
The characteristic function of $ X\sim S_\alpha(\sigma,\beta,\mu)$ is given by,  for $x \in \R$,
\begin{equation*}
\E\big [\exp\{{\rm i} x X\}\big ] =\begin{cases}
\exp\left \{ {\rm i} \mu x-\sigma^\alpha |x|^\alpha \(1-{\rm i} \beta\sign(x)
\displaystyle  \tan \frac{\pi\alpha}{2}\)\right\}, & \mbox{if $\alpha\ne 1$},\\[8pt]
\exp\left\{{\rm i}\mu x-\sigma|x|\(1+{\rm i}\displaystyle\frac{2\beta}{\pi}\sign(x)\log|x|\)\right\},
&   \mbox{if $\alpha= 1$},
\end{cases}
\end{equation*}
where $\sign(\cdot) $ is the sign function. Stable random variables do not have finite mean if $\alpha\le 1$. Stable distributions with $\alpha\in(0,1)$ and $\beta=\pm1$ are one-sided, and the support  is $[\mu,\infty)$ for $\beta=1$ (resp.~$(-\infty,\mu]$ for $\beta=-1$). All other cases of stable distributions have both left and right tails. Stable distributions include normal distributions ($\alpha=2$), Cauchy distributions ($\alpha=1$ and $\beta=0$), Landau distributions ($\alpha=1$ and $\beta=1$), and L\'evy distributions ($\alpha=1/2$ and $\beta=1$).  
See \cite{No20} for more details on stable distributions.

For non-degenerate iid random variables $X_1,\dots,X_n$, stable distributions are the limiting distributions of $a_n(X_1+\dots+X_n)+b_n$ for some $a_n\in \R_{++}$ and $b_n\in\R$. If $\E(|X_1|^2)<\infty$, the limiting distribution is the normal distribution, otherwise the limiting distribution is the stable distribution with $\alpha<2$. By Proposition \ref{prop:trivial}, we have the following result.
\begin{proposition}
If $X_1,\dots,X_n$ are iid and satisfy \eqref{eq:SD} and  $a_n(X_1+\dots+X_n)+b_n\xrightarrow{d}Z$ for some stable random variable $Z$, where $a_n\in \R_{++}$ and $b_n\in\R$, then $Z$ satisfies \eqref{eq:SD}.
\end{proposition}

Indeed, one can use the nice properties of stable distributions to give the following results of \eqref{eq:SD} for stable distributions. We assume that the stable distributions in the following result are standard for simplicity, since usual stochastic order is preserved under location-scale transforms.
Theorem \ref{thm:stable} (ii) below has appeared in Theorem 1.2.4 of \cite{ibragimov2005new} in a different form; we provide a proof here for completeness.

\begin{theorem}\label{thm:stable}
The stable distribution $S_\alpha(1,\beta,0)$ satisfies \eqref{eq:SD} if and only if one of the following conditions holds.
\begin{enumerate}[{\rm (i)}]
\item $\alpha=1$ and $\beta\in \R_+$;
\item  $\alpha< 1$ and $\beta=1$.
\end{enumerate}
\end{theorem}
\begin{proof}
Let $X_1,\dots,X_n\sim S_\alpha(1,\beta,0)$ be independent and $(w_1,\dots,w_n)\in\R_+^n$ such that $\sum_{i=1}^nw_i=1$. We first show ``$\Longleftarrow$'' direction.  If $\alpha=1$, 
it is seen from (1.7) of \cite{No20} that
\begin{equation}\label{eq:stable1}
\sum^n_{i=1} w_i X_i \simeq_{\rm st} X_1-\frac{2\beta}{\pi}\sum_{i=1}^nw_i\log w_i.
\end{equation}
As $g(t) =-t\log(t)$ is concave in $t\in (0,1)$, $\sum_{i=1}^ng(t_i)$ is Schur-concave in $(t_1,\dots, t_n)\in \R_+^n$ \citep[see][Proposition 3.C.1]{MOA11}. Hence, we have (i). 

Similarly, to show (ii), we have from (1.7) of \cite{No20} that if $\alpha\neq 1$,
\begin{equation}\label{eq:stable2}
\sum^n_{i=1} w_i X_i \simeq_{\rm st} \(\sum_{i=1}^nw_i^\alpha\)^{1/\alpha}X_1.
\end{equation}
% Then
% \begin{align*}
% \P\(\sum^n_{i=1} b_i X_i >u\)= \P\(X_1 > \frac{u}{(\sum^n_{i=1} b_i^\alpha)^{1/\alpha}}\),\quad u>0.
% \end{align*}
If $\alpha< 1$ and $\beta=1$,  $X_1$ is positive almost surely and $\sum^n_{i=1} c_i^\alpha$ is Schur-concave in $(c_1, \dots, c_n) \in \R^n_+$. Thus, we have the desired result.

For the ``$\Longrightarrow$'' direction, we first note that if $S_\alpha(1,\beta,0)$ satisfies \eqref{eq:SD}, then $\alpha\le 1$; this is due to Proposition \ref{prop:trivial} (i).  By \eqref{eq:stable1}, if $\alpha=1$, we must have $\beta\in \R_+$. If $\alpha<1$, assume that $\beta<1$. Then for $u\le0$,  by \eqref{eq:stable2}, we have 
 \begin{align*}
 \P\(\sum^n_{i=1} w_i X_i \le u\)= \P\(X_1 \le  \frac{u}{(\sum^n_{i=1} w_i^\alpha)^{1/\alpha}}\).
 \end{align*}
 Thus $\P\(\sum^n_{i=1} w_i X_i \le u\)$ is Schur-concave in $(w_1,\dots,w_2)$ and we have a contradiction. Therefore, if $\alpha<1$,  $\beta=1$.
\end{proof}
Theorem \ref{thm:stable} (i) suggests that for a random variable to satisfy \eqref{eq:SD}, the random variable is not necessarily bounded from below, which is a key assumption of Theorem \ref{thm:main}; see also Remark \ref{rem:unbounded}.









