\section{Distributions in the class $\H$}\label{sec:SHex}

In this section, we show that many infinite-mean distributions are in $\H$. For a distribution function $F$, we use $f$ to denote its density and let $h(x)=x^2f(x)$, $x\in \R_+$.

\begin{example}[Pareto distribution]\label{ex:Pareto}
For $\alpha\in \R_{++}$, the Pareto distribution function is
$$F(x)=1-\frac{1}{(x+1)^\alpha},~~ x\in \R_{++}.$$
If $\alpha\le 1$, then $F$ has infinite mean.
Let $h(x)=\overline F(1/x)=(x/(x+1))^\alpha$, $x\in \R_+$.  Taking the second-order derivative of $h$, we have 
$$h''(x)=\frac{\alpha (\alpha-2x-1)}{x^{2-\alpha}(x+1)^{2+\alpha}}.$$ 
If $\alpha\le 1$, then $h''$ is concave.  Thus, by Proposition \ref{prop:Hcont}, we have $F\in \H$ if $\alpha\le 1$.
\end{example}

\begin{example}[Log-Pareto distribution]
The log-Pareto distribution (see p.~39 in \cite{A15}) has distribution function 
$$F(x)=1-\frac{1}{(\log(x+1)+1)^\alpha},~~x\in \R_{++}.$$ 
The derivative of $h$ is 
$$h'(x)=-\frac{\alpha x}{(x+1)^2 (\log(x+1)+1)^{\alpha+2}} \big[\alpha x-(x+2)\log(x+1)-2\big].$$
Let 
$$g(x)=\alpha x-(x+2)\log(x+1)-2,~~x\in \R_+.$$
By Proposition \ref{prop:Hcont}, we need $h'(x)\ge 0$, or equivalently, $g(x)\le 0$, such that  $F\in\H$. As $g(0)=0$, it is sufficient to chose $\alpha$ such that $g$ is decreasing. We have 
$$g'(x)=\alpha-\frac{x+2}{x+1}-\log(x+1).$$
Thus if $\alpha\le 2$, then $F\in\H$.
\end{example}

\begin{example}[Inverse Burr distribution]
The inverse Burr distribution is defined as 
\begin{equation*}
F(x)=\(\frac{x^\tau}{x^\tau+1}\)^\alpha,~~ x\in \R_{++},
\end{equation*}
where $\alpha,\tau\in \R_{++}$.  For $x\in \R_+$,
$$h'(x)=\alpha\tau x^{\alpha\tau}(x^\tau+1)^{-\alpha-2}(\alpha\tau-(\tau-1)x^\tau+1).$$ 
Hence, if $\tau\le 1$, then $h'(x) \geq 0$. By Proposition \ref{prop:Hcont}, we have $F\in \H$.

\end{example}



\begin{example}[Stoppa distribution]
For $\alpha, \beta\in \R_{++}$, a (location-shifted) Stoppa distribution can be defined as
\begin{equation*}
F(x)=\(1-\frac{1}{(x+1)^\alpha}\)^\beta, ~~x\in \R_{++}.
\end{equation*}
Since a Stoppa distribution is a power transform of a Pareto distribution,
by Proposition \ref{prop:Hproperty} (i), if $\alpha\le 1$, then $F\in\H$.  Power transforms have also been used to generalize Burr distributions (see p.~211 of \cite{KK03}).
\end{example}

\begin{example}[Log-Cauchy distribution]
The log-Cauchy distribution function is 
$$F(x)=\frac{1}{\pi}\arctan(\log(x))+\frac{1}{2},~~x\in \R_{++}.$$
We have
$$f(x)=\frac{1}{x^2\pi}\frac{x}{(\log (x))^2+1}.$$
As $x/(\log(x)^2+1)$ is increasing in $x$, then $F\in\H$ by Remark \ref{rem:RV}.
\end{example}




\section{Simulation of stable distributions}\label{sec:B}
We recall below the simulation procedure of standard stable distributions $S_\alpha(1,\beta,0)$ in  \cite{WR96}. 
\begin{itemize}
\item[(1)] Let two  random variables  $V \sim U(-\pi/2, \pi/2)$ and $W \sim {\rm Exp}(1)$ be independent.
\item[(2)] For $\alpha \neq 1$, let 
$$ 
X = M_{\alpha, \beta} \frac{\sin(\alpha(V-N_{\alpha, \beta}))}{(\cos(V))^{1/\alpha}}
\left(\frac{1}{W} \cos\Big (V-\alpha(V-N_{\alpha, \beta})\Big ) \right)^{(1-\alpha)/\alpha},
$$
where
$$
M_{\alpha, \beta} = \left[1 + \beta^2 \tan^2\left(\frac{\pi\alpha}{2}\right)\right]^{1/(2\alpha)}, \qquad  N_{\alpha, \beta} = - \frac{1}{\alpha} \arctan\left(\beta \tan \frac{\pi\alpha}{2}\right).
$$

\item[(3)] For $\alpha = 1$, let
$$  X = \frac{\pi}{2} \left[\left(\frac{\pi}{2}+\beta V\right) \tan(V)
- \beta \log \left(\frac{W\cos(V)}{\pi/2+\beta V}\right)\right].
$$
\end{itemize}
As $X \sim S_\alpha(1, \beta, 0)$, one can generate samples of $X$ by first generating samples of $V$ and $W$ and then plug in the samples to the above  stochastic representations of $X$.

}

