\title{\emph{ROS Help Desk}:
GenAI Powered, User‑Centric Framework for ROS Error Diagnosis and Debugging
\\\thanks{This work was funded by CSIRO’s Data61 Science Digital}
}

\author{\IEEEauthorblockN{Kavindie Katuwandeniya$^{\dagger}$}
\IEEEauthorblockA{\textit{CSIRO Robotics} \\
Clayton, Melbourne, Australia \\
kavi.katuwandeniya@csiro.au}
\and
\IEEEauthorblockN{Samith Rajapaksha Jayasekara Widhanapathirana $^{\dagger}$}
\IEEEauthorblockA{\textit{CSIRO Robotics} \\
