\begin{algorithm}[ht]
\caption{Point Cloud Alignment via Principal Component Analysis}
\label{alg:pca}
\begin{algorithmic}[1]
\REQUIRE Point cloud $\mathbf{X} \in \mathbb{R}^{|V| \times 3}$
\ENSURE Canonical projection $\mathbf{\tilde{X}}$

\STATE \graycomment{Compute the principal component vectors}
\STATE $\mathbf{P} \gets \text{PCA}(\mathbf{X})$ \graycomment{$\mathbf{P}$ is a $3 \times 3$ matrix}

\STATE \graycomment{Ensure right-handed coordinate system}
\IF{$\det(\mathbf{P}) < 0$}
    \STATE $\mathbf{P}_{3,:} \gets -\mathbf{P}_{3,:}$ 
\ENDIF

\STATE \graycomment{Project point cloud onto principal components}
\STATE $\mathbf{\tilde{X}} \gets \mathbf{X} \mathbf{P}^\top$

\STATE \graycomment{Normalize orientation to ensure consistent quadrant placement}
% \STATE 
\STATE $\mathbf{p_{ref}} \gets \mathbf{\tilde{X}}[\arg\max(\alpha(\mathbf{\tilde{X}})), :]$ \graycomment{$\alpha$ counts the non-zero for each row}
\STATE \graycomment{\{O\} and \{Z\} are sequence, $|\{O\}|+|\{Z\}| = 3$ }
\STATE $\{O\} = \{ o \mid \mathbf{p_{ref}}[o] = 0, o=1,2,3\}$ \graycomment{$o_i$ for elements in $\{O\}$}
\STATE $\{Z\} = \{ z \mid \mathbf{p_{ref}}[z] \neq 0, z=1,2,3 \}$ \graycomment{$z_i$ for elements in $\{Z\}$}

\STATE  $c\gets 0$ \graycomment{Count flip number}
\FOR{$z$ in $\{Z\}$}
\IF{$\mathbf{p_{ref}}[z] < 0$}
    \STATE $c \gets c+ 1$
\ENDIF
\ENDFOR


\STATE  \graycomment{Ensure right-handed}
\IF{$c \equiv 1 \mod 2$}
    \IF{$|\{Z\}| < 3$}
        \STATE $\mathbf{\tilde{X}}[:,o_1] \gets -\mathbf{\tilde{X}}[:,o_1]$ 
    \ELSE
            \STATE $\mathbf{\tilde{X}}[:,3] \gets -\mathbf{\tilde{X}}[:,3]$ 
    \ENDIF
\ENDIF


\RETURN $\mathbf{\tilde{X}}$
\end{algorithmic}
\end{algorithm}


\subsection{Model Architecture}

\subsubsection{3‑D Geometric Encoder}

The point cloud $\mathbf{X} \in \mathbb{R}^{n \times 3}$ contains the Cartesian coordinates of the $n$ atoms in a molecule.
Then we sample $k$ rotation matrices
${\mathbf{R}^{(j)}} \subset \mathrm{SO}(3), j = 1, \dots, k$ and generate rotated views:
\begin{equation}
\mathbf{X}^{(j)} = \mathbf{X} \mathbf{R}^{(j)\top},
\qquad j = 1, \dots, k .
\end{equation}
Optionally, atomic embedding information can be included by concatenating the rotated coordinates with atom-wise embeddings, i.e.,
$\mathcal{X}^{(j)}_0 = [\mathbf{X}^{(j)}\| \mathrm{Emb}(z)]$,
where $\|$ denotes concatenation and $\mathrm{Emb}(z)$ denotes the embedding of atoms.
In this case, the feature dimension becomes $l \geq 3$.

\paragraph{Point‑wise convolution.}
We apply $\tau$ successive $1{\times}1$ convolutions to $\mathcal{X}^{(j)}_0$ to extract local geometric features.
\begin{equation}
  \mathcal{X}^{(j)}_{\ell}=
  \sigma (\mathrm{BN}(
    \mathrm{Conv}(\mathcal{X}^{(j)}_{\ell-1}))
  ),
  \quad \ell=1,...,\tau
  \label{eq:pw_conv}
\end{equation}
where $\mathbf{W}^{(\ell)}$ are learnable parameters for layer~$\ell$,  BN is the batch Norm, 
and $\sigma(\cdot)$ is the  activation function.  

\paragraph{Global pooling.}
As the output should be invariant to the ordering of atoms within the list (permutation invariance), a pooling operation is employed to aggregate atomic features into a unified view fingerprint.
\begin{equation}
  \mathbf{p}^{(j)}=
  \mathrm{Pool}(\mathcal{X}^{(j)}_{\tau})
  \in\mathbb{R}^{d_{p}},
  \label{eq:view_fp}
\end{equation}
where $d_{p}$ is the fingerprint length.

\paragraph{Multi‑view fusion.}
Averaging over the $k$ views yields a rotation‑robust representation:
\begin{equation}
  \mathbf{p}=\frac{1}{k}\sum_{j=1}^{k}\mathbf{p}^{(j)}, 
  \label{eq:avg_views}
\end{equation}
which approximates an integral over $\mathrm{SO}(3)$.

\subsubsection{Feature Fusion and \texorpdfstring{$\ell_{1}$}{L1} Regularisation}\label{subsec:fusion}

The geometric vector $\mathbf{p}$ is concatenated with 
the global representation $\mathbf{g}$ to form
\begin{equation}
  \mathbf{u}=
  [\mathbf{g}\,\|\,\mathbf{p}]
  \in\mathbb{R}^{d_{u}} ,
  \label{eq:concat}
\end{equation}
where $d_{u}$ is the total feature dimension.

\subsubsection{Regression Head}

A multilayer perceptron  $\gamma$ maps $\mathbf{u}$ to predictions:
\begin{align}
  \hat{\mathbf{y}} &= \gamma(\mathbf{u}),
\end{align}


The training objective combines task loss and sparsity:
\begin{equation}
  \mathcal{L}=
  \mathcal{L}_y+\lambda\lVert\mathbf{u}\rVert_{1},
  \label{eq:loss_total}
\end{equation}
where $\mathcal{L}_y$ is the prediction loss,  
and $\lambda$ controls the strength of the $\ell_{1}$ penalty. 




