    \end{table}
It can be observed from Table \ref{tab:simple_cone_proj} that the projections onto $\zerobf^d$ and $\mbb R_{+}^{d}$ are trivial.
As for the second-order cone $\mcal K_{\soc}^{d+1}$, the most time-consuming computations can be reduced to a Euclidean norm computation (i.e., a vector-vector product). For the exponential cone $\mcal K_{\exp}$, the cost of projection onto this cone is almost constant because of its low dimensionality. The only expensive projection above is the projection onto the $\mbb S_{+}^{d\times d}$, which requires a singular value decomposition. This can be computationally prohibitive for large $d$. In addition to the five cone projections presented in Table~\ref{tab:simple_cone_proj}, the rotated second-order cone ($\mcal K_{\rsoc}^{d+2}$) and the dual exponential cone ($\mcal K_{\exp}^*$) can be projected onto pretty efficiently. Notably, the  $\mcal K_{\rsoc}^{d+2}$ is equivalent to the second-order cone via reformulation, and the projection onto the $\mcal K_{\exp}^*$ closely resembles that of the exponential cone. As a result, for most typical conic programs except the ones involving semi-definite cones, PDHG remains a fully matrix-free method, making it scalable for most large-scale conic program problems.






\section{\label{sec:Practical-enhancement-technique}
A Practical Primal-Dual Conic Programming Solver}


In this section, we present the algorithmic enhancements used in PDCS. Built upon the basic PDHG framework, PDCS integrates several techniques, including adaptive step-size selection (Section~\ref{sec:adaptive_stepsize}), adaptive reflected Halpern iteration (Section~\ref{sec:adaptive_reflection}), adaptive restart (Section~\ref{sec:adaptive_restart}), and primal weight updates (Section~\ref{sec:weight_adjustment}). The overall algorithmic framework is summarized in Algorithm~\ref{alg:PDCS}, with each enhancement described in detail in the following subsections. 
\begin{algorithm}[htbp]
\caption{Primal Dual Conic Programming Solver (PDCS) (without preconditioning)\label{alg:PDCS}}
    \begin{algorithmic}[1]
        \Require{$\zbf^{0,0}=(\xbf^{0,0},\ybf^{0,0})$, total iteration $\bar{k}\leftarrow 0$, step-size $\hat{\eta}^{0,0}\leftarrow1/\norm{\Gbf}_{\infty}$, primal weight $\omega^0\leftarrow \texttt{InitializePrimalWeight}(\cbf,\hbf)$ \quad (Section~\ref{sec:weight_adjustment}).}
    \While{Termination criteria do not hold}
    \State{$k\leftarrow 0$}
    \While{both \texttt{Restart condition} (Section~\ref{sec:adaptive_restart}) and the termination criteria do not hold}
        \State{$\hat{\zbf}^{t,k+1}, \eta^{t,k+1}, \hat{\eta}^{t,k+1},\bar{k} \leftarrow$ \texttt{AdaptiveStepPDHG}($\zbf^{t,k}, \omega^t, \hat{\eta}^{t,k},\bar{k}$)\label{alg_pdcs:line4} }\quad\quad\rtcomment{ Section~\ref{sec:adaptive_stepsize}}
        \State{$\beta^{t,k}\leftarrow$ \texttt{AdaptiveReflection}($\hat{\zbf}^{t,k+1}$)\label{alg_pdcs:line5}}\quad\quad \rtcomment{Section~\ref{sec:adaptive_reflection}}
        \State{${\zbf}^{t,k+1} =\frac{k+1}{k+2}((1+\beta^{t,k})\hat{\zbf}^{t,k}-\beta^{t,k}\zbf^{t,k})) + \frac{1}{k+2}\zbf^{t,0}$}\label{alg:line:ref_Halpern}
        \State{$\bar{\zbf}^{t,k+1}\leftarrow \frac{1}{\sum_{i=1}^{k+1}\eta^{t,i}}\sum_{i=1}^{k+1}\eta^{t,i}\zbf^{t,i}$\label{alg:line:average}}
        \State{$\zbf_{c}^{t,k+1}\leftarrow\texttt{GetRestartCandidate}(\zbf^{t,k+1},\bar{\zbf}^{t,k+1})$}\quad\quad \rtcomment{Section~\ref{sec:adaptive_restart}\label{alg:line:GetRestartCandidate}}
        \State{$k\leftarrow k+1$}
    \EndWhile
    \State{Restart $\zbf^{t+1,0}\leftarrow \zbf_{c}^{t,k}$,  $t\leftarrow t+1$}
    \State{$\omega^t\leftarrow \texttt{PrimalWeightUpdate}(\zbf^{t,0}, \zbf^{t-1,0},\omega^{t-1})$}\quad\quad \rtcomment{Section~\ref{sec:weight_adjustment}}
\EndWhile 
    \end{algorithmic}
\end{algorithm} 
In addition, PDCS also applies diagonal preconditioning to improve the conditioning of problem instances. This preconditioning procedure is described in Section~\ref{subsec:Projection-onto-convex}. 

To briefly summarize the main components in Algorithm~\ref{alg:PDCS}: the function \texttt{AdaptiveStepPDHG} in Line~\ref{alg_pdcs:line4} performs a line search to determine an appropriate step size; the function \texttt{AdaptiveReflection} in Line~\ref{alg_pdcs:line5} computes the reflection coefficient; Lines~\ref{alg:line:ref_Halpern} and~\ref{alg:line:average} perform a reflected Halpern iteration and weighted averaging of iterates; and the function \texttt{GetRestartCandidate} in Line~\ref{alg:line:GetRestartCandidate} selects a candidate for restarting based on either the normalized duality gap or KKT error. At each outer iteration, the primal weight $\omega$ is updated based on the progress of primal and dual iterates, and this weight plays a central role in balancing the primal and dual step sizes via the function \texttt{AdaptiveStepPDHG}.


\subsection{\label{sec:adaptive_stepsize}Adaptive step-size} 


To ensure global convergence in theory, the step-sizes $\tau$ and $\sigma$ must satisfy the condition $\tau\sigma \le \frac{1}{\|G\|}$ \cite{chambolle2011first}. However, this requirement is often overly conservative in practice. To improve empirical performance, PDCS employs a line search heuristic similar to the one used in PDLP \cite{applegate2021practical}, allowing it to adaptively choose step-sizes. Specifically, PDCS selects the parameters as follows:
\begin{equation}\label{eq:adaptive_step_size}
\tau = \frac{\eta}{\omega},\quad \sigma = \eta \omega,\quad \eta \leq \frac{\norm{\zbf^{t+1}-\zbf^t}_{\omega}^2}{2\abs{(\ybf^{t+1}-\ybf^t)^\top \Gbf (\xbf^{t+1}-\xbf^t)}},
\end{equation}
where $\norm{\zbf}_{\omega} := \sqrt{\omega\norm{\xbf}^2 + \frac{\norm{\ybf}^2}{\omega}}$, and $\omega$ is the primal weight. 


The update of $\eta$ is carried out by the procedure described in Function~\ref{alg:adaptive_pdhg}. Here, $\bar{k}$ records the total number of PDHG iterations and controls how aggressively $\eta$ is adjusted. Compared to PDLP, which uses the inner-loop count $k$ to control the adjustment rate, PDCS uses $\bar{k}$, resulting in more conservative updates in early iterations \cite{applegate2021practical}. 

{\renewcommand{\algorithmname}{Function}
% \setcounter{algorithm}{0}
% \renewcommand{\thealgorithm}{}
\begin{algorithm}[h]
\caption{AdaptiveStepPDHG(($\xbf$,$\ybf$), $\omega$, $\eta$, $\bar{k}$)\label{alg:adaptive_pdhg}}
    \begin{algorithmic}[1]
    % \State{\textbf{Function} Adaptive Step PDHG(($\xbf$,$\ybf$), $\omega$, $\eta$, $\bar{k}$}
    % \Procedure{Adaptive Step PDHG}{($\xbf$,$\ybf$), $\omega$, $\eta$, $\bar{k}$}
    \While{True}
    \State{$\hat{\xbf} = \proj_{[\lbf,\ubf] \times \mcal K_{\textrm{p}}}\bcbra{\xbf - \frac{\eta}{\omega}(\cbf-\Gbf^\top \ybf)}$\label{alg_adaptive_pdhg_line2}}
    \State{$\hat{\ybf}=\proj_{\mcal K_{\textrm{d}}}\bcbra{\ybf + \eta \omega(\hbf-\Gbf(2\hat{\xbf}-\xbf))}$\label{alg_adaptive_pdhg_line3}}
    % \State{\Return $\zbf=(\hat{\xbf},\hat{\ybf})$}
    \State{$\bar{\eta}\leftarrow \frac{1}{2}{\norm{(\hat{\xbf}-\xbf,\hat{\ybf}-\ybf)}_{\omega}^2}/{\abs{(\hat{\ybf}-\ybf)^\top \Gbf (\hat{\xbf}-\xbf)}}$}
    \State{$\eta^{\prime}\leftarrow \min\bcbra{(1-(\bar{k}+1)^{-0.3})\bar{\eta}, (1+(\bar{k}+1)^{-0.6})\eta}$}
    \If{$\eta<\bar{\eta}$}
    \State{\Return{$(\hat{\xbf},\hat{\ybf}),\eta,\eta^{\prime},\bar{k}$}}
    \EndIf
    \State{$\eta\leftarrow \eta^{\prime},\bar{k}\leftarrow\bar{k}+1$}
    \EndWhile
    % \EndProcedure
    \end{algorithmic}
\end{algorithm}
% \setcounter{algorithm}{1}
}




\subsection{\label{sec:adaptive_reflection}Adaptive reflected Halpern iteration}  

Line~\ref{alg:line:ref_Halpern} in Algorithm~\ref{alg:PDCS} implements a reflected Halpern iteration. A similar technique has been used in practical first-order LP solvers such as HPR-LP~\cite{chen2024hpr} and r$^2$HPDHG~\cite{lu2024restarted}, where it has demonstrated significant empirical acceleration. The standard Halpern iteration involves averaging the current iterate (typically $\hat{\zbf}^{t,k}$) with the initial point $\zbf^{t,0}$ of the current inner loop. This anchoring mechanism mitigates oscillations in PDHG iterates and has been shown to yield improved worst-case convergence rates. In this setting, the point $\zbf^{t,0}$ serves as a fixed anchor. Originally introduced by \cite{halpern1967fixed}, Halpern iteration has recently been recognized again for its role in accelerating a range of minimax optimization and fixed-point methods; see, e.g., \cite{yoon2025accelerated}.


The idea behind the reflected Halpern iteration is to apply this anchoring technique not directly to $\hat{\zbf}^{t,k}$, but to an extrapolated point between the newly computed iterate $\hat{\zbf}^{t,k}$ and the previous iterate ${\zbf}^{t,k}$. Specifically, Line~\ref{alg:line:ref_Halpern} replaces $\hat{\zbf}^{t,k}$ with $(1 + \beta^{t,k})\hat{\zbf}^{t,k} - \beta^{t,k}\zbf^{t,k}$, where $\beta$ is the reflection parameter. It has been theoretically shown that the reflected Halpern iteration can further accelerate convergence in general fixed-point methods, including PDHG, see \cite{ryu2016primer,lieder2021convergence,lu2024restarted}. 

In practice, larger values of $\beta$ correspond to more aggressive extrapolation, which can accelerate convergence but may also introduce instability and oscillations if set too high. To balance acceleration with stability, PDCS adaptively adjusts the reflection coefficient based on the observed progress of iterates. When the KKT error is large, indicating that the iterate is still far from optimality, a smaller coefficient is selected to promote conservative and stable updates. As the iterates begin to converge and the KKT error decreases, a larger coefficient is used to speed up progress. For conic programs, PDCS uses the following rule to select the reflection parameter based on the KKT error at $\hat{\zbf}^{t,k} = (\hat{\xbf}^{t,k}, \hat{\ybf}^{t,k})$:

\begin{equation}\label{eq:adaptive_reflection}
    \texttt{AdaptiveReflection}(\hat{\zbf}^{t,k})=\proj_{[0,1]}\left(-0.1\cdot\log_{10}\left(\text{maxErr}(\hat{\zbf}^{t,k})\right)+0.2\right) \ ,
\end{equation}
where $\text{maxErr}(\cdot)$ measures the overall optimality error and is defined by
\begin{equation}\label{eq:tolerance} 
\text{maxErr}(\zbf):=\max\{\err_{\textrm{rel,p}}(\xbf),\err_{\textrm{rel,d}}(\bm{\lambda}_1,\bm{\lambda}_2),\err_{\textrm{rel,gap}}(\xbf,\bm{\lambda}_1,\bm{\lambda}_2)\} \ .
\end{equation}
Here $\err_{\textrm{rel,p}}(\xbf),\err_{\textrm{rel,d}}(\bm{\lambda}_1,\bm{\lambda}_2),\err_{\textrm{rel,gap}}(\xbf,\bm{\lambda}_1,\bm{\lambda}_2)$ are relative primal infeasibility, relative dual infeasibility and relative primal-dual gap: 
\begin{equation}\label{eq:tolerance-2}
\begin{aligned}
& \err_{\textrm{rel,p}}(\xbf) : =\tfrac{\err_{\textrm{abs,p}}(\xbf)}{1+\norm{\hbf}_{1}} \ , \ \ 
\err_{\textrm{rel,d}}(\bm{\lambda}_{1},\bm{\lambda}_{2}) :=\tfrac{\err_{\textrm{abs,d}}(\bm{\lambda}_{1},\bm{\lambda}_{2})}{1+\norm{\cbf}_{1}} \  , \\
& \err_{\textrm{rel,gap}}(\xbf,\bm{\lambda}_{1},\bm{\lambda}_{2}) : =\tfrac{\err_{\textrm{abs,gap}}(\xbf,\bm{\lambda}_{1},\bm{\lambda}_{2})}{1+\abs{\inner{\cbf}{\xbf}}+\abs{\ybf^{\top}\hbf+\lbf^{\top}\bm{\lambda}_{1}^{+}+\ubf^{\top}\bm{\lambda}_{1}^{-}}} \ .
\end{aligned}
\end{equation}
The absolute errors in the numerators are defined in \eqref{eq:tolerance-3}. We adopt these relative errors because they are invariant under scalar rescaling of problem data and demonstrate more stable empirical performance in our experiments.




\subsection{\label{sec:adaptive_restart}Adaptive restart} 


The restart technique resets the anchor point used in the Halpern iteration to a carefully selected point and simultaneously updates the primal weight $\omega^t$ (see Section~\ref{sec:weight_adjustment}). It has been proven that PDHG with restarts (either average-iterate restarts or Halpern restarts) achieves linear convergence for LP problems~\cite{applegate2023faster,lu2024restarted}. For general conic programs, \cite{xiong2024role} establishes global convergence of PDHG with average-iterate restarts, and similar results may be extended to Halpern-iteration restarts using the techniques in~\cite{lu2024restarted}. Empirical studies have also shown that restart strategies can significantly improve the practical performance of PDHG~\cite{applegate2021practical,applegate2023faster}.

To select the new anchor point, PDCS evaluates the normalized duality gap, which serves as a surrogate for optimality. This metric is defined as follows:
\begin{definition}[normalized duality gap~\cite{xiong2024role}]\label{defn:normalized_dual_gap}
   For any $\zbf = (\xbf, \ybf) \in \mcal X \times \mcal Y$, $r > 0$, and step-sizes $\tau > 0$, $\sigma > 0$ satisfying $\tau\sigma \leq \brbra{\sigma_{\max}(\Gbf)}^{-2}$, define $\Mbf:=\bigg(\begin{smallmatrix}
\frac{1}{\tau}\Ibf & -\Gbf^{\top}\\
-\Gbf & \frac{1}{\sigma}\Ibf
\end{smallmatrix}\bigg)$ and $\mcal{B} (r;\zbf):=\bcbra{\hat{\zbf}:=(\hat{\xbf},\hat{\ybf}):\hat{\xbf}\in \mcal X, \hat{\ybf}\in \mcal Y,\norm{\zbf-\hat{\zbf}}_{\Mbf}\leq r}$, then the normalized duality gap is given by $
\rho(r;\zbf):=\frac{1}{r}\sup_{\hat{\zbf}\in \mcal B(r;\zbf)}[\mcal L(\xbf,\hat{\ybf})-\mcal L(\hat{\xbf},\ybf)].$
\end{definition}

The $\tau$ and $\sigma$ above correspond to the current step sizes $\tau^{t,k}$ and $\sigma^{t,k}$. 
\cite{applegate2023faster,xiong2024role} show that the above normalized duality gap $\rho(r;\zbf)$ serves as a measurement of the optimality of solution $\zbf$. However, computing $\rho(r;\zbf)$  exactly involves a nontrivial projection onto $\mcal X \times \mcal Y$ under the $\Mbf$-norm, which is computationally expensive. To alleviate this, we approximate the duality gap by replacing $\Mbf$ with a diagonal surrogate matrix $\Nbf := \begin{pmatrix}
    \frac{1}{\tau}\Ibf &  \\
    & \frac{1}{\sigma}\Ibf
\end{pmatrix}$ and denote the resulting approximate gap as $\rho^{\Nbf}(\cdot,\cdot)$. This approximation $\rho^{\Nbf}(\cdot,\cdot)$ is equivalent to $\rho(\cdot,\cdot)$ under a constant factor and can be efficiently computed using a bisection search method \cite{applegate2023faster,xiong2024role}.
The details of the computation method are deferred to Appendix~\ref{app:normalized_duality_gap}.




    In PDCS, we compare the approximate normalized duality gaps of $\zbf^{t,k+1}$ and $\bar{z}^{t,k+1}$, and  select the one with the smaller gap as the new anchor point:
    \begin{equation*}
    \begin{aligned}
        & \texttt{GetRestartCandidate}(\zbf^{t,k+1},\bar{\zbf}^{t,k+1})
        \\
        & \quad \quad =\begin{cases}
    \zbf^{t,k+1} & \rho^{\Nbf}\brbra{\norm{\zbf^{t,k+1}-\zbf^{t,0}}_{\Nbf};\zbf^{t,k+1}}\leq\rho^{\Nbf}\brbra{\norm{\bar{\zbf}^{t,k+1}-\zbf^{t,0}}_{\Nbf};\bar{\zbf}^{t,k+1}}\\
    \bar{\zbf}^{t,k+1} & \text{otherwise}\ .
    \end{cases}
    \end{aligned}
    \end{equation*}
Let $\zbf_{c}^{t,k+1}$ denote the resulting restart candidate. A restart to $\zbf_{c}^{t,k+1}$ is triggered whenever its approximate normalized duality gap satisfies any of the following conditions. Let $\beta_{\text{sufficient}} = 0.4$, $\beta_{\text{necessary}} = 0.8$, and $\beta_{\text{artificial}} = 0.223$, and define the \texttt{Restart Condition} to hold if one of the following is true:

\begin{enumerate}
    \item (Sufficient decay) $\rho^{\Nbf}\Brbra{\norm{\zbf_{c}^{t,k+1}-\zbf^{t,0}}_{\Nbf};\zbf_{c}^{t,k+1}}\leq\beta_\text{sufficient} \cdot \rho^{\Nbf}\brbra{\norm{\zbf^{t,0}-\zbf^{t-1,0}}_{\Nbf};\zbf^{t,0}}$
    \item (Necessary decay + no local progress) $\rho^{\Nbf}\left(\norm{\zbf_{c}^{t,k+1}-\zbf^{t,0}}_{\Nbf};\zbf_{c}^{t,k+1}\right)>\rho^{\Nbf}\Brbra{\norm{\zbf_{c}^{t,k}-\zbf^{t,0}}_{\Nbf};\zbf_{c}^{t,k}}$
    and $\rho^{\Nbf}\Brbra{\norm{\zbf_{c}^{t,k+1} -\zbf^{t,0}}_{\Nbf};\zbf_{c}^{t,k+1}}\leq\beta_{\text{necessary}} \cdot \rho^{\Nbf}\brbra{\norm{\zbf^{t,0}-\zbf^{t-1,0}}_{\Nbf};\zbf^{t,0}}$
    \item (Long inner loop) $k \geq\beta_{\text{artifical}} \cdot \bar{k}$.
\end{enumerate}
A similar adaptive restart approach has also been used in first-order LP solvers PDLP \cite{applegate2021practical}, cuPDLP \cite{lu2023cupdlp} and cuPDLP-c \cite{lu2023cupdlp-c}.


However, for general conic programs, numerical issues are more severe, particularly when evaluating $\rho^{\Nbf}$ for cones beyond LP cones. In some cases, especially when the actual gap value is very small, the bisection method may produce negative outputs due to floating-point inaccuracies. When this occurs, PDCS switches to an alternative criterion based on the weighted KKT error. 
\begin{equation}
    \text{KKT}_{\omega}(\zbf)=\sqrt{\omega^{2}\err_{\textrm{abs,p}}(\xbf)^{2}+\frac{1}{\omega^{2}}\err_{\text{\textrm{abs,d}}}(\bm{\lambda}_{1},\bm{\lambda}_{2})^{2}+\err_{\text{\textrm{abs,gap}}}(\xbf,\bm{\lambda}_{1},\bm{\lambda}_{2})^{2}}\ ,
    \end{equation}
where $\err_{\textrm{abs,p}}, \err_{\textrm{abs,d}}, \err_{\textrm{abs,gap}}$ are as defined in~\eqref{eq:tolerance}, and the dual variables $\bm{\lambda}_1, \bm{\lambda}_2$ are recovered from $\ybf$ using the linear relation in~\eqref{eq:dual_conic}. When numerical issues happen, all instances of $\rho^{\Nbf}(r; \zbf)$ in both \texttt{GetRestartCandidate} and \texttt{RestartCondition} are replaced with $\text{KKT}_{\omega}(\zbf)$.



\subsection{\label{sec:weight_adjustment}Primal weight adjustment}



As shown in Function~\ref{alg:adaptive_pdhg}, the primal weight is used to balance the primal and dual step-sizes. A larger primal weight leads to a smaller primal step-size $\tau$ and a larger dual step-size $\sigma$. The update strategy follows a similar approach to that used in PDLP~\cite{applegate2021practical}, relying on the relative changes in the primal and dual variables. In PDCS, the primal weight is updated only at the beginning of each new restart. The primal weight is initialized using:
$\texttt{InitializePrimalWeight}(\cbf,\hbf):=\begin{cases}
\frac{\norm \cbf_{2}}{\norm \hbf_{2}}, & \norm \cbf_{2},\norm \hbf_{2}>10^{-10}\\
1 & \text{otherwise}
\end{cases}$. 
The update at the beginning of a new restart is defined as:
\begin{equation*}
    \texttt{PrimalWeightUpdate}(\zbf^{t,0},\zbf^{t-1,0},\omega^{t-1}):=\begin{cases}
\exp\Brbra{\theta\log\brbra{\frac{\Delta_{y}^{t}}{\Delta_{x}^{t}}}+\brbra{1-\theta}\log\brbra{\omega^{t-1}}} & \Delta_{x}^{t},\Delta_{y}^{t}>10^{-10}\\
\omega^{t-1} & \text{otherwise}\ ,
\end{cases}
\end{equation*} 
where $\Delta_{x}^{t}=\norm{\xbf^{t,0}-\xbf^{t-1,0}}$ and $\Delta_{y}^{t}=\norm{\ybf^{t,0}-\ybf^{t-1,0}}$ denote the changes in the primal and dual variables, respectively. In practice, we set $\theta = 0.5$.
Occasionally, we observe that the solver can become unstable when the primal weight grows too large or too small, causing imbalanced updates between the primal and dual iterates. To mitigate this, if $\omega > 10^5$ or $\omega < 10^{-5}$, we reset $\omega$ to its initial value computed by \texttt{InitializePrimalWeight}.


\subsection{\label{subsec:Projection-onto-convex}Diagonal rescaling and projections onto rescaled cones}


Like many other first-order methods, the practical performance of PDCS is closely tied to the conditioning of the problem instance. One common strategy is diagonal rescaling, which may improve the condition number of the problem while preserving the sparsity pattern. This technique has become a standard step in many first-order solvers for LPs, including PDLP~\cite{applegate2021practical}, cuPDLP~\cite{lu2023cupdlp}, and ABIP~\cite{deng2024enhanced}. 



We rescale the constraint matrix $\Gbf \in \mbb{R}^{m \times n}$ to $\hat{\Gbf} = \Dbf_1 \Gbf \Dbf_2$, where $\Dbf_1$ and $\Dbf_2$ are positive diagonal matrices. The corresponding rescaled optimization problem is:
\begin{equation}\label{eq:rescaled_prob}
\min\ \   \inner{\hat{\cbf}}{\tilde{\xbf}} \ , \quad  
\st\ \   \hat{\mathbf{G}}\tilde{\xbf}-\hat{\mathbf{h}}\in\hat{\mathcal{K}}_{\textrm{d}}^{*} \ , \ \  \hat{\lbf}\leq(\tilde{\xbf})_{[n_{1}]}\leq\hat{\ubf} \ , \ \ (\tilde{\xbf})_{[n]\backslash[n_{1}]}\in\hat{\mathcal {K}}_{\textrm{p}} 
\end{equation}
where the transformed data and cones are defined as: $\hat{\cbf}:=\cbf\Dbf_2,\hat{\Gbf}:=\Dbf_1\Gbf\Dbf_2,\hat{\hbf}:=\Dbf_1\hbf,\hat{\lbf}:=\Dbf_2^{-1}\lbf$, $\hat{\ubf}:=\Dbf_2^{-1}\ubf$, $\hat{\mcal K}_{\textrm{d}}^*:=\Dbf_1 \mcal K_{d}^*$ and $\hat{\mcal K}_{\textrm{p}}:=\Dbf_2^{-1}\mcal K_{\textrm{p}}$. 
For any optimal solution $\tilde{\xbf}$ of the rescaled problem~\eqref{eq:rescaled_prob}, an optimal solution of the original problem~\eqref{eq:prob_cp} can be recovered as $\xbf = \Dbf_2 \tilde{\xbf}$. Following the practice of PDLP, we perform several initial iterations of Ruiz rescaling~\cite{ruiz2001scaling}, followed by one iteration of Pock-Chambolle rescaling~\cite{chambolle2011first}.


The full PDCS framework with diagonal rescaling is summarized in Algorithm~\ref{alg:PDCS_after_precondition}.
\begin{algorithm}[h]
\caption{Primal Dual Conic Solver (PDCS) (with preconditioning)\label{alg:PDCS_after_precondition}}
    \begin{algorithmic}[1]
    \State{Compute rescaled instance data $\hat{\cbf},\hat{\Gbf},\hat{\hbf},\hat{\lbf}$ and $\hat{\ubf}$.}
    \State{Use Algorithm~\ref{alg:PDCS} to solve the rescaled problem~\eqref{eq:rescaled_prob} and get solution $\tilde{\xbf}$ and $\tilde{\ybf}$.}
    \State{Output solution for \eqref{eq:prob_cp}: $\xbf=\Dbf_2\tilde{\xbf}$ and $\ybf=\Dbf_1 \tilde{\ybf}$.}
    \end{algorithmic}
\end{algorithm}

This rescaling reformulates the problem in terms of non-standard cones $\hat{\mcal K}_{\textrm{p}}$ and $\hat{\mcal K}_{\textrm{d}}^*$. For LPs, the rescaled nonnegative cones remain nonnegative cones, so projections remain straightforward. However, in general conic programs, diagonal rescaling introduces new challenges.
Specifically, after rescaling, projections onto second-order cones no longer admit closed-form solutions, and projections onto exponential cones require more intricate calculations.  


\paragraph{Projection onto rescaled second-order cones.} After introducing the diagonal rescaling $\Dbf = \left(\begin{smallmatrix}
    {\dbf}_{1}\\
     & \ddots\\
     &  & {\dbf}_{n+1}
    \end{smallmatrix}\right)$, the projection onto the second-order cone is equivalent to solving the following optimization problem: 
\begin{equation}\label{eq:proj_diagonal_rescaling}
\begin{split}\proj_{\Dbf \mcal K_{\soc}}\bcbra{(t,\xbf)}=\argmin_{(s,\ybf)\in \mbb R^{n+1}}\frac{1}{2}\norm{(t,\xbf)-(s,\ybf)}^{2},\ \ \st\norm{\hat{\Dbf}^{-1}\ybf}^2\leq s^2, \ s\ge 0\ ,
\end{split}
\end{equation}
where $(t,\xbf)\in \mbb R^{n+1}$, and $\hat{\Dbf} = \left(\begin{smallmatrix}
\hat{\dbf}_{2}\\
 & \ddots\\
 &  & \hat{\dbf}_{n+1}
\end{smallmatrix}\right)$ with $\hat{\dbf}_i=\dbf_i / \dbf_1$, and $\dbf_i$ denotes the $i$-th entry in the diagonal of $\Dbf$.

Although general nondiagonal rescaling could yield the projection much more costly \cite{belloni2008second}, for diagonal rescaling considered in our case, the following theorem shows that this projection can be computed by solving an equivalent root-finding problem.
\begin{theorem}\label{thm:soc_proj}
The projection of $(t,\xbf)$ onto rescaled cone $\Dbf\mcal K_{\soc}^{n+1}$ is given as follows.

1. If $t \le 0$ and $\|\hat{\Dbf}\xbf\| \le -t$, the projection $\proj_{\Dbf \mcal K_{\soc}^{n+1}}\bcbra{(t,\xbf)} = (0,\zerobf)$.

2. If $\norm{\hat{\Dbf}^{-1}\xbf}\leq t$, then $\proj_{\Dbf \mcal K_{\soc}^{n+1}}\bcbra{(t,\xbf)}=(t,\xbf)$. 

3. If $t = 0$ and $\xbf \neq \zerobf$, then $\proj_{\Dbf \mcal K_{\soc}^{n+1}}\bcbra{(t,\xbf)} = \left(\|(\hat{\Dbf} + \hat{\Dbf}^{-1})^{-1}\xbf\|, (\Ibf_{n\times n} + \hat{\Dbf}^{-2})^{-1}\xbf \right)$.

4. Otherwise, if $\norm{\hat{\Dbf}^{-1}\xbf}> t$, then let $\lambda > 0$ be the solution of the following system of $\lambda$: 
\begin{equation*}
\sum_{i=2}^{n+1}\Brbra{\frac{\hat{\dbf}_{i}^{-1}}{1+2\lambda\hat{\dbf}_{i}^{-2}}}^{2}\xbf_{i}^{2}-\frac{t^{2}}{(1-2\lambda)^{2}}=0\ ,\ \ \frac{t}{(1-2\lambda)}>0\ .
\end{equation*}
Then the projection is given by $\proj_{\Dbf \mcal K_{\soc}^{n+1}}\bcbra{(t,\xbf)}=\brbra{(1-2\lambda)^{-1}t,(\Ibf+2\lambda\hat{\Dbf}^{-2})^{-1}\xbf}$.
\end{theorem}
In the PDCS implementation, the fourth case is handled using a root-finding routine based on a bijection method. 

 \begin{proof}[Proof of Theorem~\ref{thm:soc_proj}]
First of all, we consider the simplest case of 
$(s,\ybf)$---when it is the degenerate solution $(0,\zerobf)$. It should be noted that the projection onto a convex cone $\hat{\Dbf} \mcal K_{\soc}^{n+1}$ is $(0, \zerobf)$ if and only if $-(t,\xbf)$ lies in the dual cone of $\hat{\Dbf} \mcal K_{\soc}^{n+1}$. Because $(\hat{\Dbf} \mcal K_{\soc}^{n+1})^* = \hat{\Dbf}^{-1} (\mcal K_{\soc}^{n+1})^* = \hat{\Dbf}^{-1} (\mcal K_{\soc}^{n+1})^*$, it implies that when $\|\hat{\Dbf}\xbf\| \le -t$, the projection $(s,\ybf)$ is $(0,\zerobf)$. This proves the first case.



Now we introduce the multipliers $\lambda\ge0$ and $\mu\ge0$ for the two constraints of  \eqref{eq:proj_diagonal_rescaling}, then the Lagrangian is $\mathcal L(\ybf,s;\lambda,\mu)
=\tfrac12\|\ybf - \xbf\|^2 + \tfrac12(s - t)^2
+\lambda\bigl(\|\,\hat \Dbf^{-1}\ybf\|^2 - s^2\bigr)
+\mu\,( -s )$. Thus, the KKT condition of \eqref{eq:proj_diagonal_rescaling} is as follows:
\begin{align}
& \|\hat{\Dbf}^{-1}\ybf\|^2 - s^2 \le 0, \quad s \ge 0, \quad \lambda \ge 0, \quad \mu \ge 0 \label{eq:kkt_socp_1} \\
& \ybf - \xbf + 2\lambda \hat{\Dbf}^{-2} \ybf = 0, \quad (s - t) - 2\lambda s - \mu = 0 \label{eq:kkt_socp_2} \\
& \lambda \left( \|\hat{\Dbf}^{-1}\ybf\|^2 - s^2 \right) = 0, \quad \mu s = 0 \label{eq:kkt_socp_3}
\end{align}
It should be noted that Slater's condition holds for \eqref{eq:proj_diagonal_rescaling} as there exist strictly feasible solutions, any nonzero $(s,\ybf)$ satisfying \eqref{eq:kkt_socp_1},\eqref{eq:kkt_socp_2} and \eqref{eq:kkt_socp_3} is an optimal solution pair for \eqref{eq:proj_diagonal_rescaling}.

Let us start from the simplest case. If $(t,\xbf)$ is already in the rescaled cone, i.e., $\|\hat{\Dbf}^{-1}\xbf\|^2 \le t^2 $, then $(s,\ybf) = (t,\xbf)$ is an optimal solution for  \eqref{eq:proj_diagonal_rescaling} because it is feasible and has the smallest possible objective value $0$. This proves the second case.

Now we consider the other case $\|\hat{\Dbf}^{-1}\xbf\|^2 > t^2 $. Since $(t,\xbf)$ is not in the rescaled cone, the projected solution $(s,\ybf)$ must lie in the boundary of the cone. In other words, $\|\hat{\Dbf}^{-1}\ybf\| = s$. If $t = 0$, then the optimality conditions \eqref{eq:kkt_socp_1},\eqref{eq:kkt_socp_2} and \eqref{eq:kkt_socp_3} become 
\begin{equation}\label{eq:kkt_sys_fixed_1} 
(\ybf-\xbf)+2\lambda\hat{\Dbf}^{-2}\ybf=0\ , \ 
s-2\lambda s=\mu\ , \ 
s\mu = 0 \ , \
\norm{\hat{\Dbf}^{-1}\ybf}^{2}=s^{2}, \ 
s \ge 0\  , \ 
\lambda \ge 0\ , \  
\mu \ge 0 \ .
\end{equation}
One can observe that in this case
\begin{equation}\label{eq:kkt_sys_fixed_1_0} 
\ybf = (\Ibf_{n\times n} + \hat{\Dbf}^{-2})^{-1}\xbf\ ,\  s = \left\|(\hat{\Dbf} + \hat{\Dbf}^{-1})^{-1}\xbf\right\| \ ,\  \lambda = \frac{1}{2}\ ,\  \mu = 0 
\end{equation}
satisfy the above system. Therefore, when $t = 0$ and $\left\|\hat{\Dbf}^{-1}\xbf\right\| > 0$, \eqref{eq:kkt_sys_fixed_1_0}  gives the solution $s$ and $\ybf$ for \eqref{eq:proj_diagonal_rescaling}. This proves the third case.

If $t > 0$, let $\mu = 0$ and then the optimality conditions \eqref{eq:kkt_socp_1},\eqref{eq:kkt_socp_2} and \eqref{eq:kkt_socp_3} become 
\begin{equation}\label{eq:kkt_sys_fixed_2} 
(\ybf-\xbf)+2\lambda\hat{\Dbf}^{-2}\ybf=0\ , \ 
(1-2\lambda) s=t\ , \ 
\norm{\hat{\Dbf}^{-1}\ybf}^{2}=s^{2}\ , \ 
s \ge 0 , \ 
\lambda \ge 0 \ .
\end{equation}
If there exist $\ybf, \ s$ and $\lambda \in (0, \frac{1}{2})$ satisfying \eqref{eq:kkt_sys_fixed_2}, then $\ybf$ and $s$ can be computed by the first and second equations:
\begin{equation}\label{eq:kkt_sys_fixed_2_0} 
\ybf=(\Ibf+2\lambda\hat{\Dbf}^{-2})^{-1}\xbf \ ,\quad
s=(1-2\lambda)^{-1}t\geq0\\
\end{equation}
Substituting them into the third equation yields:
\begin{equation}\label{eq:kkt_sys_fixed_3} 
\underbrace{ \|(\hat{\Dbf}+2\lambda\hat{\Dbf}^{-1})^{-1}\xbf\|^2  -(1-2\lambda)^{-2}t^{2}}_{\text{Denoeted by $f(\lambda)$}} = 0\ .
\end{equation} 
Note that there must exist a root $\lambda \in (0,\frac{1}{2})$ of the above equation $f(\lambda) = 0$ because $f$ is continuous on $(0,\frac{1}{2})$, while $\lim_{\lambda\to 0+} f(\lambda) > 0$ (since $\|\hat{\Dbf}^{-1}\xbf\|^2 > t^2 $) and  $\lim_{\lambda\to \frac{1}{2}} f(\lambda) < 0$ (since $t >0$). Therefore, let $\lambda$ be a root of \eqref{eq:kkt_sys_fixed_3} and then \eqref{eq:kkt_sys_fixed_2_0}  gives the solution $\ybf$ and $s$.

Similarly, if $t <0$ and $\|\hat{\Dbf}\xbf\| > -t$ (the cases $\|\hat{\Dbf}\xbf\| \le -t$ has been discussed in the begining), then there exists $\lambda > \frac{1}{2}$ that is a root of $f(\lambda) = 0$. The existence of such a root is due to $\|\hat{\Dbf}\xbf\| > -t$.
Then \eqref{eq:kkt_sys_fixed_2_0}  gives the solution $\ybf$ and $s$ based using the root $\lambda$. Now the fourth case is proven.
\end{proof}




