\section{How to compute the normalized duality gap?\label{app:normalized_duality_gap}}


The main idea of computing the normalized duality gap is similar to that developed in \cite{applegate2023faster} for LPs and \cite{xiong2024role} for CLPs. Below, we restate it in the context of our CLP formulation \eqref{eq:prob_cp}.

Note that  
\begin{equation}\label{pro:compute_rho}
\rho^{\Nbf}(r;\zbf):=\frac{1}{r}\cdot\left(\begin{array}{cc}
\max_{\hat{\zbf}} & \bbf^{\top}(\hat{\zbf}-\zbf)\\
\st & \hat{\zbf}\in\mcal X\times\mcal Y,\norm{\zbf-\hat{\zbf}}_{\Nbf}^{2}\leq r^{2}
\end{array}\right)
\end{equation}
where 
$\bbf=\left(\begin{array}{c}
\bbf_{1}\\
\bbf_{2}
\end{array}\right)=\left(\begin{array}{c}
\Gbf^{\top}\ybf-\cbf\\
\hbf-\Gbf \xbf
\end{array}\right).$ 
As shown in \cite{applegate2023faster,xiong2024role}, the optimal solution of \eqref{pro:compute_rho} coincides with the solution $\zbf(t)$ of the following problem such that $\|\zbf - \zbf(t)\| = r$:
\begin{equation}\label{pro:compute_zt}
\zbf(t) := \argmax_{\tilde{\zbf} \in \mcal X \times \mcal Y} \quad t \cdot \bbf^{\top}(\tilde{\zbf} - \zbf) - \frac{1}{2} \cdot \norm{\tilde{\zbf} - \zbf}_{\Nbf}^2.
\end{equation}
Therefore, the goal becomes finding the $t$ such that $\|\zbf - \zbf(t)\|_\Nbf = r$ and we use $t_{\textrm{p}}$ to denote this $t$. We use a binary search method to identify the $t_{\textrm{p}}$ and compute $\rho^{\Nbf}(r;\zbf)$. See the overall algorithm of computing such $t_\textrm{p}$ within a tolerance $\eps$ and the corresponding $\rho^{\Nbf}(r;\zbf)$ in Algorithm~\ref{alg:binary_search_normalized_gap}.

\begin{algorithm}[htbp]
\caption{Binary search for normalzied duality gap $\rho(r;\zbf)$\label{alg:binary_search_normalized_gap}}
    \begin{algorithmic}[1]
        \Require{$t_0,\zbf=(\xbf,\ybf),r$}
        \State{$t_{\text{left}}=0,t_{\text{right}}=t_0$}
        \For{$k = 0,1,\ldots,$ } \Comment{Find an initial interval $[t_{\text{left}},t_{\text{right}}]$ by exponential search} 
        \State{ $\tilde{\zbf} \gets \zbf(t_k)$  }
        \If{$\norm{\zbf-\tilde{\zbf}}_\Nbf>r$}

        \If{$k=0$}
            \State{quit the loop}
        \Else
            \State{$t_{\text{right}}\gets t_k$, $t_{\text{left}}\gets  t_{k}/2$, and quit the loop}
        \EndIf
        \EndIf
        \State{$t_{k+1}\gets 2 t_k$}
    \EndFor 

    \While{$t_{\text{right}} - t_{\text{left}}>\eps$} \Comment{Refine $[t_{\text{left}},t_{\text{right}}]$ by binary search} 
    \State{$t_{\text{mid}}\gets (t_{\text{left}} + t_{\text{right}})/2$}
    \State{$\tilde{\zbf} \gets \zbf(t_{\text{mid}})$ }
    \If{$\norm{\zbf-\tilde{\zbf}}_\Nbf<r$}
        \State{$t_{\text{left}} \gets  t_{\text{mid}}$}
    \Else
        \State{$t_{\text{right}} \gets  t_{\text{mid}}$}
    \EndIf
    \EndWhile
    \State{\Return $\frac{\bbf^\top (\tilde{\zbf} - \zbf)}{r}$}
    \end{algorithmic}
\end{algorithm}

The problem \eqref{pro:compute_zt} is essentially a Euclidean projection onto the feasible set $\mcal X \times \mcal Y$:
\begin{equation}\label{pro:compute_zt_2}
\zbf(t) = (\proj_{\mcal X}(\xbf+{t\tau}\cdot \bbf_{1}),\proj_{\mcal Y}\{\ybf+{t\sigma}\cdot \bbf_{2}\}) \ , 
\end{equation} 
which reduces to multiple cone projection problems because $\mcal X = [\lbf , \ubf] \times \mcal K_\textrm{p}$ and $\mcal Y = \mcal K_{\textrm{d}}$. Appendix \ref{app:proj} will show more details on how to do these cone projections efficiently.


\section{Projection onto a rescaled exponential cone\label{app:proj}}
In this section, we will provide a detailed discussion of how to project onto an exponential cone, with a particular focus on the case of diagonal rescaling.

The following theorem shows that the solution pair $\vbf_{\textrm{p}}$ and $\vbf_{\textrm{d}}$ from~\eqref{eq:diagonal_moreau} can be parameterized by a scalar $\rho$, which can be obtained by solving a root-finding problem.
\begin{theorem}\label{thm:Moreau_sys_exp}
The projection of $\vbf_{0}=(r_{0},s_{0},t_{0})\in\mbb R^{3}$ onto the rescaled cone $\Dbf\mcal K_{\exp}$ is given as follows:

1. If $\vbf_{0}\in\Dbf\mcal K_{\exp}$, then $\proj_{\Dbf\mcal K_{\exp}}\brbra{\vbf_{0}}=\vbf_{0}$.

2. If $\vbf_{0}\in-\Dbf^{-1}\mcal K_{\exp}^{*}$, then $\proj_{\Dbf\mcal K_{\exp}}\brbra{\vbf_{0}}=\zerobf_{3\times 1}$.

3. If $r_{0}\leq0$ and $s_{0}\leq0$, then $\vbfp=\brbra{r_{0},0,t_{0}^{+}}$ and $\vbfd=\brbra{0,s_{0},t_{0}^{-}}$.

4. Otherwise, let  $\rho\in \mbb R$ be a scalar parameter satisfying the following system: 
\begin{equation}
d_{t}\exp(\rho)s_{\textrm{p}}-d_{t}^{-1}\exp(-\rho)r_{\textrm{d}}-t_{0}=0\ ,\ 
s_{\textrm{p}}>0\ ,\ r_{\textrm{d}}>0
\label{eq:h_rho} 
\end{equation}
in which 
\begin{equation}
\begin{aligned}{\vbf_{\textrm{p}}=\brbra{d_{r}\rho,d_{s},d_{t}\exp(\rho)}}s_{\textrm{p}}\ ,&\text{ with }\ s_{\textrm{p}}=\frac{s_{0}d_{r}^{-1}d_{s}-r_{0}(1-\rho)}{d_{s}^{2}d_{r}^{-1}+d_{r}\rho(\rho-1)}\ ,
\end{aligned}
\label{eq:vpvd_rho}
\end{equation}
\begin{equation}
\begin{aligned}
{\vbf_{\textrm{d}}=\brbra{d_{r}^{-1},(1-\rho)d_{s}^{-1},-d_{t}^{-1}\exp(-\rho)}r_{\textrm{d}}}\ , &\text{ with } \ {r_{\textrm{d}}=\frac{d_{s}^{2}r_{0}-d_{s}d_{r}\rho s_{0}}{d_{s}^{2}d_{r}^{-1}+d_{r}\rho(\rho-1)}}\ .
\end{aligned}
\label{eq:vpvd_rho2}
\end{equation}
Then $\vbf_{\textrm{p}}$ and $\vbf_{\textrm{d}}$ are the projections of $\vbf_0$ onto $\Dbf\mcal K_{\exp}$ and $-\Dbf^{-1}\mcal K_{\exp}^{*}$, respectively; i.e., $\vbf_{\textrm{d}}=\proj_{\Dbf\mcal K_{\exp}}(\vbf_0)$ and $\vbf_{\textrm{d}}=\proj_{-\Dbf^{-1}\mcal K_{\exp}^{*}}(\vbf_0)$.
\end{theorem}
In the practical implementation of PDCS, the system \eqref{eq:h_rho} is solved by a bijection method.  

Theorem~\ref{thm:Moreau_sys_exp} provides the  solution of~\eqref{eq:diagonal_moreau}. 
The first three cases of Theorem~\ref{thm:Moreau_sys_exp} are some simple cases, which are essentially the cases satisfying the elementwise orthogonality condition. In practice, we first check the first three cases, followed by solving the root-finding problem of the nonlinear system \eqref{eq:h_rho}.
Our strategy is built upon the projection algorithm for the unscaled exponential cone \cite{friberg2023projection}, yet the diagonal scaling matrix introduces a non-trivial coupling that complicates the root-finding analysis.

\section{Conic program reformulation}\label{appendix:conic programs}
\subsection{Fisher market equilibrium problem}
In this section, we give the conic program reformulation of the Fisher market equilibrium problem  (Section~\ref{sec:fisher_market}). 
The Fisher market equilibrium problem is equivalently written as the following problem:
\begin{equation}\label{pro:fisher_full}
\begin{split}\min_{\pbf\in\mbb R^{m}\ ,\ \Xbf\in\mbb R^{m\times n}, \ \tbf\in \mbb R^{m}} \ \ & -\sum_{i\in[m]}\wbf_{i}\pbf_{i}\ ,\\
\st \quad\quad\quad \ \ \ \ & \sum_{i\in[m]}\Xbf_{ij}=\bbf_{j}\ ,\ \forall~ j\in[n]\  ,\\
 & \tbf_{i}=\sum_{j\in[n]}\Ubf_{ij}\Xbf_{ij}\ ,\ \forall~ i\in[m]\ ,\\
 & \pbf_{i}\leq\log\brbra{\tbf_{i}},\forall~ i\in[m]\ ,\\
 & \Xbf_{ij}\geq0\ ,\ \forall i\in[m]\ , \ j\in[n]\ ,
\end{split}
\end{equation}
where $\wbf\in\mbb R^{m},\Ubf\in\mbb R^{m\times n}$ are given beforehand as the vector of monetary endowment for each buyer and the matrix of the utility vector for each buyer. 

Now we present the conic program formulation of the problem. 
Let the decision variables be stacked as $\ybf \in \mbb R^{m(n+2)}$:
$$\ybf=\left[\Xbf_{:,1}^{\top},\ldots,\Xbf_{:,n}^{\top},(\pbf_{1},\tbf_{1}),\ldots,(\pbf_{m},\tbf_{m})\right]^{\top} \ .$$
Let the problem parameters be stacked as follows in $\cbf, \Abf,\tilde{\bbf},\Qbf,\dbf$:
$$
\cbf:=\left[\underbrace{0,\ldots,0}_{mn \text{ items}},(-\wbf_{1},0),\ldots,(-\wbf_{m},0)\right]^{\top},$$
\begin{equation*}
\Abf:=\left[\begin{array}{cccccc}
\Ibf_{n\times n} & \cdots & \Ibf_{n\times n}\\
\Ubf_{1,:} &  &  & (0,-1)\\
 & \ldots &  &  & \cdots\\
 &  & \Ubf_{m,:} &  &  & (0,-1)
\end{array}\right],\ \ \tilde{\bbf}:=\left[\begin{array}{c}
\bbf\\
\zerobf_{m\times 1}
\end{array}\right]
\end{equation*}
\begin{equation*}
\Qbf:=\left[\begin{array}{cccc}
\zerobf_{3\times 1} & \left(\begin{array}{cc}
1 & \\
\\ & 1
\end{array}\right)\\
 &  & \ldots\\
 &  &  & \left(\begin{array}{cc}
1\\
\\ & 1
\end{array}\right)
\end{array}\right],\ \ \dbf:=\left[\begin{array}{c}
\left(\begin{array}{c}
0\\
-1\\
0
\end{array}\right)\\
\cdots\\
\left(\begin{array}{c}
0\\
-1\\
0
\end{array}\right)
\end{array}\right]\ .
\end{equation*}
Then \eqref{pro:fisher_full} is equivalent to the following conic program problem:
\begin{equation}\label{pro:fisher_cp}
\min_{\ybf\in \mbb R^{m(n+2)}}\ \ \cbf^{\top}\ybf\ ,\ \st\  \Abf \ybf = \tilde{\bbf}\ ,\ \Qbf \ybf - \dbf \in\mcal K_{\exp}^{m} , \ \ybf\geq \lbf
\end{equation}
where $\mcal K_{\exp}^{m}:=\underbrace{\mcal K_{\exp}\times\cdots\times\mcal K_{\exp}}_{m \text{ items}}$ and $\lbf:=\bsbra{\underbrace{0,\ldots,0}_{mn\text{ items}},\underbrace{-\infty,\ldots,-\infty}_{2m\text{ items}}}$.  

The above problem \eqref{pro:fisher_cp} is the problem that the various solvers, including cuPDCS, directly address in the experiments in Section \ref{sec:fisher_market}.


\subsection{Lasso Problem\label{sec:lasso_socp}} 
For completeness, we present the SOCP reformulation of the Lasso problem. The original Lasso problem is formulated as 
$$\min_{\xbf\in\mbb R^{n}}\norm{\Abf\xbf-\bbf}^{2}+\lambda\norm{\xbf}_{1}\ ,$$
where $\Abf\in\mbb R^{m\times n}$. Its SOCP reformulation is given by 
\begin{equation*}
    \begin{aligned}
\min_{\begin{array}{c}
w\in\mbb R,r\in\mbb R,\ybf\in\mbb R^{m}\\
\xbf_{1}\in\mbb R_{+}^{n},\xbf_{2}\in\mbb R_{+}^{n}
\end{array}}\ \ &\inner{\left[\begin{array}{cccc}
0 & 2 & \brbra{\zero_{m\times1}}^{\top} & \lambda\cdot\brbra{\onebf_{2n\times1}}^{\top}\end{array}\right]^{\top}}{\left[\begin{array}{ccccc}
w & r & \ybf^{\top} & \xbf_{1}^{\top} & \xbf_{2}^{\top}\end{array}\right]^{\top}}\\
\st\quad\quad\quad\quad \ \ \ &\left[\begin{array}{ccccc}
1 & 0 & 0 & \cdots & 0\\
\zero_{m\times1} & \zero_{m\times1} & \Ibf_{m\times m} & \Abf & -\Abf
\end{array}\right]\left[\begin{array}{ccccc}
w & r & \ybf^{\top} & \xbf_{1}^{\top} & \xbf_{2}^{\top}\end{array}\right]^{\top}=\left[\begin{array}{c}
1\\
\bbf
\end{array}\right]\\&\left[\begin{array}{ccc}
\frac{w+r}{2} & \frac{w-r}{2} & \ybf^{\top}\end{array}\right]^{\top}\in\mcal K_{\text{soc}}^{m+2}
    \end{aligned}
    \ .
\end{equation*}
% 
% where $\zerobf^m$ denotes an $m$-dimensional zero vector, $\onebf^{2n}$ is a vector of ones with length $2n$ and $\Ibf_{m}$ is a $m\times m$ identity matrix.


\subsection{Multi-period Portfolio Optimization (MPO)}
In this subsection, we present the MPO problem and its conic program reformulation. 
Compared with single-period portfolio optimization problems, MPO can avoid creating a greedy strategy and amortize the transaction in multi periods.


Boyd et al. \cite{boyd2017multi} present a penalty-based formulation of the Multi-Period Optimization (MPO) problem, as given below in equation~\eqref{eq:cvx_trading}:
\begin{equation}\label{eq:cvx_trading}
    \begin{split}\max_{\substack{\wbf_{\tau+1},\zbf_{\tau} \in \mbb R^{n+1}:\\ \tau=0,\ldots,T-1}}&\sum_{\tau=0}^{T-1}\left\{ \hat{\rbf}_{\tau+1}^{\top}\wbf_{\tau+1} - \gamma_{\tau}^{\text{risk}} \hat{\psi}_{\tau}(\wbf_{\tau+1}) - \gamma_{\tau}^{\text{hold}} \hat{\phi}_{\tau}^{\text{hold}}(\wbf_{\tau+1}) - \gamma_{\tau}^{\text{trade}} \hat{\phi}_{\tau}^{\text{trade}}(\zbf_{\tau}) \right\} \\
    \text{s.t.} \quad \ \ \ &\ \ \mathbf{1}^{\top}\zbf_{\tau}=0,\ \ \zbf_{\tau}\in\mathcal{Z}_{\tau},\ \wbf_{\tau}+\zbf_{\tau}\in\mathcal{W}_{\tau}, \text{ for all } \tau = 0, \ldots, T-1, \\
    &\ \ \wbf_{\tau+1} = \wbf_{\tau} + \zbf_{\tau},\ \text{for all } \tau = 0, \ldots, T-1,
    \end{split}
\end{equation}
where the decision variable $\wbf_{\tau+1} \in \mathbb{R}^{n+1}$ represents the weights of assets for the period $\tau+1$, in which the first $n$ components denote $n$ assets and the $(n+1)$-th component denotes the weight of cash. 
And the other decision variable $\zbf_{\tau}$ denotes the transaction amount in the period $\tau$.

In this formulation, the expected return $\hat{\rbf}_{\tau+1} \in \mathbb{R}^{n+1}$ is predicted beforehand using other statistical or machine learning methods. The function $\hat{\psi}_{\tau}(\cdot)$ quantifies risk, which is typically defined as $\hat{\psi}_{\tau}(\wbf_{\tau+1}) := \| \hat{\mathbf{\Sigma}}_{\tau+1}^{1/2}[\wbf_{\tau+1} - \wbf_b]_{[n]} \|^2 + \kappa(\sum_{i=1}^{n}\hat{\mathbf{\Sigma}}_{ii}^{1/2}\abs{\wbf_{\tau+1}-\wbf_b}_{(i)})^2$. In this formulation,  $\wbf_b$ denotes the benchmark asset weight and $\hat{\mathbf{\Sigma}}$ is an estimate of the covariance matrix of the stochastic returns, and the term $(\sum_{i=1}^{n}\hat{\mathbf{\Sigma}}_{ii}^{1/2}\abs{\wbf_{\tau+1}-\wbf_b}_{(i)})^2$ is a measure of covariance forecast error risk and $\kappa$ is a hyper-parameter~\cite{ho2015weighted,li2015sparse}. The term $ \hat{\phi}_\tau^{\text{hold}}$ denotes the holding cost, which may include factors such as borrowing fees. The term \( \hat{\phi}_\tau^{\text{trade}}(\zbf_\tau) \) denotes the transaction cost, which is typically modeled as a linear and quadratic function of the transaction amount $\zbf_{\tau}$, i.e., \( \hat{\phi}_\tau^{\text{trade}}([\zbf_\tau]_{i}) = a_{\tau,i} |[\zbf_{\tau}]_{i}| + b_{\tau, i} |[\zbf_{\tau}]_{(i)}|^2 \) where \( a_{\tau} \) and \( b_{\tau} \) are coefficients \cite{grinold2000active} that can be predicted using other statistical and machine learning methods. The set \( \mathcal{Z}_{\tau} \) contains the constraints for the transaction amounts \( \zbf_{\tau} \), such as limiting the transaction ratio in each period. The set \( \mathcal{W}_{\tau} \) contains the constraints on the asset weights \( \wbf_{\tau+1} \), such as the requirement for market neutrality, \( (\wbf_\tau^m)^{\top} \hat{\mathbf{\Sigma}}_{\tau} (\wbf_{\tau+1}) = 0 \) where $\wbf_{\tau}^{m}$ is the asset value in period $\tau$.

Hence, a specific example of~\eqref{eq:cvx_trading} is 
\begin{equation}\label{pro:MPO_QP}
\begin{split}\max_{\substack{\wbf_{\tau+1} \in \mbb R^{n+1}: \\ \tau=0,\ldots,T-1}}\ \ &\sum_{\tau=0}^{T-1}\Bigg[\hat{\rbf}_{\tau+1}^\top \wbf_{\tau+1}
-\gamma^{\text{risk}}_{\tau}\underbrace{\left(\norm{\hat{\mathbf{\Sigma}}_{\tau+1}^{1/2}[\wbf_{\tau+1}-\wbf_{b}]_{[n]}}^{2}+\kappa\Brbra{\sum_{i=1}^{n}\hat{\mathbf{\Sigma}}_{\tau+1,ii}^{1/2}\abs{[\wbf_{\tau+1}-\wbf_{b}]_{i}}}^{2}\right)}_{\hat{\psi}^{\text{risk}}_{\tau}(\wbf_{\tau+1})}\\&- \gamma_{\tau}^{\text{trade}} \cdot\underbrace{\left(\sum_{i=1}^{n}a_{\tau,i}\abs{\wbf_{\tau+1}-\wbf_{\tau}}_{i}-b_{\tau,i}(\wbf_{\tau+1}-\wbf_{\tau})_{i}^{2}\right)}_{\hat{\phi}_{\tau}^{\text{trade}}(\wbf_{\tau+1})}\ - \ \gamma_{\tau}^{\text{hold}}\cdot \underbrace{0}_{\hat{\phi}_{\tau}^{\text{hold}}(\wbf_{\tau+1})}\Bigg]
\\ \st \quad \quad &\onebf^{\top}(\wbf_{\tau+1}-\wbf_{\tau})=0\ ,\ \ \wbf_{\tau+1}\geq0\ ,\ \ (\wbf_{\tau}^{m})_{[n]}\hat{\mathbf{\Sigma}}_{\tau}(\wbf_{\tau+1})_{[n]}=0\ ,\tau=0,\ldots,T-1\ .
\end{split}
\end{equation}
This specific example considers the case with no borrowing fee,  long holding, and no constraint on transactions. In this formulation,  $\gamma^{\text{risk}}_{\tau},\kappa,\gamma_\tau^\text{trade}, a_{\tau,i}, b_{\tau,i} \, \gamma_\tau^\text{hold}$ are hyper-parameters.

The above problem models the risk-control tasks in the portfolio optimization problem as regularization terms added to the objective function, but choosing the proper hyperparameters to balance different objectives would be difficult in practice and require heavy parameter tuning. 
Given that, another commonly seen strategy is to model the other objectives other than profit within the constraints. In this way, the hyper-parameters directly correspond to the maximum allowed holding costs, transaction cost, or risk.  
See, for example, \cite{li2000optimal}. Such a constraint-based formulation of \eqref{pro:MPO_QP} is as follows, a SOCP problem:

\begin{equation}\label{pro:MPO_SOCP}
\begin{split}\max_{\substack{\wbf_{\tau+1} \in \mbb R^{n+1}: \\ \tau=0,\ldots,T-1}}\ \ &\sum_{\tau=0}^{T-1}\hat{\rbf}_{\tau}^\top\wbf_{\tau+1}\\
\st\quad \quad &\onebf^{\top}(\wbf_{\tau+1}-\wbf_{\tau})=0\ ,\ \ {\forall\tau=0,\ldots,T-1}\\
&\wbf_{\tau}\geq0\ ,\ \ {\forall\tau=0,\ldots,T-1}\\
&(\wbf_{\tau}^{m})_{[n]}\hat{\mathbf{\Sigma}}_{\tau+1}(\wbf_{\tau+1})_{[n]}=0\ ,\ \ {\forall\tau=0,\ldots,T-1}\\
&\norm{\hat{\mathbf{\Sigma}}_{\tau+1}^{1/2}(\wbf_{\tau+1}-\wbf_{b})_{[n]}}\leq\gamma_{1\tau}\ ,\ \ {\forall\tau=0,\ldots,T-1}\\
&-\gamma_{2\tau,i}\leq(\wbf_{\tau+1}-\wbf_{\tau})_{i}\leq\gamma_{2\tau,i}\ ,\ \ {\forall\tau=0,\ldots,T-1},i=1,\ldots,n+1\\
&-\gamma_{3\tau}\leq\sum_{i=1}^{n}\brbra{\hat{\mathbf{\Sigma}}_{\tau + 1}^{1/2}}_{ii}(\wbf_{\tau+1}-\wbf_{b})_{i}\leq\gamma_{3\tau}\ ,\ \ {\forall\tau=0,\ldots,T-1}\ .
\end{split}
\end{equation}

The above problem \eqref{pro:MPO_SOCP} is the problem that the various solvers, including cuPDCS, directly address in the experiments in Section \ref{sec:mpo}.


\section{Optimality Termination Criteria\label{app:solver_criteria}}
This section describes the termination criteria of the solvers used in our experiments on CLP problems. Generally, these criteria comprise three types of different errors: primal infeasibility ($\err_\textrm{p}$), dual infeasibility ($\err_\textrm{d}$), and the duality gap ($\err_{\textrm{gap}}$). 


\subsection{ABIP}
ABIP directly addresses the following primal and dual problems:
\begin{equation}\label{eq:abip_linear_conic}
\begin{aligned}
    \min_{\xbf} &\ \  \cbf^\top \xbf \ \ \st \Abf\xbf = \bbf\ , \ \ \xbf\in \mathcal{K}\ ,\\
    \max_{\ybf} &\ \  \bbf^\top \ybf \ \ \st \Abf^\top \ybf + \sbf = \cbf\ , \ \ \sbf \in \mathcal{K}^*\ .
\end{aligned}
\end{equation}
If the given optimization problem does not satisfy this formulation, ABIP reformulates the problem to \eqref{eq:abip_linear_conic} first and then solves it. It should be noted that for all iterates of ABIP, $\xbf$ and $\sbf$ always lie in the cones $\mcal K$ and $\mcal K^*$ because ABIP uses an ADMM-based interior point method, which ensures all iterates are always in the interior of the cones.
On the formulation \eqref{eq:abip_linear_conic}, ABIP determines its termination criteria based on the following three types of errors:
\begin{equation*} 
        \text{err}_{\textrm{p}} := \frac{\norm{\Abf \xbf - \bbf}_{\infty}}{1+\max\left\{\norm{\Abf \xbf}_{\infty},\norm{\bbf}_{\infty}\right\}}\ , \ \ 
\text{err}_{\textrm{d}}: = \frac{\norm{\cbf-\Abf^{\top}\ybf-\sbf}_{\infty}}{1+\norm{\cbf}_{\infty}}\ , \ \
\text{err}_{\textrm{gap}} := \frac{|\cbf^{\top}\xbf+\bbf^{\top}\ybf|}{1+\max\left\{|\cbf^{\top}\xbf|,|\bbf^{\top}\ybf|\right\}}\ .  
\end{equation*}
In our experiments, we say a solution satisfies the $\vep_{\textrm{rel}}$ tolerance if  $\max\{\err_{\textrm{p}}, \err_{\textrm{d}}, \err_{\textrm{gap}}\} \leq \vep_{\textrm{rel}}$ for this solution.


\subsection{SCS}
SCS directly solves the conic program problems in the following formulation:
\begin{equation}\label{eq:scs_opt}
\begin{aligned}
     \min_{\xbf}\ \  &\cbf^\top \xbf \ \ \st \Abf \xbf + \sbf = \bbf,\ \ \sbf\in \mathcal{K},\\
     \max_{\ybf}\ \  &-\bbf^\top \ybf \ \ \st \Abf^\top \ybf + \cbf = 0, \ \ \ybf\in \mathcal{K}^*.
\end{aligned}
\end{equation}
If the problem is not in this formulation, we should first reformulate it into this formulation and then use SCS to solve it.
All iterates of  SCS satisfy the conic constraints $s\in \mathcal{K}$ and $y\in \mathcal{K}^*$ as the solver does projections onto the cones in each iteration. 

On the formulation \eqref{eq:scs_opt}, SCS determines its termination criteria based on the following residual thresholds:
\begin{equation*}
\begin{aligned}
    \err_{\textrm{p}} &= \norm{\Abf \xbf+\sbf-\bbf}_{\infty} \leq \vep_{\textrm{abs}} + \vep_{\textrm{rel}}\cdot \max\left\{\norm{\Abf \xbf}_{\infty},\norm{\sbf}_{\infty},\norm{\bbf}_{\infty}\right\},\\
    \err_{\textrm{d}} &= \norm{\Abf^\top \ybf + \cbf}_{\infty} \leq \vep_{\textrm{abs}} + \vep_{\textrm{rel}}\cdot \max\left\{\norm{A^\top y}_{\infty},\norm{\cbf}_{\infty}\right\},\\
    \err_{\textrm{gap}} &= |\cbf^\top \xbf - \bbf^\top \ybf| \leq \vep_{\textrm{abs}} + \vep_{\textrm{rel}}\cdot \max\left\{|\cbf^\top \xbf|,|\bbf^\top \ybf|\right\}.
\end{aligned}
\end{equation*}
In our experiments, we say a solution satisfies the $\eps$ tolerance if the above conditions all hold with $\eps_{\textrm{rel}} = \eps_{\textrm{abs}} = \eps$.

\subsection{COPT}
The algorithm used in the solver COPT is an interior point method, but the definition of tolerance in its optimality criteria is not publicly available yet. 


\subsection{MOSEK}
MOSEK uses an interior-point method to solve the conic program problem that is similarly structured to~\eqref{eq:abip_linear_conic}. However, it directly addresses the self-dual homogeneous model below:
\begin{equation*}
\begin{split}\Abf \xbf - \bbf\tau & =0\\
\Abf^{\top}\ybf+\sbf-\cbf\tau & =0\\
-\cbf^{\top}\xbf+\bbf^{\top}\ybf-\kappa & =0\\
\xbf\in\mathcal{K},\ \ \sbf\in\mathcal{K}^*, & \ \ \tau,\kappa\geq0 \ .
\end{split}
\end{equation*}
A solution is regarded as satisfying the $\eps_{\mathrm{rel}}$ tolerence in MOSEK if the following conditions hold:
\begin{equation*}
    \begin{aligned}
        \err_{\textrm{p}} &= \frac{\norm{\Abf\frac{\xbf}{\tau}-\bbf}_{\infty}}{1+\norm{\bbf}_{\infty}} \leq \vep_{\textrm{rel}},\\
        \err_{\textrm{d}} & = \frac{\norm{A^\top \frac{\ybf}{\tau} + \frac{\sbf}{\tau} - c}_{\infty}}{1 + \norm{\cbf}_{\infty}} \leq \vep_{\textrm{rel}}, \\
        \err_{\textrm{gap}} & = \max\left\{\frac{x^\top s}{\tau^2}, \left|\frac{\cbf^\top \xbf}{\tau} - \frac{\bbf^\top \ybf}{\tau}\right|\right\}\ \Big/ \ \max\left\{1,\frac{\min\left\{|\cbf^\top \xbf|,|\bbf^\top \ybf|\right\}}{\tau}\right\} \leq \vep_{\textrm{rel}}\ .
    \end{aligned}
\end{equation*}

\subsection{CuClarabel}
The problem formulation that CuClarabel solves is similar to that of SCS, i.e.,~\eqref{eq:scs_opt}. However, CuClarabel introduces two slack variables $\tau,\kappa \geq 0$ and consider the following optimization problem:
\begin{equation*}
    \begin{aligned}
        \min \ \ &\sbf^\top \ybf + \tau \kappa\\
        \st  \ \ & \cbf^\top \xbf + \bbf^\top \ybf = -\kappa\\
        & \Abf^\top \ybf + \cbf\tau = 0\\
        &\Abf \xbf + \sbf - \bbf \tau = 0\\
        &(\sbf,\ybf,\tau,\kappa)\in \mcal K\times \mcal K^*\times \mbb R_+ \times \mbb R_+    \ .
    \end{aligned}
\end{equation*}
For the above formulation, a solution is regarded as satisfying the $\eps_{\mathrm{rel}}$ tolerance if the following conditions hold:
\begin{equation*}
    \begin{aligned}
        \err_{\textrm{p}} &= \frac{\norm{\Abf\frac{\xbf}{\tau} - \frac{\sbf}{\tau} + \bbf}_{\infty}}{\max\{1,\norm{\bbf}_{\infty}+\norm{\xbf/\tau}_{\infty}+\norm{\sbf/\tau}_{\infty}\}}\leq \eps_{\mathrm{rel}}\\
        \err_{\textrm{d}} &= \frac{\norm{\Abf^\top \frac{\ybf}{\tau} + \cbf}_{\infty}}{\max\{1,\norm{\cbf}_{\infty}+\norm{\xbf/\tau}_{\infty}+\norm{\zbf/\tau}_{\infty}\}}\leq \eps_{\mathrm{rel}}\\
        \err_{\textrm{gap}} &= \frac{\abs{\cbf^\top \xbf + \bbf^\top \ybf}}{\max\{1,\min\{\abs{\cbf^\top \xbf},\abs{\bbf^\top \ybf}\}\}}\leq \eps_{\mathrm{rel}}\ .
    \end{aligned}
\end{equation*}
Since CuClarabel also uses an interior-point method, all iterates of CuClarabel are within the cones.





