% \[\gamma t_i^{C_4}\cdot (t_m^{C_4})^{2^i}=0\in R_m[1/t_m^{C_4}]\]
% which implies $\gamma t_i^{C_4}=0\in R_m[1/t_m^{C_4}]$. Using this, a simple induction argument using the $i$-th relation in \cite[Theorem 1.1]{BHSZ} for $1\le i\le m$ now implies that $t_i^{C_4}=0\in R_m[1/t_m^{C_4}]$ for all $1\le i\le m$. In particular, $t_m^{C_4}$ is both a unit and zero in $R_m[1/t_m^{C_4}]$, so $R_m[1/t_m^{C_4}]$ is the zero ring.
% \end{proof}

\begin{corollary}\label{cor:bpgmregularsequence}
    The sequence $(2,v_1,\ldots,v_{h})$ is regular in $\pi_*^e\bpgm{m}$.
\end{corollary}
\begin{proof}
    The element $2$ is a nonzero divisor in $\pi_*^e\bpgm{m}$, so we will show that $(v_1,\ldots,v_{h})$ is a regular sequence in
\[\pi_*^e\bpgm{m}/2=\F_2[G\cdot t_1^G,\ldots,G\cdot t_m^G]\]
This follows from the fact that the latter is a polynomial ring of Krull dimension $h$, and the quotient by the ideal $(v_1,\ldots,v_{h})$ gives a Krull dimension zero ring by Corollary \ref{cor:bpgmfinite}. Indeed, for each $i$, the ring $\F_2[G\cdot t_1^G,\ldots,G\cdot t_m^G]/(v_1,\ldots,v_i)$ is a natural subring of $\F_2[[G\cdot t_1^G,\ldots,G\cdot t_m^G]]/(v_1,\ldots,v_i)$, so the regularity claim follows from the corresponding one in $\F_2[[G\cdot t_1^G,\ldots,G\cdot t_m^G]]$, which is a complete Noetherian regular local ring of Krull dimension $h$, with each $v_i$ contained in the maximal ideal $\mathfrak{m}=(G\cdot t_1^G,\ldots,G\cdot t_m^G)$.
\end{proof}

\subsection{Poincaré series and dimension}
Our Corollary \ref{cor:bpgmfinite} implies that 
\[\pi_*^e\bpgm{m}/(2,v_1,\ldots,v_{h})\] is a finite dimensional $\F_2$-vector space. In fact, by using Poincaré series, we can compute its dimension explicitly in terms of Gaussian binomial coefficients.

\begin{definition}
   For a $\Z_{\ge0}$-graded $\F_2$-vector space $V_*$, let
    \[f_{V_*}(x)=\sum\limits_{n\ge0}(\dim_{\F_2}V_n) x^n\in\F_2[[x]]\]
    be its \emph{Poincaré series}. 
\end{definition}

For the Poincaré series we consider below, we work with graded vector spaces concentrated in even degrees, so we implicitly divide all degrees by 2. Note that this does not change the dimension of the underlying vector space.

\begin{proposition}\label{prop:poincarebpgm}
    The Poincaré series $f_m(x)$ of $\pi_*^e\bpgm{m}/(2,v_1,\ldots,v_{h})$ is given by
\[f_m(x)=\frac{\prod\limits_{i=1}^{h}1-x^{2^i-1}}{\bigg(\prod\limits_{i=1}^m1-x^{2^i-1}\bigg)^{|G|/2}}\]
% In particular, the dimension of the graded $\F_2$-vector space $\pi_*^e\bpgm{m}/(2,v_1,\ldots,v_{m|G|/2})$ is given by\
% \[\lim_{x\to 1}\frac{\bigg(\prod\limits_{i=1}^{m}\frac{1}{1-x^{2^i-1}}\bigg)^{|G|/2}}{\prod\limits_{i=1}^{m|G|/2}\frac{1}{1-x^{2^i-1}}}\]
\end{proposition}    
\begin{proof}
    By Corollary \ref{cor:bpgmregularsequence}, there is an isomorphism of graded $\F_2$-vector spaces
\[\F_2[G\cdot t_1^G,\ldots,G\cdot t_m^G]\cong \pi_*^e\bpgm{m}/(2,v_1,\ldots,v_{h})\otimes_{\F_2}\F_2[v_1,\ldots,v_{h}]\]
giving an equation
\[\bigg(\prod\limits_{i=1}^{m}\frac{1}{1-x^{2^i-1}}\bigg)^{|G|/2}=f_m(x)\cdot \prod\limits_{i=1}^{h}\frac{1}{1-x^{2^i-1}}\in \F_2[[x]],\]
and the claim is obtained by dividing in $\F_2[[x]]$.
\end{proof}

\begin{definition}
    Let 
    \[\binom{n}{m}_2=\frac{(1-2^n)(1-2^{n-1})\cdots(1-2^{n-m+1})}{(1-2)(1-2^2)\cdots(1-2^m)}\]
    be the Gaussian $q$-binomial coefficient with $q=2$.
\end{definition}

\begin{remark}
    For all $n\ge m$, $\binom{n}{m}_2$ is a positive integer, which is therefore odd as it divides the odd number $(1-2^n)(1-2^{n-1})\cdots(1-2^{n-m+1})$.
\end{remark}

\begin{corollary}\label{cor:bpgmodd}
    For all $m\ge0$, one has
    \[\dim_{\F_2}\big(\pi_*^e\bpgm{m}/(2,v_1,\ldots,v_{h})\big)=\prod\limits_{j=0}^{|G|/2-1}\binom{jm}{m}_2\]
    In particular, this $\F_2$-vector space has odd dimension.
\end{corollary}
\begin{proof}
    We prove the claim via l'Hôpital's rule. We have
    \begin{align*}
        \lim_{x\to 1}f_m(x)&=\lim_{x\to 1}\frac{\prod\limits_{i=1}^{h}1-x^{2^i-1}}{\bigg(\prod\limits_{i=1}^m1-x^{2^i-1}\bigg)^{|G|/2}}\\
        &=\prod\limits_{j=0}^{|G|/2-1}\lim_{x\to 1}\prod\limits_{i=1}^m\frac{1-x^{2^{jm+i}-1}}{1-x^{2^i-1}}\\
        &=\prod\limits_{j=0}^{|G|/2-1}\prod\limits_{i=1}^m\lim_{x\to 1}\frac{1-x^{2^{jm+i}-1}}{1-x^{2^i-1}}\\
        &=\prod\limits_{j=0}^{|G|/2-1}\prod\limits_{i=1}^m\frac{1-2^{jm+i}}{1-2^i}\\
        &=\prod\limits_{j=0}^{|G|/2-1}\binom{jm}{m}_2
    \end{align*}
\end{proof}

\begin{example}\label{ex:formalgroupbpc4}
    In the case $G=C_4$, the ring $\pi_*^e\bpcm{m}/2$ is isomorphic to the quotient
    \[\F_2[\xi_1,\ldots,\xi_m]/(\zeta_{m+1},\ldots,\zeta_{2m})\]
    of the dual Steenrod algebra $\mathcal{A}_*$, where $\xi_i$ are the usual Milnor generators, and $\zeta_i$ are the Hopf conjugates. The group scheme $\Spec(\mathcal{A}_*)$ is the (strict) automorphism group of the additive formal group $\widehat{\mathbb{G}_a}$ over $\F_2$. Under this identification, $\Spec(\pi_*^e\bpcm{m}/2)$ is the subscheme consisting of those automorphisms of the form
    \[f(x)=x+\xi_1x^2+\cdots +\xi_mx^{2^m}\]
    with the property that $f^{-1}(x)$ has the same form 
    \[f(x)=x+\zeta_1x^2+\cdots +\zeta_mx^{2^m}.\]
    Corollary \ref{cor:bpgmodd} computes the dimension over $\F_2$ of the ring of functions on this scheme, and we speculate that the appearance of Gaussian binomial coefficients has a modular interpretation in these terms.
\end{example}

\section{A filtration for equivariant quotients}\label{sec:filtration}
We recall the twisted monoid construction $M/(G\cdot \bar{x})$ of the second author, Hopkins, and Ravenel, and we introduce the Koszul filtration on the fiber of the quotient map
\[
    M\to M/(G\cdot \bar{x}).
\]

\subsection{Equivariant quotients} 

\begin{definition}\label{def:equivariantcofiber}
    Let $\mathbb{S}[\bar{x}]$ be the free $\mathbb{E}_1$-algebra in $\Sp^{C_2}$ on a class $\bar{x}$ in degree $k\rho_2$. We use the notation
    \[\mathbb{S}[G\cdot\bar{x}]:=\begin{cases}N_{C_2}^G(\mathbb{S}[\bar{x}])& C_2\subset G\\\mathrm{Res}^{C_2}_e(\mathbb{S}[\bar{x}])&G=\{e\}\end{cases}\]
    Note that $\mathbb{S}[\{e\}\cdot\bar{x}]=\mathbb{S}[x]$ is the free $\mathbb{E}_1$-algebra in $\Sp$ on the underlying class $x:=\mathrm{Res}^{C_2}_e(\bar{x})$. Moreover, since $N_{C_2}^G$ is monoidal, $\mathbb{S}[G\cdot\bar{x}]$ is canonically an augmented $\mathbb{E}_1$-algebra in $\Sp^G$.

    For classes $\bar{x}_i$ in degrees $k_i\rho_2$, we define the augmented $\mathbb{E}_1$-algebra
    \[\mathbb{S}[G\cdot\bar{x}_1,\ldots,G\cdot\bar{x}_n]:=\bigotimes\limits_{i=1}^n\mathbb{S}[G\cdot\bar{x}_i],\]
    and for $M\in\mathrm{Mod}(\mathbb{S}[G\cdot\bar{x}_1,\ldots,G\cdot\bar{x}_n])$, we define
    \[M/(G\cdot\bar{x}_1,\ldots,G\cdot\bar{x}_n):=M\otimes_{\mathbb{S}[G\cdot\bar{x}_1,\ldots,G\cdot\bar{x}_n]}\mathbb{S}.\]
\end{definition}

\begin{example}\label{example:equivariantcofibers}
    When $G\subset C_2$, the quotient $M/(G\cdot\bar{x}_1,\ldots,G\cdot\bar{x}_n)$ is the ordinary (iterated) cofiber by the elements $\bar{x}_i$ when $G=C_2$, and $x_i:=\mathrm{Res}^{C_2}_e(\bar{x}_i)$ when $G=\{e\}$, respectively. More generally, it follows from the definitions that
    \[\mathrm{Res}^G_H(M/(G\cdot\bar{x}_1,\ldots,G\cdot\bar{x}_n))=M/(H\cdot g\bar{x}_1,\ldots,H\cdot g\bar{x}_n\mid gH\in G/H).\]
    For example, when $G=C_4$, the underlying $C_2$-spectrum of $M/(C_4\cdot\bar{x})$ is the ordinary (iterated) cofiber $\mathrm{Res}^{C_4}_{C_2}(M)/(\bar{x},\gamma\bar{x})$, where $\gamma$ is a generator of $C_4$.
\end{example}

It is shown in \cite[Section 5]{HHR} that there exist classes $\bar{t}_i^G\in\pi_{*\rho_2}^{C_2}BP^{(\!(G)\!)}$ such that
\[\pi_{*\rho_2}^{C_2}BP^{(\!(G)\!)}=\Z[G\cdot\bar{t}_1^G,G\cdot\bar{t}_2^G,\ldots],\]
and $\mathrm{Res}(\bar{t}_i^G)=t_i^G$, where the $t_i^G$'s are the underlying generators discussed in Section \ref{sec:algebraicstuff}.

\begin{definition}\label{def:bpgm}
    We define the $MU^{(\!(G)\!)}$-module
    \[\bpgm{m}:=\mathrm{colim}_kBP^{(\!(G)\!)}/(G\cdot\bar{t}_m^G,\ldots,G\cdot\bar{t}_{m+k}^G)\]
\end{definition}

\begin{remark}
    Note in particular that
    \(\bpgm{m-1}=\bpgm{m}/(G\cdot\bar{t}_m^G)\).
\end{remark}

\subsection{Norms of quotients via filtrations} 
The parametrized Day convolution developed by Nardin and Shah \cite[Section 3]{nardinshah} immediately gives the following facts about equivariant filtrations.

\begin{proposition}
    The categories $\mathrm{Fil}(\Sp^G)$ and $\mathrm{gr}(\Sp^G)$ of filtered and graded $G$-spectra respectively admit the structure of $G$-symmetric monoidal $\infty$-categories with the property that the functors
\begin{align*}
    \mathrm{colim}:\mathrm{Fil}(\Sp^G)&\to\Sp^G\\
    X^\bullet&\mapsto X^{-\infty}\\
    \mathrm{gr}:\mathrm{Fil}(\Sp^G)&\to\mathrm{gr}(\Sp^G)\\
    X^\bullet&\mapsto (\mathrm{cofib}(X^{i+1}\to X^i))_{i\in\Z}\\
    \mathrm{forget}:\mathrm{gr}(\Sp^G)&\to\Sp^G\\
    (X^i)_{i\in\Z}&\mapsto\bigoplus\limits_{i\in\Z}X^i
\end{align*}
have canonical $G$-symmetric monoidal structures.
\end{proposition}

\begin{remark}
    The norm functors in $\mathrm{gr}(\Sp^G)$ are computed in terms of the norms in $\Sp^G$ using the fact that $\mathrm{forget}:\mathrm{gr}(\Sp^G)\to\Sp^G$ is $G$-symmetric monoidal and by use of the distributive laws of the second author, Hopkins, and Ravenel, which describe the behavior of the norm functors in $\Sp^G$ with respect to sums (see \cite[Proposition A.37]{HHR}).
\end{remark}

We begin by unpacking the distributive law of \cite[Proposition A.37]{HHR} in our case of interest, which yields a decomposition:

\begin{equation}\label{eq:distributive}
    N_{C_2}^{G}\big(\mathbb S\oplus E\big)\simeq \bigoplus_{f\in\Map^{C_2}\big(G,\{0,1\}\big)} E^{\otimes f^{-1}(1)},
\end{equation}
where $\{0,1\}$ has a trivial $C_2$-action, and $\Map^{C_2}(-,-)$ denotes $C_2$-equivariant maps. When we view this as a graded object, with \(\mathbb S\) in grading \(0\) and \(E\) in grading \(1\), then the grading of a summand associated to \(f\) is $\frac{1}{2}\sum_{g\in G} f(g)$.

In fact, the sum and the tensor appearing in (\ref{eq:distributive}) are  their indexed variants. For the sum, each of the $G$-conjugates of a $C_2$-equivariant function \(f\colon G\to \{0,1\}\) is grouped via induction in a single equivariant summand
\[\mathrm{Ind}_{H_f}^GE^{\otimes f^{-1}(1)},\]
where $H_f$ is the stabilizer of $f$ in $G$. For the tensor, factors are grouped via the norm.

\begin{definition}
    The indexed tensor summand associated to \(f\) is the \(H_f\)-equivariant spectrum
    \[
        E^{\otimes f^{-1}(1)}:=\bigotimes_{gH_f\in f^{-1}(1)/H_f} g\cdot N_{C_2}^{H_f}(E).
    \]
\end{definition}

When we apply this to \(E=\Sigma^{k\rho_2}\mathbb S^0[\bar{x}]\) for a \(C_2\)-equivariant class \(\bar{x}\) in degree $k\rho_2$, then this can be rewritten in the notation of Definition \ref{def:equivariantcofiber} as
\[
    \big(\Sigma^{k\rho_2}\mathbb S^0[\bar{x}]\big)^{\otimes f^{-1}(1)}=\Sigma^{n_f\cdot k\rho_{H_f}}\mathbb S^0[H_f\cdot g\bar{x}\mid gH_f\in f^{-1}(1)/H_f].
\]
where we set $n_f:=|f^{-1}(1)/H_f|$. Putting this all together, this gives us a description of the norm of the associated graded as a graded object.

\begin{proposition}
    The norm $N_{C_2}^G$ of the graded $C_2$-spectrum $\mathbb{S}\oplus\Sigma^{k\rho_2}\mathbb{S}[\overline{x}]$ with $\mathbb{S}$ in grading $0$ and $\Sigma^{k\rho_2}\mathbb{S}[\bar{x}]$ in grading $1$ is
    \[
        \bigoplus_{f\in\Map^{C_2}\big(G,\{0,1\}\big)/G} \Ind_{H_f}^{G} \Sigma^{n_f\cdot k\rho_{H_f}}\mathbb S^0[H_f\cdot g\bar{x}\mid gH_f\in f^{-1}(1)/H_f],
    \]
    with the summand associated to \(f\) in grading \(\tfrac{1}{2}|f^{-1}(1)|\).
\end{proposition}

The $\mathbb{S}[G\cdot \overline{x}]$-module structure on the summand 
\[\Ind_{H_f}^{G} \mathbb S^0[H_f\cdot g\bar{x}\mid gH_f\in f^{-1}(1)/H_f]\]
is induced from  the $\mathrm{Res}^G_{H_f}\mathbb{S}[G\cdot \overline{x}]=\mathbb{S}[H_f\cdot g\overline{x}\mid gH_f\in G/H_f]$-module structure on $S^0[H_f\cdot g\bar{x}\mid gH_f\in f^{-1}(1)/H_f]$ furnished by the ring map
\[\mathbb{S}[H_f\cdot g\overline{x}\mid gH_f\in G/H_f]\to \mathbb{S}[H_f\cdot g\overline{x}\mid gH_f\in f^{-1}(1)/H_f],\]
which quotients out $(H_f\cdot g\overline{x}\mid gH_f\in f^{-1}(0)/H_f)$. Tensoring this filtration with an $\mathbb{S}[G\cdot\bar{x}]$-module $M$, this yields the following.

\begin{proposition}\label{prop:associatedgradedformula}
    Let $M$ be an $\mathbb{S}[G\cdot x]$-module with $|x|=k\rho_2$. Then $M$ admits a $\mathbb{S}[G\cdot x]$-linear filtration with associated graded
   \[
        \bigoplus_{f\in\Map^{C_2}\big(G,\{0,1\}\big)/G} \Ind_{H_f}^{G} \Sigma^{n_f\cdot k\rho_{H_f}}M/(H_f\cdot g\bar{x}\mid gH_f\in f^{-1}(0)/H_f),
    \]
    with the summand associated to \(f\) in grading \(\tfrac{1}{2}|f^{-1}(1)|\).
\end{proposition}
% \begin{proof}
%     The filtration is obtained by applying the functor $N_{C_2}^{G}$ to the filtration
%     \[X^\bullet=(\cdots \to 0\to\Sigma^{k\rho_2}\mathbb{S}[x]\xrightarrow{x}\mathbb{S}[x])\in\mathrm{Fil}(\mathrm{Mod}_{\Sp^G}(\mathbb{S}[x]))\]
%     and then applying $M\otimes_{\mathbb{S}[G\cdot x]}-$ pointwise. Passing to associated graded commutes with applying $M\otimes_{\mathbb{S}[G\cdot x]}-$ pointwise, so we may establish the claim in the universal case $M=\mathbb{S}[G\cdot x]$.

