\begin{example}
    Let $M$ be an $\mathbb{S}[C_4\cdot \bar{x}]$-module with $|\bar{x}|=k\rho_2$. Then $M$ admits a $\mathbb{S}[C_{4}\cdot \bar{x}]$-linear filtration with associated graded
    \[
    \mathrm{gr}_m=
    \begin{cases}
        M/(C_{4}\cdot \bar{x})&m=0\\
        \mathrm{Ind}_{C_2}^{C_4}\Sigma^{k\rho_2}M/\bar{x}&m=1\\
        \Sigma^{k\rho_{4}}M&m=2
    \end{cases}
    \]
\end{example}

\begin{example}
    Let $M$ be an $\mathbb{S}[C_8\cdot \bar{x}]$-module with $|\bar{x}|=k\rho_2$. Then $M$ admits a $\mathbb{S}[C_{8}\cdot \bar{x}]$-linear filtration with associated graded
    \[
    \mathrm{gr}_m=
    \begin{cases}
        M/(C_{8}\cdot \bar{x})&m=0\\
        \mathrm{Ind}_{C_2}^{C_8}\Sigma^{k\rho_2}\frac{M}{(\bar{x},\gamma \bar{x},\gamma^2 \bar{x})}&m=1\\
        \mathrm{Ind}_{C_4}^{C_8}\Sigma^{k\rho_4}M/(C_4\cdot \bar{x})\oplus \mathrm{Ind}_{C_2}^{C_8}\Sigma^{2k\rho_2}\frac{M}{(\bar{x},\gamma \bar{x})}&m=2\\
        \mathrm{Ind}_{C_2}^{C_8}\Sigma^{3k\rho_2}M/(\bar{x})&m=3\\
        \Sigma^{k\rho_{8}}M&m=4
    \end{cases}
    \]
\end{example}

\subsection{Nilpotence on equivariant quotients} We will use the filtration of Proposition \ref{prop:associatedgradedformula} to prove a generalization to the equivariant setting of the following well-known fact.

\begin{lemma}\label{lem:x^2actsbyzero}
    Let $R$ be an $\mathbb{E}_1$-ring in a stably monoidal $\infty$-category $(\mathcal{C},\otimes,\mathbf{1})$ and let $x\in[\Sigma^k\mathbf{1},R]_{\mathcal{C}}$. Then $x^2$ acts by zero on $R/x$ in $\mathrm{Mod}_{\mathcal{C}}(R)$. 
\end{lemma}
\begin{proof}
    Consider the diagram
    \[
    \begin{tikzcd}
        R\arrow[r]\arrow[d,"x"]&R/x\arrow[r]\arrow[d,"x"]\arrow[dl,dashed]&\Sigma R\arrow[d,"x"]\\
        R\arrow[r]\arrow[d,"x"]&R/x\arrow[r]\arrow[d,"x"]&\Sigma R\arrow[d,"x"]\arrow[dl,dashed]\\
        R\arrow[r]&R/x\arrow[r]&\Sigma R
    \end{tikzcd}
    \]
    in $\mathrm{Mod}_{\mathcal{C}}(R)$, where the rows are cofiber sequences, and we suppress shifts by $k$ for simplicity. The dashed arrows exist by universal property of the cofiber, and they imply that the composite in the middle column factors through the composite in the middle row, which is zero as it is a cofiber sequence.
\end{proof}

We generalize this to the equivariant setting by replacing cofibers $R/x$ with equivariant quotients $R/(G\cdot \bar{x})$.

\begin{proposition}\label{prop:nilpotenceequivariantcofiber}
    Let $R$ be a $G$-$\mathbb{E}_\infty$-ring with $\bar{x}_1,\ldots,\bar{x}_n\in\pi_{*\rho_2}^{C_2}R$, and let $M$ be an $R$-module. Then $N_{C_2}^H(\bar{x}_i)$ acts nilpotently on $\mathrm{Res}^G_H(M/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_n))$ in $\mathrm{Mod}_{\Sp^H}(\mathrm{Res}^G_HR)$ for all $C_2\subset H\subset G$ and $1\le i\le n$.
\end{proposition}
\begin{proof}
    We proceed by induction on $n$ and $|G|$. For induction on $n$, we use the fact that
\[M/(G\cdot \bar{x}_1,\ldots, G\cdot \bar{x}_n)=M/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_{n-1})\otimes_R R/(G\cdot \bar{x}_n)\]
and that if $N_{C_2}^H(\bar{x}_n)$ acts nilpotently on $M$, then it acts nilpotently on the tensor product
\[M/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_{n-1})=M\otimes_RR/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_{n-1})\]
by functoriality. We may therefore take $n=1$.

When $G=C_2$, this is Lemma \ref{lem:x^2actsbyzero}, using the identification of Example \ref{example:equivariantcofibers}. We may therefore take $|G|>2$ and assume the result for all $C_2\subset H\subsetneq G$ and all $n$. For any such subgroup $H$, we have $\mathrm{Res}^G_H (M/(G\cdot \bar{x}))=M/(H\cdot g\bar{x}\mid gH\in G/H)$. It follows then by the inductive hypothesis that $N_{C_2}^H(\bar{x})$ acts nilpotently on $\mathrm{Res}^G_H (M/(G\cdot \bar{x}))$.

    It remains to show that $N_{C_2}^G(\bar{x})$ acts nilpotently on $M/(G\cdot \bar{x})$. The filtration of Proposition \ref{prop:associatedgradedformula} factors the multiplication map
    \[N_{C_2}^G(\bar{x}):M\to M\]
    into a composite of $2^{n-1}$ maps, such that the cofiber of the $m$-th map is given by $\mathrm{gr}_m$. It follows that $M/(G\cdot \bar{x})$ is in the thick subcategory in $\mathrm{Mod}(R)$ spanned by $M/N_{C_2}^G(\bar{x})$ and the $\mathrm{gr}_m$'s for $0<m<2^n$. The class $N_{C_2}^G(\bar{x})^2$ acts by zero on the ordinary cofiber $M/N_{C_2}^G(\bar{x})$ by Lemma \ref{lem:x^2actsbyzero}, so it suffices to show that $N_{C_2}^G(\bar{x})$ acts nilpotently on each of the $\mathrm{gr}_m$'s for $0<m<2^n$. In this case, up to shifts, $\mathrm{gr}^m$ is of the form $\mathrm{Ind}_H^G\mathrm{Res}^G_H(M)/(H\cdot S)$, for $H$ a proper subgroup, and $S$ a set of variables containing $G/H$ conjugates of $\bar{x}$. This therefore follows by the inductive hypothesis.
\end{proof}

With an eye toward applying our Theorem \ref{thm:mainalgebraicthm}, we will need a similar nilpotence statement replacing $x_i$ by any element in the augmentation ideal.

\begin{corollary}\label{cor:nilpotentfromaugideal}
    Let $M\in\mathrm{Mod}_{\Sp^G}(R)$, and let $\bar{x}$ be any class in the ideal
    \[(G\cdot\bar{x}_1,\ldots,G\cdot\bar{x}_n)\subset\pi_{*\rho}^{C_2}R\] generated by the classes $g\bar{x}_j$ for all $1\le j\le n$ and all $g\in G/C_2$. Then $N_{C_2}^H(\bar{x})$ acts nilpotently on $\mathrm{Res}^G_HM/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_n)$ in $\mathrm{Mod}_{\Sp^H}(\mathrm{Res}^G_HR)$ for all $C_2\subset H\subset G$.
\end{corollary}
\begin{proof}
    The class $\bar{x}$ can be written as a linear combination of monomials in the generators $g \bar{x}_j$. Applying the norm $N_{C_2}^H(-)$ to this sum yields a linear combination of transfers of norms of monomials in the generators $g \bar{x}_j$. This concludes the proof as, by Proposition \ref{prop:nilpotenceequivariantcofiber}, each term in this sum acts nilpotently on $\mathrm{Res}^G_HM/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_n)$. 
\end{proof}

\subsection{Thick subcategories} For a $G$-$\mathbb{E}_\infty$-ring $R$ and an $R$-module $M$, we use the notation
\[\mathrm{Thick}^R(M)\]
to denote the thick subcategory of $\mathrm{Mod}_{\Sp^G}(R)$ generated by $M$.


\begin{proposition}\label{prop:thicksubcatsprop}
Let $R\in Sp^{G}$ be a $G$-$\mathbb{E}_\infty$-ring and $M\in\mathrm{Mod}_{\Sp^G}(R)$. Suppose $\bar{x}_1,\ldots,\bar{x}_n\in \pi_\star^{C_2}R$ have the property that the maps
\[N_{C_2}^H(\bar{x}_i):\Sigma^{|N_{C_2}^H(\bar{x}_i)|}M\to M\]
are nilpotent in $\mathrm{Mod}_{\Sp^H}(\mathrm{Res}^G_HR)$ for all $1\le i\le n$ and $C_2\subset H\subset G$. Then
\[M\in \mathrm{Thick}^R_{H\subset G}\big(G/H_+\otimes M/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_n)\big)\]
\end{proposition}

\begin{proof}
Our proof closely follows that of Proposition \ref{prop:nilpotenceequivariantcofiber}. We reduce as before to the case $n=1$ and set $\bar{x}:=\bar{x}_1$. When $G=C_2$, the result is a standard argument using that thick subcategories are closed under retracts. We may therefore assume that the result is known at $C_2\subset H\subsetneq G$, for all $n$.

Since $N_{C_2}^G(\bar{x})$ acts nilpotently on $M$, it follows that
\[M\in \mathrm{Thick}^R_{H\subset G}(G/H_+\otimes M/N_{C_2}^G(x)).\]
The filtration of Proposition \ref{prop:associatedgradedformula} implies that
\[M/N_{C_2}^G(x)\in\mathrm{Thick}^R(\mathrm{gr}_m)_{0<m<2^n},\]
so it suffices to show that $\mathrm{gr}_m\in \mathrm{Thick}^R_{H\subset G}\big(G/H_+\otimes M/(G\cdot \bar{x})\big)$ for all $0<m<2^n$. In this case, up to shifts, $\mathrm{gr}_m$ is of the form $\mathrm{Ind}_H^G\mathrm{Res}^G_H(M)/(H\cdot S)$, for $C_2\subset H\subsetneq G$ and $S$ a set of variables containing $G/H$-conjugates of $\bar{x}$. The class $N_{C_2}^H(\bar{x})$ acts nilpotently on $\mathrm{Res}^G_HM$ by assumption and therefore the same is true for all of its $G/H$-conjugates. By functoriality, these classes also act nilpotently on the quotient $\mathrm{Res}^G_H(M)/(H\cdot S)$. It follows by the induction hypothesis that 
\[\mathrm{Res}^G_H(M)/(H\cdot S)\in\mathrm{Thick}^{\mathrm{Res}^G_H(R)}_{K\subset H}(H/K_+\otimes \mathrm{Res}^G_H(M/(G\cdot\bar{x}))),\]
since $\mathrm{Res}^G_H(M/(G\cdot\bar{x}))$ is of the form $\big(\mathrm{Res}^G_H(M)/(H\cdot S)\big)/(H\cdot S')$ for $S'$ some set of variables containing $G/H$-conjugates of $\bar{x}$. Since the left adjoint 
\[\mathrm{Ind}_H^G:\mathrm{Mod}_{\Sp^H}(\mathrm{Res}^G_HR)\to\mathrm{Mod}_{\Sp^G}(R)\]
is exact, it follows that
\[\mathrm{Ind}_H^G\mathrm{Res}^G_H(M)/(H\cdot S)\in\mathrm{Thick}^R_{H\subset G}(G/H_+\otimes M/(G\cdot \bar{x})),\]
completing the induction.\qedhere
