\section{The $\bpgm{m}$'s are \emph{fp}-spectra}\label{sec:fpsection}
In this section, we carry out an induction argument to show that $\bpgm{m}^H$ is an \emph{fp} spectrum for all $H\subset G$ and $m\ge0$. When $m=0$, this always gives the Eilenberg--Maclane spectrum $H\Z$, which is an \emph{fp} spectrum, and we can reduce to this case using Proposition \ref{prop:thicksubcatsprop}. This requires us to know that the norms of the classes $\overline{t}_i^G\in \pi_{*\rho_2}^{C_2}BP^{(\!(G)\!)}$ act nilpotently on $\bpgm{m}$ for $1\le i\le m$. Algebraically, this is a consequence of Theorem \ref{thm:mainalgebraicthm}, and we lift this to the spectrum level in this section.

Up to taking powers, modding out by the ideal $(2,v_1,\ldots,v_{h})$ is realized on the spectrum level by tensoring with a finite spectrum $K$ of chromatic type $h+1$. Theorem \ref{thm:mainalgebraicthm} states that, up to raising to powers, the classes $\overline{t}_i^G$ lie in the ideal $(G\cdot \overline{t}_{m+1}^G,\ldots,G\cdot \overline{t}_{h}^G)$ after modding out by $(2,v_1,\ldots,v_{h})$, which takes the following form on the spectrum level. In the following, recall from \cite[Theorem 2.28]{HK} that, given a choice of $v_i$ generators in $BP_*$, there exist unique lifts $\bar{v}_i\in\pi_{(2^i-1)\rho}^{C_2}BP_\R$ along the restriction map.

\begin{proposition}\label{prop:ticlasses}
Let $K$ be a finite, homotopy commutative $C_2$ ring spectrum such that $i^*_eK$ has chromatic type $h+1$. Then, for all $i\le m$, there exists $N_i>>0$ and 
\[x_i\in(G\cdot \overline{t}_{m+1}^G,\ldots,G\cdot \overline{t}_{h}^G)\subset\pi_{*\rho_2}^{C_2}BP^{(\!(G)\!)}\]
such that the unit map
\[\eta:\pi_{*\rho_2}^{C_2}BP^{(\!(G)\!)}\to \pi_{*\rho_2}^{C_2}(BP^{(\!(G)\!)}\otimes K)
\]
satisfies $\eta(\overline{t}_i^{N_i})=\eta(x_i)$.
\end{proposition} 
\begin{proof}
We first note that each of the elements $2,\overline{v}_1,\ldots,\overline{v}_{h}$ is nilpotent in the ring $\pi_{*\rho_2}^{C_2}(BP^{(\!(G)\!)}\otimes K)$, since for each $0\le i\le h$, the $C_2$-spectrum
\[(\mathrm{Res}^G_{C_2}BP^{(\!(G)\!)}\otimes K)[\overline{v}_i^{-1}]\]
is contractible. Indeed, it is a module over 
\[(\BPR\otimes K)[\overline{v}_i^{-1}],\]
which is contractible since $\Phi^{C_2}(\overline{v}_i)=0$ and $\mathrm{Res}^G_e\BPR[\overline{v}_i^{-1}]=BP[v_i^{-1}]$, and $BP[v_i^{-1}]$ is Bousfield equivalent to the Johnson-Wilson theory $E(i)$. It follows that, for all $0\le i\le h$, there exist $k_i>>0$ such that $\eta(\overline{v}_i^{k_i})=0$. Moreover, since $BP^{(\!(G)\!)}\otimes K$ is homotopy commutative, the ring $\pi_{*\rho_2}(BP^{(\!(G)\!)}\otimes K)$ is graded-commutative, so if $x\in (2,\bar{v}_1,\ldots,\bar{v}_{h})$, then $\eta(x)$ is nilpotent.

 By Theorem \ref{thm:mainalgebraicthm}, for all $1\le i\le m$, there exists $n_i>>0$ such that
\[\overline{t}_i^{n_i}=w_i+y_i,\]
for some $w_i\in (2,\overline{v}_1,\ldots,\overline{v}_{h})$ and $y_i\in (G\cdot \overline{t}_{m+1}^G,\ldots,G\cdot \overline{t}_{h}^G)$. 
 It follows then that $\eta(w_i^{M_i})=0$ for some $M_i>>0$, and by replacing $n_i$ with a larger power $N_i$, it follows that $\eta(\overline{t}_i^{N_i})=\eta(x_i)$, for some 
\[x_i\in (G\cdot \overline{t}_{m+1}^G,\ldots,G\cdot \overline{t}_{h}^G),\]
as claimed.
\end{proof}

\begin{example}
If $K$ is a finite (nonequivariant) homotopy commutative ring spectrum, both $\mathrm{inf}_e^{C_2}K$ and $N_e^{C_2}K$ work here. Such finite spectra $K$ of any chromatic type exist by work of Burklund \cite{burklundquotients}.
\end{example}

This puts us now in the situation to apply Proposition \ref{prop:thicksubcatsprop}. In the following, we let $K$ be a finite, homotopy commutative ring spectrum of type $h+1$. 

\begin{lemma}\label{lemma:nilpotentactiononbpgm}
Kor all $C_2\subset H\subset G$, $N_{C_2}^H(\overline{t_i}^G)$ acts nilpotently on \[\mathrm{Res}^G_H(\bpgm{m})\otimes \mathrm{inf}_e^HK\in\mathrm{Mod}_{\Sp^H}(\mathrm{Res}^G_HMU^{(\!(G)\!)})\]
for $1\le i\le m$.
\end{lemma}
\begin{proof}
By Proposition \ref{prop:ticlasses}, the unit map 
\[\eta:\pi_{*\rho}^{C_2}(MU^{(\!(G)\!)}_{(2)})\to \pi_{*\rho}^{C_2}(BP^{(\!(G)\!)}\otimes \mathrm{inf}_e^{C_2}K)\]
has the property that
\[\eta((\overline{t}_i^G)^{N_i})=\eta(x_i)\]
for some exponent $N_i$ and some 
\[x_i\in (G\cdot \overline{t}_{m+1}^G,\ldots,G\cdot \overline{t}_{h}^G)\in\pi_{*\rho}^{C_2}(MU^{(\!(G)\!)}_{(2)}),\]
for all $1\le i\le m$. Since $\mathrm{Res}^G_HBP^{(\!(G)\!)}\ip{m}\otimes N_{C_2}^H(\mathrm{inf}_e^{C_2}K)$ is a module over \[\mathrm{Res}^G_HBP^{(\!(G)\!)}\otimes N_{C_2}^H(\mathrm{inf}_e^{C_2}K)\] 
in $\mathrm{Mod}_{\Sp^H}(\mathrm{Res}^G_HMU^{(\!(G)\!)})$, it follows that the action of $N_{C_2}^H((\overline{t}_i^G)^{N_i})$ on \[\mathrm{Res}^G_H(BP^{(\!(G)\!)}\ip{m})\otimes N_{C_2}^H(\mathrm{inf}_e^{C_2}K)\]
is the same as that of $N_{C_2}^H(x_i)$.

We claim then that $N_{C_2}^H(x_i)$ acts nilpotently on
\[\mathrm{Res}^G_H(BP^{(\!(G)\!)}\ip{m})\otimes N_{C_2}^H(\mathrm{inf}_e^{C_2}K)\]
Indeed, this follows from from Corollary \ref{cor:nilpotentfromaugideal} by setting $R=MU^{(\!(G)\!)}$, $x=x_i$, and 
\[M=BP^{(\!(G)\!)}/(G\cdot \overline{t}_i^G | i>h)\otimes \mathrm{inf}_{H}^GN_{C_2}^H(\mathrm{inf}_e^{C_2}K),\]
so that 
\[\bpgm{m}\otimes \mathrm{inf}_{H}^GN_{C_2}^H(\mathrm{inf}_e^{C_2}K)=M/(G\cdot\overline{t}_{m+1}^G,\ldots,G\cdot\overline{t}_{h}^G),\]
and
\[\mathrm{Res}^G_HM/(G\cdot\overline{t}_{m+1}^G,\ldots,G\cdot\overline{t}_{h}^G)=\mathrm{Res}^G_H(BP^{(\!(G)\!)}\ip{m})\otimes N_{C_2}^H(\mathrm{inf}_e^{C_2}K).\]

We now consider the subcategory $\mathcal{T}_i\subset Sp^{H,\omega}_{(2)}$ consisting of those finite $2$-local $H$-spectra $X$ with the property that the class $N_{C_2}^H(\overline{t}_i^G)$ acts nilpotently on \[\mathrm{Res}^G_H\bpgm{m}\otimes X\]
in $\mathrm{Mod}_{\Sp^H}(\mathrm{Res}^G_HMU^{(\!(G)\!)})$. We observe that $\mathcal{T}_i$ is a thick tensor-ideal of $Sp^{H,\omega}_{(2)}$ and that  $N_{C_2}^H(\mathrm{inf}_e^{C_2}K)\in\mathcal{T}_i$ for all $1\le i\le m$. The two finite $H$-spectra $N_{C_2}^H(\mathrm{inf}_e^{C_2}K)$ and $\mathrm{inf}_e^H(K)$ are both of chromatic type $m|G|/2+1$ at each subgroup of $H$, in the sense of \cite{balmersanders}. By the determination of the topology of the Balmer spectrum in \cite{6author}, they therefore generate the same thick tensor-ideal, and we conclude that $\mathrm{inf}_e^H(K)\in \mathcal{T}_i$ for all $1\le i\le m$, proving the claim of the proposition.
\end{proof}

\begin{theorem}\label{thm:fptypem|G|/2}
$BP^{(\!(G)\!)}\ip{m}^H$ is fp of type $\le h$ for all $H\subset G$.
\end{theorem}
\begin{proof}
Fixing a type $h+1$ finite ring spectrum $K$ as above, it follows from Lemma \ref{lemma:nilpotentactiononbpgm} and Proposition \ref{prop:ticlasses} that
\[\mathrm{Res}^G_H(BP^{(\!(G)\!)}\ip{m}\otimes \mathrm{inf}_e^GK)\in \mathrm{Thick}_{L\subset H}(H/L_+\otimes H\underline{\Z}\otimes \mathrm{inf}_e^HK).\]
It follows then that 
\begin{align*}
  BP^{(\!(G)\!)}\ip{m}^H\otimes K&=(\mathrm{Res}^G_HBP^{(\!(G)\!)}\ip{m}\otimes \mathrm{inf}_e^HK)^H\\
  &\in\mathrm{Thick}(H\Z\otimes K)\\
  &\subset\mathrm{Thick}(H\F_2)
\end{align*}
where we use the fact that $H\Z$ is an \emph{fp} spectrum of type $\le h$.
\end{proof}

\section{$K$-theory and Euler Characteristics}\label{sec:moorespectra} For each $H\subset G$, the fixed point spectrum $\bpgm{m}^H$ now determines an object in the stable $\infty$-category $\fp{h}$ of \emph{fp} spectra of type $\le h$. The filtration of Section \ref{sec:filtration} allows us to give explicit relations between the $K$-theory classes of these spectra in $K_0(\fp{h})$. 

\subsection{K theory relations for fixed point spectra}

The regular representation sphere $S^{\rho_G}$ for a cyclic $2$-group $G$ has a straightforward cell structure. This allows us to determine the $K$-theory class of $RO(G)$ shifts of $X$ in terms of that of $X$. We use here the defining property of $K$-theory, which states that the $K$-theory class of an object with a finite filtration is the same as the $K$-theory of its associated graded. 

\begin{notation}
    In this section, for a set of spectra $T$, let $\langle T\rangle$ denote the smallest stable subcategory of spectra containing $T$.
\end{notation}

\begin{proposition}\label{prop:ktheoryofshift}
    Let $G=C_{2^n}$, $G'=C_{2^{n-1}}$ and $X\in \Sp^G$, then one has $K$-theory relations
    \[[(\Sigma^{m\rho_G}X)^G]=\begin{cases}
        [X^{G'}]-[X^G]&m=2k+1\\
        [X^G]&m=2k
    \end{cases}\]
    in $K_0(\langle X^H\rangle_{H\subset G})$
\end{proposition}
\begin{proof}
    The cell structure on $S^{\rho_G}$ determines a filtration
    \[
    \begin{tikzcd}
        S^1\arrow[r]&K_2\arrow[r]\arrow[d]&K_3\arrow[d]\arrow[r]&\cdots\arrow[r]&K_{2^n}=S^{\rho_G}\arrow[d]\\
        &L_2&L_3&&L_{2^n}
    \end{tikzcd}
    \]
    where $L_j=\mathrm{Ind}_{C_{2^{n-i}}}^{C_{2^n}}S^j$ for $2^{i-1}<j\le 2^{i}$, by \cite[Proposition 8.4.7]{HHRbook}. This gives a $K$-theory relation
    \[[(\Sigma^{\rho_G}X)^G]=-[X^G]+\sum\limits_{i=1}^n\sum\limits_{j=2^{i-1}+1}^{2^{i}}(-1)^j[X^{C_{2^{n-i}}}]\]
    The terms in the inner summation cancel in pairs except when $i=1$, leaving $[X^{G'}]$. The statement of the proposition then follows by induction on $m$.
\end{proof}

While an ordinary cofiber $M/x$ is in the stable subcategory $\langle M\rangle$, the cellular filtration of $S^{\rho_G}$ along with the filtration of Proposition \ref{prop:associatedgradedformula} immediately imply the following for equivariant cofibers $M/(G\cdot \bar{x})$.

\begin{proposition}\label{prop:equivariantcofiberstablesubcat}
    Let $M$ be an $\mathbb{S}[G\cdot \bar{x}]$-module for $|x|=k\rho_2$. For all $H\subset G$, the equivariant cofiber $M/(G\cdot\bar{x})^H$is in the stable subcategory $\langle M^H\rangle_{H\subset G}$.
\end{proposition}

We may now apply Proposition \ref{prop:associatedgradedformula} to compute the $K$-theory class $[M]$ in terms of $[M/(G\cdot x)]$. As in the notation of Proposition \ref{prop:associatedgradedformula}, we let $M$ be an $\mathbb{S}[G\cdot x]$-module with $|x|=k\rho_2$, and we ask here that $k$ be odd. The following relation is immediate from Propositions \ref{prop:associatedgradedformula} and \ref{prop:ktheoryofshift}.

\begin{corollary}\label{cor:ktheoryoffiltration}
    There is a $K$-theory relation
    \begin{align*}
        2[M^{G}]&=[M^{G'}]+[M/(G\cdot \bar{x})^{G}]\\
        &+\sum_{\substack{f\in\Map^{C_2}\big(G,\{0,1\}\big)/G \\\mathrm{nonconstant }}}\bigg[\Sigma^{n_f\cdot k\rho_{H_f}}\frac{M}{(H_f\cdot g\bar{x}\mid gH_f\in f^{-1}(0)/H_f)}^{H_f}\bigg]
    \end{align*}
    in $K_0(\langle M^H\rangle_{H\subset G})$.
\end{corollary}

\begin{example}
    With notation as above, setting $G=C_4$, there is a $K$-theory relation
    \begin{align*}
       2[M^{C_4}]&=[M^{C_2}]+[M/(C_4\cdot x)^{C_4}]\\
       &+[M/\bar{x}^e]-[M/\bar{x}^{C_2}] 
    \end{align*}
in $K_0(\langle M^H\rangle_{H\subset G})$.
\end{example}

\begin{example}
    With notation as above, setting $G=C_8$, there is a $K$-theory relation
    \begin{align*}
        2[M^{C_8}]&=[M^{C_4}]+[M/(C_8\cdot \bar{x})^{C_8}]\\
        &+[M/(\bar{x},\gamma \bar{x},\gamma^2 \bar{x})^e]-[M/(\bar{x},\gamma \bar{x},\gamma^2 \bar{x})^{C_2}]\\
        &+[M/(\bar{x},\gamma^2 \bar{x})^{C_2}]-[M/(C_4\cdot \bar{x})^{C_4}]\\
        &+[M/(\bar{x},\gamma \bar{x})^{C_2}]\\
        &+[M/\bar{x}^e]-[M/\bar{x}^{C_2}]
    \end{align*}
in $K_0(\langle M^H\rangle_{H\subset G})$.
\end{example}

\subsection{Torsion $K$-theory classes} Nonequivariantly, the cofiber sequence
\[\Sigma^{2(2^n-1)}BP\ip{n}\xrightarrow{v_n}BP\ip{n}\to BP\ip{n-1}\]
gives the $K$-theory relation
\[[BP\ip{n-1}]=0\in K_0(\ip{BP\ip{n}})\]
Equivariantly, we will use our filtration to show that the classes $[\bpgm{m-1}^H]$ are \emph{torsion} in $K_0(\ip{\bpgm{m}^H}_{H\subset G})$ for all $H\subset G$. It seems plausible that these $K$-theory classes are in fact zero, but we do not know this, and we won't need it. 

\begin{proposition}\label{prop:ktheoryclassestorsion}
    Let $M$ be an $\mathbb{S}[G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_n]$-module for $|x_i|=(2k_i+1)\rho_2$. If the classes
    \[[M/(G\cdot \bar{x}_1,\ldots,G\cdot \bar{x}_n)^H]\in K_0(\langle M^H \rangle_{H\subseteq G})\]
    are torsion for all $H\subseteq G$, then the classes 
    \[[M/(G\cdot \bar{x_1},\ldots,G\cdot\bar{x}_i)^H]\in K_0(\langle M^H \rangle_{H\subseteq G})\]
    are torsion for all $H\subseteq G$, for all $1\le i\le n$.
\end{proposition}
\begin{proof}
    We argue by induction on $|G|$. The base case $G=\{e\}$ follows from the fact that the restriction of $\bar{x}_i$ has even degree, and for a cofiber sequence of spectra
    \[\Sigma^{2k}X\to X\to Y,\]
    one has that $[Y]=0\in K_0(\langle X\rangle)$.

Suppose now that $|G|>1$, and note that, for $H\subset G$ a proper subgroup
\[M/(G\cdot \bar{x}_1,\ldots,G\cdot\bar{x}_i)^H=\begin{cases}M/(H\cdot g\bar{x}_1,\ldots,H\cdot g\bar{x}_i\mid gH\in G/H)&|H|>1\\M/(gx_1,\ldots,gx_i\mid gC_2\in G/C_2)
&H=\{e\}\end{cases}\]
so that by induction $M/(G\cdot \bar{x}_1,\ldots,G\cdot\bar{x}_i)^H$ is torsion in $K_0(\langle M^K\rangle_{K\subset H})$ and therefore also in $K_0(\langle M^H\rangle_{H\subset G})$. 

It therefore suffices to prove the claim for $M/(G\cdot \bar{x}_1,\ldots,G\cdot\bar{x}_i)^G$,
and we proceed by downward induction on $i$, the case $i=n$ being the assumption of the proposition. Let $i\ge1$, and assume then that the classes
    \[[M/(G\cdot \bar{x_1},\ldots,G\cdot\bar{x}_{i+1})^H]\in K_0(\langle M^H \rangle_{H\subseteq G})\]
    are torsion for all $H\subset G$. We set $N:=M/(G\cdot \bar{x_1},\ldots,G\cdot\bar{x}_{i})$, and apply Corollary \ref{cor:ktheoryoffiltration} replacing $M$ and $\bar{x}$ with $N$ and $\bar{x}_{i+1}$, respectively. This gives the relation
    \begin{align*}
        2[N^{G}]&=[N^{G'}]+[N/(G\cdot\bar{x}_{i+1})^{G}]\\
        &+\sum_{\substack{f\in\Map^{C_2}\big(G,\{0,1\}\big)/G \\\mathrm{nonconstant }}}\bigg[\Sigma^{n_f\cdot k\rho_{H_f}}\frac{N}{(H_f\cdot g\bar{x}_{i+1}\mid gH_f\in f^{-1}(0)/H_f)}^{H_f}\bigg]   
    \end{align*}
    in $K_0(\langle N^H\rangle_{H\subset G})$, and therefore also in $K_0(\langle M^H\rangle_{H\subset G})$ by Proposition \ref{prop:equivariantcofiberstablesubcat}. We will show that each term on the right hand side is torsion in $K_0(\langle M^H\rangle_{H\subset G})$, completing the induction.

    After applying Proposition \ref{prop:ktheoryofshift} to get rid of shifts in the third term, we see that every term in this summation is torsion by the induction hypothesis on $|G|$. The term $[N/(G\cdot\bar{x}_{i+1})^G]$ is torsion by the inductive hypothesis on $i$, so it remains to examine
    \[[N^{G'}]=[M/(G'\cdot\bar{x}_j,G'\cdot\gamma\bar{x}_j\mid 1\le j\le i)^{G'}]\]
    where $\g$ is a generator of $G$. This class is torsion in $K_0(\langle M^H\rangle_{H\subset G'})$ by the inductive hypothesis on $|G|$ and therefore also in  $K_0(\langle M^H\rangle_{H\subset G})$.
\end{proof}

We now specialize to $M=\bpgm{m}$ and obtain the following.

\begin{theorem}\label{thm:mainktheoryrelation}
    For all $H\subset G$, there is an equation
    \[|H|\cdot[BP^{(\!(G)\!)}\langle m\rangle^H]\equiv[BP^{(\!(G)\!)}\langle m\rangle^e]\in K_0(\fp{h})\]
    modulo torsion.
\end{theorem}
\begin{proof}
    Since 
    \[BP^{(\!(G)\!)}\langle m\rangle /(G\cdot \overline{t}_1^G,\ldots, G\cdot \overline{t}_m^G)^H=\Z\]
    for all $H\subset G$, and the cofiber sequence
    \[\Sigma^2 ku\to ku\to\Z\]
    implies that $[\Z]=0\in K_0(\fp{n})$ for all $n\ge1$, applying the previous proposition shows that 
    \[2[BP^{(\!(G)\!)}\langle m\rangle ^{C_{2^k}}]\equiv [BP^{(\!(G)\!)}\langle m\rangle^{C_{2^{k-1}}}]\]
    for all $1\le k\le n$, modulo torsion.
    Applying this inductively yields the result.
\end{proof}

\subsection{Euler Characteristics} Since $\Z$ is torsion free, Levy's Euler characteristic vanishes on torsion $K$-theory classes, and Theorem \ref{thm:mainktheoryrelation} already gives us the relation
\[|G|\cdot\chi_{\bpgm{m}^G}=\chi_{\bpgm{m}^e}.\]
We will in fact relate the Euler characteristics $\chi_{\bpgm{m}^e}$ and $\chi_{BP\ip{h}}$, by comparing their values on generalized Moore spectra. This hinges on the following result of Burklund--Levy.

\begin{theorem}[Burklund--Levy]\label{thm:burklundlevy}
    Let $X,Y\in\fp{h}$. Then $\chi_X=\chi_Y$ if and only if 
    \[\chi_X(\mathbb{S}/(2^{i_0},\ldots,v_n^{i_h}))=\chi_Y(\mathbb{S}/(2^{i_0},\ldots,v_h^{i_h}))\]
    for some generalized Moore spectrum $\mathbb{S}/(2^{i_0},\ldots,v_h^{i_h})$.
\end{theorem}
\begin{proof}
    Burklund--Levy show that the map
    \[\chi_{BP\ip{h}}:K_0(\Sp^\omega_{> h})\to\Z\]
    is an isomorphism rationally \cite{burklundlevy} (see \cite[Theorem 1.5, Proposition 7.8, and Remark 7.9]{levy}). Since $\chi_{BP\ip{h}}$ evaluated on any generalized Moore spectrum of type $h+1$ is nonzero, it follows also that the source is generated rationally by any generalized Moore spectrum. Since $\chi_X$ and $\chi_Y$ land in the torsion free abelian group $\Z$, the claim follows.
\end{proof}

\begin{lemma}\label{lemma:eulercharacteristicbpn}
If $\mathbb{S}/(2^{i_0},\ldots,v_n^{i_h})$ is a generalized Moore spectrum, then 
\[\chi_{BP\ip{h}}(\mathbb{S}/(2^{i_0},\ldots,v_h^{i_h}))=\prod\limits_{j=0}^hi_j\]
\end{lemma}
\begin{proof}
    This follows from the fact that
    \[\pi_*(BP\ip{h}\otimes \mathbb{S}/(2^{i_0},\ldots,v_h^{i_h}))=\Z[v_1,\ldots,v_h]/(2^{i_0},\ldots,v_h^{i_h})\]
    together with the formula of Lemma \ref{lem:introlemma}.
\end{proof}

For $\chi_{\bpgm{m}^e}$, we have the following related formula.

\begin{proposition}\label{prop:keyEulercharacteristicrelation}
    Let $\mathbb{S}/(2^{i_0},\ldots,v_{h}^{i_{h}})$ be a generalized Moore spectrum, where $h=m|G|/2$. Then one has
    \[\chi_{\bpgm{m}^e}(\mathbb{S}/(2^{i_0},\ldots,v_{h}^{i_{h}}))=\prod\limits_{j=0}^{|G|/2-1}\binom{jm}{m}_2\cdot\prod\limits_{k=0}^{h}i_k.\]
    In particular,
    \[\chi_{\bpgm{m}^e}=\prod\limits_{j=0}^{|G|/2-1}\binom{jm}{m}_2\cdot\chi_{BP\ip{h}}\]
\end{proposition}

\begin{proof}
    By regularity, one has
\[\pi_*(\bpgm{m}^e\otimes \mathbb{S}/(2^{i_0},\ldots,v_{h}^{i_{h}}))=\pi_*(\bpgm{m}^e)/(2^{i_0},\ldots,v_{h}^{i_{h}})\]
The formula $\sum_i\log_2|\pi_i(-)|$ is additive under short exact sequences of evenly graded abelian $2$-groups, so it follows from filtering by powers of the $v_i$'s that
\[\chi_{\bpgm{m}^e}(\mathbb{S}/(2^{i_0},\ldots,v_{h}^{i_{h}}))=\bigg(\prod\limits_{k=0}^{h}i_k\bigg)\cdot \dim_{\F_2}\frac{\pi_*^e\bpgm{m}}{(2,v_1,\ldots,v_{h})}\]
and we conclude by applying Corollary \ref{cor:bpgmodd}. The second statement now follows directly from Theorem \ref{thm:burklundlevy}.
\end{proof}

