\begin{corollary}\label{cor:fpgem|G|/2}
    $\bpgm{m}^H$ is \emph{fp} type $h$ for all $H\subset G$.
\end{corollary}
\begin{proof}
    By Theorem \ref{thm:fptypem|G|/2}, $BP^{(\!(G)\!)}\ip{m}^H$ is \emph{fp} type $\le h$. To see that $BP^{(\!(G)\!)}\ip{m}^H$ is not \emph{fp} type $<h$, we may assume for the sake of contradiction that there exists a generalized Moore spectrum
\[F:=\mathbb{S}/(2^{i_0},v_1^{i_1},\ldots,v_{h-1}^{i_{h-1}})\]
of chromatic type $h$ such that $BP^{(\!(G)\!)}\ip{m}^H\otimes F$ is $\pi$-finite. We may choose a $v_{h}$-self map $v:=v_{h}^{i_{h}}$ of $F$ that acts by zero on $\pi_*(BP^{(\!(G)\!)}\ip{m}^H\otimes F)$, since the latter is concentrated in finitely many degrees, and $v$ must have nonzero degree. Since $v$ is in even degree, this gives a short exact sequence
\[0\to \pi_*BP^{(\!(G)\!)}\ip{m}^H\otimes F\to \pi_*BP^{(\!(G)\!)}\ip{m}^H\otimes F/v\to \pi_*\Sigma^{2k+1}BP^{(\!(G)\!)}\ip{m}^H\otimes F\to0\]
for some $k$. Passing to Euler characteristics, this gives 
\[\chi_{BP^{(\!(G)\!)}\ip{m}^H}(F/v)=\chi_{BP^{(\!(G)\!)}\ip{m}^H}(F)-\chi_{BP^{(\!(G)\!)}\ip{m}^H}(F)=0\]
From Theorem \ref{thm:mainktheoryrelation}, we have that
\[\chi_{\bpgm{m}^e}(F/v)=|H|\cdot\chi_{BP^{(\!(G)\!)}\ip{m}^H}(F/v)=0\]
which contradicts Proposition \ref{prop:keyEulercharacteristicrelation}.
\end{proof}

\section{Chromatic localizations of $MU^{(\!(G)\!)}$-modules}\label{sec:telescope} In this section, we show that chromatic localizations force $MU^{(\!(G)\!)}$-modules to be Borel-complete. In other words, after applying chromatic localizations, there is no difference between taking genuine fixed points and taking homotopy fixed points of $MU^{(\!(G)\!)}$-modules. We also see that the fixed points of an $MU^{(\!(G)\!)}$-module satisfies the condition of the telescope conjecture.

\begin{proposition}\label{prop:chromaticlocalizations}
    Let $M\in\mathrm{Mod}(MU^{(\!(G)\!)})$. For all $h\ge0$, for all \[E\in\{K(h),T(h),L_h^f\mathbb{S},L_h\mathbb{S}\}\]
    the map
    \[\mathrm{inf}_e^G(E)\otimes M\to\mathrm{inf}_e^G(E)\otimes F(EG_+,M)\]
    is am equivalence of $G$-spectra. Moreover, the map $\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes M\to\mathrm{inf}_e^GL_h\mathbb{S}\otimes M$ is an equivalence of $G$-spectra.
\end{proposition}
\begin{proof}
It suffices to check that each of the maps induces an equivalence on geometric fixed points $\Phi^H$ for all $H\subset G$.

    For each $E\in\{K(h),T(h),L_h^f\mathbb{S},L_h\mathbb{S}\}$, the map
    \[\mathrm{inf}_e^G(E)\otimes M\to\mathrm{inf}_e^G(E)\otimes F(EG_+,M)\]
    induces an equivalence of underlying spectra since the functor $F(EG_+,-)$ restricts to the identity functor on underlying spectra. The map $\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes M\to\mathrm{inf}_e^GL_h\mathbb{S}\otimes M$ induces an equivalence on underlying spectra because $\mathrm{Res}^G_eM$ is an $MU$-module, and $MU$-modules satisfy the telescope conjecture at all heights.

    Applying $\Phi^H$ for $H\neq \{e\}$, one has that $\Phi^HM$ and $\Phi^HF(EG_+,M)$ are modules over $\Phi^HMU^{(\!(G)\!)}$. The ring spectrum $\Phi^HMU^{(\!(G)\!)}$ is an algebra over $\Phi^HMU^{(\!(H)\!)}=MO$, which is an $H\F_2$-algebra. Since each of the spectra in $\{K(h),T(h),L_h^f\mathbb{S},L_h\mathbb{S}\}$ are $H\F_2$-acyclic, applying $\Phi^H$ to any of the maps in question gives a map with both source and target equal to $0$, and therefore gives an equivalence.
\end{proof}

\begin{corollary}\label{cor:chromaticlocalizations}
  Let $M\in\mathrm{Mod}(MU^{(\!(G)\!)})$. For all $n\ge0$, $H\subset G$, and for all $L\in\{L_{K(h)},L_{T(h)},L_h^f,L_h\}$, the map
    \[L(M^H)\to L(M^{hH})\]
    is an equivalence of spectra. Moreover the map $L_h^f(M^H)\to L_h(M^H)$ is an equivalence of spectra.
\end{corollary}
\begin{proof}
    This is an immediate corollary of the previous proposition by use of the projection formula $(\mathrm{inf}_e^G(X)\otimes Y)^G\simeq X\otimes Y^G$, for $X\in\Sp$ and $Y\in\Sp^G$.
\end{proof}


\begin{theorem}
    The map $\bpgm{m}\to F(EG_+,\bpgm{m})$ induces an equivalence on $\underline{\pi}_i$ for all $i$ sufficiently large.
\end{theorem}
\begin{proof}
    Consider the following commutative square of $G$-spectra
   \[
    \begin{tikzcd}
        \bpgm{m}\arrow[d]\arrow[r]&\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes\bpgm{m}\arrow[d]\\
        F(EG_+,\bpgm{m})\arrow[r]&\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes F(EG_+,\bpgm{m})
    \end{tikzcd}
    \]
    The top map induces an isomorphism on $\underline{\pi}_i$ for all $i$ sufficiently large by \cite[Theorem 3.1.3]{hahnwilson} because $\bpgm{m}^H$ is an \emph{fp} spectrum of type $h$ for all $H$. The righthand map is an equivalence by Proposition \ref{prop:chromaticlocalizations}, so it suffices to show the bottom map induces an equivalence on $\underline{\pi}_i$ for all $i$ sufficiently large.

    We claim first that the bottom map may be identified with the map
    \[F(EG_+,\bpgm{m})\to F(EG_+,\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes\bpgm{m})\]
    Indeed this follows from the fact that the canonical maps
\[\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes F(EG_+,\bpgm{m})\to \mathrm{inf}_e^GL_h^f\mathbb{S}\otimes F(EG_+,\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes\bpgm{m}) \]
\[ F(EG_+,\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes\bpgm{m})\to \mathrm{inf}_e^GL_h^f\mathbb{S}\otimes F(EG_+,\mathrm{inf}_e^GL_h^f\mathbb{S}\otimes\bpgm{m})\]
are both equivalences. This may be checked as in the proof of Proposition \ref{prop:chromaticlocalizations}. The maps induce equivalences on underlying spectra, and each of the geometric fixed points $\Phi^H$ is a module over $\Phi^H(MU^{(\!(G)\!)})\otimes L_h^f\mathbb{S}$, which is zero as $\Phi^H(MU^{(\!(G)\!)})$ is an $H\F_2$-algebra.

    It remains to show that, for all $H\subset G$, the map of spectra \[\bpgm{m}^{hH}\to(L_h^f\bpgm{m})^{hH}\]
    induces an isomorphism on $\pi_i$ for $i$ sufficiently large. Since $\bpgm{m}^e$ is \emph{fp} of type $h$, it follows that $\bpgm{m}^e\to L_h^f\bpgm{m}^e$ induces an isomorphism on $\pi_i$ for $i$ sufficiently large, so that \[H^s(H;\pi_i\bpgm{m}^e)\to H^s(H;\pi_iL_h^f\bpgm{m}^e)\]
    is an isomorphism for $i$ sufficiently large, for all $s$. The claim now follows from the convergence of the homotopy fixed point spectral sequence.
\end{proof}

\begin{corollary}
    For all $H\subset G$, the spectrum $\tau_{\ge0}(\bpgm{m}^{hH})$ is an \emph{fp} spectrum of type $h$.
\end{corollary}
\begin{proof}
    By the theorem, the fiber of the map
    \[\bpgm{m}\to \tau_{\ge0}F(EG_+,\bpgm{m})\]
    is contained in the thick subcategory generated by $\{\mathrm{Ind}_H^G(H\underline{\Z})\}_{H\subset G}$, and therefore is an \emph{fp} spectrum of type $0$. The result then follows from the fact that $\fp{h}$ is a thick subcategory.
\end{proof}

