\subsection{Macroscopic hydrodynamic description}
\la{ss:macro}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% FIGURE %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{figure}[t]

