\begin{lem}\label{dualnumberlem}
    Let $A$ be the dg algebra $k[x]/(x^2)$ with $|x|=n \in \mathbb{Z}$. Then $A$ is reflexive and the unique simple $A$-module is a $\pvd$-generator.
\end{lem}
\begin{proof}It is easy to check that $A$ is derived complete at $k$. Hence for $n<0$, reflexivity follows from \Cref{lem: coconnective semisimple H^0 = reflexive} and the generation statement from \Cref{prop: keller-nicolas locality}. For $n\geq 0$, reflexivity follows from \Cref{connectiveDC} and the generation statement from \Cref{prop: Dfd generator connective case}.
\end{proof}

\begin{thm}\label{thm: proper graded gentle is reflexive}
For every proper graded gentle algebra $A$, $\per(A)$ and $\pvd{(A)}$ are reflexive dg categories. 
\end{thm}
\begin{proof}
  This follows from the repeated application of \Cref{thm:Gluing over Semiorthogonal decompositions} to \Cref{prop: semiorthogonal decomposition gentle}, combined with the fact that smooth proper dg categories are reflexive (\Cref{refexamples}) and the dual numbers are reflexive (\Cref{dualnumberlem}).
\end{proof}



The decomposition of \Cref{prop: semiorthogonal decomposition gentle} can also be used to show that the maximal semisimple quotient of any proper graded gentle algebra is a $\pvd$-generator:

% The following is shown in \cite{OpperPlamondonSchroll}
%\begin{thm}[{\cite[]{OpperPlamondonSchroll}}]
%Let $A$ be a proper graded gentle algebra. Then $A^!$ is properly generated relative to its induced augmentation.
%\end{thm}
% The proof goes through the derived completion functor $$F:\per B \rightarrow \per B^{!!} \simeq \per A^!,$$
% where $B=\Omega(A^{\vee})$. The dg algebra $B$ is quasi-isomorphic to a smooth graded gentle algebra. By an explicit computation of $F$ and using the classification of objects in $\per B$ from \cite{HaidenKatzarkovKontsevich} it is shown in loc.cit. that $F$ restricts to an equivalence $\cT \rightarrow \pvd{A}$ from a thick subcategory $\cT \subseteq \pvd{B} \subseteq \per B$, which implies $\pvd{A^!} \subseteq \per A^!$. Now \Cref{thm: proper graded gentle is reflexive} and  \Cref{thm: reflexivity via Koszul dual} imply the following. 
\begin{thm}
Let $A$ be a proper graded gentle algebra. Then $A/\rad(A)$ is a $\pvd$-generator for $A$. In other words, the thick subcategory of $\cD(A)$ generated by the simple $A$-modules coincides with $\pvd(A)$.
\end{thm}
\begin{proof} We know from \Cref{prop: semiorthogonal decomposition gentle} and its proof that $A$ is Morita equivalent to a proper graded gentle algebra $B$ which admits a semiorthogonal decomposition of the form
$$\per(B) \simeq \langle \per(B'), \per(k[x_1]/(x_1^2)), \dots, \per(k[x_n]/(x_n^2)) \rangle,$$
so that $B'$ and all graded dual numbers correspond to idempotent subalgebras of $B$. Moreover, $B'$ is a smooth proper graded gentle algebra. We claim that this is sufficient to conclude that $\pvd(B)$ is generated by $B/\rad(B)$. Indeed, the above semiorthogonal decomposition induces a semiorthogonal decomposition of $\pvd(B)$ (with orders reversed). On the other hand, by \Cref{dualnumberlem}, $\pvd(k[x_i]/(x_i^2))$ is generated by the simple $k[x_i]/(x_i^2)$-module and, as a thick subcategory of $\pvd(B)$ is generated by the simple $A$-module corresponding to the idempotent of $A$ associated with the subalgebra $k[x_i]/(x_i^2)$. Because $B'$ is smooth and proper (and hence reflexive), $\pvd(B')\simeq \per(B')$ is generated by the simple $B'$-modules. As before, these can equally be considered as simple $A$-modules which generate the thick subcategory of $\pvd(B)$ corresponding to $\pvd(B')$. Altogether, this shows that $B/\rad(B)$ generates $\pvd(B)$. 

Since $B$ is reflexive by \Cref{thm: proper graded gentle is reflexive} and derived complete (it is proper), is thus follows from \Cref{lem: reflexive and Koszul dual} that $B^!$ is reflexive and $\thick_{B^!} \left(B/\rad(B)\right)=\pvd(B^!)$. Hence, in order to show that $A/\rad(A)$ is a generator of $\pvd(A)$, it suffices by \Cref{lem: reflexive and Koszul dual} to show that there is an equivalence $\per(A^!) \simeq \per(B^!)$ which identifies $\thick_{A^!} A/\rad(A)$ with $\thick_{B^!} B/\rad(B)$. We recall from \Cref{prop: Koszul dual of Fukaya category}, that, up to passing to a category algebra, $A$ and $B$ are the Koszul duals of $\cF_A=\cF(\Gamma_A)$ and $\cF_B=\cF(\Gamma_B)$ for full formal arc systems $\Gamma_A, \Gamma_B \subseteq \Sigma$ on a graded marked surface $\Sigma$. In other words, $A^!$ and $B^!$ are the derived completions of $\cF_A$ and $\cF_B$ at the thick subcategories $\cB_A$ and $\cB_B$ generated by the respective canonical augmentations. But now we recall from \cite[Appendix C, Step 6 (3)]{OpperPlamondonSchroll} that under the equivalence $\per(\cF(\Gamma_A)) \simeq \per(\cF(\Gamma_B))$ from \Cref{fukmorita}, $\cB_A$ and $\cB_B$ are mapped to each other. Our assertion therefore follows from the Morita invariance of derived completion, cf.~\Cref{dercomprmk}(2). 
\end{proof}
 By \Cref{cor: Fukaya category as proper graded gentle}, we also obtain the following:
\begin{cor} If $\Sigma$ is a graded marked surface with at least one marked interval and without fully marked components of vanishing winding number, then $\Fuk(\Sigma)$ is reflexive. 
\end{cor}
\begin{ex}\label{exa: non reflexive Fukaya}
One cannot drop the assumption on the winding numbers. Indeed, the polynomial ring $k[x]$ with $x$ in degree zero is not reflexive by \Cref{noeththm}. The associated surface is an annulus with one marked interval and one fully marked component whose winding numbers vanish.
\end{ex}






