\begin{abstract}
We establish the existence of common fixed points for $C_q$-commuting self-mappings satisfying a generalized Gregus-type inequality with quadratic terms in $q$-starshaped subsets of normed linear spaces. Our framework extends classical fixed point theory through:
\begin{enumerate}[label=(\roman*)]
    \item Set-distance constraints $\delta(\cdot, [q, \cdot])$ generalizing norm conditions
    \item Compatibility via $C_q$-commutativity without full affinity requirements
    \item Reciprocal continuity replacing full map continuity.
\end{enumerate} 
Explicit examples (e.g., Example 2.6) demonstrate the non-triviality of these extensions. As applications, we derive invariant approximation theorems for best approximation sets. Our results generalize Nashine's work \cite{Nashine2007} and unify several known fixed point theorems.
\end{abstract}
\textbf{Keywords:} $C_q$-Commuting maps; $q$-affine maps; Gregus-type inequality; common fixed points; reciprocally continuous maps; invariant approximation.

\textbf{AMS(2000) Mathematics Subject Classification:} 47H10, 54H25.

\section{Introduction}
In 1980, Greg\'{u}s established the following existence theorem of fixed points for nonexpansive mappings in a Banach space.

\begin{theorem}[Greg\'{u}s, 1980]
Let $E$ be a closed convex subset of a Banach space $X$ and $T:X\to X$ a mapping that satisfies
\[
\|Tx-Ty\|\leq a\|x-y\|+b\|Tx-x\|+c\|Ty-y\|
\]
for all $x,y\in E$, $0<a<1$, $b\geq 0$, $c\geq 0$ and $a+b+c=1$. Then $T$ has a unique fixed point in $E$.
\end{theorem}

This result has many generalizations such as in Babu \textit{et al.} \cite{BabuPrasad2006}, \'{C}iri\'{c} \textit{et al.} \cite{CiricUme2003}, Fisher \textit{et al.} \cite{FisherSessa1986}, Murthy \textit{et al.} \cite{MurthyEtAl}, Pathak \textit{et al.} \cite{PathakEtAl1995,PathakFisher1999}.


\begin{definition}[Jungck \cite{Jungck1986}]
Let $E$ be a non-empty subset of a metric space $(X,d)$ and let $A$ and $T$ be two selfmaps on $E$. The pair $(A,T)$ is said to be:
\begin{enumerate}
    \item \textit{compatible} if $\lim\limits_{n\to\infty}d(ATx_{n},TAx_{n})=0$, whenever $\{x_{n}\}$ is a sequence in $X$ such that $\lim\limits_{n\to\infty}Ax_{n}=\lim\limits_{n\to\infty}Tx_{n}=t$, for some $t$ in $X$.

    \item \textit{reciprocally continuous} \cite{Pant1998} if $\lim\limits_{n\to\infty}ATx_{n}=At$ and $\lim\limits_{n\to\infty}TAx_{n}=Tt$ whenever $\{x_{n}\}$ is a sequence in $X$ such that $\lim\limits_{n\to\infty}Ax_{n}=\lim\limits_{n\to\infty}Tx_{n}=t$, for some $t$ in $X$.
\end{enumerate}
\end{definition}

Evidently any two continuous functions are reciprocally continuous, but its converse need not be true \cite{Pant1998}.

\begin{theorem}[Tas, Telci and Fisher \cite{TasEtAl1996}]
Let $A$, $B$, $S$ and $T$ be selfmaps of a complete metric space $(X,d)$ satisfying:
\begin{enumerate}
    \item $A(X)\subseteq T(X)$ and $B(X)\subseteq S(X)$;
    \item $[d(Ax,By)]^{2}\leq c_{1}$ max $\{[d(Sx,Ax)]^{2},\ [d(Ty,By)]^{2},\ [d(Sx,Ty)]^{2}\}$

    $\quad\quad\quad\quad\quad+c_{2}$ max $\{d(Sx,Ax)\ d(Sx,By),\ d(Ty,Ax)\ d(Ty,By)\}$

    $\quad\quad\quad\quad\quad+c_{3}$ $d(Sx,By)$ $d(Ty,Ax)$

    for all $x,y\in X$, where $c_{1},c_{2},c_{3}\geq 0$, $c_{1}+2c_{2}<1$, $c_{1}+c_{3}<1$, and
    \item the pairs $(A,S)$ and $(B,T)$ are compatible on $X$.
\end{enumerate}
If one of the mappings $A$, $B$, $S$ and $T$ is continuous then $A$, $B$, $S$ and $T$ have a unique common fixed point in $X$.
\end{theorem}

\begin{definition}
Let $E$ be a non-empty subset of a metric space $(X,d)$ and let $A$ and $S$ be two selfmaps on $E$. The pair $(A,T)$ is said to be \textit{weakly compatible} if $TAx=ATx$ whenever $Ax=Tx$, $x\in X$.
\end{definition}

Obviously, every compatible pair is weakly compatible but its converse need not be true \cite{JungckRhoades1998}.

Babu and Kameswari \cite{BabuKameswari2004} generalized Theorem 1.3 by relaxing the continuity of $A$, $B$, $S$, and $T$ and replacing compatible by weakly compatible in (iii). In fact, Kameswari \cite{Kameswari2008} proved the following theorem.

\begin{theorem}[Kameswari \cite{Kameswari2008}]
Let $A$, $B$, $S$ and $T$ be selfmaps of a complete metric space $(X,d)$ satisfying (i) and (ii) of Theorem 1.3 and
\begin{enumerate}
    \item[(iii)] the pairs $(A,S)$ and $(B,T)$ are compatible on $X$.
\end{enumerate}
If either of $A(X)$ or $B(X)$ or $S(X)$ or $T(X)$ is a complete subspace of $X$, then $A$, $B$, $S$ and $T$ have a unique common fixed point in $X$.
\end{theorem}

\begin{definition}[1.6]
Let $X$ be a normed linear space. A subset $E$ of $X$ is said to be:
\begin{enumerate}
    \item \textit{convex} if $\lambda x+(1-\lambda)y\in E$, whenever $x,y\in E$ and $0\leq\lambda\leq 1$;

    \item \textit{$q$-starshaped} if there exists at least one point $q\in E$ such that the line segment $[x,q]$ joining $x$ to $q$ is contained in $E$ for all $x,y\in E$ (that is, $\lambda x+(1-\lambda)q\in E$, whenever $x,y\in E$ and $0<\lambda<1$). In this case, $q$ is called the star-center of $E$.
\end{enumerate}
\end{definition}

Every convex set is starshaped with respect to each of its points, but its converse need not be true \cite{BabuAlemayehu}.
\begin{example}

 Example of a $q$-Starshaped Set that is Not Convex\\
Consider $\mathbb{R}^2$ with the Euclidean norm. Define the set:
\[
E = \overline{B}((0,0), 1) \cup \overline{B}((2,0), 1)
\]
where $\overline{B}((a,b), r)$ denotes the closed disk of radius $r$ centered at $(a,b)$. Explicitly:
\[
E = \left\{(x,y) : x^2 + y^2 \leq 1\right\} \cup \left\{(x,y) : (x-2)^2 + y^2 \leq 1\right\}.
\]
The \textbf{star-center} is $q = (1,0)$.

\paragraph{Verification of Properties}

\paragraph{(1) $q$-Starshapedness}
For any $p \in E$, the line segment $[q, p]$ lies in $E$:
\begin{itemize}
    \item \textbf{Case 1:} $p \in \overline{B}((0,0), 1)$ \\
    Parametrize $\gamma(t) = (1-t)(1,0) + t(x_p, y_p) = (1 + t(x_p-1), ty_p)$ for $t \in [0,1]$. Then:
    \[
    \|\gamma(t) - (0,0)\|^2 = [1 + t(x_p-1)]^2 + (ty_p)^2 \leq 1
    \]
    since $x_p^2 + y_p^2 \leq 1$ and the function is convex.

    \item \textbf{Case 2:} $p \in \overline{B}((2,0), 1)$ \\
    Parametrize $\gamma(t) = (1 + t(x_p-1), ty_p)$ for $t \in [0,1]$. Then:
    \[
    \|\gamma(t) - (2,0)\|^2 = [t(x_p-1) -1]^2 + (ty_p)^2 \leq 1
    \]
    since $(x_p-2)^2 + y_p^2 \leq 1$ and the function is convex.
\end{itemize}
Thus $E$ is $q$-starshaped with $q = (1,0)$.

\paragraph{(2) Non-Convexity}
Take $a = (0,1) \in E$ and $b = (2,1) \in E$. Their midpoint is:
\[
c = \frac{a + b}{2} = (1,1)
\]
But $(1,1) \notin E$ because:
\[
\|(1,1) - (0,0)\| = \sqrt{2} > 1 \quad \text{and} \quad \|(1,1) - (2,0)\| = \sqrt{2} > 1
\]

\paragraph{Geometric Illustration}
