    % Draw disks
    \fill[gray!20] (0,0) circle (1);
    \fill[gray!20] (2,0) circle (1);
    \draw[thick] (0,0) circle (1);
    \draw[thick] (2,0) circle (1);

    % Star-center q
    \fill[red] (1,0) circle (2pt) node[below] {$q = (1,0)$};

