\title{The Memorization Problem: \\ Can We Trust LLMs' Economic Forecasts?}
\author{Alejandro Lopez-Lira, Yuehua Tang, Mingyin Zhu\thanks{Contact information: Alejandro Lopez-Lira: alejandro.lopez-lira@warrington.ufl.edu;\phantom{ }Yuehua Tang: yuehua.tang@warrington.ufl.edu;\phantom{ } Mingyin Zhu: mingyin.zhu@warrington.ufl.edu}
