	\title{Localization of trigonometric polynomials and the Lev-Tselishchev lemma}
\author{Bochkov Ivan}
\address{SPB SU}
\email{bv1997@ya.ru}
\subjclass[2010]{60G55, 46E22, 47B32}
\keywords{quasi-bases, Schauder frames, trigonometric polynomials}
\begin{document}
	%\thanks{The author is indebted to results presented in Sections 3–5 were supported by the Russian Science Foundation under grant no. 22–11–00071}
	%
	\begin{abstract}
	The paper shows that the localization lemma used by N. Lev and A. Tselishchev in solving the problem of constructing quasi-bases from uniformly separated shifts of a function in the space $L^p (\mathbb R) $ for $ p > ( 1 + \sqrt 5 )/2 $, is not carried over to small $p$.
	\end{abstract} 

	\maketitle

In the series of recent works by N. Lev and A. Tselishchev \cite{LT, LT2}, the problem of the existence of a quasibasis (Schauder frame) in the space $L^p(\mathbb{R})$, $1 \le p \le 2$, consisting of shifts of one function, was studied. The main result of these works is that a unconditional quasibasis of this type does not exist for all $p$ in the considered interval, and for $p > (1 + \sqrt{5})/2$, there exists a quasibasis consisting of uniformly spaced shifts of a function.

A key role in the proof of the latter result is played by the following lemma. Let $Q = \sum_m q_m e^{imt}$, $t \in \mathbb{R}$, be a trigonometric polynomial. For $p \in [1, \infty)$, we set $|Q|_{A_p} = \left(\sum_m |q_m|^p\right)^{1/p}$. We also denote $S_N(Q) = \sum_{m=-N}^N q_m e^{imt}$ the partial Fourier sum for $ Q$.

\begin{lemmata}\label{LT} Let $p > (1 + \sqrt{5})/2$. Then for any $\epsilon > 0$, there exist trigonometric polynomials $P = \sum_m p_m e^{imt}$ and $Q = \sum_m q_m e^{imt}$, $t \in \mathbb{R}$, such that
	%\begin{itemize}

	\begin{Enumerate}
		\item $q_0 = 0$, $\max_j |q_j| < \epsilon$;
		\item $|P - 1|_{A_p} < \epsilon$;
		\item $|PQ - 1|_{A_p} < \epsilon$;
		\item $|PS_m(Q)|_{A_p} < C_p$ for some constant $C_p$ depending only on $p$.
	\end{Enumerate}
	%\end{itemize}
\end{lemmata}

The condition $p > (1 + \sqrt{5})/2$ in the main result of Lev-Tselishchev arises from this lemma. The authors of \cite{LT} noted that the validity of the lemma for all $p > 1$ would imply the existence of the desired Schauder frame for all $p > 1$.

The purpose of this paper is to demonstrate that for $p < (1 + \sqrt{5})/2$, this lemma is false, which means that the question of the Schauder frame from shifts of a function cannot be solved by this method. Thus, there is a unique value for which the validity of the lemma is unknown, namely $p = (1 + \sqrt{5})/2$.

\section{Notations}

$ \mathbb T $ is the unit circle identified with the interval $ [0 , 2\pi ] $. We use $ | M | $ for the Lebesgue measure of a subset $ M \subset  \mathbb T $. 

The notation $x = \theta(y)$ frequently used in the article means that $y = O(x)$. The notation $x \succeq y$ means that $x \ge Cy$ for some absolute constant $C$. In this paper, the exponent $p$ will be fixed, i.e., all constants may depend on it. 

We will naturally identify measurable complex-valued functions on the unit circle with their trigonometric series. Then, $ f_m $ stands for the Fourier coefficients of a function $ f \in L^1 ( \mathbb T ) $. By $|F|_{L^p}$ we denote the $L^p$ norm of $F$ on the circle, and by $|F|_{A^p}$ the $l^p$ norm of its Fourier coefficients. The classical Hausdorff-Young inequality states that $|F|_{A^p} \ge c_p |F|_{L^q}$, $ p \in [1,2] $, where $c_p$ is an absolute constant depending on $p$, and $q = p/(p-1) $ is the dual exponent to $p$. Then, for any integrable function $ f$ on the unit circle we define $S_N(f) = \sum_{m=-N}^N f_m e^{imt}$, the partial Fourier sum. Occasionally we use $| \cdot|_{l^p}$ for the $l^p$-norm.

For two functions $A, B$ on the unit circle, $A* B$ stands for their convolution.

For a segment of the circle $I$ and a function $F$, we denote by $\mathbb{E}_I(F)$ the average of $F$ over the segment $I$ with respect to the Lebesgue measure unless otherwise specified. By $\mathbb{E}(F)$ we denote the average of $F$ over the entire circle. By $\int F$ we denote the integral of $F$ over the entire circle.

By $\widehat{A}(m)$ we denote the $m$-th Fourier coefficient of the function $A$.

For vectors $u, v$, by $(u, v)$ we denote their scalar product.

By $\chi_k$ we denote the characteristic function of the segment $[-k, k]$. By $\chi_M$ for an arbitrary set $M$ we denote the characteristic function of this set.

By $\mathbb{VAR}(F)$ we denote the variation of the function $F$.

By $D_m$ we denote the $m$-th Dirichlet kernel, $D_m(x) = \sum_{k=-n}^n \frac{e^{ikx}}{2}$.

By $\Re F$ we denote the real part of the function $F$.

A compactly supported function $f$ on the real  line will sometimes be identified with a function $F$ on the circle as follows, $F(x) = \sum_{n \in \mathbb{Z}} f(x + 2\pi n)$. For a function $f$ defined on $[-\pi, \pi]$, this coincides with the classical understanding.

\section{Main result}

\begin{theorem}\label{main} Let $ 1 < p < \frac{1 + \sqrt{5}}{2} $, $q$ be the dual exponent, $C > C_p > 1$ be a sufficiently large real number, $1 > \delta > 0$ be an arbitrary fixed real number. Let $ \widetilde A \in A_1 $ be such that for a function $ \tilde B \in A_1 $ the following assumptions are obeyed,

	1) $\mathbb{E}(\widetilde{B}) = 1$,

	2) $\Re(\mathbb{E}(\widetilde{A})) \leq C^{-1}$,

	3) $\max_m | (1 - \widetilde{A}) S_m(\widetilde{B}) |_{A_p} \preceq 1$

	4) $| (1 - \widetilde{A}) \widetilde{B} |_{A_p} < 1 - \delta$.

Then
	$$\label{norm} \left| \widetilde{A} \right|_{A_p} \succeq C^{\frac{q(2-p)-1}{p}-\epsilon}$$ for any $ \epsilon > 0 $, where the constants here and in point 3) may depend on $p$.
	\end{theorem}

Notice that $\frac{q(2-p)-1}{p} > 0$ whenever $p < \frac{1 + \sqrt{5}}{2}$.

	From this, it follows that the statement of Lemma \ref{LT} is not satisfied for any $p \in (1, \frac{1 + \sqrt{5}}{2})$. Indeed, if it were satisfied for some $p$ in this interval, then for any given $C > 1$, taking sufficiently small $\epsilon$ and setting $\widetilde{A} = 1 - P$, $\widetilde{B} = 1 - Q$, we would obtain trigonometric polynomials $\widetilde{A}$ and $\widetilde{B}$ satisfying the conditions of the theorem for a given $D$. Indeed, conditions (i), (iii), and (iv) are checked directly, and condition (ii) follows from the fact that as the $A_p$ norm tends to 0, then $|\widetilde{\widehat{A}}(0)| \to 0$ as well, and hence $\Re(\mathbb{E} A) \to 0$.

The result of the theorem now obviously contradicts condition (ii) of the lemma.

First, we prove a lemma that will allow us to estimate the $A_p$-norm of a function through an object called a $T$-sequence in the article.

	\section{$T$-sequences and key Lemma}

	We call a $T$--system $\mathcal{TS}_m = (F_m, T_m)$ a tuple of a natural number $m$, a function $F_m$ on the unit circle $ \mathbb T $, and a finite set of disjoint segments $T_m = \{T_{m,1}, T_{m,2}, \ldots T_{m,k_m}\}$, $ T_{ m, j } \subset \mathbb T $, with the following properties:

	\begin{enumerate}
		\item $F_m = 0$ outside $T_m$,
		\item $\forall i \quad \int_{T_{m,i}} F_m = 0$,
		\item $\forall x \quad |F_m(x)| \leq 1$,
		\item $\forall j \quad |T_{m,j}| \leq \frac{2\pi}{2^m}$
		\item $\mathbb{VAR}(F_m) \prec k_m$.
	\end{enumerate}

	For a $T$ system, we denote $\mu_m = \frac{k}{2^m}$.

	A $T$-sequence is a sequence of $T$-systems ${\mathcal{TS}_0, \mathcal{TS}_1, \ldots, \mathcal{TS}_k, \ldots}$.

	\begin{lemma}\label{T-sec} Fix some real numbers $p, r, \alpha$, such that $2 > p, r > 1$, $2 - p > \alpha > 0$. Let for some real $M, C$, such that $M \geq 1$, $C \geq 1$, there exist a $T$-sequence $\mathcal{P}$ and a complex-valued function $A$ on the circle with the following properties:
		\label{eq:lemma2}
		\begin{enumerate}
			\item $|\mathbb{E}(F_i A)| \succeq \frac{\mu_i}{M}$,
			\item $\mu_i \preceq C^{-r}$,
			\item $\sum_i \mu_i \succeq \frac{M^{2-\alpha}}{C}$.
		\end{enumerate}

		Then $|A|_{A_p} \succeq C^{\frac{r(2-p)-1}{p}}$ (the implied constant may depend on $p, r, \alpha$).

	\end{lemma}
\begin{proof}

Given an $ j \in \mathbb N $ denote by $P_j(F)$ for a function $F\in L^1 ( \mathbb T ) $ the projection onto the space of functions whose Fourier transform has support on the union of segments $[-2^{j+1}, -2^j]$ and $[2^j, 2^{j+1}]$, that is, 

\[ P_j ( F ) (x) = \sum_{2^j \le |n| < 2^{j+1} } F_n e^{inx} . \]

Also denote $A_j = |P_j(A)|_{A_p}$. To prove the lemma, we need to estimate $\sum A_i$.

\begin{proposition} For any $ j \in \mathbb N $ \begin{equation}\label{Pr3} \left\|  P_j(F_m)\right\|_{L_2(\mathbb T ) }^2 \preceq \frac{\mu_m}{2^{|j-m|}}. \end{equation} \label{eq:prop3}
	\begin{proof}

Notice first that $\left\| P_j(F_m)\right\|^2_{L_2 (\mathbb T)} \leq \left\| F_m \right\|^2_{L^2(\mathbb T) } \leq \mu_m $, so it suffices to consider $|m-j| > 10 $.

For $j < m$, consider $T = 2^{j+2} F_m *\chi_{2^{-j-2}}$. We have
$$\left\|T\right\|_{{L_2}}^2 = 2^{2j} \sum_{ t \in \mathbb Z } 
		\left|
		\widehat{F_m}(t)
		\right|^2 \widehat{\chi_{2^{-j-2}}}(t)^2 \succeq \sum_{2^j \leq |t| < 2^{j+1}} \left|\widehat{F_m}(t) \right|^2 = \left\|P_j(F_m)\right\|_{{L_2}}^2 $$ 
		since $\left|\widehat{\chi_{2^{-j-2}}}(t) \right| \succeq 2^{-j} $ for $2^j \leq |t| < 2^{j+1}$. %Denote now for a point $x$ by $I_+(x)$ the segment from $T_m$ containing the point $(x + 2^{-j-2})$ (if there are none, it is an empty segment). Similarly, define $I_-(x)$, the segment from $T_m$ containing the point $(x - 2^{-j-2})$. 
According to assumption (2) from the definition of $T$-systems the means of $ F_m $ over the intervals of the system vanish, hence $ T (x ) $ vanishes whenever neither end of the interval $ ( x - 2^{-j-2}, x + 2^{-j-2} ) $ belongs to a segment from $ T_m $, and, if either of them does, the integration in the definition of $ T $ actually goes over that segment(s) only. These two observations imply, respectively, that, first, the meausure of the support of $T $ is $O(\mu_m)$, and second, that $|T(x)| \preceq 2^{j-m}$ for any $ x$. It follows that $\left\|  P_j(F_m)\right\|^2_{L_2(\mathbb T ) } \preceq \left\|T \right\|_{L_2}^2 \preceq \frac{\mu_m}{2^{2|j-m|}}$, as required.

		For $ j > m$, consider $T = F_m - 2^{j-2} F_m* \chi_{2^{2-j}}$. Then $ \left\|  P_j(F_m)\right\|^2_{L_2(\mathbb T ) } \preceq \left\|T\right\|_{L_2}^2$ similarly to the previous case. On the other hand, slicing the circle into equal $ \sim 2^{-j } $-intervals we have \[ \int_0^{2\pi} |T| = \int_0^{\frac{2\pi}{2^{j-3}}} \sum_{i=0}^{2^{j-3}-1} |T\bigl(x + \frac{i}{2^{j-3}}\bigr)| dx . \] Since $|T(x)| \leq \max_{|u-x| < 2^{2-j}} |F_m(u) - F_m(x)|$, we infer that the sum in the integrand is estimated above by $ \mathbb{VAR}(F_m)$. Taking into account that   $|T| \preceq 1$, we obtain 
		\[ \int_0^{2\pi} |T|^2 \prec \int_0^{2\pi} |T| \leq 2^{-j} \mathbb{VAR}(F_m) \preceq \frac{k_m}{2^j}, \] which is exactly \eqref{Pr3} in the case $ j > m $.
	\end{proof}
\end{proposition}

\begin{proposition} $\left|\widehat{F_m}(n) \right| \prec \frac{\mu_m}{2^{|j-m|}}$ for $2^j \leq |n| < 2^{j+1}$. \label{eq:prop4}
	\begin{proof}

		Note that $\int_0^{2\pi} |F_m| \preceq \mu_m$, so it suffices to consider $|m-j| > 10$.

		Fix an arbitrary $n$ such that $|n| \in [2^j, 2^{j+1})$. If $j \leq m$ then for an arbitrary $I \in T_m, I = [u,v]$, we have 
		$$ \left|\int_I F_m(x) e^{inx}\right| = \left| e^{inu} \int_I F_m(z)(e^{in(x-u)} - 1) + e^{inu} \int_I F_m(x)\right| \preceq |n| |I|^{2}, $$ 
hence $|\widehat{F_m}(n)| \preceq k_m 2^{j-2m} = \mu_m 2^{ j-m } $, as required.

For $j \geq m$, we use \cite[Vol. I. Theorem 4.12]{Zygmund} according to which $ | \hat{f}(n) |\preceq  \mathbb{VAR}(f) /|n| $ for any function $ f $ of bounded variation. Applied to $ f = F_m $ it gives that $|\widehat{F_m}(n)| \le  \mathbb{VAR}(F_m) 2^{-j }  \preceq k_m 2^{-j} =\frac{\mu_m}{2^{j-m}}$, as required.
	\end{proof}
\end{proposition}

