\begin{corollary}\label{convol}
	Let $\eta(-d, -c, c, d)\in \mathcal{PRS}_{\frac{|I|}{2^{600}}, 2^{600}|I|, 2^{600}|I|}$ , $d \preceq 1$. We will treat $\eta(a, b, c, d)$ as a function on the circle. Then there exist real numbers $\alpha_0, \alpha_1, \ldots$ such that $\sum |\alpha_i| \preceq d$ and 
\begin{equation}\label{Four} F \ast \eta(-d, -c, c, d) = \sum_{i=0}^{\infty} \alpha_i S_i(F) \end{equation} 
 for all trigonometric polynomials $ F $. 	
\end{corollary}

\begin{proof}
Let $\alpha_i = \widehat{\eta(-d, -c, c, d)}(i) - \widehat{\eta(-d, -c, c, d)}(i+1)$. Identity \eqref{Four} holds since  the right and left hand sides of it have the same Fourier coefficients,  the $k$-th Fourier coefficient being $ \sum_{i=k}^{\infty} \alpha_i \widehat{F}(k)$. Finally $\sum |\alpha_i| \preceq d$ by Proposition \ref{Fouriercoeff}. 
\end{proof}

\begin{corollary}\label{maxS}
	Let $G \in A_1$, $1 \leq a > b > 0, 2^{20}(a-b) > b$, and $\mu$ be a finite measure on the circle. Then 
\[\int |\mathcal{SK}_{a,b}(G)|^q d\mu \leq \max_n \int \left| S_n(G) \right|^q d\mu . \]  \end{corollary}

	\begin{proof}
In the current notation, $\mathcal{SK}_{a,b}(G) = \frac{1}{a+b} G \ast \eta(-a, -b, a, b)$. Since $S_n(G) \to G$ uniformly, it suffices to prove that 
\[ \int \left| S_n(G) \ast \eta (-a,-b,b,a) \right|^q d\mu \preceq a^q \max_{ i \le n } \int \left|S_i(G) \right|^q d\mu\] 
uniformly in $ n $. By Corollary \ref{convol}, $S_n(G) \ast \eta(-a,-b,b,a) = \sum_{i=0}^n \alpha_i S_i(G)$, hence by the triangle inequality in $ L^q ( d\mu ) $ we have $$\int \left| S_n(G) \ast \eta (-a,-b,b,a) \right|^q d\mu \preceq (\sum |\alpha_i|)^q \max_{i\le n } \int |S_n|^q d\mu \preceq a^q \max_n \int |S_n|^q d\mu $$ as required.
\end{proof}

\begin{lemma}\label{Disj1}
	Let a disjoint set of segments $\mathcal{M}$ be chosen on the circle, such that the lengths of any two of them differ by no more than a factor of 2. Then $\sum_{I \in \mathcal{M}} \mathcal{SAI}(I) \preceq 1$.
\end{lemma}

\begin{proof}
	Denote the length of any of the segments $\mathcal{M}$ by $l$. Let us also denote by $\mathcal{P}_l$ the set of such pairs $(a, b)$ that $\eta(-a, -b, b, a) \in \mathcal{PRS}_{\frac{l}{2^{1000}}, 2^{1000}l, 2^{1000}l}$. Then
\begin{multline*} \sum_{I \in \mathcal{M}} \mathcal{SAI}(I) \preceq \frac{1}{l^2} \int_{\mathcal{P}_l} \int_{y \in \mathbb{T}} |\mathbb{E}(y-a, y-b, y+b, y+a)B|^q |1-A(x)|^q dx \preceq \\
\preceq \frac{1}{l^2} \int_{(a, b) \in \mathcal{P}_l} \int |\mathcal{SK}_{a,b}(B)(x)|^q |1-A(x)|^q dx \preceq \frac{1}{l^2} \int_{(a, b) \in \mathcal{P}_l} \max_n \left\| S_n(B)(1-A) \right\|_{L_q}^q
\end{multline*}  by Corollary \ref{maxS}, since $\int |1-A|^q < \infty$. But by the Hausdorff-Young inequality and condition 3 of the theorem, $1 \succeq \left| S_n(B)(1-A)\right|_{A_p} \succeq \left\| S_n(B)(1-A)\right\|_{L_q} $ for any $ n$, whence $$\frac{1}{l^2} \int_{(a, b) \in \mathcal{P}_l} \max_n \left\|S_n(1-A)\right\|_{L_q}^q \preceq \frac{1}{l^2} \int_{(a, b) \in \mathcal{P}_l} \preceq 1,$$ as required.
\end{proof}

\begin{proposition}\label{doubling}
		Let $a, b, c > 0$, and $2a < c$. Then $FB_{a, b, c}(z) \preceq FB_{a, b, \frac{c}{2}}(z)$.
