		\int_{t \in \mathcal{M}, \eta(a, b, y - u, y - v) \in \mathcal{SYMS}_t} |\mathbb{E}(a, b, y - u, y - v)B|  + \\
		\int_{t \in \mathcal{M}, \eta(y - u, y - v, a, b) \in \mathcal{SYMS}_t} |\mathbb{E}(y - u, y - v, a, b)B| +\\
		\int_{t \in \mathcal{M}, \eta(y + v, y + u, a, b) \in \mathcal{SYMS}_t} |\mathbb{E}(a, b, y + v, y + u)B| + \int_{t \in \mathcal{M}, \eta(y + v, y + u, a, b) \in \mathcal{SYMS}_t} |\mathbb{E}(y + v, y + u, a, b)B|).
\end{multline*} 
\end{proposition}
		\begin{proof}
			Note that if $a < b < c < d < e < f$, then $\eta(a, b, c, d) + \eta(c, d, e, f) = \eta(a, b, e, f)$. Consider cases depending on the magnitude of $v$.
			\begin{enumerate}
				\item If $v \ge \frac{|I|}{6}$, then for $|t| \le \frac{|I|}{30}$, $t - \frac{u - v}{2} \in [-v, v]$ and $t + \frac{u - v}{2} \in [-v, v]$, respectively.
				$$\eta(y - u, y - v, y + u, y + v) =$$
				$$\eta(y - u, y - v, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2}) +$$
				$$\eta(y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2}, y + v, y + u),$$
				and thus
				$$|\mathbb{E}(y - u, y - v, y + v, y + u)B| \prec$$
				$$|\mathbb{E}(y - u, y - v, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2})B| +$$
				$$|\mathbb{E}(y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2}, y + v, y + u)B|.$$

				Denote by $\mathcal{IT}$ the set of such $t \in \left[-\frac{|I|}{30}, \frac{|I|}{30}\right]$ that $y + \frac{t - \frac{u + v}{2}}{2} \in \mathcal{M}$ and $y + \frac{t + \frac{u + v}{2}}{2} \in \mathcal{M}$. Note that $|\mathcal{IT}| \ge \frac{|I|}{60} - \frac{|I|}{99} \succeq |I|$. Hence,
				$$\mathbb{E}(y - u, y - v, y + v, y + u)B \preceq$$
				$$\frac{1}{|\mathcal{IT}|} \int{t \in \mathcal{IT}}(|\mathbb{E}(y - u, y - v, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2})B| +$$
				$$|\mathbb{E}(y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2}, y + v, y + u)B|) \preceq D(u, v),$$
				which was to be shown.

				\item If $v \le \frac{|I|}{6}$, then for $|t| \ge \frac{2|I|}{5}$, $t - \frac{u - v}{2} \notin [-v, v]$ and $t + \frac{u - v}{2} \notin [-v, v]$, respectively. Assume $y$ is in the left half of the segment, the other case is symmetric.

				Then for $t \ge \frac{2}{5}$,
				$$\eta(y - u, y - v, y + v, y + u)B =$$
				$$\eta(y - u, y - v, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2}) -$$
				$$\eta(y + v, y + u, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2}),$$
				and thus
				$$|\mathbb{E}(y - u, y - v + y + v, y + u)B| \preceq$$
				$$|\mathbb{E}(y - u, y - v, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2})B| +$$
				$$|\mathbb{E}(y + v, y + u, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2})B|.$$

				Denote by $\mathcal{IT}$ the set of such $t \in \left[\frac{2|I|}{5}, \frac{|I|}{2}\right]$ that $y + \frac{t - \frac{u + v}{2}}{2} \in \mathcal{M}$ and $y + \frac{t + \frac{u + v}{2}}{2} \in \mathcal{M}$. Then $|\mathcal{IT}| \ge \frac{|I|}{40} - \frac{|I|}{99} \succeq |I|$ and
				$$|\mathbb{E}(y - u, y - v, y + v, y + u)B|
				\preceq$$
				$$\frac{1}{|\mathcal{IT}|} \int_{t \in \mathcal{IT}}(|\mathbb{E}(y - u, y - v, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2})B| +$$
				$$|\mathbb{E}(y + v, y + u, y + t - \frac{u - v}{2}, y + t + \frac{u - v}{2})B|) \preceq D(u, v),$$
				which was to be shown.
			\end{enumerate}
		\end{proof}

	\begin{corollary}\label{measu}
