			We call a \bfseries signature \mdseries a quadruple $(len, w, l, r)$.

			\begin{lemma}
				Fix an arbitrary $\epsilon > 0$. Then for arbitrary real numbers $l, r, L, R \ge 0$ such that $lL = rR$, there exists a finite set of signatures $\mathcal{S}i = (len_i, w_i, ls_i, rs_i)$ such that
				\begin{enumerate}
					\item $0 \le len_i, ls_i, rs_i \le \max(L, R)$
					\item $\sum |w_i| \le l + r$
					\item $\forall t$, $|l\chi{[0,L]} - \sum w_i \chi_{[ls_i, ls_i + len_i]}|(t) < \epsilon$
					\item $\forall t$, $|r\chi_{[0,R]} - \sum w_i \chi_{[rs_i, rs_i + len_i]}|(t) < \epsilon$.
				\end{enumerate}
				\begin{proof}
					Consider the set $\mathcal{M}$ of all possible quadruples $T = (l, r, L, R)$ such that $lL = rR$. We call $T \in \mathcal{M}$ good if it satisfies the conditions of the lemma. In particular, all quadruples with $r, l \ge \epsilon$ are good, as well as all quadruples with $l = 0$ or $r = 0$ are good, since for such quadruples we can take the empty set of segments. We also define an operator $\mathcal{H}: \mathcal{M} \to \mathcal{M}$ acting on the quadruple $T = (l, r, L, R)$ as follows:
					\begin{enumerate}
						\item if $L < R$, then $\mathcal{H}(T) = (r, l, R, L)$
						\item if $L \ge R$, then $\mathcal{H}(T) = (l, r - l, L - R, R)$
					\end{enumerate}

					\begin{proposition}
						For any quadruple $T$, there exists a natural number $n$ such that $\mathcal{H}^{(n)}(T)$ is good.
						\begin{proof}
							Denote $\mathcal{H}^{(k)}(T) = (r_k, l_k, R_k, L_k)$. Notice that for some $n_0$, $\min(l_{n_0}, r_{n_0}) < \epsilon$, since otherwise $r_{k+2} + l_{k+2} \le r_k + l_k - \epsilon$, and thus for some $m$, $r_m + l_m < 0$, which is impossible. If for a given $n_0$, $l_{n_0} = 0$ or $r_{n_0} = 0$, then $\mathcal{H}^{(n)}(T)$ is good. If this is not the case, then $r_{n_0+1} < \epsilon$. After that, applying $\mathcal{H}$ will subtract $r_{n_0+1}$ from $l$ until $l > r_{n_0+1}$. There can be only a finite number of such subtractions, so for some $m$, $l_m, r_m < \epsilon$, i.e., $\mathcal{H}^{(m)}(T)$ is good.
						\end{proof}
					\end{proposition}

					\begin{proposition}\label{HTT}
						If $\mathcal{H}(T)$ is good, then so is $T$.
						\begin{proof}
							\begin{enumerate}
								\item if $L < R$, then $\mathcal{H}(T) = (r, l, R, L)$. Take a set of signatures $\mathcal{S}_i = (len_i, w_i, r_i, l_i)$ for the quadruple $(r, l, R, L)$ from the lemma's condition and swap $rs_i$ and $ls_i$ in each signature for each $i$. The resulting set of signatures will be suitable for $T$, so $T$ is good.
								\item if $L \ge R$, then $\mathcal{H}(T) = (l, r - l, L - R, R)$. Take the signature $\mathcal{S} = (R, l, L - R, 0)$. Notice that $l\chi{[0,L]} - l\chi_{[L - R, L]} = l\chi_{[0, L - R]}$ and $r\chi_{[0, R]} - l\chi_{[0, R]} = (r - l)\chi_{[0, R]}$, and also the sum $r + l$ in $\mathcal{H}(T)$ is less than the corresponding sum in $T$ by exactly $l$. Thus, if we take a set of signatures for $\mathcal{H}(T) = (l, r - l, L - R, R)$ and add $\mathcal{S}$ to it, the resulting set will be suitable for $T$, so $T$ is good.
							\end{enumerate}
						\end{proof}
					\end{proposition}

					From the two propositions above, it follows that all quadruples are good, which completes the proof of Lemma \ref{HTT}.
				\end{proof}



			\begin{corollary}\label{SigSet}

				Fix an arbitrary $\epsilon > 0$. Then for arbitrary real $l, r, L, R \ge 0$ such that $lL = rR$, there exists a finite set of signatures $\mathcal{S}_i = (len_i, w_i, ls_i, rs_i)$ such that
				\begin{enumerate}
					\item $0 \le len_i, ls_i, rs_i \le \max(L, R), len_i \ge \frac{\min(L, R)}{3}$

					\item $\sum |w_i| \le 2(l + r)$,

					\item $\forall t$ $|l\chi{[0, L]} - \sum w_i \chi_{[ls_i, ls_i + len_i]}|(t) < \epsilon$

					\item $\forall t$ $|r\chi_{[0, R]} - \sum w_i \chi_{[rs_i, rs_i + len_i]}|(t) < \epsilon$.
				\end{enumerate}

				\begin{proof}
					We use Lemma \ref{HTT} and consider the set of signatures $\mathcal{S}'_i$ that it provides. If for some signature in it $len_i < \frac{\min(L, R)}{3}$, we replace it with 2 signatures $\left(\frac{1}{3} + len_i, w_i, l{i,1}, r_{i,1}\right)$ and $\left(\frac{1}{3}, -w_i, l_{i,2}, r_{i,2}\right)$, where
					\begin{enumerate}
						\item If $l_i \ge \frac{1}{3}$, then $l_{i,1} = l_i - \frac{1}{3}$, $l_{i,2} = l_i - \frac{1}{3}$.

						\item If $l_i < \frac{1}{3}$, then $l_{i,1} = l_i$, $l_{i,2} = l_i + len_i$.

						\item Similarly (replacing $l_i, L$ with $r_i, R$) we define $r_{i,1}, r_{i,2}$.
					\end{enumerate}
					By doing this for all $i$, we obtain a set of signatures satisfying the condition of the corollary.
				\end{proof}
			\end{corollary}

			\begin{proposition}\label{sigfinal}

				Fix an interval $I$, a real $\beta$, $\frac{1}{2^{100}} \le \beta \le 2^{100}$, and $\epsilon > 0$. Then there exists a finite set of five-number sets ${\alpha_i, ac_i, bc_i, cc_i, dc_i}$ such that:
				\begin{enumerate}

					\item $0 \le ac_i, bc_i, cc_i, dc_i \le 2^{105}$

					\item $\sum_i |\alpha_i| \preceq |I|$

					\item $dc_i - cc_i = bc_i - ac_i \ge \frac{1}{2^{105}}$

					\item for any SO $\eta(a, b, c, d) \in OU(I) \cap \mathcal{SR}_\beta$, the estimate holds
					$$
					|\eta(a, b, c, d) - \sum_i \frac{\alpha_i}{b - a} \eta\left(a + (b - a)ac_i, a + (b - a)bc_i, c - (b - a)cc_i, c - (b - a)dc_i\right)| \succeq \epsilon
					$$
				\end{enumerate}
				Recall that
				$$
				OU(I) = {\eta(a, b, c, d): \eta(a, b, c, d) \in \mathcal{PRS}{\frac{|I|}{2^{300}}, \frac{(2^{200} + 1)|I|}{2^{200}}, \frac{|I|}{2^{200}}}, I \subset [b, c]},
				$$
				and $\mathcal{SR}_\beta$ means the set of such SST $\eta(a, b, c, d)$ that $\frac{b - a}{d - c} = \beta$.

				\begin{proof}
					Let $l = L = 1, r = \beta, R = \frac{1}{\beta}$ and choose a set of signatures $\mathcal{S}_i = (len_i, w_i, l_i, r_i)$ for $(l, r, L, R)$ by Corollary \ref{SigSet}. Take $\alpha_i = \frac{w_i}{len_i}, ac_i = ls_i, bc_i = ls_i + len_i, cc_i = rs_i, dc_i = rs_i + len_i$ and verify that such $\alpha, ac_i, bc_i, cc_i, dc_i$ are suitable.

					Properties 1-3 are checked by straightforward substitution of properties from Corollary \ref{SigSet}. Note that from these properties it also follows that $c - (b - a)cc_i > a + (b - a)bc_i$, i.e., the order in the parameters of the SO in point 4 is correct.

					To prove property 4, consider an arbitrary SO $\eta(a, b, c, d) \in OU(I) \cup \mathcal{SR}\beta$. Then
					$$
					\mathcal{D}(a, b, c, d) = \frac{1}{b - a}\chi_{[a, b]} - \frac{1}{d - c}\chi_{[c, d]} =
					$$
					$$
					\frac{1}{b - a}\left(\sum w_i \chi_{[a + (b - a)ls_i, a + (b - a)ls_i + len_i(b - a)]} - \sum w_i \chi_{[c + (a - b)rs_i, c + (a - b)rs_i + (a - b)len_i(d - c)]} + O\left(\frac{\epsilon}{|I|}\right)\right) =
					$$
					$$
					\frac{1}{b - a} \sum_i \alpha_i \mathcal{D}\left(a + (b - a)ac_i, a + (b - a)bc_i, c - (b - a)cc_i, c - (b - a)dc_i\right) + O\left(\frac{\epsilon}{|I|}\right).
					$$
					Hence
					$$
					\eta(a, b, c, d)(t) = \int_a^t \mathcal{D}(a, b, c, d) =
					$$
					$$
					\int_a^t \left(\frac{1}{b - a} \sum_i \alpha_i \mathcal{D}\left(a + (b - a)ac_i, a + (b - a)bc_i, c - (b - a)cc_i, c - (b - a)dc_i\right) + O\left(\frac{\epsilon}{|I|}\right)\right) =
					$$
					$$
					\sum_i \frac{\alpha_i}{b - a} \eta\left(a + (b - a)ac_i, a + (b - a)bc_i, c - (b - a)cc_i, c - (b - a)dc_i\right)(t) + O(\epsilon),
					$$
					which completes the proof.
				\end{proof}
			\end{proposition}

		\end{lemma}

\begin{lemma}

$|I|FI(I) \preceq \mathcal{SSI}(I)$ for any interval $I$.

Recall that $FI(I) = \frac{1}{|I|^4} \int_{\eta(a, b, c, d) \in OI(I)} |\mathbb{E}(a, b, c, d)B|^q$.
\end{lemma}

\begin{proof}

Fix a small $\epsilon > 0$.

$$
FI(I) = \frac{1}{|I|^4} \int_{\eta(a, b, c, d) \in OI(I)} |\mathbb{E}(a, b, c, d)B|^q \preceq \frac{1}{|I|^4} \int_{\frac{1}{10} \le \beta \le 10} \int_{\eta(a, b, c, d) \in OI(I) \cup \mathcal{SR}\beta} |\mathbb{E}(a, b, c, d)B|^q.
$$

Fix $\frac{1}{2^{100}} \le \beta \le 2^{100}$ and choose a set of sets ${\alpha_i, ac_i, bc_i, cc_i, dc_i}$ by Corollary \ref{sigfinal} for given $\beta$ and $\epsilon$.

Note that
$$
\int_{\eta(a, b, c, d) \in OI(I) \cup \mathcal{SR}_\beta} |\sum_i \frac{w_i}{b - a}\mathbb{E}(a + (b - a)ac_i, a + (b - a)bc_i, c - (b - a)cc_i, c - (b - a)dc_i)|^q \preceq \mathcal{SSI}(I),
$$
since $\eta(a + (b - a)ac_i, a + (b - a)bc_i, c - (b - a)cc_i, c - (b - a)dc_i) \in \mathcal{PRS}_{\frac{|I|}{2^{400}}, |I|2^{400}, |I|2^{400}}$ by the previous proposition, and the Jacobian of the change of variables
$$
(a, b, c) \to (a + (b - a)ac_i, a + (b - a)bc_i, c - (b - a)cc_i)
$$
is equal to $\theta(1)$ (exercise for the reader).

Now, to complete the proof of the lemma, it is sufficient to sum over $i$ and integrate over $\beta$, and then pass to the limit as $\epsilon \to 0$.
\end{proof}

	 \section{Completion of the proof of the theorem}

	Now we can formulate an analogue of Lemma \ref{Feuer}, necessary to complete the proof. Namely:

	\begin{lemma}\label{BSai}
		Let $I = [a, b]$ be an interval that fell into the dyadic decomposition tree at one of the phases, $I \in \mathcal{NL}$. Then $|I| |E_I B|^q \preceq_K \mathcal{SAI}(I)$.
	\end{lemma}

	\begin{proof}

		\begin{enumerate}

			\item Suppose the interval $I$ is not dense. Then by Proposition 24, its endpoints are balanced. We choose intervals $I_a, I_b$ from the definition of the balanced point for $a, b$ such that $\frac{|I|}{2^{200}} \leq |I_a|, |I_b| \leq \frac{|I|}{2^{210}}$. Consider the set $$U =\{ x < y \in I_a, z < t \in I_b, y - x > \frac{I_a}{100}, t - z > \frac{I_b}{100} \}$$ and consider $\mathcal{TI}(I) = \int_U |(T(t) - T(z)) - (T(y) - T(x))|^q$ (recall that $S = \int B, T = \int S$). Then $\mathcal{TI}(I) \succeq |(S(1) - (T(y) - T(x)))|^q \succeq |S(1) - S(0)|^q = |I|^q |E_I B|^q$ by the definition of a balanced point. On the other hand, $(T(t) - T(z)) - (T(y) - T(x)) = \int_{\eta(x, y, z, t)} B \preceq |I| \mathbb{E}(x, y, z, t) B$ and $U \subset OU(I)$, which means $\mathcal{TI}(I) \preceq |I|^q \int_U |\mathbb{E}(x, y, z, t) B|^q \preceq |I|^q \int_{OU(I)} |\mathbb{E}(x, y, z, t) B|^q = |I|^q F_I(I)$. Now by Lemmas 37 and 31, $|I| F_I(I) \preceq \mathcal{SSI}(I) \prec \mathcal{SAI}(I)$, hence $|I| |E_I B|^q \preceq \mathcal{SAI}(I)$.

			\item Now let us assume $I$ is dense. The interval has reached the last step of the algorithm, and in particular, this means that $1000KC \geq \mathbb{E}_I B \geq \frac{C}{1000K}$, since $A_0(I) \geq \frac{1}{1000}$, and it was not declared a leaf in previous steps. Consider the interval $I_1 = \left[ \frac{a + b}{2} - \frac{4}{K^2}, \frac{a + b}{2} - \frac{3}{K^2} \right]$. Suppose there exists a point $u$ in it such that $F_B\left( \frac{|I|}{2^{600}}, 2^{600} |I|, 2^{600} |I| \right) < \frac{C^q}{10^{10q} K^{10q}}$. Choose in this case an interval $I'$ from the definition of a balanced point for point $a$ of length between $\left[ \frac{1}{100K^2}, \frac{1}{K^2} \right]$. Reflect it with respect to point $u$, and obtain the interval $I''$. For a point $t$ in the interval $I'$, we will denote the reflected point as $t'$. By Lemma \ref{midpoint}, there exists a function $F$ such that in any interval $I_2$ of length $|I'|$, there exists a balanced point $p$ with $\mathcal{IF}(I_2) = S(p) = \int_U F(a, b) \frac{T(b) - T(a)}{b - a}$, and since $I'$ is chosen as an interval from the definition of a balanced point for $a$, then $\mathcal{IF}(I') = S(0)$. On the other hand,
			$$
			|\mathcal{IF}(I'') - \mathcal{IF}(I')| \preceq \int_U \left| \frac{T(a') - T(b') - (T(b) - T(a))}{b - a} \right| \preceq
			$$
			$$
			\int_U |E(a, b, b', a')| \preceq \left( F_B\left( \frac{|I|}{2^{600}}, 2^{600} |I|, 2^{600} |I| \right) \right)^{\frac{1}{q}} \leq \frac{C}{10^{10} K^{10}},
			$$
			where the penultimate inequality holds by the power means inequality.

			Choose now a balanced point $p \in I'', S(p) = \mathcal{IF}(I'')$. Then at this point, $|S(p) - S(a)| \preceq \frac{C}{K^{10}}$, that is, $|E_{[p, b]} B| = |S(b) - S(p)| \geq \left(1 - \frac{3}{K}\right) |S(b) - S(a)| = E_I B$, and on the other hand, $|p - b| \preceq \frac{b - a}{K^2}$. Thus, the interval $[p, b]$ satisfies the conditions for a subinterval described in step 5 of the algorithm, that is, the interval $[p, 1]$ will be placed in $\mathcal{AL}$ - in any case, the interval $I$ does not fall under the conditions of the lemma.

			\item If such a point $u$ does not exist, then
			$$
			\mathcal{SAI}(I) = \int_I F_B\left(\frac{|I|}{2^{600}}, 2^{600} |I|, 2^{600} |I|\right)(z) |1 - A(z)|^q , dz \succeq
			$$
			$$
			\int_{I_1} F_B\left(\frac{|I|}{2^{600}}, 2^{600} |I|, 2^{600} |I|\right)(z) |1 - A(z)|^q \succeq_K C^q \int_{I_1} |1 - A(z)|^q.
			$$
			But note that $\mathbb{E}I A < \frac{1}{2}$, and hence $\mathbb{E}{I_1} A < \frac{2}{3}$, otherwise the interval would have been declared a leaf at step 4 of the algorithm. Therefore, by the mean inequality,
			$$
			C^q \int_{I_1} |1 - A(z)|^q \succeq_K C^q |I|,
			$$
			and at the same time, $|\mathbb{E}_I B| \preceq_K 1$, which completes the proof of the lemma.

		\end{enumerate}
	\end{proof}

	Now we are ready to complete the proof of the theorem in the same way as in the particular case.

	Consider a successful phase of the algorithm. Fix some $p_1$, $\frac{1 + \sqrt{5}}{2} < p_1 < p$, $q_1 = \frac{p_1}{p_1 - 1}$, and also $\alpha$ such that $2 - p_1 > \alpha > 0$.

	Note that since by Lemma \ref{SumBal}, $\sum_{I \in \mathcal{NL}, A_0(I) \geq \frac{|I|}{10^{1000} K^{1000}}} \mathcal{BAL}(I) \succeq_K 1$, then for some $M_1$, it is true that
	$$
	\sum_{I \in \mathcal{NL}, A_0(I) \geq \frac{|I|}{10^{1000} K^{1000}}, \frac{1}{M_1} \geq DA(I, \frac{1}{10^{100} K^{100}}) \geq \frac{1}{2M_1}} |I| DA(I, \frac{1}{10^{100} K^{100}})^2 \succeq \frac{1}{C M_1^{\alpha}}.
	$$
	Take this $M_1$ and call the intervals from this set interesting. Denote the set of such intervals by $\mathcal{IS}$.

	Also note that if any two interesting intervals intersect, they differ in length by at least a factor of $\frac{3}{2}$. Thus, we can break the set of interesting intervals into 2 such that within each, any intersecting intervals differ in length by at least a factor of 2. For one of these 2 subsets of the partition, the same equality holds; we will narrow the set of interesting intervals to this subset. By $\mathcal{IS}_i$ we will denote interesting intervals of length from $\frac{2\pi}{2^i}$ to $\frac{2\pi}{2^{i+1}}$.

	 Let's now define the function $F_i$ as follows:

	\begin{enumerate}

		\item $F_i(x) = 0, x \notin \mathcal{IS}_i$.

		\item Define the function on some $I \in \mathcal{IS}_i$. In the definition of $DA(I, \frac{1}{10^{100}K^{100}})$, the maximum over subintervals is involved. Choose the subinterval $I_1$ where the maximum is achieved, and from all such, the shortest one. Then $F_i(x) = 1, x \in I_1, F_i(x) = c, x \in I \setminus I_1$,
		where the constant $c$ is chosen such that $\mathbb{E}_IF_i = 0$.

	\end{enumerate}

	It is easy to see that $\mathcal{TS}_i = (F_i, \mathcal{IS}_i)$ is a $T$-system. Let's verify that the condition of Lemma 2 is satisfied for sufficiently large $C$ for given numbers $p, r = q_1, \alpha, M = C^{p_1 - p}M_1, C$, as well as the $T$-sequence $\mathcal{P} = \{\mathcal{TS}_0, \mathcal{TS}_1, \mathcal{TS}_2, \ldots\}$ and function $A$.

	\begin{enumerate}

		\item First condition holds since $\mathbb{E}(F_i A) = \frac{1}{2\pi} \sum_{I \in \mathcal{IS}_i} |I| \mathbb{E}I(F_i A) \succeq_K \sum{I \in \mathcal{IS}_i} |I| \succeq \frac{\mu_i}{M}$.

		\item By Lemmas \ref{Disj1} and \ref{BSai} and Proposition \ref{BeqA}, $$1 \succeq_K \sum_{\mathcal{IS}i} \mathcal{SAI}(I) \succeq_K \sum_{\mathcal{IS}i} |I||E_IB|^q \succeq_K \sum_{\mathcal{IS}i} |I|C^q|E_IA|^q \succeq_K \sum_{\mathcal{IS}i} |I|C^q$$. Hence, $\mu_i \preceq \sum_{\mathcal{IS}_i} |I| \preceq_K C^{-q}$, i.e., $\mu_i \preceq C^{-q_1}$ for sufficiently large $C$, and second condition holds.

		\item $\sum_{I \in \mathcal{IS}i} |I|DA(I, \frac{1}{10^{100}K^{100}})^2 \succeq_K \frac{1}{CM_1^{\alpha}}$ by the definition of interesting intervals, hence $\sum_i \mu_i = \sum_{I \in \mathcal{IS}} |I| \succeq_K \frac{M_1^{2 - \alpha}}{C}$, i.e., $\sum_i \mu_i \ge \frac{M^{2 - \alpha}}{C}$ for sufficiently large $C$, so the last condition holds aswell.

	\end{enumerate}

	Applying Lemma \ref{T-sec} now, we obtain that $\left|A\right|_{A_p} \succeq C^{q_1(2 - p) - 1}$ for any $q_1 > q$, i.e., $ \left| A \right|_{A_p} \succeq C^{q(2 - p) - 1 - \epsilon}$ for any $\epsilon > 0$ for sufficiently large $C$, which completes the proof of Theorem \ref{main}.

The condition of Theorem \ref{main} can be somewhat weakened. Here is one of the possible variants.

	\begin{proposition}

		Let $\delta > 0$ be a fixed positive number, and let $F: \mathbb{R} \to \mathbb{R}$ such that there exists an interval $I$, $|I| < 1 - \delta$ such that $|F(x)| \succeq 1, x \notin I$. Let also the complex-valued $G$ such that $|G(z)| \succ F(\Re z)$. Then condition 3 of the theorem can be replaced by
		\begin{itemize}
			\item $\max_m ||G(\widetilde{A})S_m(\widetilde{B})||{A_p} \preceq 1$.
		\end{itemize}
		In particular, for $G = 1 - z$ and $F = 1 - x$, we obtain the original formulation, and for $G = z, F = x$, we get
		\begin{itemize}
			\item $\max_m ||A S_m(\widetilde{B})||{A_p} \preceq 1$.
		\end{itemize}

		The proof remains the same.

	\end{proposition}

