\title{Underreporting of Intimate Partner Violence in Brazil}

\author{Diego de Maria André\thanks{Professor at the Graduate Program in Economics (PPECO), Federal University of Rio Grande do Norte (UFRN) and Intelligence Analyst at CENSIPAM/Ministry of Defense. E-mail:diego.andre@ufrn.br. ORCID: 0000-0003-3142-8336. (Author for correspondence)}  and José Raimundo Carvalho\thanks{Full Professor at the Graduate Program in Economics, CAEN/UFC and Intelligence Analyst at CENSIPAM/Ministry of Defense. E-mail: josecarv@ufc.br. ORCID: 0000-0001-5774-5925.}}
