\title{Note on a non-parametric method for change-point detection}
\author{Pierre Ailliot\footnote{Univ Brest, CNRS UMR 6205, Laboratoire de Mathématiques de Bretagne Atlantique, France.\newline
pierre.ailliot@univ-brest.fr
}\, ,
