\includegraphics[scale=0.4]{coveragetau10.pdf}
\includegraphics[scale=0.4]{longmoytau10.pdf}\\
\includegraphics[scale=0.4]{coveragetau30.pdf}
\includegraphics[scale=0.4]{longmoytau30.pdf}
  \caption{
Same as Figure~\ref{IC20} with $\tau=10$ (top) and $\tau=30$ (bottom).
}
    \label{IC10_30}
\end{figure}




