\section{Background on enriched $\infty$-categories}\label{Backgroundsec}



\begin{notation} Fix an infinite sequence of uncountable inaccessible cardinals $\tav_0<\tav_1<\tav_2<....<\tav_n<...$. 
\begin{itemize}
\item A \underline{$\tav_n$-small} set is a set with cardinality less than $\tav_n$.  A \underline{$\tav_n$-large} set is a set with cardinality less than $\tav_{n+1}$.  A $\tav_n$-huge set is a set with cardinality less than $\tav_{n+2}$
	\item Let $\tav_n\mathcal{S}$ denote the $\infty$-category of $\tav_n$-small spaces (homotopy types). 
		\item Denote by $\tav_n\cat_\infty$ the ($\tav_{n}$-large) category of $\tav_n$-small $\infty$-categories, and $\tav_n\widehat{\cat}_\infty$ the ($\tav_n$-huge) category of $\tav_n$-large categories. 
		\item Denote by $\tav_n\widehat{\cat}^{\colim}_\infty$ the ($\tav_{n}$-huge) category of $\tav_n$-large categories which admit $\tav_n$-small colimits, and functors which preserve $\tav_n$-small colimits. 
		\item Denote by $\tav_n\Pr\subset \tav_n\widehat{Cat}_\infty^{\colim}$ the full subcategory on $\tav_n$-compact objects (\cite{StefanichPhD} 12.1.4).  Its objects are called \underline{$\tav_n$-presentable categories}. 
	\item $\mathcal{V}\in \Alg(\tav_n\Pr)$ is called a \underline{$\tav_n$-presentably monoidal} category. Denote by $\tav_n\Pr^\mathcal{V}:=\LMod_\mathcal{V}(\tav_n\Pr)$ the category of \underline{$\tav_n$-presentable $\mathcal{V}$-module categories}. 
		\end{itemize}
When it is not necessary to address more than three cardinals from this sequence, we shall implicitly fix one and omit the $\tav_n$ from our notation, refering to sets only as \underline{small}, \underline{large}, or \underline{huge}. 
\end{notation}
\subsection{Hom objects}
We give an overview of morphism objects, as defined in \cite{LurieHA} 4.2.1.28.  See also \cite{ReutterZetto} 2.3. 
\begin{definition}
	Suppose that $\mathcal{C}\in \Alg(\cat_\infty)$ and $\mathcal{M}\in \LMod_\mathcal{C}(\cat_\infty)$.  

\begin{itemize}
	\item An \underline{hom object} for $m,m'\in \mathcal{M}$, denoted $\underline{\Hom}_\mathcal{M}(m,n)\in \mathcal{C}$, is a representing object for the presheaf
	\begin{equation}
		Map_\mathcal{M}(-\otimes m,m'):\mathcal{C}^{op}\to \mathcal{S}. 
	\end{equation}
\item The internal hom for $m\in \mathcal{M}$ with itself, if it exists, will be denoted by $\underline{\End}_\mathcal{M}(m):=\underline{\Hom}_\mathcal{M}(m,m)$. 
\item $\mathcal{M}$ is called \underline{closed} if every pair of objects $m,n\in \mathcal{M}$ has an internal hom, or equivalently, if $(m,m')\mapsto Map_\mathcal{M}(-\otimes m,m'):\mathcal{M}^{op}\times \mathcal{M}\to \mathcal{P}(\mathcal{C})$ factors through $\mathcal{C}$. 
\end{itemize}
One can define analogous notions for right module categories and large module categories. 


\begin{remark}\label{internalhomfunctorial}
If $F:\mathcal{M}\to \mathcal{N}$ is a morphism between closed left $\mathcal{C}$ module categories and $m,m'\in \mathcal{M}$, then the universal property of internal hom induces a $\mathcal{C}$-morphism 
\begin{equation}
	\underline{\Hom}_\mathcal{M}(m,m')\to \underline{\Hom}_\mathcal{N}(F(m),F(m')). 
\end{equation}
\end{remark}

\begin{remark}
If $\mathcal{C}\in \Alg(\Pr)$ and $\mathcal{M}\in \LMod_\mathcal{C}(\Pr)$, then it follows from adjoint functor theorem that $\mathcal{M}$ is a closed $\mathcal{C}$ module category. 
\end{remark}

\begin{remark}\label{adjinternalhom}
Suppose that $\mathcal{V},\mathcal{W}$ are monoidal categories, and $L:\mathcal{V}\to \mathcal{W}$ is a monoidal functor with right adjoint $R:\mathcal{W}\to \mathcal{V}$ (which is laxly monoidal by \cite{HaugsengMates}).  Suppose that $\mathcal{M}\in \LMod_\mathcal{W}(\cat_\infty)$ is closed.  Denote its restriction to a $\mathcal{V}$-module by $L^*\mathcal{M}$.  Then $L^*\mathcal{M}$ is closed, and for $m,m'\in \mathcal{M}$, the internal hom is given by 
\begin{equation}
	\underline{\Hom}_{L^*\mathcal{M}}(m,m')\simeq R\underline{\Hom}_{\mathcal{M}}(m,m'). 
\end{equation}
\end{remark}


\end{definition}



\subsection{Results on enriched $\infty$-categories}

One can think of $\infty$-categories enriched over monoidal $\infty$-category $\mathcal{V}$ as a sort of `weak left module' $\mathcal{M}$ for $\mathcal{V}$, equipped with a closed structure, giving a hom object for each pair of objects in $\mathcal{M}$. This perspective is formalized in \cite{LurieHA} 4.2.1.28.  However, this definition is technically difficult to work with.  Alternative definitions of $\mathcal{V}$-enriched $\infty$-categories appear in \cite{GepnerHaugseng,Hinich2021,ReutterZetto}, and equivalence between the various models is proven in \cite{HeineEquivalence,Macpherson2019}.  Enriched versions of the Yoneda embedding are given in \cite{Hinich2021,HeineEquivalence,ReutterZetto} and are proven to be equivalent in \cite{HeinePresheaves}.  Further properties are explored in \cite{Hinich2023,Ben-Moshe2024,HeineBienriched,HeineWeighted}.

We will not give the definition or provide proofs here, since we will not need to work with them directly, but give an overview of some of the key results needed for our discussion on monoidal monads.  We invite the reader to look in \cite{ReutterZetto} for an excellent summary and further details, but freely use results from other models of enriched $\infty$-categories.  




\begin{theorem}[\cite{ReutterZetto} corollary 7.27, corollary 8.20, corollary 8.21]
There is a symmetric monoidal functor 
\begin{equation}
	Cat^{(-)}:\Alg(\Pr)\to \Pr
\end{equation}
taking a presentably monoidal $\infty$-category $\mathcal{V}$ to the presentable category $\cat^\mathcal{V}$ of small $\mathcal{V}$-enriched categories. 

\end{theorem}
\begin{theorem}[\cite{GepnerHaugseng} theorem 6.32]\label{delooping}
	Let $\mathcal{V}\in \Alg_{E_1\otimes \mathcal{O}}(\Pr)$.  There is a `looping/delooping' adjunction
	\begin{equation}
		\begin{tikzcd}
			\Alg(\mathcal{V})\ar[r,shift left =2,"B"{name=B}]&\ar[l,shift left=2,"\Omega"{name=A}]\Alg_{E_0}(Cat^\mathcal{V})\ar[phantom,from=B,to=A,"\dashv" rotate=-90]
		\end{tikzcd}
	\end{equation}
where the delooping functor $B$ is fully faithful and $\mathcal{O}$-monoidal, and $\Omega$ is lax $\mathcal{O}$-monoidal. 	

\end{theorem}

\begin{remark}
	It was proven in \cite{HeineEquivalence} that $\mathcal{B}\in \Pr^\mathcal{V}$ is automatically (large) $\mathcal{V}$-enriched, and that the induced monoidal structures from enrichment and as module categories agree.  
\end{remark}

\begin{proposition}[\cite{ReutterZetto}  proposition 7.3, observation 8.13,\cite{HeineWeighted} corollary 3.101]\hfill

	Suppose that $\mathcal{V}$ is presentably $E_1\otimes \mathcal{O}$-monoidal.  The free cocompletion functor $\mathcal{P}_\mathcal{V}$ is $\mathcal{O}$-monoidal and left adjoint to the inclusion $\Pr^\mathcal{V}\to \widehat{\cat}^\mathcal{V}$.  
\begin{equation}
	\begin{tikzcd}
\widehat{Cat}^\mathcal{V}\ar[r,"\mathcal{P}_\mathcal{V}"{name=A},shift left=2]&\Pr^\mathcal{V}\ar[l,"\iota"{name=B},hookrightarrow,shift left=2]\arrow[phantom,from=A,to=B,"\dashv" rotate=-90]
	\end{tikzcd}
\end{equation}
Its restriction to $\cat^\mathcal{V}$ is faithful, and we can identify it with the enriched presheaf functor.  Its unit is the Yoneda embedding, which we denote by $\yo^\mathcal{V}_\mathcal{C}:\mathcal{C}\to \mathcal{P}_\mathcal{V}(\mathcal{C})$. 
\end{proposition}

\begin{definition}
Suppose that $\mathcal{V}\in \Alg(\Pr)$.  Then there is a unique colimit preserving monoidal functor $\mathcal{S}\to \mathcal{V}$, which takes $*\in \mathcal{S}$ to the monoidal unit $1_\mathcal{V}\in \mathcal{V}$.  This induces an adjunction
\begin{equation}
	\begin{tikzcd}
		\cat_\infty\simeq \cat^\mathcal{\mathcal{S}}\ar[r,shift left=2,"1_\mathcal{V}\otimes -"{name=A}]&\cat^\mathcal{V}\ar[l,shift left=2,"(-)_0"{name=B}]\ar[phantom, from=A,to=B,"\dashv" rotate=-90].
	\end{tikzcd}
\end{equation}
We call $\mathcal{C}_0\in Cat_\infty$ the \underline{underlying ($\infty$-) category} of $\mathcal{C}$.  Moreover, if $\mathcal{V}\in \Alg_{E_1\otimes\mathcal{O}}(\Pr)$, then the underlying category functor is lax $\mathcal{O}$-monoidal. 
\end{definition}
\begin{definition}

	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$ and $\mathcal{C},\mathcal{D}\in \cat^\mathcal{V}$. 
	\begin{itemize}
		\item $\cat^\mathcal{V}$ is presentably $E_1\otimes \mathcal{O}$ monoidal.  Let $\ucat^\mathcal{V}$ denote $\cat^\mathcal{V}$ viewed as a closed module category over itself.  Denote the internal hom by 
\begin{equation}
	\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{D}):=\underline{\Hom}_{\ucat^\mathcal{V}}(\mathcal{C},\mathcal{D})\in \cat^\mathcal{V}. 
\end{equation}
\item $\ucat^\mathcal{V}$ becomes a closed $\cat_\infty$-module category along the underlying category functor as in remark \ref{adjinternalhom}, which we denote by $\catr^\mathcal{V}$.  Denote the internal hom by 
	\begin{equation}
		\Fun_\mathcal{V}(\mathcal{C},\mathcal{D}):=\underline{\Hom}_{\catr^\mathcal{V}}(\mathcal{C},\mathcal{D})\in \cat_\infty.
	\end{equation}
\item $\Pr^\mathcal{V}$ is closed $E_1\otimes \mathcal{O}$-monoidal.  Let $\underline{\Pr}^\mathcal{V}$ denote $\Pr^\mathcal{V}$ viewed as a closed module category over itself.  For $\mathcal{A},\mathcal{B}\in \Pr^\mathcal{V}$, denote the internal hom by 
	\begin{equation}
		\underline{\Fun}^L_\mathcal{V}(\mathcal{A},\mathcal{B}):=\underline{\Hom}_{\underline{\Pr}^\mathcal{V}}(\mathcal{A},\mathcal{B}). 
	\end{equation}

	\end{itemize}

	\end{definition}

\begin{definition}\hfill
	\begin{itemize}
		\item An \underline{$(\infty,2)$-category} is a category enriched over $\tav_i\cat_\infty$ in the Cartesian symmetric monoidal structure.  
		\item For $(\infty,2)$-categories $\mathcal{C},\mathcal{D}$, denote the internal hom by $\Fun_{(\infty,2)}(\mathcal{C},\mathcal{D}):=\underline{\Fun}_{\tav_i\cat_\infty}(\mathcal{C},\mathcal{D})$. 
		\item  For $1\leq i\leq 2$, denote by $\mathcal{C}^{iop}\in \cat_{(\infty,2)}$ the category obtained from $\mathcal{C}$ by reversing $i$-morphisms.  
		\item If $\mathcal{C}\in \Alg(\cat_{(\infty,2)})$ is monoidal, denote by $\mathcal{C}^{mop}\in \Alg(\cat_{(\infty,n)})$ the monoidal category obtained from $\mathcal{C}$ by reversing the monoidal product. 
	\end{itemize}

\end{definition}


\begin{remark}
	While we will not provide a list of presentably monoidal categories for enriching here, we will refer to \cite{SoergelBimodule} sections 3 and 4 for an excellent treatment of `higher linear algebra', which will provide many examples of the appropriate type, beyond the typical 1-categorical examples. 
\end{remark}








\subsection{Conical colimits }
In the following subsection, we introduce the notion of conical colimit in an enriched $\infty$-category.  The theory of condensation also uses the more general notion of weighted colimit, which is treated in \cite{HeineWeighted}.  We will not address this here. 
\begin{definition}
	For $\mathcal{V}\in \Alg(\Pr)$, $\mathcal{C}$ a $\mathcal{V}$-enriched category, $\mathcal{J}\in \widehat{Cat}_\infty$ and functor $D:\mathcal{J}\to \mathcal{C}_0$, a \underline{conical colimit} (respectively \underline{conical limit}) is an object in $\mathcal{C}$
\begin{align}
	\colim^\mathcal{C}_\mathcal{J}(D)&&\text{resp.}&& \lim^\mathcal{C}_\mathcal{J}(D)
\end{align}
equipped with a $\mathcal{V}$-natural equivalence

	\begin{align}
		\Hom_\mathcal{C}(\colim^\mathcal{C}_\mathcal{J}(D),c)\simeq \lim^\mathcal{V}_{\mathcal{J}^{op}}\Hom_\mathcal{C}(D(-),c)&&\text{resp.}&& \Hom_\mathcal{C}(c,\lim^\mathcal{C}_\mathcal{J}(D))\simeq \lim^\mathcal{V}_\mathcal{J}\Hom_\mathcal{C}(c,D(-))
	\end{align}
	for all objects $c\in \mathcal{C}$. 
\end{definition}

\begin{remark}
If $D:\mathcal{J}\to \mathcal{C}_0$ admits a conical (co)limit, then it admits a (co)limit on the underlying category of $\mathcal{C}$ which agrees with the conical (co)limit on $\mathcal{C}$. 
\end{remark}
\begin{notation}
	Suppose that $\mathcal{V}\in \Alg_{E_1}(\Pr)$ and $\mathcal{K}$ is small a collection of small $\infty$-categories.  Denote by $\cat^\mathcal{V}(\mathcal{K})\subset \cat^\mathcal{V}$ the subcategory of $\cat^\mathcal{V}$ on the $\mathcal{V}$-enriched categories that have $K$-indexed conical colimits for all $K\in \mathcal{K}$, and those functors that preserve $K$-indexed conical colimits for all $K\in \mathcal{K}$.  
We will in particular denote $\cat_\infty(\mathcal{K}):=\cat^\mathcal{S}(\mathcal{K})$, and note that this is equivalent to the categories defined in \cite{LurieHA} 4.8.1.1.

\end{notation}


\begin{proposition}[\cite{HeineWeighted} 4.43]\label{HeineWeighted4.43}
	Suppose that $\mathcal{V}\in \Alg_{E_1\otimes \mathcal{O}}(\Pr)$ and $\mathcal{K}$ is a small collection of small $\infty$-categories.  Then $\cat^\mathcal{V}(\mathcal{K})\in \Alg_{\mathcal{O}}(\Pr)$.  i.e., it is presentably $\mathcal{O}$-monoidal.  
\end{proposition}

\begin{definition}
	Let $\mathcal{K}$ is a collection of $\infty$-categories.  We will say that an $(\infty,2)$-category $\mathcal{D}$ is \underline{locally compatible with $\mathcal{K}$-indexed colimits} if it is enriched over $\tav_i\cat_\infty(\mathcal{K})$. 
\end{definition}




\subsection{Semiadditivity}
In the following subsection, we introduce the notion of semiadditive enriched $\infty$-categories, following \cite{MazelGeeStern} appendix A and \cite{HeineWeighted} 5.6 (where we note that they are instead called preadditive).  Semiadditivity gives a monoidal structure corresponding to a notion of direct sum of objects, and induces an abelian monoid structure on each morphism object.  In contrast, an \emph{additive} structure corresponds to a semiadditive structure where the induced abelian monoid structure on each morphism object is in fact an abelian group.  
\begin{definition}\hfill

	Let $\mathcal{V}\in \Alg(\Pr)$.  Let $\mathcal{C}$ be a $\mathcal{V}$-enriched category.
	\begin{itemize}
		\item Denote by $\finset$ the collection of finite sets.  
		\item A \underline{finite (co)product} is a conical (co)limit indexed by $K\in \finset$.  
		\item We will say that $\mathcal{C}$ \underline{admits finite (co)products} if it admits $K$-indexed conical (co)limits for all $K\in \finset$.   
		\item Suppose that $\mathcal{C}$ admits a initial and terminal objects, i.e. a conical colimit and limit for the empty set.  If the unique morphism from the initial object to the terminal object is an equivalence, we will call the initial/terminal object a \underline{zero object} and denote it by $0_\mathcal{C}$. 
	\end{itemize}
If $\mathcal{C}$ admits a zero object, then for every $X,Y\in \mathcal{C}$, there is morphism $0:X\to 0_\mathcal{C}\to Y$.  One may then construct canonical inclusion maps $Y\to X\times Y$, which further induce comparison maps $X\coprod Y\to X\times Y$.  


\begin{itemize}
	\item A $\mathcal{V}$ enriched $\infty$-category $\mathcal{C}$ is \underline{semiadditive} if 

	\begin{enumerate}
		\item $\mathcal{C}$ admits a zero object. 
		\item $\mathcal{C}$ admits finite products and finite coproducts. 
		\item The canonical map from the coproduct to the product is an equivalence. 
	\end{enumerate}
\end{itemize}
In particular, an $\infty$-category is semiadditive iff it is semiadditive as a category enriched over $\mathcal{S}$.
\begin{itemize}
	\item If $\mathcal{C}$ is semiadditive and $X,Y\in \mathcal{C}$, we will denote their (co)product by $X\oplus Y$, and call it a \underline{direct sum}. 
\item If $\mathcal{C},\mathcal{D}$ are semiadditive $\mathcal{V}$-categories, we will say that $\mathcal{V}$-functor $F:\mathcal{C}\to \mathcal{D}$ is an \underline{additive $\mathcal{V}$-functor} if it preserves $K$-indexed (co)limits for all $K\in \finset$. 
\item Denote by $\Semiadd^\mathcal{V}\subset \cat^\mathcal{V}$ the subcategory on the semiadditive $\mathcal{V}$-categories and additive functors.
\end{itemize}

\end{definition}

\begin{remark}
If $\mathcal{V}\in \Alg(\Pr)$ is semiadditive, then $\Semiadd^\mathcal{V}\subset\cat^\mathcal{V}$ is a full subcategory, and so direct sums are absolute colimits (see \cite{MazelGeeStern} A.5.10). 
\end{remark}

\begin{example}\label{semiaddsemiadd}
$\Semiadd^\mathcal{V}$ is a semiadditive $\infty$-category by \cite{HeineWeighted} proposition 5.71.   
\end{example}

\begin{remark}\label{colimsemiadd}
	Suppose that $\mathcal{V}\in \Alg(\Pr)$ semiadditive, and $\mathcal{C}$ is a $\mathcal{V}$-enriched $\infty$-category.  If $\mathcal{C}$ admits finite products (coproducts), then it admits finite coproducts (products) and the canonical comparison map is an equivalence.  In particular, $\mathcal{C}$ is semiadditive.  

	Moreover, in this situation, if $F:\mathcal{C}\to \mathcal{D}$ preserves finite conical products or coproducts, then $F$ is an additive functor. 
\end{remark}

\begin{corollary}
	Suppose that $\mathcal{V}\in \Alg(\Pr)$ is semiadditive.  Then the inclusion $\Semiadd(\Pr^\mathcal{V})\subset \Pr^\mathcal{V}$, of semiadditive presentable $\mathcal{V}$-categories into presentable $\mathcal{V}$-categories, is an equivalence. 
\end{corollary}










\begin{lemma}\label{CatKsemiadd}
	Suppose that $\mathcal{V}\in \Alg_{E_1\otimes \mathcal{O}}(\Pr)$ is semiadditive, and $\finset\subset\mathcal{K}$ is a collection of $\infty$-categories.  Then $Cat^{\mathcal{V}}(\mathcal{K})$ is semiadditive. 
\end{lemma}
We would like to thank Markus Zetto for suggesting the following simpler proof. 

\begin{proof*}
	We first note that by \cite{LurieHA} corollary 3.4.1.7 and \cite{LurieSAG} proposition C.4.1.9, we get an equivalence between semiadditive presentable categories and presentably symmetric monoidal categories equipped with a cocontinuous symmetric monoidal functor from $Alg_{E_\infty}(\mathcal{S})$.  Using that $\cat^\mathcal{V}(\finset)$ is semiadditive, we get a symmetric monoidal functor 
	\begin{equation}
		Alg_{E_\infty}(\mathcal{S})\to Cat^\mathcal{V}(\finset)\to Cat^\mathcal{V}(\mathcal{K}),
	\end{equation}
where the second symmetric monoidal functor is given by completion under $\mathcal{K}$-indexed colimits.  Then $\cat^\mathcal{V}(\mathcal{K})$ is semiadditive.  	
\end{proof*}






\section{Monads in monoidal $(\infty,2)$-categories}\label{Monadssec}
In the following section, we will construct two functors taking a monad to its Eilenberg-Moore object and show that they are monoidal.  As a corollary, we will see that the functors taking an algebra object to its (enriched) category of modules is monoidal.  A reader more interested in condensation may choose to accept corollary \ref{AlgebraEML} and skip this section, returning only if further details are required. 

\subsection{Enriched Day convolution}\label{Dayconvolution}
In the following, we prove functoriality of the enriched Day convolution, introduced in \cite{Hinich2023} section 8.3, by generalizing the approach of \cite{BenMosheSchlank} to the enriched setting.
\begin{remark}
	Suppose that $\mathcal{V}\in \Alg_{E_1\otimes \mathcal{O}}(\Pr)$.  An $\mathcal{O}$-monoidal presentable $\mathcal{V}$-module is $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$.  Equivalently, $\mathcal{B}$ defines an $\mathcal{O}\otimes LM$-algebra in $\Pr$, so one can speak of lax $\mathcal{O}$-monoidal functors between $\mathcal{O}$-monoidal presentable $\mathcal{V}$-modules, and they satisfy the expected properties. 
\end{remark}


\begin{theorem}[\cite{Hinich2023} 8.3]
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$, and $\mathcal{C},\mathcal{D}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$.  Then $\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})$ inherits an $\mathcal{O}$-monoidal structure, which we shall denote by $\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$ and call the \underline{Day convolution} $\mathcal{O}$-monoidal structure.  Moreover, there is an $\mathcal{O}$-monoidal $\mathcal{V}$-linear equivalence  
	\begin{equation}
		\underline{\Fun}_\mathcal{V}(\mathcal{D},\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes)^\otimes \simeq \underline{\Fun}_\mathcal{V}(\mathcal{D}\otimes \mathcal{C},\mathcal{B})^\otimes. 
	\end{equation}

\end{theorem}

\begin{lemma}\label{presentablepostcomp}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{C}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$, and $g:\mathcal{B}\to \mathcal{A}$ is a morphism in $\Alg_\mathcal{O}(\Pr^\mathcal{V})$.  Then the postcomposition functor 
	\begin{equation}
		g_*:\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes \to \underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{A})^\otimes
	\end{equation}
is $\mathcal{O}$-monoidal. 	
\end{lemma}


\begin{proof*}
	By the monoidal tensor-hom adjunction, $\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes$ is a representing object for the lax $\mathcal{O}$-monoidal functor $Map_{\widehat{\cat}^\mathcal{V}}(-\otimes \mathcal{C},\mathcal{B})^\otimes:\cat^\mathcal{V}\to \Pr^\mathcal{V}$.  Since $g:\mathcal{B}\to \mathcal{A}$ in $\Alg_\mathcal{O}(\Pr^\mathcal{V})$ induces an $\mathcal{O}$-monoidal natural transformation, we see that it also induces a morphism $g_*:\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes \to \underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{A})^\otimes$ between representing objects in $\Alg_\mathcal{O}(\Pr^\mathcal{V})$. 
\end{proof*}



\begin{remark}
	There is an $\mathcal{O}$-monoidal $\mathcal{V}$-linear equivalence $\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{V})^\otimes\simeq \mathcal{P}_\mathcal{V}(\mathcal{C})$ between the Day convolution monoidal structure and the monoidal structure induced by monoidality of the presheaf functor. 
\end{remark}

\begin{lemma}\label{YonedaLeftKan}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$ and $f:\mathcal{C}\to \mathcal{D}$ is a morphism in $\Alg_\mathcal{O}(\cat^\mathcal{V})$.  Then the left Kan extension functor 
	\begin{equation}
		f_!:\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{V})^\otimes\to \underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{V})^\otimes
	\end{equation}
is a morphism in $\Alg_\mathcal{O}(\Pr^\mathcal{V})$, i.e., a strong $\mathcal{O}$-monoidal colimit preserving $\mathcal{V}$-functor. 
\end{lemma}

\begin{proof*}
	Under the identification $\underline{\Fun}_\mathcal{V}(\mathcal{C}^{op},\mathcal{V})^\otimes\simeq \mathcal{P}_\mathcal{V}(\mathcal{C})$, one can identify $g_!\simeq \mathcal{P}_\mathcal{V}(g):\mathcal{P}_\mathcal{V}(\mathcal{C})\to \mathcal{P}_\mathcal{V}(\mathcal{D})$, which is an $\mathcal{O}$-algebra morphism in $\Pr^\mathcal{V}$ by $\mathcal{O}$-monoidality of $\mathcal{P}_\mathcal{V}:\cat^\mathcal{V}\to \Pr^\mathcal{V}$.  We apply this to $f^{op}:\mathcal{C}^{op}\to \mathcal{D}^{op}$. 
\end{proof*}

\begin{lemma}\label{YoyoLeftKan}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{C},\mathcal{D},\mathcal{E}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$, and $f:\mathcal{D}\to \mathcal{E}$ is a morphism in $\Alg_\mathcal{O}(\cat^\mathcal{V})$.  Then the left Kan extension functor
	\begin{equation}
		f_!:\underline{\Fun}_\mathcal{V}(\mathcal{E},\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{V})^\otimes)^\otimes \to \underline{\Fun}_\mathcal{V}(\mathcal{D},\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{V})^\otimes)^\otimes
	\end{equation}
	is $\mathcal{O}$-monoidal. 
\end{lemma}

\begin{proof*}
$f_!$ is equivalent to the composition
\begin{multline}
	\underline{\Fun}_\mathcal{V}(\mathcal{D},\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{V})^\otimes)^\otimes\simeq \underline{\Fun}_\mathcal{V}(\mathcal{D}\otimes \mathcal{C},\mathcal{V})
	\xrightarrow{(f\otimes id_\mathcal{C})_!}\underline{\Fun}_\mathcal{V}(\mathcal{E}\otimes \mathcal{C},\mathcal{V})^\otimes\\
	\simeq \underline{\Fun}_\mathcal{V}(\mathcal{E},\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{V})^\otimes)^\otimes. 
\end{multline}
The result follows from lemma \ref{YonedaLeftKan}. 

\end{proof*}

\begin{proposition}\label{reflectivelocalization}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$ and $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$.  Then $\mathcal{B}$ is an $\mathcal{O}$-monoidal $\mathcal{V}$-linear localization of $\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{V})^\otimes$ for some $\mathcal{C}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$. 
\end{proposition}
\begin{proof*}
Note that $\mathcal{B}$ is a presentably $LM\otimes\mathcal{O}$-monoidal $\infty$-category.  It follows from \cite{NikolausSagave} theorem 2.2 that we can find small $LM\otimes\mathcal{O}$-monoidal category $\mathcal{M}$ and $LM\otimes \mathcal{O}$-monoidal localization $\Fun(\mathcal{M},\mathcal{S})^\otimes\to \mathcal{B}^\otimes$.  Looking at the fiber over $E_1\otimes \mathcal{O}\subset LM\otimes \mathcal{O}$, we find an $E_1\otimes \mathcal{O}$-monoidal category $\mathcal{A}$ with $E_1\otimes \mathcal{O}$-monoidal localization $\Fun(\mathcal{A},\mathcal{S})^\otimes \to \mathcal{V}^\otimes$.  Extension of scalars along this localization gives a presentably $\mathcal{O}$-monoidal left $\mathcal{V}$-module structure on $\Fun(\mathcal{M},\mathcal{S})\otimes \mathcal{V}$, which we identify with $\underline{\Fun}_\mathcal{V}(\mathcal{M},\mathcal{V})$ where $\mathcal{M}$ has the free $\mathcal{V}$-enrichment, with $LM\otimes \mathcal{O}$-monoidal localization $\underline{\Fun}_\mathcal{V}(\mathcal{M},\mathcal{S})\to \mathcal{B}$, as desired. 
\end{proof*}

\begin{proposition}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$, and $f:\mathcal{C}\to \mathcal{D}$ is a morphism in $\Alg_\mathcal{O}(\cat^\mathcal{V})$.  Then the left Kan extension functor  
	\begin{equation}
		f_!:\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes \to \underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{B})^\otimes
	\end{equation}
is $\mathcal{O}$-monoidal. 
\end{proposition}
\begin{proof*}
	The proof is identical to \cite{BenMosheSchlank} proposition 3.6.  By proposition \ref{reflectivelocalization}, $\mathcal{B}$ is an $\mathcal{O}$-monoidal reflective localization of $\underline{\Fun}_\mathcal{V}(\mathcal{E},\mathcal{B})^\otimes$ for some $\mathcal{E}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$.  Then then the functor $\underline{\Fun}_\mathcal{V}(\mathcal{C},\underline{\Fun}_\mathcal{V}(\mathcal{E},\mathcal{V})^\otimes)^\otimes\to \underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes$ given by postcomposition is a $\mathcal{V}$-linear reflective localization, and $\mathcal{O}$-monoidal by lemma \ref{presentablepostcomp}, and similarly for $\underline{\Fun}_\mathcal{V}(\mathcal{D},\underline{\Fun}_\mathcal{V}(\mathcal{E},\mathcal{V})^\otimes)^\otimes\to \underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{B})^\otimes$.  By lemma \ref{YoyoLeftKan}, we get $\mathcal{O}$-monoidal $\mathcal{V}$-linear functor
	\begin{equation}
		\underline{\Fun}_\mathcal{V}(\mathcal{C}, \underline{\Fun}_\mathcal{V}(\mathcal{E},\mathcal{V})^\otimes)^\otimes \xrightarrow{f_!}\underline{\Fun}_\mathcal{V}(\mathcal{D}, \underline{\Fun}_\mathcal{V}(\mathcal{E},\mathcal{V})^\otimes)^\otimes\to \underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{B})^\otimes, 
	\end{equation}
	which factors $\mathcal{O}$-monoidaly through the $\mathcal{O}$-monoidal localization $\underline{\Fun}_\mathcal{V}(\mathcal{C},\underline{\Fun}_\mathcal{V}(\mathcal{E},\mathcal{V})^\otimes)^\otimes \to \underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes$, giving the desired $\mathcal{O}$-monoidal functor $f_!:\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes\to \underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{B})^\otimes$. 
\end{proof*}

\begin{corollary}\label{precompmon}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$, and $f:\mathcal{C}\to \mathcal{D}$ is a morphism in $\Alg_\mathcal{O}(\cat^\mathcal{V})$.  Then the restriction functor 
	\begin{equation}
		f^*:\underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{B})^\otimes \to\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes
	\end{equation}
is lax $\mathcal{O}$-monoidal. 	
\end{corollary}
\begin{proof*}
$f^*$ is right adjoint to $f_!$, and so automatically lax $\mathcal{O}$-monoidal by \cite{HaugsengMates}.  
\end{proof*}


\begin{definition}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$, and $\mathcal{C}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$.  A \underline{lax $\mathcal{O}$-monoidal $\mathcal{V}$-functor} from $\mathcal{C}$ to $\mathcal{B}$ is $f\in \Alg_\mathcal{O}(\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes)$. 
\end{definition}
\begin{corollary}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{B}\in \Alg_{\mathcal{O}}(\Pr^\mathcal{V})$, $\mathcal{C},\mathcal{D}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$, $f:\mathcal{C}\to \mathcal{D}$ is a morphism in $\Alg_\mathcal{O}(\cat^\mathcal{V})$, and $g:\mathcal{D}\to \mathcal{B}$ is a lax $\mathcal{O}$-monoidal $\mathcal{V}$-functor.  Then $g\circ f:\mathcal{D}\to \mathcal{B}$ is a lax $\mathcal{O}$-monoidal $\mathcal{V}$-functor. 
\end{corollary}

\begin{proof*}
	$f^*:\underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{B})^\otimes \to \underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes$ is a lax $\mathcal{O}$-monoidal functor of presentable $\mathcal{V}$-modules, and so takes $g\in \Alg_\mathcal{O}(\underline{\Fun}_\mathcal{V}(\mathcal{D},\mathcal{B})^\otimes)$ to $g\circ f\simeq f^*(g)\in \Alg_\mathcal{O}(\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes)$. 
\end{proof*}


\begin{proposition}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$, and $\mathcal{C}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$.  Suppose that $f:\mathcal{C}\to \mathcal{B}$ is a lax $\mathcal{O}$-monoidal $\mathcal{V}$-functor.  Then the underlying functor $f_0:\mathcal{C}_0\to \mathcal{B}_0$ is lax $\mathcal{O}$-monoidal. 
\end{proposition}
\begin{proof*}
	The universal property of $(\infty,1)$-Day convolution (see \cite{LurieHA} 2.2.6) induces a $\mathcal{O}$-monoidal functor $\Fun_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes\to \Fun(\mathcal{C}_0,\mathcal{B}_0)^\otimes$.  In particular, $f\in \Alg_\mathcal{O}(\underline{\Fun}_\mathcal{V}(\mathcal{C},\mathcal{B}))^\otimes:=\Alg_\mathcal{O}(\Fun_\mathcal{V}(\mathcal{C},\mathcal{B})^\otimes)$ is taken to an $\mathcal{O}$-algebra in $\Fun(\mathcal{C},\mathcal{B})^\otimes$, determining a lax $\mathcal{O}$-monoidal functor by definition of $(\infty,1)$-Day convolution. 
\end{proof*}

\begin{corollary}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{B}\in \Alg_\mathcal{O}(\Pr^\mathcal{V})$, $\mathcal{C}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$, and $f:\mathcal{C}\to \mathcal{B}$ is a lax $\mathcal{O}$-monoidal $\mathcal{V}$-functor.  Then $f$ takes $\mathcal{O}$-algebra objects in $\mathcal{C}$ to $\mathcal{O}$-algebra objects in $\mathcal{B}$.  
\end{corollary}






\subsection{Adjunctions and monads}
In the following section, we shall use the Day convolution monoidal structure constructed in section \ref{Dayconvolution} to enhance the treatment of monads in $(\infty,2)$-categories given by \cite{StefanichPhD} 7.1.3, 7.2.4, 7.3.7, to treat monoidal monads.  See also \cite{HeineMonadicity} for another approach. 


\begin{construction}\label{Yonedamodule}
	Suppose that $\mathcal{O}$ is a symmetric $\infty$-operad, $\mathcal{V}\in \Alg_{E_2\otimes\mathcal{O}}(\Pr)$, $\mathcal{D}\in \Alg_\mathcal{O}(\cat^\mathcal{V})$ and $y\in \Alg_\mathcal{O}\mathcal{D}$.  By delooping hypothesis (theorem \ref{delooping}), $\End_{\mathcal{D}}(y)\in \Alg_{E_1\otimes\mathcal{O}}(\mathcal{V})$.  The restriction functor $\Fun_\mathcal{V}(\mathcal{D}^{op},\mathcal{V})\to \Fun_\mathcal{V}(B\End_\mathcal{D}(y)^{op},\mathcal{V})$ along the inclusion is lax $\mathcal{O}$-monoidal $\mathcal{V}$-linear by corollary \ref{precompmon}.  With monoidal Yoneda embedding, we then have composition of lax $\mathcal{O}$-monoidal $\mathcal{V}$-functors
\begin{equation}
	\Hom_\mathcal{D}^{enh}(-,y):\mathcal{D}^{1op}\to \Fun_\mathcal{V}(\mathcal{D},\mathcal{V})\to \Fun_\mathcal{V}(B\End_\mathcal{D}(y),\mathcal{V})\simeq \LMod_{\End_\mathcal{D}(y)}(\mathcal{V}),
\end{equation}
taking $x\in \mathcal{D}$ to $\Hom_\mathcal{D}(x,y)$, viewed as a left $\End_\mathcal{D}(y)$-module.  

\end{construction}


\begin{definition}
	Suppose that $\mathcal{D}$ is an $\mathcal{O}$-monoidal $(\infty,2)$-category, i.e. $\mathcal{D}\in \Alg_{\mathcal{O}}(\cat_{(\infty,2)})$.  A \underline{monad} on $y\in \mathcal{D}$ is $T\in \Alg(\End_\mathcal{D}(y))$.  If $y\in \Alg_{\mathcal{O}}(\mathcal{D})$, an \underline{$\mathcal{O}$-monoidal monad} on $y$ is $T\in \Alg_{E_1\otimes \mathcal{O}}(\End_\mathcal{D}(y))$. 
\end{definition}

\begin{definition}
	Suppose that $f:x\to y$ is a morphism in $\mathcal{D}\in Cat_{(\infty,2)}$.  Consider $\Hom_\mathcal{D}(x,y)$ as a left module over $\End_\mathcal{D}(y)$.  Then an \underline{endomorphism monad} for $f$ is an endomorphism object $\End(f)\in \End_\mathcal{D}(y)$ for $f$.  
\end{definition}

\begin{definition}
	Let $\mathcal{D}$ be an $(\infty,2)$-category. 
\begin{itemize}
	\item 	A \underline{right adjoint} to 1-cell $f:y\to x$ in $\mathcal{D}$ is the following collection of data: 
	\begin{enumerate}
		\item A 1-cell $r:x\to y$ in $\mathcal{D}$. 
		\item 2-cells $\eta:id_f\Rightarrow rf$ and $\epsilon:fr\Rightarrow id_x$ in $\mathcal{D}$, called the \underline{unit} and \underline{counit}, respectively. 
		\item The following triangle identities hold:  
			\begin{align}
				(\epsilon \circ f)\circ (f\circ \eta)\simeq id_f&& (r\circ \epsilon )\circ (\eta \circ r) \simeq id_r 
			\end{align}

	\end{enumerate}
\item A \underline{left adjoint} for $f:y\to x$ is a right adjoint for $r$ in the $(\infty,2)$-category $\mathcal{D}^{1op}$. 
\item We say that $f$ \underline{admits a right (left) adjoint} if a right (left) adjoint for $f$ exists. 
\item An \underline{adjunction} in $\mathcal{D}$ is the data of morphism $f:y\to x$ and an adjoint to $f$.
\end{itemize}
\end{definition}


\begin{theorem}[\cite{RiehlVerity2016}]
	There exists an $(\infty,2)$-category $\Adj$ such that an $(\infty,2)$-functor $\Adj\to \mathcal{D}$ is equivalent to an adjunction in $\mathcal{D}$.  
\end{theorem}

\begin{corollary}
	Suppose that $\mathcal{C},\mathcal{D}$ are $(\infty,2)$-categories, $\Adj\xrightarrow{\alpha}\mathcal{D}$ is an adjunction in $\mathcal{D}$, and $\mathcal{D}\xrightarrow{F}\mathcal{C}$ is an $(\infty,2)$-functor.  Then $\Adj\xrightarrow{\alpha}\mathcal{D}\xrightarrow{F}\mathcal{C}$ is an  adjunction in $\mathcal{C}$, so $(\infty,2)$-functors preserve adjunctions. 
\end{corollary}


\begin{proposition}\label{adjendmon}
	Suppose that $\mathcal{D}\in \cat_{(\infty,2)}$ and $r:x\to y$ is a morphism in $\mathcal{D}$.  Suppose that $r$ admits a left adjoint $l:y\to x$.  Then $r$ admits an endormorphism monad with underlying object $rl\in \End_\mathcal{D}(y)$, and action map $rlr\to r$ induced by the counit $rl\to id_y$. 
\end{proposition}
\begin{proof*}
The representable $(\infty,2)$-functor $\Hom_\mathcal{D}(-,y): \mathcal{D}^{1op}\to \mathscr{C}at_\infty$ induces an adjunction of categories 
	\begin{equation}
		\begin{tikzcd}
			\End_\mathcal{D}(y):\ar[r,shift left=2,"r^*"{name=A}]&\Hom_\mathcal{D}(x,y)\ar[l,shift left=2,"l^*"{name=B}]\ar[phantom,from=A,to=B,"\dashv"rotate=-90]
		\end{tikzcd}
	\end{equation}
	In particular, for all $f\in \Hom_\mathcal{D}(x,y)$, $g\in \End_\mathcal{D}(y)$, the counit map $rl\to id_y$ induces an equivalence 
	\begin{equation}
		\Hom_{\Hom_\mathcal{D}(x,y)}(gr,f)\simeq \Hom_{\Hom_\mathcal{D}(x,y)}(r^*g,f)\simeq \Hom_{\End_\mathcal{D}(y)}(g,l^*f)\simeq \Hom_{\End_\mathcal{D}(y)}(g,fl).
	\end{equation}
	Putting $f=r$, for all $g\in \Hom_\mathcal{D}(x,y)$, the counit map induces an equivalence $\Hom_{\Hom_\mathcal{D}(x,y)}(gr,r)\simeq \Hom_{\End_\mathcal{D}(y)}(g,rl)$, exhibiting $rl$ as an endomorphism object for $r$. 	

\end{proof*}



\begin{construction}\label{LModunfold}
	Let $\mathcal{K}$ be a collection of $\infty$-categories.  Suppose that $\mathcal{C}\in \Alg_{E_1\otimes \mathcal{O}}(\cat_\infty(\mathcal{K}))$.  By \cite{Hinich2023} 8.1.3, there is $\mathcal{O}$-monoidal category $\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))^\otimes\to \mathcal{O}^\otimes$.  The universal property of the Boardman-Vogt tensor product induces a functor $LM^\otimes \otimes \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))^\otimes\to \cat_\infty(\mathcal{K})^\otimes$.  This unstraightens to a coCartesian fibration 
\begin{equation}
	\widetilde{\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))}^\otimes \to LM^\otimes \otimes \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))^\otimes. 
\end{equation}
Define coCartesian fibrations 
\begin{align}
p:\Alg_{LM}(\widetilde{\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))})\to \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))^\otimes\\
q:\Alg_{Ass}(\widetilde{\LMod_\mathcal{C}(\cat_\infty(\mathcal{K})})\to \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))^\otimes
\end{align}
as in \cite{LurieHA} 3.2.4.1.  Pulling back along the map $Ass\to LM$ induces a commutative diagram 
\begin{equation}
	\begin{tikzcd}[column sep=5]
		\Alg_{LM}(\widetilde{\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))})^\otimes\ar[rr,"\phi"]\ar[dr,swap,"p"]&&\Alg_{Ass}(\widetilde{\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))})^\otimes\ar[dl,"q"]\\
											     &\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))^\otimes
	\end{tikzcd}
\end{equation}
Suppose that $\alpha$ is a $p$-coCartesian morphism in $\Alg_{LM}(\widetilde{\LMod_\mathcal{C}(\cat_\infty)})^\otimes$.  By \cite{LurieHA} 3.2.4.3, for all $o\in Ass\hookrightarrow LM$, $\alpha(o)$ is coCartesian in $\LMod_\mathcal{C}(\cat_\infty)^\otimes$ over $\mathcal{O}^\otimes$.  Then, again by \cite{LurieHA} 3.2.4.3, $\phi(\alpha)$ is a $q$-coCartesian edge in $\Alg_{Ass}(\widetilde{\LMod_\mathcal{C}(\cat_\infty)})^\otimes$.  Then $\phi$ is a morphism of coCartesian fibrations. 

$\mathcal{O}$-monoidaly straightening over $\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$ (see \cite{RamziUnstraightening}), and noting that each fiber is an object in $\widehat{\cat}_\infty(\mathcal{K})$ by \cite{LurieHA} 4.2.3.5, we obtain a pair of lax $\mathcal{O}$-monoidal functors and a monoidal natural transformation between them 
\begin{equation}
	\begin{tikzcd}[column sep=80]
		\LMod_\mathcal{C}(\cat_\infty(\mathcal{K})) 
		\ar[bend left=30,"\Alg_{LM}",name=U]{r}[name=U]{}
		\ar[bend right=30,swap,"\Alg_{Ass}"]{r}[name=D]{} &
		       \widehat{\cat}_\infty(\mathcal{K})
		       \arrow[shorten <=10pt,shorten >=10pt,Rightarrow,to path={(U) -- node[label=right:$\phi$]{} (D)}]
			    \end{tikzcd}
	\end{equation}
This gives $\Theta:\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))\to \Fun([1],\widehat{\cat}_\infty(\mathcal{K})_0)$. 

\end{construction}

\subsection{The right Eilenberg-Moore functor}
\begin{notation}
	Suppose that $\mathcal{D}$ is an $(\infty,2)$-category and $y\in \mathcal{D}$.  Denote by $\mathcal{D}^R_{/y}$ the full subcategory of $\mathcal{D}_{/y}$ on the right adjoint morphisms to $y$. 
\end{notation}

\begin{construction}\label{endmonfunc}
	Suppose that $\mathcal{D}$ is an $(\infty,2)$-category, and $x\xrightarrow{f} y$ and $x'\xrightarrow{f'} y$ are objects in $\mathcal{D}$ that admit endomorphism monads, and $h$ is a morphism from $f$ to $f'$ in $\mathcal{D}_{/y}$, i.e. a morphism $h:x\to x'$ making the apparent diagram commute.  Then $f$ becomes a left $\End(f')$-module using the factorization $f\simeq f'h$.  By remark \ref{internalhomfunctorial}, there is unique morphism $\End(h):\End(f')\to \End(f)$ such that $\End(h)^*f\simeq f\circ h\in \LMod_{\End(f')}(\Hom_\mathcal{D}(x',y))$. 

Every object in $\mathcal{D}_{/y}^R$ admits an endomorphism object in $\End_\mathcal{D}(y)$ by proposition \ref{adjendmon}.  This will define a functor $\End_L:\mathcal{D}_{/y}^R\to \Alg(\End_\mathcal{D}(y))^{op}$.  Functoriality of this assigmnent is treated with more care in \cite{HeineMonadicity} 6.28. 

\end{construction}

\begin{construction}\label{EMRepresentable}
	Suppose that $\mathcal{K}$ is a collection of $\infty$-categories and $\mathcal{C}\in \Alg_\mathcal{O}(\cat_\infty(\mathcal{K}))$.  Consider the lax $\mathcal{O}$-monoidal functor $\Theta:\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))\to \Fun([1],\widehat{\cat}_\infty(\mathcal{K})_0)$ defined in construction \ref{LModunfold}, which takes $\mathcal{M}\in \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$ to $\phi_\mathcal{M}:\Alg_{LM}(\mathcal{M})\to \Alg(\mathcal{C})$.  For all $\mathcal{M}\in \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$, $\phi_\mathcal{M}$ is a Cartesian fibration, and morphisms in $\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$ are taken to morphisms of Cartesian fibrations by \cite{LurieHA} 4.2.3.2. 
	Then $\Theta$ factors $\mathcal{O}$-monoidaly through $cart_{/\Alg_{Ass}(\mathcal{C})}$.  Using the underlying category adjunction, we have $Fun(Alg(\mathcal{C})^{op},\cat_\infty(\mathcal{K})_0)\simeq Fun_{(\infty,2)}(Alg(\mathcal{C})^{op},\cat_\infty(\mathcal{K}))_0$.  Note that straightening is monoidal and $\cat_\infty$-linear (see \cite{RamziUnstraightening}).  By straightening over $\Alg_{Ass}(\mathcal{C})$, we obtain lax $\mathcal{O}$-monoidal $(\infty,2)$-functor 
	\begin{equation}
		\LMod^*_{-}(-):	\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))\to \Fun_{(\infty,2)}(\Alg(\mathcal{C})^{op},\cat_\infty(\mathcal{K}))^\otimes. 
	\end{equation}
  One should note that, for algebra morphism $f:A\to B$ in $\Alg(\mathcal{C})$ and $\mathcal{M}\in \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$, the functor $\LMod_B(\mathcal{M})\to \LMod_A(\mathcal{M})$ is given by restriction of scalars along $f$. 
Specializing construction \ref{Yonedamodule} to $\mathcal{V}=\cat_\infty$, and composing with $\LMod^*_-(-)$, we obtain lax $\mathcal{O}$-monoidal $(\infty,2)$-functor 
	\begin{equation}
		\mathcal{D}^{1op}\to \LMod_{\End_\mathcal{D}(y)}(\cat_\infty)\to \Fun_{(\infty,2)}(\Alg(\End_\mathcal{D}(y))^{op},\cat_\infty(\mathcal{K}))^\otimes,
	\end{equation}
which takes $x\in \mathcal{D}$ to the functor $\LMod_{-}(\Hom_\mathcal{D}(x,y)):\Alg(\End_\mathcal{D}(y))^{op}\to \cat_\infty(\mathcal{K})$.  Using $\mathcal{O}$-monoidal tensor hom adjunction, we have $\mathcal{O}$-monoidal equivalence
\begin{multline}
	\Fun_{(\infty,2)}(\mathcal{D}^{1op},\Fun_{(\infty,2)}(\Alg(\End_\mathcal{D}(y))^{op},\cat_\infty(\mathcal{K})))^\otimes\simeq \Fun_{(\infty,2)}(\mathcal{D}^{1op}\otimes \Alg(\End_\mathcal{D}(y))^{op},\cat_\infty(\mathcal{K}))^\otimes\\
	\simeq \Fun_{(\infty,2)}(\Alg(\End_\mathcal{D}(y))^{op},\Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty(\mathcal{K})))^\otimes,
\end{multline}
which takes the previously defined lax $\mathcal{O}$-monoidal $(\infty,2)$-functor to lax $\mathcal{O}$-monoidal functor 
\begin{equation}
	\LMod^*_{-}(\Hom_\mathcal{D}(-,y)):	\Alg(\End_\mathcal{D}(y))^{op}\to \Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty(\mathcal{K}))^\otimes,
\end{equation}
with algebra morphism $f:A\to B$ in $\Alg(\End_\mathcal{D}(y))$ taken to restriction of scalars along $f$.
\end{construction}

\begin{definition}\label{defEilenbergMoore}
	Suppose that $\mathcal{D}\in \cat_{(\infty,2)}$ and $y\in \mathcal{D}$.  Suppose that $T\in \Alg(\End_\mathcal{D}(y))$ is a monad on $y\in \mathcal{D}$.  
\begin{itemize}
	\item An \underline{Eilenberg-Moore object} for $T$ is a an object $\EM(T)\in \mathcal{D}$ with morphism $f:\EM(T)\to y$ in $\mathcal{D}$ so that postcomposition with $f$ induces a natural equivalence 
		\begin{equation}
			\Hom_\mathcal{D}(-,\EM(T))\to \LMod^*_T(\Hom_\mathcal{D}(-,y)).
		\end{equation}
		That is, $\EM(T)$ represents the $(\infty,2)$-functor $\LMod^*_T(\Hom_{\mathcal{D}}(\_,y)):\mathcal{D}^{1op}\to \cat_\infty$ given in construction \ref{EMRepresentable}.  We say that $T$ \underline{admits an  Eilenberg-Moore object} if such an object exists.
	\item We say that $\mathcal{D}\in \cat_{(\infty,2)}$ \underline{admits Eilenberg-Moore objects at $y$} if every monad on $y$ admits an Eilenberg-Moore object. 
\end{itemize}
\end{definition}
\begin{proposition}[\cite{StefanichPhD} 7.3.5]\label{presentableEM}
	Suppose that $\mathcal{D}\in \Pr^{\cat_\infty}$.  Then $\mathcal{D}$ admits Eilenberg-Moore objects at $y$ for all $y\in \mathcal{D}$.  
\end{proposition}
\begin{proposition}[\cite{StefanichPhD} 7.3.7]\label{Stefanich7.3.7}
	Suppose that $\mathcal{D}$ is an $(\infty,2)$-category, $y\in \mathcal{D}$, and $T\in \Alg(\End_\mathcal{D}(y))$ is a monad on $y$.  Suppose that $g:X\to y$ is a module for $T$, and $g$ exhibits $X$ as an Eilenberg-Moore object for $T$.  Then $g$ admits a right adjoint and the induced morphism $T\to \End(g)$ is an equivalence. 
\end{proposition}

\begin{notation}
Suppose that $\mathcal{D}$ is an $(\infty,2)$-category, $y\in \mathcal{D}$, and $T$ is a monad in $\mathcal{D}$ which admits an Eilenberg-Moore object.  We shall denote the object by $\EM(T)\in \mathcal{D}$, and the right adjoint monadic morphism by $\EM_R(T):\EM(T)\to y$.  
\end{notation}



\begin{theorem}\label{EMR}
	Suppose that $\mathcal{D}\in \Alg_\mathcal{O}(\cat_{(\infty,2)})$ admits Eilenberg-Moore objects at $y\in \Alg_\mathcal{O}(\mathcal{D})$.  Then, there is an adjunction 
	\begin{equation}
		\begin{tikzcd}
			\Alg(\End_\mathcal{D}(y))^{op}\ar[r,shift left=2,"\EM_R"{name=B}]&		\mathcal{D}_{/y}^R \ar[l,shift left=2,"\End_L"{name=A}] \ar[phantom,from=A,to=B,"\dashv"rotate=90] 
		\end{tikzcd}
	\end{equation}
$\EM_R$ is fully faithful and lax $\mathcal{O}$-monoidal, taking a monad $T$ on $y$ to its Eilenberg-Moore object, and morphisms of monads to restriction of scalars, and $\End_L$ is as defined in construction \ref{endmonfunc}. 

\end{theorem}

\begin{proof*}
	By the assumption that $\mathcal{D}$ admits Eilenberg-Moore objects, $\LMod^*_{-}(\Hom_\mathcal{D}(-,y)):\Alg(\End_\mathcal{D}(y))^{op}\to \Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty)$ factors monoidaly through the full subcategory on representable presheaves $\Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty)^{rep}\subset \Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty)$.  
Since $\Alg(\End_\mathcal{D}(y))$ has initial object given by the algebra structure on $id_y$, which is taken to $\Hom_\mathcal{D}(\_,y)$ under the above functor, the desired functor is given by 
\begin{equation}
	\EM_R:\Alg(\End_\mathcal{D}(y))^{op}\simeq (\Alg(\End_\mathcal{D}(y))_{id/})^{op}\to \Fun(\mathcal{D}^{1op},\cat_\infty)^{rep}_{/\Hom_\mathcal{D}(-,y)}\simeq \mathcal{D}_{/y},
\end{equation}
where the final equivalence is by monoidal Yoneda embedding, and factors through $\mathcal{D}_{/y}^R$ by proposition \ref{Stefanich7.3.7}.  We may prove that $End_L$ provides a left adjoint to $EM_R$ as in the proof of \cite{HeineMonadicity} theorem 6.30, which we recall here. 

Consider the identity $id\in Fun^{oplax}(\mathcal{D}^R_{/y},\mathcal{D}^R_{/y})$ in the $(\infty,2)$-category of endofunctors and oplax natural transformations (which can be constructed using the Gray tensor product of \cite{Campion}).  Let $L\in Fun^{oplax}(\mathcal{D}^R_{/y}, \mathcal{D}^R_{/y})$ be the Eilenberg-Moore object of its endomorphism monad.  We can identify $EM_R\circ End_L:\mathcal{D}^R_{/y}\to \mathcal{D}^R_{/y}$ with $L$.  

Since $End(id)$ acts on $id$, we obtain a canonical morphism $id\to L \in Fun(\mathcal{D}^R_{/y},\mathcal{D}^R_{/y})$, i.e, a natural transformation $\eta:id\Rightarrow EM_R\circ End_L$.  Suppose that $f\in \mathcal{D}^{mon}_{/y}\subset \mathcal{D}^R_{/y}$ is a monadic morphism (i.e. in the essential image of $EM_R\circ End_L$).  Then $\eta_f$ is an equivalence by proposition \ref{Stefanich7.3.7}.  Suppose that $f\in \mathcal{D}^R_{/y}$.  Then $EM_R\circ End_L(\eta_f)$ is an equivalence by \cite{HeineMonadicity} lemma 4.16 part 3.  It follows from \cite{LurieHTT} 5.2.7.4 that $EM_R$ is fully faithful with left adjoint $End_L$. 





\end{proof*}
\begin{remark}
	A global (non-monoidal) version of theorem \ref{EMR} for structured monads appears in \cite{HeineMonadicity} theorem 6.30. 
\end{remark}


\begin{corollary}
	Suppose that $\mathcal{D}\in \Alg_\mathcal{O}(\cat_{(\infty,2)})$, $y\in co\Alg_\mathcal{O}(\mathcal{D})$ and $T\in \Alg_{E_1\otimes \mathcal{O}}(\End_\mathcal{D}(y))$.  Then $\EM(T)\in \Alg_\mathcal{O}(\mathcal{D})$. 
\end{corollary}

\subsection{The left Eilenberg-Moore functor}




\begin{construction}\label{EMop}
	Let $\mathcal{K}$ be a collection of $\infty$-categories containing $\Delta^{op}$, and suppose that $\mathcal{C}\in \Alg_{E_1\otimes\mathcal{O}}(\cat_\infty(\mathcal{K}))$.  Consider the functor $\Theta:\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))\to \Fun([1],\widehat{\cat}_\infty(\mathcal{K}))$ given in construction \ref{LModunfold}, which takes $\mathcal{M}\in \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$ to $\phi_\mathcal{M}:\Alg_{LM}(\mathcal{M})\to \Alg(\mathcal{C})$. 

	Since $\mathcal{K}$-contains $\Delta^{op}$, $\phi_\mathcal{M}$ is a coCartesian fibration by \cite{LurieHA} 4.6.2.17 and \cite{LurieHTT} 5.2.2.5.  Moreover, an edge $(A,L)\to (B,N)$ in $\Alg_{LM}(\mathcal{M})$ is coCartesian over $\Alg(\mathcal{C})$ if and only if it induces an equivalence $B\otimes_AL\simeq N$ (see for example the proof of \cite{LurieHA} 4.8.3.15).  Since $\Theta$ takes a morphism in $\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$ to a natural transformation which preserves geometric realizations, we see that morphisms in $\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$ are taken to morphisms of coCartesian fibrations.  Then $\Theta$ factors $\mathcal{O}$-monoidaly through $cocart_{/\Alg_{Ass}(\mathcal{C})}$.  Note that straightening is monoidal and $\cat_\infty$-linear (see \cite{RamziUnstraightening}).  By straightening over $\Alg(\mathcal{C})$ and using the underlying category adjunction, we obtain lax $\mathcal{O}$-monoidal $(\infty,2)$-functor 
	\begin{equation}
		\LMod_{!-}(-):\LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))\to \Fun_{(\infty,2)}(\Alg(\mathcal{C}),\cat_\infty(\mathcal{K}))^\otimes. 
	\end{equation}
One should note that, for algebra morphism $f:A\to B$ in $\Alg(\mathcal{C})$ and $\mathcal{M}\in \LMod_\mathcal{C}(\cat_\infty(\mathcal{K}))$, the functor $\LMod_A(\mathcal{M})\to \LMod_B(\mathcal{M})$ is given by extension of scalars along $f$. 	
	Composing with the lax $\mathcal{O}$-monoidal functor of constructions \ref{Yonedamodule}, applied to $\mathcal{V}=\cat_\infty(\mathcal{K})$, gives lax $\mathcal{O}$-monoidal $(\infty,2)$-functor 
	\begin{equation}
		\mathcal{D}^{1op}\to \LMod_{\End_\mathcal{D}(y)}(\cat_\infty(\mathcal{K}))\to \Fun_{(\infty,2)}(\Alg(\End_\mathcal{D}(y)),\cat_\infty(\mathcal{K}))^\otimes. 
	\end{equation}
Using $\mathcal{O}$-monoidal tensor hom adjunction we have $\mathcal{O}$-monoidal equivalence
\begin{multline}
	\Fun_{(\infty,2)}(\mathcal{D}^{1op},\Fun_{(\infty,2)}(\Alg(\End_\mathcal{D}(y)),\cat_\infty(\mathcal{K})))^\otimes\simeq \Fun_{(\infty,2)}(\mathcal{D}^{1op}\otimes \Alg(\End_\mathcal{D}(y)),\cat_\infty(\mathcal{K}))^\otimes\\
	\simeq \Fun_{(\infty,2)}(\Alg(\End_\mathcal{D}(y)),\Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty(\mathcal{K})))^\otimes,
\end{multline}
which takes the previously defined lax $\mathcal{O}$-monoidal $(\infty,2)$-functor to a lax $\mathcal{O}$-monoidal $(\infty,2)$-functor
\begin{equation}
	\LMod_{!-}(\Hom_\mathcal{D}(-,y)):\Alg(\End_\mathcal{D}(y))\to \Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty(\mathcal{K}))^\otimes, 
\end{equation}
with algebra morphism $f:A\to B$ in $\Alg(\End_\mathcal{D}(y))$ taking to extension of scalars along $f$. 
\end{construction}

\begin{notation}
 Suppose that $\mathcal{D}$ is an $(\infty,2)$-category and $y\in \mathcal{D}$.
	\begin{itemize}
		\item Denote by $\mathcal{D}_{y/}^L$ the full subcategory of $\mathcal{D}_{/y}$ on the left adjoint morphisms from $y$. 
		\item Suppose that $T$ is a monad on $y$ which admits an Eilenberg-Moore object.  Denote the corresponding left-adjoint monadic morphism by $\EM_L(T):y\to \EM(T)$. 
	\end{itemize}

\end{notation}


\begin{theorem}\label{EML}
	Let $\mathcal{K}$ be a collection of $\infty$-categories containing $\Delta^{op}$, and suppose that $\mathcal{D}\in \Alg_\mathcal{O}(\cat^{\mathcal{S};\mathcal{K}}_{(\infty,2)})$, admits Eilenberg-Moore objects at $y\in \Alg_\mathcal{O}(\mathcal{D})$.  Then there is lax $\mathcal{O}$-monoidal functor 
	\begin{equation}
\EM_L:\Alg(\End_\mathcal{D}(y))\to \mathcal{D}_{y/}^L
	\end{equation}
	taking a monad $T$ to the left-adjoint monadic morphism $y\to \EM(T)$, and morphisms of monads to extension of scalars.  
\end{theorem}
\begin{proof*}
	By the assumption that $\mathcal{D}$ admits Eilenberg-Moore objects, $\LMod_{!-}(\Hom_\mathcal{D}(-,y)):\Alg(\End_\mathcal{D}(y))\to \Fun(\mathcal{D}^{1op},\cat_\infty(\mathcal{K}))$ factors $\mathcal{O}$-monoidaly through the full subcategory on representable presheaves $\Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty(\mathcal{K}))^{rep}\subset \Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty(\mathcal{K}))$.  $\Alg(\End_\mathcal{D}(y))$ has an initial object $id_y$.  The desired functor is given by 
	\begin{equation}
\EM_L:		\Alg(\End_\mathcal{D}(y))\simeq \Alg(\End_\mathcal{D}(y))_{id_y/}\to \Fun_{(\infty,2)}(\mathcal{D}^{1op},\cat_\infty)_{\Hom_\mathcal{D}(\_,y)/}^{rep}\simeq \mathcal{D}_{y/}.
	\end{equation}
\end{proof*}

\begin{remark}
	\cite{HaugsengMonad} corollary 5.8 provides a closely related result for `cosmifiable' $(\infty,2)$-categories, and \cite{ReutterZetto} section 4, for $\Pr^\mathcal{V}$. 
\end{remark}


\begin{corollary}
	Suppose that $\mathcal{D}\in \Alg_\mathcal{O}(\cat_{(\infty,2)})$ locally admits geometric realizations, $y\in \Alg_\mathcal{O}(\mathcal{D})$ and $T\in \Alg_{E_1\otimes \mathcal{O}}(\End_\mathcal{D}(y))$.  Then $\EM(T)\in \Alg_\mathcal{O}(\mathcal{D})$. 
\end{corollary}




\subsection{Application to relative tensor products of modules}

\begin{construction}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{K}$ is a collection of $\infty$-categories, and $\mathcal{C}\in \Alg_{E_1\otimes \mathcal{O}}(\cat^\mathcal{V}(\mathcal{K}))$.  Then $\RMod_\mathcal{C}(\cat^\mathcal{V}(\mathcal{K}))\in \Alg_\mathcal{O}(\Pr^{\cat^\mathcal{V}(\mathcal{K})})$ by \cite{LurieHA} 4.8.5.16 applied to a larger universe.  We may then consider $RMod_\mathcal{C}(\cat^\mathcal{V}(\mathcal{K}))$ as a large $(\infty,2)$-category which is locally compatible with $\mathcal{K}$-indexed colimits by changing enrichment along the underlying category functor $\cat^\mathcal{V}(\mathcal{K})\to \cat_\infty(\mathcal{K})$.
\end{construction}
\begin{construction}\label{algmonad}
	Suppose that $\mathcal{V}\in \Alg_{E_1\otimes \mathcal{O}}(\Pr)$, $\mathcal{K}$ is a collection of $\infty$-categories containing $\Delta^{op}$, and $\mathcal{C}\in \Alg_{\mathcal{O}}(Cat^\mathcal{V}(\mathcal{K}))$.  There is $\mathcal{O}$-monoidal equivalence $\RMod_\mathcal{C}(Cat^\mathcal{V}(\mathcal{K}))\simeq \Fun_\mathcal{V}(B\mathcal{C}^{op},Cat^\mathcal{V}(\mathcal{K}))$.  By delooping hypothesis (theorem \ref{delooping}), we get $E_1\otimes \mathcal{O}$-monoidal equivalence $\mathcal{C}\simeq \End_{\RMod_\mathcal{C}(Cat^\mathcal{V}(\mathcal{K}))}(\mathcal{C})$.  In particular, we get an $\mathcal{O}$-monoidal equivalence 
	\begin{equation}
A\mapsto A\otimes -:\Alg(\mathcal{C})\simeq \Alg(\End_{\RMod_\mathcal{C}(Cat^\mathcal{V}(\mathcal{K}))}(\mathcal{C}))
	\end{equation}
	between algebra objects in $\mathcal{C}$ and right $\mathcal{C}$-linear monads on $\mathcal{C}$.  Note that we have an equivalence of categories $\LMod_{A}(\mathcal{C})\simeq \LMod_{A\otimes-}(\mathcal{C})$. 
\end{construction}


\begin{corollary}\label{AlgebraEMR}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{K}$ is a collection of $\infty$-categories, and $\mathcal{C}\in \Alg_{E_1\otimes \mathcal{O}}(Cat^\mathcal{V}(\mathcal{K}))$.  Then there is a fully faithful $\mathcal{O}$-monoidal functor 
	\begin{equation}
		\LMod^*_{-}(\mathcal{C}):\Alg(\mathcal{C})^{op}\to \RMod_\mathcal{C}(Cat^\mathcal{V}(\mathcal{K}))_{/\mathcal{C}}
	\end{equation}
such that for $A\in \Alg(\mathcal{C})$, the induced morphism $\LMod_A(\mathcal{C})\to \mathcal{C}$ is the right adjoint in a monadic adjunction in $\RMod_\mathcal{C}(Cat^\mathcal{V}(\mathcal{K}))$.  

Moreover, $\LMod^*_{-}(\mathcal{C})$ admits a left adjoint. 
\end{corollary}
\begin{proof*}
Note that by proposition \ref{presentableEM}, $\RMod_\mathcal{C}(\cat^\mathcal{V})$ admits monoidal Eilenberg-Moore objects.  Then the desired functor is given by 
\begin{equation}
	\begin{tikzcd}
		\Alg(\mathcal{C})\ar[r,"\ref{algmonad}"]&\End_{\RMod_\mathcal{C}(Cat^\mathcal{V})}(\mathcal{C})\ar[r,"\EM_R"]&\RMod_\mathcal{C}(\cat^\mathcal{V})_{/\mathcal{C}}.
	\end{tikzcd}
\end{equation}

\end{proof*}



\begin{corollary}\label{AlgebraEML}
	Suppose that $\mathcal{V}\in \Alg_{E_2\otimes \mathcal{O}}(\Pr)$, $\mathcal{K}$ is a collection of $\infty$-categories containing $\Delta^{op}$, and $\mathcal{C}\in \Alg_{E_1\otimes \mathcal{O}}(Cat^\mathcal{V}(\mathcal{K}))$.  Then there is a $\mathcal{O}$-monoidal functor 
	\begin{equation}
		\LMod_{!-}(\mathcal{C}):\Alg(\mathcal{C})\to \RMod_\mathcal{C}(Cat^\mathcal{V}(\mathcal{K}))_{\mathcal{C}/}
	\end{equation}
such that for $A\in \Alg(\mathcal{C})$, the induced morphism $\mathcal{C}\to \LMod_A(\mathcal{C})$ is the left adjoint in a monadic adjunction in $\RMod_\mathcal{C}(Cat^\mathcal{V}(\mathcal{K}))$.  
\end{corollary}
\begin{proof*}
Note that by proposition \ref{presentableEM}, $\RMod_\mathcal{C}(\cat^\mathcal{V}(\mathcal{K}))$ admits monoidal Eilenberg-Moore objects, and is locally compatible with geometric realizations.  Then the desired functor is given by 
\begin{equation}
	\begin{tikzcd}
		\Alg(\mathcal{C})\ar[r,"\ref{algmonad}"]&\End_{\RMod_\mathcal{C}(Cat^\mathcal{V})}(\mathcal{C})\ar[r,"\EM_L"]&\RMod_\mathcal{C}(\cat^\mathcal{V}(\mathcal{K}))_{/\mathcal{C}}.
	\end{tikzcd}
\end{equation}
\end{proof*}





\begin{example}
	Corollaries \ref{AlgebraEMR} and \ref{AlgebraEML} appear to be very similar.  One should notice that \ref{AlgebraEML} requires that $\mathcal{C}$ is is locally compatible with geometric realizations, while \ref{AlgebraEMR} does not.  It is useful to provide an example to illustrate the difference.
	\begin{itemize}
		\item If one has bialgebra object $A$ in $\mathcal{C}$, (i.e. $A\in co\Alg(\Alg(\mathcal{C}))$, the monoidality of $\LMod_{-}^*(\mathcal{C})$ gives the natural monoidal structure on $\LMod_A(\mathcal{C})$. 
		\item Alternatively, if one gives $E_{k+1}$ algebra object $A$ in $\mathcal{C}$, monoidality of $\LMod_{!-}(\mathcal{C})$ gives the natural $E_k$-monoidal structure on $\LMod_A(\mathcal{C})$. 
	\end{itemize}

\end{example}

We use an alternative proof to obtain that the analogous functor for presentably $\mathcal{V}$-enriched $\infty$-categories is also fully faithful with right adjoint.  We are not sure to what extent this applies beyond the presentable case. 

\begin{lemma}\label{presentableAlgEML}
	Suppose that $\mathcal{V}\in \Alg_{E_{k+1}}(\Pr)$ for $k\geq 1$, and $\mathcal{C}\in \Alg_{E_{k}}(Pr^\mathcal{V})$.  Then there is a fully faithful $E_{k-1}$-monoidal functor 
	\begin{equation}
		\RMod_{!-}(\mathcal{C}):\Alg(\mathcal{C})\to \LMod_\mathcal{C}(Pr^\mathcal{V})_{\mathcal{C}/}
	\end{equation}
such that for $A\in \Alg(\mathcal{C})$, the induced morphism $\mathcal{C}\to \LMod_A(\mathcal{C})$ is the left adjoint in a monadic adjunction in $\RMod_\mathcal{C}(Pr^\mathcal{V})$.  

Moreover, $LMod_{!-}(\mathcal{C})$ admits a right adjoint. 
\end{lemma}

\begin{proof*}
	It follows from corollary \ref{AlgebraEML} (or alternatively \cite{LurieHA} 4.8.5.16) applied to a larger universe that one obtains an $E_{i-1}$-monoidal functor $LMod_{!-}(\mathcal{C})_0:Alg(\mathcal{C}_0)\to RMod_\mathcal{C}(Pr)_{\mathcal{C}/}$.  By \cite{LurieHA}, this is fully faithful with right adjoint.  By \cite{LurieHA} theorem 7.1.3.1 and corollary 7.1.3.4, one has a monoidal equivalence $RMod_\mathcal{C}(Pr^\mathcal{V})\simeq RMod_{\mathcal{C}_0}(Pr)$.  The desired functor is given by the composition
	\begin{equation}
		Alg(\mathcal{C}):=Alg(\mathcal{C}_0)\xrightarrow{LMod_{!-}(\mathcal{C})_0}RMod_{\mathcal{C}_0}(Pr)_{/\mathcal{C}}\simeq RMod_\mathcal{C}(Pr^\mathcal{V}).
	\end{equation}

\end{proof*}




\begin{definition}\label{Moritadef}
	Suppose that $\mathcal{V}\in \Alg_{E_{k+1}}(\Pr)$, $\mathcal{K}$ is a small collection of $\infty$-categories containing $\Delta^{op}$, and $\mathcal{C}\in Alg(\cat^\mathcal{V}(\mathcal{K}))$.  Then the \underline{Morita category} $Morita(\mathcal{C})$ of $\mathcal{C}$ is the essential image of the functor $\LMod_{!-}(\mathcal{C}):\Alg(\mathcal{C})\to \RMod_\mathcal{C}(\cat^\mathcal{V}(\mathcal{K}))$.  Notice that this inherits a natural enrichment over $\cat^\mathcal{V}(\mathcal{K})$ from the enrichment of $\RMod_\mathcal{C}(\cat^\mathcal{V}(\mathcal{K}))$.  It follows from \cite{LurieHA} theorem 4.8.4.1 that $Hom_{Morita(\mathcal{C})}(A,B)$ agrees with the (enriched) category of $B-A$ bimodule objects in $\mathcal{C}$. 
\end{definition}
\begin{remark}
	This definition has the same flavour as the ones given in in \cite{LurieHA} 4.8.4.9 and \cite{SoergelBimodule} section 6, and provides an enriched version of the `higher Morita category' and `even higher Morita catgory' constructions of \cite{ScheimbauerPhD,Haugseng2017,JohnsonFreyd2017,HaugsengEnMor,Haugseng2023}.  Note however, that the Morita category does not generally admit geometric realizations, so we may not be able to take iterated Morita categories. 

\end{remark}

\begin{warning}
	The version of Morita category given in \ref{Moritadef} uses the opposite convention for left/right modules to others listed above.  This is fixed by instead considering the essential image of $\RMod_{!-}(\mathcal{C}):\Alg(\mathcal{C})\to \LMod_\mathcal{C}(\Pr^\mathcal{V})$. 
\end{warning}



\section{Condensation in enriched categories}\label{condensationsec}
We will now treat the theory of condensation in enriched $\infty$-categories.  We begin by sketching how one recovers many familiar features from the ordinary fusion categorical theory of condensation in this language. 


\begin{construction}\label{theorybimodule}
Suppose that $\mathcal{V}\in \Alg(\Pr)$ and $\mathfrak{C}\in \cat^\mathcal{V}$.  We think of $\mathfrak{C}$ as the `category of vacua', where objects are vacua and morphisms are defects between them.  In particular, for $v\in \mathfrak{C}$ a vacuum, $\Omega_v\mathfrak{C}\in \Alg(\mathcal{V})$ consists of operators on $v$, so that $\Omega_v\mathfrak{C}$ is `the theory built on $v$'.  Note that $B\Omega_v\mathfrak{C}$ is the full subcategory of $\mathfrak{C}$ on the object $v$.  Choosing another $w\in \mathfrak{C}$ and using Yoneda embedding and restriction, we obtain a functor
\begin{equation}
	\begin{tikzcd}
		B\Omega_w\mathfrak{C}\ar[r,hookrightarrow]&\mathfrak{C}\ar[r,"\yo"]&\Fun_\mathcal{V}(\mathfrak{C}^{op},\mathcal{V})\ar[r]&\Fun_\mathcal{V}((B\Omega_v)^{op},\mathcal{V}).
	\end{tikzcd}
\end{equation}
Noting the equivalence $\Fun_\mathcal{V}(B\Omega_w\mathfrak{C},\Fun_\mathcal{V}((B\Omega_v)^{op},\mathcal{V})))\simeq {}_{\Omega_w\mathfrak{C}}Bimod_{\Omega_v\mathfrak{C}}(\mathcal{V})$, we see that this picks out $\Hom_\mathfrak{C}(v,w)$, viewed as an $\Omega_w\mathfrak{C}-\Omega_v\mathfrak{C}$ bimodule.  That is, the collection of defects from v to w is naturally a bimodule over the theories on v and w. 
\end{construction}

\begin{definition}
Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$, $\mathcal{K}$ is a $\tav_0$-small collection of $\tav_0$-small $\infty$-categories containing $\Delta^{op}$.  Suppose that $\mathfrak{C}\in \cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}$, considered as a \underline{category of vacua}.  An \underline{i-form symmetry} \underline{algebra} on $v\in\mathfrak{C}$ is $A\in \Alg_{E_{i+1}}(\Omega_v^{i+1}\mathfrak{C})$.   
\end{definition}


\begin{example}\label{EM1}
	Suppose that $\mathcal{W}\in \Alg(\Pr)$ and $\mathfrak{C}\in \cat^\mathcal{W}$ , which we think of as a category of $\mathcal{W}$-enriched vacua.  Suppose that $v\in \mathfrak{C}$.  Suppose that $\mathfrak{C}$ admits Eilenberg-Moore objects (definition \ref{defEilenbergMoore}).  Consider $\Omega_v\mathfrak{C}\in \Alg_{E_1}(\cat^\mathcal{W})$, describing endo-defects of the vacuum $v$.  Then $A\in \Alg(\Omega\mathfrak{C})$ describes a family of 0-form symmetries in the theory on $v$.  Notice that $A$ is a monad on $v$ in $\mathfrak{C}$.  Then the left Eilenberg-Moore functor $\EM_L:\Alg(\Omega\mathfrak{C})\to \mathfrak{C}_{/v}$ picks out another vacuum $\EM_L(A)\in \mathfrak{C}$, equipped with an adjunction 
	\begin{equation}
		\begin{tikzcd}
			v\ar[r,shift left=2,"\EM_L(A)"{name=A}]&\EM(A)\ar[l,shift left=2,"\EM_R(A)"{name=B}"]\ar[phantom,from=A,to=B,"\dashv"rotate=-90], 
		\end{tikzcd}
	\end{equation}
	which we will call the \underline{condensate} of $A$.  The condensate of $A$ satisfies the universal property of an Eilenberg-Moore object: for any $w\in \mathfrak{C}$ and any $f\in \LMod_A(\Hom_\mathfrak{C}(w,v))$, $f$ factors uniquely through $\EM_R(A)$.  Described physically, for any vacuum $w\in \mathfrak{C}$ and any $A$-invariant defect $f:w\to v$, $f$ may be replaced with a thin slice of the condensate $\EM(A)$, equipped with an essentially unique defect $\tilde{f}$ from $w$ to $\EM(A)$. 
	\begin{figure}[h]
		\centering
\begin{tikzpicture}
	\draw[thick] (0,0.75)--(0,-.75);
	\draw[thick] (6,.75)--(6,-.75);
	\draw[thick] (8,.75)--(8,-.75);
	\node at (-1,0){$v$};
	\node at (1,0){$w$};
	\node at (0,1.1){$f$};
	\node at (5,0){$v$};
	\node at (7,0){$\EM(A)$};
	\node at (9,0){$w$};
	\node at (6,1.1){$\EM_R(A)$};
	\node at (8,1.1){$\tilde{f}$};
	\node at (3,0){$\simeq$};
\end{tikzpicture}
\end{figure}

We will see that this defines a 1-unital 1-condensation of $v$ onto $\EM(A)$, in the sense of definition \ref{truncatedcondensation} below.  Moreover, by proposition \ref{semiadduniv}, this is compatible with semiadditive structures. 

Since we can choose $\mathcal{W}=\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n-1)}$ (notation \ref{inftyndef}),  we may choose $\mathfrak{C}$ to contain $n$-dimensional vacua.  Then the above procedure describes condensation of $0$-form symmetries in arbitrary dimension. 
\end{example}
\begin{remark}
In the example above, while $f\in \Hom_\mathfrak{C}(w,v)$, $v$ is drawn to the left, so that the left-right ordering of the image is compatible with the ordering of composable morphisms. 
\end{remark}



\begin{example}\label{bimodulecondensation}
	Suppose now $\mathcal{W}\in \Alg_{E_\infty}(\Pr)$, $\mathcal{K}$ is a collection of $\infty$-categories containing $\Delta^{op}$, and $\mathcal{C}\in \Alg(Cat^\mathcal{W}(\mathcal{K}))$, and consider $\mathfrak{C}=\RMod_\mathcal{C}(Cat^\mathcal{W}(\mathcal{K}))\in \Pr_{Cat^\mathcal{W}}$.  One should think of $\mathfrak{C}$ as the category of \underline{$\mathcal{C}$-equivariant vacua}.  This has a canonical choice of vacuum $c\in \RMod_\mathcal{C}(Cat^\mathcal{W}(\mathcal{K}))$: namely $\mathcal{C}$ itself, considered as a left $\mathcal{C}$ module.  In this case, the theory on the vacuum $c$ is $\Omega_c(\RMod_\mathcal{C}(Cat^\mathcal{W}))\simeq \mathcal{C}$. 

	Suppose that $A\in \Alg(\mathcal{C})$.  Then by corollary \ref{AlgebraEML}, $\LMod_A(\mathcal{C})\in \RMod_\mathcal{C}(Cat^\mathcal{W}(\mathcal{K}))$ is another choice of vacuum, equipped with pair of functors 
	\begin{equation}
		\begin{tikzcd}
			c\ar[r,shift left=2,"Free"{name=A}]&			\LMod_A(\mathcal{C})\ar[l,shift left=2,"For"{name=B}]\ar[phantom, from=A,to=B,"\dashv"rotate=-90]
		\end{tikzcd}
	\end{equation}
	giving the forgetful-free adjunction, which is morover an adjunction in $\RMod_\mathcal{C}(Cat^\mathcal{W}(\mathcal{K}))$.  This this will specify a 1-unital $1$-condensation of $\mathcal{C}$ onto $\LMod_A(\mathcal{C})$ in $\RMod_\mathcal{C}(\cat^\mathcal{W}(\mathcal{K}))$.  Moreover, by corollary \ref{semiadduniv}, this is compatible with semiadditive structures. 

Importantly, the theory on the vacuum $\LMod_A(\mathcal{C})$ is given by 
\begin{equation}
	\Omega_{\LMod_A(\mathcal{C})}\RMod_\mathcal{C}(Cat^\mathcal{W})\simeq \End_{\RMod_\mathcal{C}(Cat^\mathcal{W})}(\LMod_A(\mathcal{C}))\simeq {}_ABimod_A(\mathcal{C}).
\end{equation}
The ${}_ABimod_A(\mathcal{C})-\mathcal{C}$ bimodule given by construction \ref{theorybimodule} is $\Hom_{\RMod_\mathcal{C}(Cat^\mathcal{W})}(c,\LMod_A(\mathcal{C}))\simeq \LMod_A(\mathcal{C})$, with the distinguished morphism $c\xrightarrow{Free} \LMod_A(\mathcal{C})$ corresponding to $A\in \LMod_A(\mathcal{C})$.  This recovers a typical picture of two dimensional condensation, presented for example in \cite{BhardwajTachikawa2017}. 

Notice that this is a special case of the previous example, but a particularly relevant one for symmetry TFTs.  
\end{example}

\subsection{Higher multifusion categories}\label{multifusionsec}
Multifusion categories are characterized amongst linear monoidal categories by certain dualizability or finiteness properties.  In order to treat the general case, we must introduce the analogue of these finiteness properties in $\mathcal{V}$-enriched $\infty$-categories, called $\mathcal{V}$-atomicity.  

We are intentionally vague with our treatment of weighted colimits and absolute colimits.  See \cite{HeineWeighted} for more details, and particularly section 5.5 for absolute colimits and Cauchy completion.



\begin{definition}
	Suppose that $\mathcal{V}\in \Alg(\Pr)$ and $\mathcal{B}\in \Pr^\mathcal{V}$. $M\in \mathcal{B}$ is called \underline{$\mathcal{V}$-atomic} if $\Hom_\mathcal{B}(M,-):\mathcal{B}\to \mathcal{V}$ preserves small colimits and $\mathcal{V}$-tensoring.   
\end{definition}

\begin{lemma}[\cite{ReutterZetto} 3.22 ]\label{ReutterZetto3.22}
	Suppose that $\mathcal{V}\in Alp_{E_2}(\Pr)$ and $A\in \Alg(\mathcal{V})$.  Then $M\in \RMod_A(\mathcal{V})\in \Pr^\mathcal{V}$ is $\mathcal{V}$-atomic iff it is right dualizable.  That is, iff there exists ${}^\vee M\in \LMod_A(\mathcal{V})$ such that the functor
\begin{equation}
	-\otimes_A{}^\vee M:\RMod_A(\mathcal{V})\to \mathcal{V}
\end{equation}
 is right adjoint to  $-\otimes M:\mathcal{V}\to \RMod_A(\mathcal{V})$. 
\end{lemma}
\begin{proof*}
	If $M$ is left dualizable, then $\Hom_{\RMod_A(\mathcal{V})}(M,-)\simeq -\otimes_A{}^\vee M$ preserves colimits and left $\mathcal{V}$-tensoring, so it is $\mathcal{V}$-atomic. 
	If $M$ is $\mathcal{V}$-atomic, then $\Hom_{\RMod_A(\mathcal{V})}(M,-)$ preserves the bar construction, so the following equivalence exhibits $\Hom_{\RMod_A}(M,A)$ as a right dual to $M$.  
	\begin{equation}
		\Hom_{\RMod_A(\mathcal{V})}(M,N)\simeq \Hom_{\RMod_A(\mathcal{V})}(M,N\otimes_A A)\simeq N\otimes_A \Hom_{\RMod_A(\mathcal{V})}(M,A)
	\end{equation}
\end{proof*}
\begin{definition}
	An \underline{absolute colimit} is a (weighted) colimit that is preserved by \textbf{all} functors.  A $\mathcal{V}$-category is called \underline{Cauchy complete} if it admits all absolute colimits. 
\end{definition}
\begin{definition}
	Suppose that $\mathcal{V}\in \Alg(\Pr)$ and $\mathcal{C}\in \cat^\mathcal{V}$.  The \underline{Cauchy completion} of $\mathcal{C}$ is the full subcategory $Cau(\mathcal{C})\subset \mathcal{P}_\mathcal{V}(\mathcal{C})$ on the atomic objects. 
\end{definition}

\begin{proposition}[\cite{HeineWeighted} 5.50,5.53]
	 $Cau(\mathcal{C})$ is small and Cauchy complete. 
\end{proposition}



\begin{remark}
Suppose that $\mathcal{V}\in \Alg(\Pr)$ and $A\in \Alg(\mathcal{V})$.  Notice that $\RMod_A(\mathcal{V})\simeq \mathcal{P}_\mathcal{V}(BA)$.  Then $Cau(BA)$ consists exactly of the right-dualizable $A$-modules.  
\end{remark}



\begin{notation}
	Let $\mathcal{V}\in \Alg(\Pr)$.  
\begin{itemize}
	\item Denote by $\cat^\mathcal{V}(\Cau)\subset \cat^\mathcal{V}$ the full subcategory on the Cauchy complete $\mathcal{V}$-enriched $\infty$-categories. 
	\item Denote by $\Semiadd^\mathcal{V}(\Cau)\subset \cat^\mathcal{V}$ the subcategory on the Cauchy complete semiadditive $\mathcal{V}$-enriched $\infty$-categories and additive functors.  
\end{itemize}

\end{notation}

\begin{proposition}[\cite{HeineWeighted} 5.50, 5.52, 5.53, 5.56, 5.76]\label{leftpreadd}
	Let $\mathcal{V}\in \Alg_{E_{k+1}}(\Pr)$ for $k\geq 0$.  The category $\cat^\mathcal{V}(Cau)$ is presentably $E_k$-monoidal.  There is an adjunction 
	\begin{equation}
		\begin{tikzcd}
			\cat^\mathcal{V}\ar[r,shift left=2,"\Cau"{name=A}]&\cat^\mathcal{V}(Cau)\ar[l,shift left=2,"\iota"{name=B}]\ar[phantom,from=A,to=B,"\dashv" rotate=-90],
		\end{tikzcd}
	\end{equation}
	where the Cauchy completion functor $\Cau$ is $E_k$-monoidal and the inclusion $\iota$ is fully faithful.   

If $\mathcal{V}$ is semiadditive, then $\Semiadd^\mathcal{V}(Cau)$ is presentably $E_{k}$-monoidal and semiadditive.  Since direct sums are absolute colimits in semiadditively-enriched categories, the above restricts to an adjunction 
	\begin{equation}
		\begin{tikzcd}
			\cat^\mathcal{V}\ar[r,shift left=2,"\Cau"{name=A}]&\Semiadd^\mathcal{V}(Cau)\ar[l,shift left=2,"\iota"{name=B}]\ar[phantom,from=A,to=B,"\dashv" rotate=-90],
		\end{tikzcd}
	\end{equation}
\end{proposition}


\begin{definition}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$.  Inductively define 
	\begin{align}
		\Semiadd^\mathcal{V}_{(\infty,0)}(\Cau):=\mathcal{V}		&&\Semiadd_{(\infty,n)}^\mathcal{V}(\Cau):=\Semiadd^{\Semiadd^\mathcal{V}_{(\infty,n-1)}(\Cau)}
	\end{align}

\end{definition}

\begin{construction}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$ is semiadditive and $0\leq i\leq n-1$.  Notice that the looping/delooping adjunction of theorem \ref{delooping} acts as an adjunction between $E_1$ and $E_0$ algebras in the categories defined above.  Composing with the semiadditive adjunction of proposition \ref{leftpreadd}, we obtain an adjunction
\begin{equation}
		\begin{tikzcd}
			\Alg_{E_1}(\Semiadd^\mathcal{V}_{(\infty,i)}(\Cau))\ar[r,shift left =2,"B"{name=B}]&\ar[l,shift left=2,"\Omega"{name=A}]\Alg_{E_0}(\cat^{\Semiadd^\mathcal{V}_{(\infty,i)}(\Cau)})\ar[phantom,from=B,to=A,"\dashv" rotate=-90]\ar[r,shift left=2,"Cau"{name=C}]&\ar[l,shift left=2,"\iota"{name=D}]\Alg_{E_0}(\Semiadd^\mathcal{V}_{(\infty,i+1)}(\Cau))\ar[phantom,from=C,to=D,"\dashv" rotate=-90], 
		\end{tikzcd}
	\end{equation}
	where $B$ and $\Cau$ are $E_{n-i}$-monoidal.  We denote $\Sigma:=\Cau\circ B$, and abuse notation to denote $\Omega:=\Omega\circ \iota$.  Notice that the unit of this adjunction is an equivalence, since $\Omega_{\Sigma\mathcal{C}}(\mathcal{C})\simeq \Omega_{\RMod_\mathcal{C}}(\mathcal{C})\simeq \mathcal{C}$, and so $\Sigma$ is fully-faithful as an $(\infty,1)$-functor.  Define $\Omega^0:=id$, and inductively denote 
\begin{equation}
	\Omega^{l}:=\Omega\circ \Omega^{l-1}:\Alg_{E_{k-l}}(\Semiadd^\mathcal{V}_{(\infty,i+l)}(\Cau))\to \Alg_{E_{k}}(\Semiadd^\mathcal{V}_{(\infty,i)}(\Cau)), 
	\end{equation}
and similarly, denote $\Sigma^0:=id$, and inductively denote 
	\begin{equation}
		\Sigma^{l}:=\Sigma\circ \Sigma^{l-1}:\Alg_{E_k}(\Semiadd^\mathcal{V}_{(\infty,i)}(\Cau))\to \Alg_{E_{k-l}}(\Semiadd^\mathcal{V}_{(\infty,i+l)}(\Cau)). 
	\end{equation}

\end{construction}





\begin{definition}\label{Fusiondef}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$.  Let $\mathds{1}_\mathcal{V}\in \mathcal{V}$ be the monoidal unit.  Define the \textbf{category of} \underline{$\mathcal{V}$-multifusion $(\infty,k)$-categories} to be 
\begin{equation}
	\Fus_{(\infty,k)}(\mathcal{V}):=	\Sigma^{k+1}\mathds{1}_\mathcal{V}\in \Alg_{n-k-1}(\Semiadd^\mathcal{V}_{(\infty,k+1)}(\Cau)). 
\end{equation}
\end{definition}

\begin{example}
	Suppose that $\mathbb{K}$ is a field.  Then $\Vect_\mathbb{K}$ is presentably symmetric monoidal.  Denote 
	\begin{equation}
\Fus_k(\mathbb{K}):=\Fus_{(\infty,k)}(\Vect_\mathbb{K}), 
	\end{equation}
and call it the category of \underline{$\mathbb{K}$-linear multifusion $k$-categories}.   
\end{example}


\begin{remark}\label{moritasubcat}
	By lemma \ref{ReutterZetto3.22}, $\Fus_{(\infty,k)}(\mathcal{V})\subset \RMod_{\Sigma^k\mathds{1}_\mathcal{V}}(\Semiadd^{\mathcal{V}}_{(\infty,k)}(\Cau))$ is the full subcategory on the $1$-dualizable objects.  Using \cite{GaiottoJohnsonFreyd} corollary 4.2.3, one sees apriori that $\Fus_k(\mathbb{K})$ is slightly larger than the category of $\mathbb{K}$-linear multifusion k-categories defined in \cite{JohnsonFreyd} II.9, and they coincide if and only if every dualizable object in $\RMod_{\Sigma^k\mathds{1}_\mathcal{V}}$ comes from an algebra object, i.e. $\Sigma^{k+1}\mathds{1}_\mathcal{V}\subset Mor(\Sigma^k\mathds{1}_\mathcal{V})$.  

	We expect this to be true by combining the separable monads of \cite{DouglasReutter2018} appendix A with \cite{GaiottoJohnsonFreyd} theorem 3.3.3 and 4.2.2, which would exhibit the Cauchy completion of a locally Cauchy complete category as equivalent to the completion under Eilenberg-Moore objects of separable monads. 

If they do indeed coincide, then the above establishes symmetric monoidality of $\Fus_k(\mathbb{K})$, which is used extensively in \cite{JohnsonFreyd}. 

\end{remark}


\begin{remark}
	There is a forgetful functor 
\begin{equation}
\Sigma^{k+1}\mathds{1}_\mathcal{V}\subset \RMod_{\Sigma^k\mathds{1}_\mathcal{V}}(\Semiadd^\mathcal{V}_{(\infty,n)}(\Cau))\to \Semiadd^\mathcal{V}_{(\infty,n)}(\Cau), 
\end{equation}
so a $\mathcal{V}$-fusion $(\infty,n)$-category is in particular a semiadditive Cauchy complete $\mathcal{V}$-$(\infty,n)$-category.  
\end{remark}

\begin{example}
	Suppose that $\mathbb{K}$ is a field, and let $H\mathbb{K}\in \Alg_{E_\infty}(\Sp)$ be the associated Eilenberg-MacLane spectrum.  Consider $\Fus_{(\infty,n)}(\LMod_{H\mathbb{K}}(\Sp))$, where $\Sp$ is the category of spectra.  By \cite{LurieHA} 7.1.1.16, this consists of `multifusion $(\infty,n)$-categories' with enrichment in the (unbounded) derived category of $\mathbb{K}$. 
\end{example}





\subsection{Large condensates of $E_k$-algebras}\label{Largesec}
We would now like to implement the iterative condensation procedure for $E_i$-algebras of \cite{Kong2024} section 5.2 on our enriched multifusion categories, and we will refer the reader there for physical intuition.  However, Cauchy completions of deloopings do not generally admit geometric realizations, so corollary \ref{AlgebraEML} and theorem \ref{EML} do not apply.  A purely fusion-categorical approach circumvents this issue by considering only the algebras whose condensates are obtained as absolute colimits.  We shall proceed another way.  The functor $\Sigma$ described in the previous section is given by delooping, cocompleting, and then passing to the subcategory on atomic objects. 
\begin{equation}
\Sigma\mathcal{C}\subset \mathcal{P}_*(B\mathcal{C})\simeq \RMod_\mathcal{C}. 
\end{equation}
However, we need not consider consider only the atomic objects; an analogue of the iterative condensation procedure of \cite{Kong2024} can be applied to \textbf{any} right module or algebra object, not only the dualizable or `separable' ones.  This will take some care, as we do run into set-theoretic size concerns.  To demonstrate the relative size the relevant categories, it will be helpful for us to sketch one step in this iterative prodedure. 
\begin{equation}
	\begin{tikzcd}
		\Alg(\cat^{\mathcal{V}})\ar[d,shift left=2,"B"{name=B}]&\\
		\Alg_{E_0}(\widehat{\cat}^{\cat^\mathcal{V}})\ar[u,shift left=2,"\Omega"{name=A}]\ar[phantom,from=B,to=A,"\dashv"rotate=-180]\ar[r,shift left=2,"\mathcal{P}_{\cat^\mathcal{V}}"{name=C}]&\Alg_{E_{0}}(\Pr^{\cat^\mathcal{V}})\ar[l,shift left=2,"\iota"{name=D}]\ar[phantom,from=C,to=D,"\dashv"rotate=-90], 
	\end{tikzcd}
\end{equation}
If one begins with small monoidal $\mathcal{V}$-category $\mathcal{C}\in Alg(\cat^\mathcal{V})$, then $\RMod_\mathcal{C}(\cat^\mathcal{V})$ is identified with the image of $\mathcal{C}$ under the composition $\iota\circ \mathcal{P}_{\cat^\mathcal{V}}\circ B$.  Then $\RMod_\mathcal{C}(\cat^\mathcal{V})$ is \emph{large}.  Applying the relevant functor again to get the category of right modules over $\RMod_\mathcal{C}(\cat^\mathcal{V})$ gives a \emph{huge} category, and so on.  Then we can not iterate this functor within one universe. 

We will fix an infinite sequence of uncountable inaccessible cardinals $\tav_n$, and enforce that our (enriched) $(\infty,n)$-categories are are $\tav_n$-small and locally $\tav_{n-1}$ small.  In this way, each `categorical layer' has its own associated cardinality.  

We will now establish notation for the categories of $\mathcal{V}$-$(\infty,i)$-categories which are locally compatible with $\mathcal{K}$-indexed conical colimits.  This is somewhat cumbersome, but we hope that the role of each object will become clear when the iterative procedure is established.  

\begin{notation}For $\mathcal{W}\in \Alg(\tav_i\Pr)$, denote by $\tav_j\cat^\mathcal{W}$ the category of $\tav_j$-small $\mathcal{W}$-enriched $\infty$-categories.
\end{notation}



	\begin{remark}
		Notice that, if $\mathcal{W}\in \Alg(\tav_i\Pr)$ and $j\geq i$, then $\tav_j\cat^\mathcal{W}\in \tav_j\Pr$.  
	\end{remark}


	\begin{notation}\label{inftyndef}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\tav_0\Pr)$ is a $\tav_0$-presentably $E_n$-monoidal category.  (In particular, it is $\tav_0$-large and locally $\tav_0$-small).  Let $\mathcal{K}$ be a $\tav_0$-small collection of $\tav_0$-small $\infty$-categories.  

\begin{itemize}
	\item For $1\leq i\leq n$, inductively denote 
		\begin{align}
			\cat^{\mathcal{V};\mathcal{K}}_{(\infty,0)}(\mathcal{K}):=\mathcal{V}&&
			\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i)}(\mathcal{K}):=\tav_{i}\cat^{\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i-1)}(\mathcal{K})}(\mathcal{K})\in \Alg_{E_{n-i}}(\tav_{i+1}\Pr).
		\end{align}
	\item For $1\leq i\leq n$, inductively denote 
		\begin{align}
			\cat^{\mathcal{V};\mathcal{K}}_{(\infty,0)}:=\mathcal{V}&&			\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i)}:=\tav_i\cat^{\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i-1)}(\mathcal{K})}\in \Alg_{E_{n-i}}(\tav_{i+1}\Pr). 
		\end{align}	
	\item For $1\leq i\leq n$, denote 
		\begin{equation}
			s\Pr^{\mathcal{V};\mathcal{K}}_{(\infty,i)}:=\LMod_{\cat^{\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i-2)}(\mathcal{K})}}(\tav_{i}\Pr). 
		\end{equation}

	\item For $1\leq i\leq n$, denote 
\begin{equation}
			\Pr^{\mathcal{V};\mathcal{K}}_{(\infty,i)}:=\LMod_{\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i-1)}}(\tav_{i+1}\Pr). 
		\end{equation}
\end{itemize}
In all of the above cases, if $\mathcal{K}$ is empty, we shall omit it from our notation. 
\end{notation}
\begin{remark}
	$s\Pr^{\mathcal{V};\mathcal{K}}_{(\infty,i)}$ is nearly the same as $\Pr^{\mathcal{V};\mathcal{K}}_{(\infty,i)}$, but `one universe smaller'.  We introduce this notation as it is exactly the target for the delooping/cocompletion, and it includes lax monoidally into $\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i)}(\mathcal{K})$. 
\end{remark}




\begin{construction}

Notice that the looping and delooping functors of theorem \ref{delooping} acts as an adjunction between categories as defined above.  We compose this with the appropriate $\tav_i$-small enriched free cocompletion adjunction (denoted here only by $\mathcal{P}_*$ for readability)
\begin{equation}
	\begin{tikzcd}
		\Alg(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i)}(\mathcal{K}))\ar[d,shift left=2,"B"{name=B}]&\\\Alg_{E_0}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i+1)})\ar[u,shift left=2,"\Omega"{name=A}]\ar[phantom,from=B,to=A,"\dashv"rotate=-180]\ar[r,shift left=2,"\mathcal{P}_*"{name=C}]&\Alg_{E_{0}}(s\Pr^{\mathcal{V};\mathcal{K}}_{(\infty,i+1)})\ar[l,shift left=2,"\iota"{name=D}]\ar[phantom,from=C,to=D,"\dashv"rotate=-90], 
	\end{tikzcd}
\end{equation}
where $B$ and $\mathcal{P}_*$ are $E_{n-i}$-monoidal, and $\Omega$ and $\iota$ are lax $E_{n-i}$-monoidal.  We denote the composition $\bSigma:=\mathcal{P}_*\circ B$ and abuse notation to denote $\Omega:=\Omega\circ \iota$.  The unit of this adjunction is an equivalence since $\Omega_{\RMod_\mathcal{C}}(\mathcal{C})\simeq \mathcal{C}$, and so $\bSigma$ is fully faithful as an $(\infty,1)$-functor.  $\iota$ factors monoidally through $\Alg_{E_0}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i+1)}(\mathcal{K}))$, since a presentable category certainly has $\mathcal{K}$-indexed colimits. 
\begin{itemize}
	\item  Denote $\Omega^0:=id$, and for $1\leq k\leq n$, inductively define
			\begin{equation}
				\Omega^k:=\Omega\circ \Omega^{k-1}:\Alg_{E_0}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)})\to \Alg_{E_{k}}(Cat^{\mathcal{V};\mathcal{K}}_{(\infty,n-k)}(\mathcal{K})))
			\end{equation}
	\item Denote $\bSigma^0:=id$, and for $i+k\leq n$ and $1\leq l\leq k$, denote $\bSigma^l$ to be the composition
		\begin{equation}
			\begin{tikzcd}
				\Alg_{E_k}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i)}(\mathcal{K}))\ar[dr,"\BSigma^{l-1}"]& \\
\Alg_{E_{k-l}}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,i+l-1)}(\mathcal{K}))\ar[dr,swap,"\BSigma"]&\Alg_{E_{k-l+1}}(s\Pr^{\mathcal{V};\mathcal{K}}_{(\infty,i+l-1)})\ar[l,"\iota"]\\
											   &\Alg_{E_{k-l}}(s\Pr^{\mathcal{V};\mathcal{K}}_{(\infty,i+l)}). 
			\end{tikzcd}
		\end{equation}

\end{itemize}

\end{construction}


\begin{notation}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$ and $\mathcal{K}$ is a collection of $\tav_0$-small $\infty$-categories containing $\Delta^{op}$.  By construction, the functor defined in corollary \ref{AlgebraEML} acts as  
\begin{equation}
	\LMod_{!-}(\mathcal{C}):\Alg_{E_i}(\mathcal{C})\to \Alg_{E_{i-1}}(\bSigma\mathcal{C}). 
\end{equation}
Denote $\LMod_{!-}^0:=id$, and inductively denote 
\begin{equation}
	\LMod^l_{!-}:=\LMod_{!-}\circ \LMod^{l-1}_{!-}:\Alg_{E_k}(\mathcal{C})\to \Alg_{E_{k-l}}(\bSigma^l\mathcal{C}). 
\end{equation}
\end{notation}
We can now proceed just as in \cite{Kong2024} 5.2.2. 
\begin{definition}\label{largecondensationdef}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$, and $\mathcal{K}$ is a $\tav_0$-small collection of $\tav_0$-small $\infty$-categories containing $\Delta^{op}$.  Suppose that $\mathfrak{C}\in \cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}$ and $v\in \mathfrak{C}$.  Suppose that $A\in \Alg_{E_i}(\Omega^i_v\mathfrak{C})$.  The \underline{condensate} of $A$ is $\LMod^i_A\in \Alg_{E_0}(\bSigma^i\Omega^i_v\mathfrak{C})$. 
\end{definition}
\begin{remark}
	If one instead began with a monoidal $\mathcal{V}$-$(\infty,n-1)$ category $\mathcal{C}\in \Alg(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n-1)}(\mathcal{K}))$, then one applies the above condensation procedure to $B\mathcal{C}\in \Alg_{E_0}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)})$.  One then recovers a monoidal $\mathcal{V}$-$(\infty,n-1)$ category, given by $\Omega_{\LMod^i_A}$, which agrees with the category of $\LMod^{i-1}_A-\LMod^{i-1}_A$-bimodules (see example \ref{bimodulecondensation}).     
\end{remark}


It is necessary to show that the condensation procedure above is also compatible with semiadditive structures. 
\begin{proposition}\label{semiadduniv}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\tav_0\Pr)$ is semiadditive, and $\mathcal{K},\mathcal{K}'$ are $\tav_0$-small collections of $\tav_0$-small $\infty$-categories containing $\finset$.  Then 
	\begin{itemize}
		\item All objects and morphisms of $\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}(\mathcal{K}')$ are semiadditive, i.e. 
		\begin{equation}
			\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}(\mathcal{K}')\simeq \tav_n\Semiadd^{\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n-1)}(\mathcal{K})}. 
		\end{equation}
		\item $\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}(\mathcal{K}')$ is semiadditive. 
	\end{itemize}
\end{proposition}

\begin{proof*}
	We prove by induction on $n$.  When $n=1$, the first point follows from remark \ref{colimsemiadd}, and the second from lemma \ref{CatKsemiadd}.  Fix $n_0$, and suppose now that the result holds for $n=n_0$.  Then, by inductive hypothesis, $\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n_0)}(\mathcal{K})$ is semiadditive, so it follows from remark \ref{colimsemiadd} that every $\mathcal{C}\in \cat^{\mathcal{V};\mathcal{K}}_{(\infty,n_0+1)}(\mathcal{K}'):=\tav_{n_0+1}\cat^{\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n_0)}(\mathcal{K})}(\mathcal{K}')$ is semiadditive, and from lemma \ref{CatKsemiadd} that $\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n_0+1)}(\mathcal{K}')$ is semiadditive. 
\end{proof*}
\begin{remark}
	It follows from proposition \ref{semiadduniv} that, in the situation of definition \ref{largecondensationdef}, if one chooses $\mathcal{V}$ to be semiadditive and $\mathcal{K}$ containing finset and $\Delta^{op}$ and $\mathcal{K}'$ containing $\finset$, then $\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}(\mathcal{K}')\simeq \tav_n\Semiadd^{\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n-1)}(\mathcal{K})}$, and all categories that can be obtained by looping, delooping, or condensing are also semiadditive, obtaining a commutative monoid structure.  Then, if one wishes to work with semiadditive categories, one should fix such $\mathcal{K}$ and $\mathcal{K}'$ and work within $\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}(\mathcal{K}')$. 
\end{remark}

\begin{remark}
	One could instead build a functor analogous to $\Sigma$ or $\bSigma$ by delooping and then completing under some other family of colimits.  The two introduced here are chosen because functors between them are easily understood in terms of dualizable bimodules and bimodules, respectively. 
\end{remark}

\begin{remark}
	Using \cite{LurieHA} lemma 5.3.2.12, one may perform a variant of the iterated module category construction category above while remaining in the same universe.  This is completed by, at each iteration, picking a cardinal $\kappa$ for which $\mathcal{C}$ is $\kappa$-compactly generated, and then factoring $LMod_{!-}(\mathcal{C})$ through the presentably monoidal subcategory of $RMod_\mathcal{C}(Pr^\mathcal{V})$ on the $\kappa$-compactly generated objects.  We do not do this here, as it depends on the cardinals chosen at each stage in the iteration, and these can not be chosen uniformly for all enriched monoidal categories $\mathcal{C}$.  
\end{remark}



\subsection{Truncated condensations}\label{Truncatedsec}
We would like to be able to construct dualizable objects from our iterative condensation procedure.  To do this, we introduce a variant of the notion of condensation introduced in \cite{GaiottoJohnsonFreyd}.  
\begin{definition}[\cite{GaiottoJohnsonFreyd} 2.1.1]\label{truncatedcondensation}Let $\mathcal{C}$ be an $(\infty,n)$-category, and $X,Y\in\mathcal{C}$. 
	\begin{itemize}
		\item A \underline{0-condensation} of $X$ onto $Y$ is a 1-morphism $X\to Y$.
		\item For $k\geq 1$, inductively define a \underline{$k$-condensation} of $X$ onto $Y$, denoted by $X\condense^kY$, to be a pair of morphisms $f:X\rightleftharpoons Y:g$ and a $(k-1)$-condensation $fg\condense^{k-1}id_Y$. 

\item A $k$-condensation in $\mathcal{C}$ will be called \underline{truncated} when $k<n$. 
		\item For $k\geq i\geq 1$, a $k$-condensation $X\condense^kY$ is called \underline{$i$-unital} if, for all $k-i\leq j\leq k-1$, the defining $j$-condensation $f_jg_j\condense^{j}id^j_Y$ is the counit of an adjunction. 
		\item The \underline{walking $k$-condensation} $\spadesuit_k$ is the free $(\infty,k+1)$-category on a $k$-condensation.  
	\end{itemize}

	\end{definition}

	\begin{remark}
	Note that there is fully faithful functor $\cat_{(\infty,n)}\to \cat_{(\infty,n+1)}$ (see \cite{BSP2020}).  Then, for $\mathcal{C}\in \cat_{(\infty,n)}$ and $m\geq n$, we can view $\mathcal{C}$ as an $(\infty,m)$-category with only invertible $i$-morphisms for $i>n$.  


For $k\leq n-1$, a k-condensation in $\mathcal{C}$ is equivalent to an $(\infty,n)$-functor $\spadesuit_k\to \mathcal{C}$, where $\spadesuit_k$ is viewed as an $(\infty,n)$-category.  

For $k>n-1$, a $k$-condensation in $\mathcal{C}$ is equivalent to an $(\infty,k+1)$-functor $\spadesuit_k\to \mathcal{C}$, where $\mathcal{C}$ is viewed as an $(\infty,k+1)$-category. 
	\end{remark}



\begin{warning}
The definition of a walking k-condensation differs slightly from the definition of a walking k-condensation given in \cite{GaiottoJohnsonFreyd}.  Their walking k-condensation is recovered from our walking $k$-condensation as the image under the left adjoint functor $\cat_{(\infty,k+1)}\to \cat_{(\infty,k)}$, which inverts all $k+1$ morphisms.  In particular, a k-condensation in an $(\infty,k)$- (or weak $k$-) category $\mathcal{C}$, in the sense of definition \ref{truncatedcondensation}, is equivalent to a k-condensation in $\mathcal{C}$ in the sense of \cite{GaiottoJohnsonFreyd} definition 2.1.1. 

This is necessary, since we wish to be able to speak of $k$-condensations in $(\infty,n)$-categories for $k<n$ with non-invertible top cell, motivating the `truncated condensation' terminology.  For this reason, the value of $k$ for any $k$-condensation shall always be specified. 
\end{warning}

\begin{remark}\label{kadjunctions}
	One should notice the resemblance between a $k$-unital $k$-condensation and $k$-rigid objects.  In particular, a $k$-unital $k$-condensation defines a $k$-adjunction if all of the associated units are also $i$-rigid for appropriate $i$.  In our context, since our condensations will be constructed from iterated condensation of monads, this will occur exactly when the corresponding monads are rigid. 
\end{remark}



\begin{example}
There is an $(\infty,2)$-functor $\spadesuit_1\rightarrow \Adj$.  Then every adjunction in an $(\infty,2)$-category $\mathcal{D}$ induces a $1$-condensation in $\mathcal{D}$.  This will be the basis for the examples to follow. 
\end{example}

\begin{remark}
	Suppose that $\mathfrak{C}\in \cat^{\mathcal{V}}_{(\infty,n)}$ and $v\in \mathfrak{C}$.  We consider the pair $(\mathfrak{C},v)$ as giving an object in $\Alg_{E_0}(\cat^\mathcal{V}_{(\infty,n)})$. 
\end{remark}
\begin{notation}Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$, $0\leq i\leq n$.  Suppose that $\mathfrak{C}\in \cat^\mathcal{V}_{(\infty,n)}$, and $v\in \mathfrak{C}$ is such that $v\in \mathfrak{C}$ is such that $\Omega^j_v\mathfrak{C}$ admits Eilenberg-Moore objects at its unit for all $0\leq j\leq i-1$.  Denote $\EM^0:=id$, and for $1\leq j \leq i$, inductively denote 
	\begin{equation}
\EM^j=For\circ \EM_R\circ \EM^{j-1}:\Alg_{E_i}(\Omega^i\mathfrak{C})\to \Alg_{E_{i-j}}(\Omega^{i-j}\mathfrak{C})
	\end{equation}
	where $For$ is the forgetful functor $\Omega^i\mathfrak{C}_{/x}\to \Omega^i\mathfrak{C}$. 	


\end{notation}



\begin{theorem}\label{monadcondensation}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$, $0\leq i\leq n$, and $\mathcal{K}$ is a $\tav_0$-small collection of $\tav_0$-small $\infty$-categories containing $\Delta^{op}$.  Suppose that 
\begin{enumerate}
	\item $\mathfrak{C}\in \cat^{\mathcal{V};\mathcal{K}}_{(\infty,n)}$. 
	\item $v\in \mathfrak{C}$ is such that $\Omega^j_v\mathfrak{C}$ admits Eilenberg-Moore objects at its unit for all $0\leq j\leq i-1$. 
	\item $A\in \Alg_{E_i}(\Omega_v^i\mathfrak{C})$. 
\end{enumerate}
Then there is an i-unital i-condensation $v\condense^i\EM^i(A)$ in $\mathfrak{C}$. 
\end{theorem}


\begin{proof*}
	We prove by induction on $i$.  Suppose that $i=0$.  Then an $E_0$-algebra object in $A\in \Alg_{E_0}(\mathfrak{C},v)$ is exactly a 1-morphism $v\to A$, giving a $0$-condensation $v\condense^0A$. 


	Suppose now that $i_0\geq 0$ is finite, and the claimed result holds for all $1\leq i\leq i_0$.  Suppose that $A\in \Alg_{E_{i_0+1}}(\Omega^{i_0+1}_v\mathfrak{C})$.  

	By Dunn additivity (\cite{LurieHA} theorem 5.1.2.2), $A$ determines an object $A\in \Alg_{E_{i_0}}(\Omega^{i_0}_{id_v}(\Omega_v\mathfrak{C}))$.  It follows from the inductive hypothesis that one obtains a $i_0$-unital $i_0$-condensation $id_v\condense^{i_0}\EM^{i_0}(A)$.  By proposition \ref{Stefanich7.3.7}, $\EM^{i_0}(A)$ is equivalent to the endormorphism monad of a monadic adjunction 
\begin{equation}
	\begin{tikzcd}
		\EM^{i_0+1}(A)\ar[r,shift left=1,"r"]&v\ar[l,shift left=1,"l"]
	\end{tikzcd}
\end{equation}
Then we have specified morphisms $l:v\leftrightharpoons \EM^{i_0+1}(A):r$, with $i_0$-condensation $id_v\condense^{i_0}\EM^{i_0}(A)$.  It follows by universal property of $\spadesuit_{i_0+1}$ that this lifts to a $i_0+1$ condensation $v\condense^{i_0+1}\EM^{i_0+1}(A)$, which is moreover $i_0+1$-unital since it is $1$-unital and the the $i_0$-condensation $id_v\condense^{i_0}\EM^{i_0}(A)$ is $i_0$-unital.
\end{proof*}



\begin{corollary}\label{higherbasechange}
	Suppose that $\mathcal{V}\in \Alg_{E_n}(\Pr)$, $\mathcal{K}$ is a $\tav_0$-small collection of $\tav_0$-small $\infty$-categories containing $\Delta^{op}$.  Suppose that $1\leq i\leq n$, $\mathcal{C}\in \Alg_{E_i}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n-i)})$ and $A\in \Alg_{E_i}(\mathcal{C})$.  

	Then there is $i$-unital $i$-condensation $\bSigma^{i-1}\mathcal{C}\condense^i \LMod^i_A$ in $\bSigma^i\mathcal{C}$. 

\end{corollary}
\begin{proof*}
	Note that for $j\leq i$, we have $\Omega^j\bSigma^i_\mathcal{C}\simeq \bSigma^{i-j}_\mathcal{C}\simeq \RMod^{i-j}_\mathcal{C}$.  In particular, $\Omega^i\bSigma^i_\mathcal{C}\simeq \mathcal{C}$.  Then $\Omega^j_{\BSigma^{i-1}_\mathcal{C}}\bSigma^i \mathcal{C}$ admits Eilenberg-Moore objects at its unit for all $0\leq j\leq i-1$. We have the identity $\LMod_{-}\simeq \EM:\Alg(\bSigma^j\mathcal{C})\to \bSigma^{j+1}\mathcal{C}$.  Then the result follows from theorem \ref{monadcondensation} applied to $\mathfrak{C}=\bSigma^i_\mathcal{C}$. 

\end{proof*}

\begin{remark}
	If one chooses $\mathcal{C}\simeq \bSigma B$ for some $B\in \Alg_{E_{i+1}}(\cat^{\mathcal{V};\mathcal{K}}_{(\infty,n-i-1)})$, then one should view corollary \ref{higherbasechange} as giving a sort of `higher base-change' $\RMod^i_B\condense^i\LMod^i_A$ for $E_i$-algebras.
\end{remark}


\begin{remark}
	If an algebra $A$ is `separable' in the appropriate sense, then its descendants $\LMod_{A}^i$ are dualizable.  By corollary \ref{higherbasechange} and remark \ref{kadjunctions}, any separable algebra object $A\in \Alg_{E_{n-i}}(\bSigma^i\mathds{1}_\mathcal{V})$ induces a fully-unital \textbf{untruncated} condensation, and so is fully-dualizable in $\bSigma^i\mathcal{C}$. 
\end{remark}

\subsection{Centers and centralizers}\label{centralizersec}
Below, we will introduce the notions of center and centralizer for coherent symmetric $\infty$-operads.  We will primarily care for the case $\mathcal{O}=E_k$, which does indeed satisfy these conditions. 
\begin{definition}[\cite{LurieHA} 5.3.1.2, 5.3.1.12]
	Suppose that $\mathcal{O}$ is a coherent symmetric $\infty$-operad and $\mathcal{V}\in Alg_{E_1\otimes \mathcal{O}}(Pr)$.  Then $Alg_\mathcal{O}(\mathcal{V})$ is $E_1$-monoidal, hence a left module over itself.  Let $\mathds{1}_\mathcal{V}\in Alg_\mathcal{O}(\mathcal{V})$ be the monoidal unit, and suppose we have morphism $f:\mathds{1}_\mathcal{V}\otimes \mathcal{C}\to \mathcal{B}$ in $Alg_\mathcal{O}(\mathcal{V})$.  The \underline{$\mathcal{O}$-centralizer} of $f$ is terminal amongst objects $\mathcal{A}\in Alg_\mathcal{O}(\mathcal{V})$ equipped with a morphism $\mathcal{A}\otimes \mathcal{C}\to \mathcal{B}$ making the following diagram commute
	\begin{equation}
		\begin{tikzcd}
			& \mathcal{A}\otimes \mathcal{C}\ar[dr]&\\
			\mathds{1}_\mathcal{V}\otimes \mathcal{C}\ar[ur,"\iota_\mathcal{A}\otimes id_\mathcal{C}"]\ar[rr,swap,"f"]&&\mathcal{B},
		\end{tikzcd}
	\end{equation}
	where $\iota_\mathcal{A}:\mathds{1}_\mathcal{V}\to \mathcal{A} $ is the unit morphism.  The $\mathcal{O}$-centralizer of $f$ exists by \cite{LurieHA} theorem 5.3.1.14, and will be denoted by $\FZ_\mathcal{O}(f)$. 	
\end{definition}

\begin{definition}
	Suppose that $\mathcal{V}\in Alg_{E_1\otimes \mathcal{O}}(Pr)$ and $\mathcal{C}\in Alg_\mathcal{O}(\mathcal{V})$.  The \underline{$\mathcal{O}$-center} of $\mathcal{C}$ is the $\mathcal{O}$ centralizer of $id_\mathcal{C}:\mathcal{C}\to \mathcal{C}$, denoted by $\FZ_\mathcal{O}(\mathcal{C}):=\FZ_\mathcal{O}(id_\mathcal{C})\in Alg_{E_1\otimes \mathcal{O}}(\mathcal{V})$, where we note that $\FZ_\mathcal{O}(id_\mathcal{C})$ obtains an additional $E_1$-monoidal structure as in \cite{LurieHA} remark 5.3.1.13. 
\end{definition}
\begin{example}
	Consider $\cat_\infty\in Alg_{E_\infty}(Pr)$. 
	\begin{itemize}
		\item Consider a monoidal category $\mathcal{C}\in Alg(\cat_\infty)$.  The \underline{Drinfeld center} of $\mathcal{C}$ is $\FZ_{E_1}(\mathcal{C})\in Alg_{E_2}(\cat_\infty)$.  
		\item Consider a braided monoidal category $\mathcal{D}\in Alg_{E_2}(\cat_\infty)$.  The \underline{M\"uger center} of $\mathcal{D}$ is $\FZ_{E_2}(\mathcal{D})\in Alg_{E_3}(\cat_\infty)$. 
	\end{itemize}

\end{example}
\begin{theorem}[\cite{LurieHA} 5.3.1.30]\label{5.3.1.30}
	Suppose that $\mathcal{O}$ is a coherent symmetric $\infty$-operad, and $\mathcal{V}\in Alg_{E_1\otimes \mathcal{O}}(Pr)$ and $f:\mathcal{C}\to \mathcal{D}$ is a morphism in $Alg_\mathcal{O}(\mathcal{V})$.  Define $\Mod^{\mathcal{O}}_\mathcal{C}(\mathcal{V})$ as in \cite{LurieHA} 3.3.3, and consider $f^*\mathcal{D}\in Mod^{\mathcal{O}}_{\mathcal{C}}(\mathcal{V})$ (\cite{LurieHA} 3.4.1.7).  Then we have an equivalence 
	\begin{equation}
		\FZ_\mathcal{O}(f)\simeq \underline{Hom}_{\Mod^{\mathcal{O}}_{\mathcal{C}}(\mathcal{V})}(\mathcal{C},f^*\mathcal{D})
	\end{equation}
	between the $\mathcal{O}$-centralizer of $f$ and the morphism-object between $\mathcal{C}$ and $\mathcal{D}$, viewed as $\mathcal{O}$-modules over $\mathcal{C}$. 
\end{theorem}
\begin{corollary}
The $\mathcal{O}$-center of $\mathcal{C}$ can be identified with endomorphisms of $\mathcal{C}$, viewed as an $\mathcal{O}$-module over itself. 
\begin{equation}
	\FZ_\mathcal{O}(\mathcal{C})\simeq \underline{End}_{\Mod^\mathcal{O}_\mathcal{C}(\mathcal{V})}(\mathcal{C}). 
\end{equation}

\end{corollary}
The following is adapted from the proof of \cite{LurieHA} 5.3.2.5.  
\begin{proposition}\label{iterativecentralizer}

	Suppose that $\mathcal{V}\in Alg_{E_{k+1}}(Pr)$, and $f:\mathcal{C}\to \mathcal{D}$ is a morphism in $Alg_{E_k}(\mathcal{V})$.  Then one has an equivalence in $Alg_{E_k}(\mathcal{V})$
\begin{equation}
	\FZ_{E_k}(f)\simeq \Omega \FZ_{E_{k-1}}(\bSigma f). 
\end{equation}
\end{proposition}

\begin{proof*}
Using corollary \ref{AlgebraEML} (or alternatively \cite{LurieHA} theorem 4.8.5.16) applied to a larger universe, together with \cite{LurieHA} 4.8.5.11, one obtains an adjunction 
\begin{equation}
\begin{tikzcd}
	Alg_{E_k}(\mathcal{V})\ar[r,shift left=2,"\BSigma"]&Alg_{E_{k-1}}(Pr^\mathcal{V})\ar[l,shift left=2,"\Omega"]
\end{tikzcd}
\end{equation}
where $\bSigma=RMod_{!-}(\mathcal{V})$ is fully faithful and monoidal.  This gives equivalence 

\begin{equation}
	Hom_{Alg_{E_k}(\mathcal{V})}(\mathcal{A},\Omega \FZ_{E_{k-1}}(f))\simeq Hom_{Alg_{E_{k-1}}(Pr^\mathcal{V})}(\bSigma\mathcal{A},\FZ_{E_{k-1}}(f)). 
\end{equation}
Using the universal property of $\FZ_{E_{k-1}}(\bSigma f)$, this is identified with the collection of morphisms $\bSigma (\mathcal{A})\otimes \bSigma (\mathcal{C})\to \bSigma (\mathcal{D})$ making the following diagram commute 
\begin{equation}
		\begin{tikzcd}
			&\bSigma (\mathcal{A})\otimes \bSigma (\mathcal{C})\ar[dr]&\\
			\bSigma (\mathcal{C})\ar[ur]\ar[rr,swap,"\BSigma(f)"]&&\bSigma (\mathcal{D}). 
		\end{tikzcd}
	\end{equation}
Using that $\bSigma$ is fully faithful and monoidal, this is identified with the collection of morphisms $\mathcal{A}\otimes \mathcal{C}\to \mathcal{D}$ making the following diagram commute

\begin{equation}
		\begin{tikzcd}
			&\mathcal{A}\otimes \mathcal{C}\ar[dr]&\\
			\mathcal{C}\ar[ur]\ar[rr,swap,"f"]&&\mathcal{D}, 
		\end{tikzcd}
	\end{equation}
	which, using the universal property of $\FZ_{E_k}(f)$, is in turn identified with $Hom_{Alg_{E_k}(\mathcal{V})}(\mathcal{A},\FZ_{E_k}(f))$.  We then get an isomorphism $Hom_{Alg_{E_k}(\mathcal{V})}(\mathcal{A},\FZ_{E_k}(f))\simeq Hom_{Alg_{E_{k-1}}(Pr^\mathcal{V})}(\mathcal{A},\Omega \FZ_{E_{k-1}}(\bSigma f))$.  The result follows from Yoneda lemma. 
\end{proof*}
This offers a simplified method of calculating centralizers, since $E_1$ and $E_0$ centralizers are more easily accessible using therem \ref{5.3.1.30}.  As a special case, we recover \cite{Kong2024} theorem 2.3.25. 
\begin{corollary}
	Suppose that $\mathcal{V}\in Alg_{E_{k+1}}(Pr)$ and $\mathcal{C}\in Alg_{E_k}(\mathcal{V})$.  Then one has an equivalence in $Alg_{E_{k+1}}(\mathcal{V})$
	\begin{equation}
		\FZ_{E_k}(\mathcal{C})\simeq \Omega^{k-i}\FZ_{E_i}(\bSigma^{k-i} \mathcal{C}). 
	\end{equation}

\end{corollary}




\subsection{Morita equivalence of atomic condensates}\label{Moritasec}
In the following subsection, we would like to recover some analogue of the fact that condensates of fusion categories are Morita equivalent.  We will see that this is true only if one `takes the condensate' with respect to a dualizable module category.  
\begin{remark}
	Suppose that $\mathcal{V}\in \Alg(\Pr)$ and $A\in \Alg(\mathcal{V})$.  Then $\RMod_A(\mathcal{V})\in \Pr^\mathcal{V}$ is generated from the free $A$ modules under geometric realizations, and so generated from $BA\subset \RMod_A(\mathcal{V})$ under $\mathcal{V}$-tensoring and geometric realizations.  
\end{remark}


Recall the construction of the enhanced representable functor $\Hom^{enh}_\mathcal{B}(M,-):\mathcal{B}\to \RMod_{\End(M)}(\mathcal{V})$ from construction \ref{Yonedamodule}.  If $\Hom_\mathcal{B}(M,-)$ preserves $K$-indexed colimits and $\mathcal{V}$-tensoring, then so does $\Hom^{enh}_\mathcal{B}(M,-)$.  The following is an adaptation of \cite{EGNO} 7.10.1. 
\begin{proposition}\label{Homenhequiv}
	Suppose that $\mathcal{V}\in \Alg(\Pr)$, $\mathcal{B}\in \Pr^\mathcal{V}$.  For $M\in \mathcal{B}$, denote $\langle M\rangle\subset \mathcal{B}$ to be the $\mathcal{V}$-tensored subcategory generated from $M$.  Suppose that $M\in \mathcal{B}$ and $K\in \cat_\infty$ are such that $\langle M\rangle$ generates $\mathcal{B}$ under $K$-indexed colimits, and $\Hom_\mathcal{B}(M,-):\mathcal{B}\to \mathcal{V}$ preserves $K$-indexed colimits, geometric realizations, and $\mathcal{V}$-tensoring. 
	Then $\Hom^{enh}_\mathcal{B}(M,-):\mathcal{B}\to \RMod_{\End_\mathcal{B}(M)}(\mathcal{V})$ is an equivalence in $\LMod_\mathcal{V}(\widehat{\cat}_\infty)$.  
\end{proposition}


\begin{proof*}
	Denote $F=\Hom^{enh}_\mathcal{B}(M,-):\mathcal{M}\to \RMod_{\End_\mathcal{B}(M)}(\mathcal{V})$.  It preserves $\mathcal{V}$-tensoring since $\Hom_\mathcal{B}(M,-)$ does, by the definition of the $\mathcal{V}$-tensoring on $\RMod_{\End_\mathcal{B}(M)}(\mathcal{V})$.  For $L,N\in \mathcal{B}$, the universal property of morphism objects induces $\mathcal{V}$-morphism 
	\begin{equation}
	\Hom_\mathcal{M}(L,N)\to \Hom_{\RMod_{\End_\mathcal{M}(M)}(\mathcal{V})}(F(L),F(N)).
	\end{equation}
We claim that this is an equivalence.  Suppose first that $L\simeq v\otimes M$ for some $v\in \mathcal{V}$.  Then 
	\begin{multline}
		\Hom_{\RMod_{\End_\mathcal{M}(M)}(\mathcal{V})}(F(v\otimes M),F(N))\simeq 
		\Hom_{\RMod_{\End_\mathcal{M}(M)}(\mathcal{V})}(v\otimes F(M),F(N))\\
\simeq \Hom_{\RMod_{\End_\mathcal{M}(M)}(\mathcal{V})}(v\otimes \End_\mathcal{M}(M),F(N))\simeq \Hom_\mathcal{V}(v,\Hom_\mathcal{M}(M,N))\\
		\simeq \Hom_\mathcal{M}(v\otimes M,N), 
	\end{multline}
	using $\mathcal{V}$-linearity, the forgetful-free module adjunction, and the definition of Hom objects.  We now pick arbitrary $L\in \mathcal{B}$.  Write $L\simeq \colim_{K}D$ for some $D:K\to \langle M\rangle \subset \RMod_{\End_\mathcal{B}(M)}(\mathcal{V})$.  
\begin{multline}
	\Hom_\mathcal{M}(L,N)\simeq \Hom_\mathcal{M}(\colim_KD ,N)\simeq \lim_{K^{op}}\Hom_\mathcal{M}(D,N)\\
	\simeq \lim_{K^{op}}\Hom_{\RMod_{\End_\mathcal{B}(M)}(\mathcal{V})}(F(D),F(N))\simeq 
	\Hom_{\RMod_{\End_\mathcal{B}(M)}(\mathcal{V})}(F(\colim_KD,F(N))\\
	\simeq \Hom_{\RMod_{\End_\mathcal{B}(M)}(\mathcal{V})}(F(L),F(N))
\end{multline}
Then $F$ is fully faithful as a $\mathcal{V}$-functor.  Finally, we must confirm that it is essentially surjective.  Suppose that $P\in \RMod_{\End_\mathcal{B}(M)}(\mathcal{V})$.  Since $\RMod_{\End_\mathcal{B}(M)}(\mathcal{V})$ is generated from the free modules under geometric realizations, we can write $N$ as a colimit of $Free\circ D$, where $D:\Delta^{op}\to \mathcal{V}$.  Then 
\begin{equation}
	P\simeq \colim_{\Delta^{op}}D\otimes \End_\mathcal{B}(M)\simeq \colim_{\Delta^{op}} F(D\otimes M)\simeq F(\colim_{\Delta^{op}}D\otimes M), 
\end{equation}
so $F$ is essentially surjective, and hence a $\mathcal{V}$-equivalence. 
\end{proof*}



\begin{corollary}\label{Decondensation}
	Suppose that $\mathcal{V}\in \Alg(\Pr)$, $\mathcal{C}\in \Alg(\mathcal{V})$, and $M\in \RMod_\mathcal{C}(\mathcal{V})\in \Pr^\mathcal{V}$ is $\mathcal{V}$-atomic.  Then $\mathcal{C}$ is Morita equivalent to $\End_{\RMod_\mathcal{C}(\mathcal{V})}(M)$.  
\end{corollary}
\begin{proof*}
	Both $\RMod_{\End_{\RMod_\mathcal{C}(\mathcal{V})}}(\mathcal{V})$ and $\RMod_\mathcal{C}(\mathcal{V})$ are generated from free modules under geometric realization.  Since $M\in \RMod_\mathcal{C}(\mathcal{V})$ is $\mathcal{V}$-atomic, it satisfies the conditions of proposition \ref{Homenhequiv}, so $\Hom^{enh}_{\RMod_\mathcal{C}(\mathcal{V})}(M,-):\RMod_{\mathcal{C}}(\mathcal{V})\to \RMod_{\End_{\RMod_\mathcal{C}(\mathcal{V})}(M)}(\mathcal{V})$ is an equivalence in $\LMod_\mathcal{V}(\widehat{\cat}_\infty)$, and moreover an equivalence in $\Pr^\mathcal{V}$ since it preserves all colimits.  Then we obtain the desired Morita equivalence.  
\end{proof*}

\begin{remark}
	One should notice that, if $\mathcal{V}$ is taken to be the category of fusion categories, the category $\RMod_{\End_{\RMod_\mathcal{C}(\mathcal{V})}(M)}(\mathcal{V})$ is exactly the (opposite of the) \underline{dual fusion category} $\mathcal{C}^*_M$ with respect to the module $M$ (see \cite{EGNO} definition 7.12.2).  Then corollary \ref{Decondensation} recovers \cite{EGNO} theorem 7.12.16 in the generality of enriched $\infty$-categories.  This also shares some formal similarities to \cite{DimofteNiu}, particularly the Yoneda functors of 3.4.3. 

\end{remark}
\begin{corollary}\label{decond}
	Suppose that $\mathcal{V}\in \Alg(\Pr^L)$, $\mathcal{C}\in \Alg(\mathcal{V})$, and $M\in \bSigma\mathcal{C}:=\RMod_\mathcal{C}(\mathcal{V})$ is a $\mathcal{V}$-atomic module category.  Then there exists $N\in \bSigma\Omega_{M}(\bSigma \mathcal{C})$ such that $\Omega_N(\bSigma \Omega_M(\bSigma\mathcal{C}))\simeq \mathcal{C}$. 
\end{corollary}

\begin{proof*}
By corollary \ref{Decondensation}, there is an equivalence $\bSigma\mathcal{C}\simeq \bSigma\Omega_M(\bSigma \mathcal{C}) $.  Let $N$ be the image of $\mathcal{C}\in \bSigma \mathcal{C}$ under this isomorphism.  Then $\mathcal{C}\simeq \Omega_\mathcal{C}(\bSigma\mathcal{C})\simeq \Omega_N(\bSigma \Omega_M(\bSigma \mathcal{C}))$.    
\end{proof*}


\begin{remark}
	Written in the dual tensor category notation, the above says there is a module $N\in \RMod_{\End_{\RMod_\mathcal{C}}(\mathcal{V})}(M)$ such that $(\mathcal{C}^*_M)_N^*\simeq \mathcal{C}$.  This is analogous to \cite{EGNO} theorem 7.12.11, and recovers the `dual symmetry' of \cite{BhardwajTachikawa2017}, and extends the equivariantization/deequivariantization correspondence to the higher non-invertible setting.  For this reason, we will call this construction \underline{decondensation} or \underline{degauging}. 
\end{remark}

\begin{corollary}
	Suppose that $\mathcal{V}\in \Alg(\Pr^L)$ and $\mathcal{C}\in \Alg(\mathcal{V})$.  Then the $E_1$-center $\FZ_{E_1}(\mathcal{C})$ (definition \cite{LurieHA} 5.3.1.12) is invariant under condensation by an atomic module category.  That is, if $\mathcal{M}\in \bSigma \mathcal{C}$ is $\mathcal{V}$-atomic, then $\FZ_{E_1}(\Omega_\mathcal{M}(\bSigma \mathcal{C}))\simeq \FZ_{E_1}(\mathcal{C})$. 
\end{corollary}
\begin{proof*}
	By \cite{LurieHA} theorem 4.4.1.28 and corollary \ref{Decondensation}, one gets a monoidal equivalence 
	\begin{equation}
		\Mod^{E_1}(\mathcal{C})\simeq {}_{\mathcal{C}}Bimod_\mathcal{C}(\mathcal{V})\simeq \Omega_{\BSigma \mathcal{C}} (\Pr^\mathcal{V})\simeq \Omega_{\BSigma \Omega_\mathcal{M}(\BSigma \mathcal{C})}(\Pr^\mathcal{V})\simeq \Mod^{E_1}(\Omega_\mathcal{M}(\bSigma\mathcal{C})). 
	\end{equation}
	By \cite{LurieHA} theorem 5.3.1.30 and the previous equation, we have 
	\begin{equation}
		\FZ_{E_1}(\mathcal{C})\simeq \End_{\Mod^{E_1}(\mathcal{C})}(\mathcal{C})\simeq \End_{\Mod^{E_1}_{\Omega_\mathcal{M}(\BSigma \mathcal{C})}}(\Omega_\mathcal{M}(\bSigma \mathcal{C}))\simeq \FZ_{E_1}(\Omega_\mathcal{M}(\bSigma \mathcal{C})). 
	\end{equation}
\end{proof*}


\begin{remark}
	In the following, we make use of the fact that the retract of a $\mathcal{V}$-atomic object is $\mathcal{V}$-atomic.  While this is expected to be true, it has not been justified in the preceeding work. 
\end{remark}

\begin{example}
 We sketch an application to possibly infinite monoids, and so beyond the reach of fusion categories. Let $G\in \Alg_{E_\infty}(\Set)$ be a (discrete) commutative monoid.  There is lax symmetric monoidal forgetful functor $\Vect_G\to \Vect$ from the category of $G$-graded vector spaces (not necessarily of finite dimension) to the category of vector spaces.  We can consider $\Vect$ as a module category $For^*\Vect\in \bSigma \Vect_G$ along this functor.  We have retract $For:\Vect_G \leftrightharpoons For^*\Vect:\iota$ in $\bSigma \Vect_G$, where $\iota$ is given by the inclusion of $\Vect$ into the component graded by the identity in $G$ and so $For^*\Vect$ is $\cat$-atomic.  

	As in \cite{EGNO} example 7.12.19, we identify $\Omega_{For^*\Vect}(\bSigma \Vect_G)\simeq \Rep (G)$.  It follows from corollary \ref{Decondensation} and \ref{decond} that $\Vect_{G}$ is Morita equivalent to $\Rep(G)$, and there exists $M\in \Rep(G)$ whose automorphisms are equivalent to $\Vect_{G}$.  
\end{example}
\begin{remark}
	We expect an argument similar to the one above to apply far more generally, and so also to continuous monoids, which we sketch here.  Suppose that $\mathcal{V}\in \Alg_{E_2}(\Pr^L)$, $\mathcal{B}\in \Alg(\Pr^\mathcal{V})$, and $A\in \Alg(\cat^\mathcal{V})$.  We can identify $\underline{\Fun}_\mathcal{V}(A,\mathcal{B})^\otimes$ in the Day convolution monoidal structure with the category of \underline{$A$-graded objects in $\mathcal{B}$} (see \cite{SoergelBimodule} 4.3).  Build a lax monoidal `forgetful' functor $\underline{\Fun}_\mathcal{V}(A,\mathcal{B})^\otimes\to \mathcal{B}$ using the evaluation maps.  This induces a retract $For:\underline{\Fun}_\mathcal{V}(A,\mathcal{B})\leftrightharpoons For^*\mathcal{B}:\iota$ in $\bSigma \underline{\Fun}_\mathcal{V}(A,\mathcal{B})^\otimes$, and so $For^*\mathcal{B}\in \bSigma \underline{\Fun}_\mathcal{V}(A,\mathcal{B})^\otimes$ is atomic, and one gets Morita equivalence between $\underline{\Fun}_\mathcal{V}(A,\mathcal{B})^\otimes$  and $\Omega_{For^*\mathcal{B}}\bSigma \underline{\Fun}_\mathcal{V}(A,\mathcal{B})^\otimes$.  One would then like to identify $\Omega_{For^*\mathcal{B}}\bSigma\underline{\Fun}_\mathcal{V}(A,\mathcal{B})^\otimes$ with `$A$-representations'.  We will treat this with more care in future work. 
\end{remark}









