\section{Appendix}
This appendix provides additional formulas for the calculation of the expected cost functions of the spoofer given by Equations \eqref{eq:cost_bid_spoofer} and \eqref{eq:cost_ask_spoofer}.

\paragraph{Gaussian:} If $\Delta p\sim\mathcal{N}(\mu, \sigma^2)$, then

\begin{equation}
    \mathbb{P}(\Delta p \leq x)=\Phi\left(\frac{x-\mu}{\sigma}\right),
\end{equation}

\begin{equation}
    \mathbb{E}(\Delta p | \Delta p \leq x)=\mu-\sigma\frac{\phi\left(\frac{x-\mu}{\sigma}\right)}{\Phi\left(\frac{x-\mu}{\sigma}\right)},
\end{equation}

\begin{equation}
    \mathbb{E}(\Delta p | \Delta p > x)=\mu+\sigma\frac{\phi\left(\frac{x-\mu}{\sigma}\right)}{1-\Phi\left(\frac{x-\mu}{\sigma}\right)},
\end{equation}

