\\&+T\|C_{w,\mu}^{-1}C_{m,\mu}
\|^2_{C_{w,\mu}}/2)\left(1+\|C_{w,\mu}^{-1/2}\sqrt{T}^{-1}\gamma\|^{\kappa}+\|C_{w,\mu}^{-1}C_{m,\mu}\|^{\kappa}\right)]\IF(\gamma \in B_{\gamma} ) N_T(\mu)d\mu\\
