\subsection{Proof of Lemma \ref{coverageprt}.}\label{Proof: lemma1}
\begin{proof}
We aim to establish that
\begin{align}
\int_\mu \mathbb{P}_{\mu}\left(\theta(\mu) \in PR_T \right) \pi(\mu) d\mu = 1 - \alpha +o_p(1). \label{eq:lemma1-1}
\end{align}

We begin by considering the case under the conditions of Theorem \ref{Theorem:1}, as the argument for Theorem \ref{Theorem:2} proceeds analogously.

We know from Theorem \ref{Theorem:1} that $PR_T(\alpha)=\left\{\theta: T(\widehat{m}(\theta))^\top  A_{\theta_0} (\widehat{m}(\theta)) \leq {Z_{\alpha}}\right\}$ such that $Z_\alpha$ satisfies the following condition 
\begin{align*}
\P_{T,\theta}\left(T(\widehat{m}(\theta)^\top  A_{\theta_0} \widehat{m}(\theta)) \leq {Z_{\alpha}}\right)  =1-\alpha,
\end{align*}
where $\mathbb{P}_{T,\theta}$ denotes the probability measure of $\widehat{m}(\theta)-\mu+ \mu$ corresponding to the marginal posterior $p_T(\theta)$, which in this case is Gaussian with mean $0$ and covariance matrix $A_{\theta_0}^{-1}$. Therefore, $Z_\alpha$ is the $(1 - \alpha)$ quantile of a chi-squared distribution with $q$ degrees of freedom. To verify equation~\eqref{eq:lemma1-1}, it suffices to show that
\begin{align}
\label{eq:lemma 1 linear}
\int \mathbb{P}_{\mu}\left(T(\widehat{m}({\theta}(\mu))-\mu+ \mu)^\top  A_{\theta_0}(\widehat{m}(\theta(\mu))-\mu+\mu)) \leq {Z_{\alpha}}\right)f_{\mu}(\mu)d\mu =1-\alpha + o_p(1),
\end{align}
where $A_{\theta_0} = \Lambda^{-1} - \Lambda^{-1} \left( \Omega(\theta_0)^{-1} + \Lambda^{-1} \right)^{-1} \Lambda^{-1}$, so that $A_{\theta_0}^{-1} = \Omega(\theta_0) + \Lambda$ by the Woodbury matrix identity.

{Note that under $\mathbb{P}$, $m(\theta(\mu)) =\mu$ following the distribution specified by $f_\mu(\cdot)$ corresponding to the local Gaussian prior, while for a given $\mu$, under $\mathbb{P}_\mu$, $\widehat{m}(\theta(\mu))-\mu$ is asymptotically Gaussian with mean zero and variance $T^{-1}\Omega(\theta_0)$. Consequently, the sum of $\widehat{m}(\theta(\mu))-\mu$ and $\mu $ is Gaussian with mean zero and variance $A_{\theta_0}^{-1}$ under $\mathbb{P}$.
Thus by the definition of the quantile $Z_{\alpha}$, the following is true:
\begin{align*}
\int \mathbb{P}_{\mu}\left(T(\widehat{m}(\theta(\mu))- \mu+\mu))^\top A_{\theta_0} (\widehat{m}(\theta(\mu))- \mu+\mu) \leq Z_\alpha   \right)f_{\mu}(\mu)d\mu =1-\alpha,
\end{align*}
which then implies equation (\ref{eq:lemma 1 linear}) upon noting that $\|\mu - \mu_0 \|=O_p(\frac{\sqrt{q}}{\sqrt{T}})$ in this local misspecficiation case.  }


We now generalize the preceding argument to the nonlocal case under the conditions of Theorem~\ref{Theorem:2}. Here, we have that by definition $PR_T(\alpha)=\left\{\theta:  \int_{\mu}p_T(\theta,\mu)d\mu \geq {Z_{\alpha}} \right\}=\left\{\theta:  p_T(\theta) \geq {Z_{\alpha}} \right\}$ where $Z_\alpha$ is chosen to satisfy
\begin{align*}
\P_{T,\theta}\left( p_T(\theta) \geq {Z_{\alpha}}\right)  =1-\alpha,
\end{align*}
and $\mathbb{P}_{T, \theta}$ corresponds to the marginal posterior $p_T(\theta)$. With a slight abuse of notation, we treat $p_T(\theta)$ as a function of the sample moments $\widehat{m}(\theta)$, rather than of $\theta$ directly. Define this function as $\tilde{p}_T(\widehat{m}(\theta)) := p_T(\theta)$. Then the above condition can be rewritten as
\begin{align}
\label{eq:lemma 1 --40}
\P_{T,\theta}\left( \tilde{p}_T(\widehat{m}(\theta)) \geq {Z_{\alpha}}\right)  =1-\alpha. 
\end{align} 

To verify equation~\eqref{eq:lemma1-1}, it suffices to show that
\begin{align}
\label{eq:lemma 1 --41}
\int \mathbb{P}_{\mu} \left( \tilde{p}_T(\widehat{m}(\theta(\mu))) \geq Z_{\alpha} \right) f_\mu(\mu) d\mu = 1 - \alpha + o_p(1).
\end{align}
Similar to the above local case, for a given $\mu$, under the posterior the distribution of $\widehat{m}(\theta) -\mu +\mu$ coincides with the asymptotic distribution of $\widehat{m}(\theta(\mu)) - \mu +\mu$ under $\mathbb{P}_\mu$, and thus Equation (\ref{eq:lemma 1 --41}) is implied by (\ref{eq:lemma 1 --40}).  







\end{proof}

\subsubsection{Step of Gaussian Integral}
In this section, we derive a lemma regarding the Gaussian integral and the tail probability involved in the above main theorem.
\begin{lemma}\label{gai}
Under Assumptions \ref{assummu1}-\ref{rT}, $0\leq \kappa<\infty$,  we have, for any fixed $\mu \in \Gamma$, $\varepsilon\asymp \sqrt{k}\log T$, 
$$ \int_{B_{\varepsilon}}N_{T}(\theta|\mu)\left|\left(1+\|\theta-\theta(\mu)\|^{\kappa}\right)\right|\mathrm{d}
\theta N_T(\mu)d\mu\lesssim_p {k}^{\kappa/2},$$
and
$$ \sup_{\mu \in \Gamma}\mathbb{P}_{\gamma}(\|C_{w,\mu}^{-1/2}(\sqrt{T}^{-1}\gamma-C_{w,\mu}^{-1/2}C_{m,\mu})\|^{\kappa}>\frac{\varepsilon}{\sqrt{T}}|\mu)\lesssim_p \sqrt{k}^{\kappa} \exp(-\varepsilon).$$
\end{lemma}

\begin{proof} It suffices to just show it for $\kappa>0$. It is well known that for a positive continuous random variable $X$, $\E(X)=\int_{0}^{\infty}\mathbb{P}(X>x)dx$.
Recall that $\Gamma_\epsilon$ is the set of $\mu$ corresponds $B_{\varepsilon}$, where
$\varepsilon$ is set to be  $\varepsilon \asymp \sqrt{k}\log T$. We also have the fact that 
$\int_{B_{\varepsilon} }d\theta d\mu\leq\int_{\Gamma}\int_{B_{\varepsilon, \theta|\mu}}d\theta d\mu,$ with $B_{\varepsilon, \theta|\mu}\defeq \{\theta:\sqrt{T}\|G(\theta(\nu(\mu)))(\theta-\theta(\nu(\mu)))\|\leq \varepsilon\}$ for a point $\mu \in \Gamma_\epsilon$, therefore, we may start by looking at
$
\int_{B_{\varepsilon,\theta|\mu}}N_{T}(\theta|\mu)\left|\left(1+\|\theta-\theta(\nu(\mu))\|^{\kappa}\right)\right|\mathrm{d}\theta.$ Since for $x\geq 0$,
$x=\int_{z\geq 0}\text{}\IF(z\leq x)dz$, 
\begin{align*}
&\int_{B_{\varepsilon, \theta|\mu}} N_{T}(\theta|\mu)(1+\|\theta-\theta(\nu(\mu))\|^{\kappa})\IF(\theta\in B_{\varepsilon,\theta})d\theta\\
=&\int_{B_{\varepsilon, \theta|\mu}}\int_{0}^\infty\IF( x \leq 1+\|\theta-\theta(\nu(\mu))\|^{\kappa})\IF(\theta\in B_{\varepsilon,\theta})dxN_{T}(\theta|\mu)d\theta\\
=&\int_{0}^\infty\int_{B_{\varepsilon, \theta|\mu}}\IF(1+\|\theta-\theta(\nu(\mu))\|^{\kappa}\geq x)\IF(\theta\in B_{\varepsilon,\theta})N_{T}(\theta|\mu)d\theta dx.
\end{align*}

As in the proof of Theorem \ref{Theorem:2},  $\mathbb{P}_{N_T(\theta|\mu)}(.)$ is the probability measure conditioning on $\mu$ corresponding to the density $N_T(\theta|\mu)$, and $\gamma$ is a standard $k$-dimensional multivariate Gaussian random variable with the associated probability measure $\mathbb{P}_{\gamma}$ and density $f(\lambda)$ with respect to the Lebesgue measure. Let us look for a fixed $\mu$, then we can proceed from the above as follows,
\begin{align*}
&\int_{0}^{\infty}
\mathbb{P}_{N_T(\theta|\mu)}(\|\theta-\theta(\nu(\mu))\|^{\kappa} >x-1 ,\|\sqrt{T}G(\theta(\nu(\mu)))(\theta-\theta(\nu(\mu)))\|^{2}\leq \varepsilon^{2}|\mu)dx\\=&\int_{0}^{\infty}\mathbb{P}_{\gamma}(\|\sqrt{T}^{-1}C_{w,\mu}^{-1/2}(\gamma -C_{w,\mu}^{-1/2}C_{m,\mu})\|>{((x-1) \vee 0)}^{1/{\kappa}},
\\&\|\sqrt{T}^{-1}G(\theta(\nu(\mu)))(C_{w,\mu}^{-1/2}(\gamma-C_{w,\mu}^{-1/2}C_{m,\mu}))\|^{2}\leq  \varepsilon^{2}/T|\mu)dx
\\ 
\le & \int_{0}^{\infty}\mathbb{P}_{\gamma}(\|\sqrt{T}^{-1}C_{w,\mu}^{-1/2}\gamma\|>((x-1) \vee 0)^{1/{\kappa}}-\|C_{w,\mu}^{-1}C_{m,\mu}\||\mu)dx.
\end{align*} 

Let $\lambda=\left(\sqrt{T}^{-1}\lambda_{\max}\left(C_{w,\mu}^{-1/2}\right)\right)^2$, and
by Assumption \ref{assum33}, $\lambda {\lesssim _{p}}{T}^{-1},$  
$\|C_{w,\mu}^{-1}C_{m,\mu}\|\lesssim_{p}\frac{\sqrt{k}}{\sqrt{T}}$.   Note that,
\begin{align*}
&\int_{0}^{\infty}\mathbb{P}_{\gamma}(\|\sqrt{T}^{-1}C_{w,\mu}^{-1/2}\gamma\|>((x-1) \vee 0)^{1/\kappa}-\|C_{w,\mu}^{-1/2}C_{m,\mu}\||\mu)dx\\
=&\int_{0}^{1+ (\sqrt{k}  +\sqrt{T}\|C_{w,\mu}^{-1}C_{m,\mu}\|)^{\kappa} } \mathbb{P}_{\gamma}(\|\sqrt{T}^{-1}C_{w,\mu}^{-1/2}\gamma\|>((x-1) \vee 0)^{1/\kappa}-\|C_{w,\mu}^{-1}C_{m,\mu}\||\mu) dx \\
& + \int_{1+ (\sqrt{k}+\sqrt{T} \|C_{w,\mu}^{-1}C_{m,\mu}\|)^{\kappa}}^{\infty}\mathbb{P}_{\gamma}(\|\sqrt{T}^{-1}C_{w,\mu}^{-1/2}\gamma\|>(x-1)^{1/{\kappa}}-\|C_{w,\mu}^{-1}C_{m,\mu}\||\mu)dx,
\end{align*}
where the first term can be bounded by $\int_{0}^{1+ (\sqrt{k}+\sqrt{T}\|C_{w,\mu}^{-1}C_{m,\mu}\|)^{\kappa} }1dx\lesssim k^{\frac{\kappa}{2}},$ and the second term, via the inequality as in Lemma \ref{tail}. For a positive constant $c>0$, it can be bounded by\\$\int_{c(\sqrt{k})^{\kappa}}^\infty\exp(-z^{2/\kappa}/2)dz\lesssim_p  k^{\frac{\kappa}{2}}$.The second statement in Lemma \ref{gai} is a direct result of Lemma \ref{tail}.
\end{proof}

