\end{align*}





We see that $\|(\widehat{m}(\theta)-\mu)\|\lesssim \|r_T(\theta, \mu)\|+\|\widehat{m}(\theta(\mu))-\mu\| + \|h(\theta, \mu)\|\lesssim_p \left( \frac{\sqrt{q}}{\sqrt{T}} \vee \frac{{\sqrt{k}\log T}\log T}{\sqrt{T}}\right).$ 
Thus, we have $\sup_{(\theta, \mu) \in B_{\varepsilon}}T\left(\widehat{m}(\theta)-\mu\right)^{\top}(W(\theta(\mu))-\widehat{W}_T(\theta))\left(\widehat{m}(\theta)-\mu\right)  \lesssim_p\left( \frac{{q} }{\sqrt{kT}}\vee \frac{(\log(T))^2 \sqrt{k} }{\sqrt{T}} \right) \sup_{(\theta, \mu) \in B_{\varepsilon}}(\sqrt{k}+\sqrt{T}\|h(\theta,\mu)\|).$

By Assumption \ref{2}, we have that $W(\theta(\mu))$ has a bounded maximum eigenvalue,  
and from Lemma \ref{lemmart} 
$\sup_{(\theta, \mu) \in B_{\varepsilon}}r_T(\theta,\mu)\lesssim_p \sup_{(\theta, \mu) \in B_{\varepsilon}} \frac{\sqrt{k}\left(\sqrt{k}+\sqrt{T}\|h(\theta,\mu)\|\right)}{T},$ therefore, implied by Lemma \ref{lemmart} we have the following on $B_{\varepsilon}$, 
\begin{align*}
&\sup_{(\theta,\mu) \in B_{\varepsilon}} T R_{T}(\theta,\mu)\\\lesssim_p & \sup_{(\theta,\mu) \in B_{\varepsilon}} \lambda_{\max}(W(\theta(\mu)))T[\|r_{T}(\theta,\mu)\|^2\vee (\|r_{T}(\theta,\mu)\|\|h(\theta,\mu)\|)]
\\&+ \sup_{(\theta, \mu) \in B_{\varepsilon}}\lambda_{\max}(W(\theta(\mu)))T[\|r_{T}(\theta,\mu)\|\|\widehat{m}(\theta(\nu(\mu)))-\mu)\|
\\&+\sup_{(\theta, \mu) \in B_{\varepsilon}}T\left(\widehat{m}(\theta)-\mu\right)^{\top}\left(W(\theta(\mu))-\widehat{W}_T^{-1}(\theta)\right)\left(\widehat{m}(\theta)-\mu\right)
\\
\lesssim_p & \sup_{(\theta,\mu) \in B_{\varepsilon}} T({{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|)^2 \left(\frac{\sqrt{k}}{T}\right)^2 \vee \sup_{(\theta,\mu) \in B_{\varepsilon}}\left({{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|\right)\frac{\sqrt{k}\varepsilon}{\sqrt{T}} \\
&+\sup_{(\theta,\mu) \in B_{\varepsilon}} \frac{T\sqrt{k}(\sqrt{k}\log T+\sqrt{T}\|h(\theta,\mu)\|)}{T} \left(   \frac{\sqrt{q}}{\sqrt{T}} \vee \frac{\sqrt{k}\log T}{\sqrt{T}} \right)
\\&+ \frac{ T(\log T)^2 \sqrt{k}}{\sqrt{T} }\left( \frac{\sqrt{q}}{\sqrt{T}} \vee \frac{\sqrt{k}\log T}{\sqrt{T}} \right)^2.
\end{align*}



Thus, $$\sup_{\theta, \mu \in  B_{\varepsilon}} \frac{\left|TR_{T}(\theta,\mu)\right|}{k(\log T)^2+\|\sqrt{T}h(\theta,\mu)\|^2}
\lesssim_p\frac{{(\log T)}^2\sqrt{k}}{\sqrt{T}}. $$ 
Additionally, on $B_{\varepsilon}$ for sufficiently large $T$, we have that $$\sup_{(\theta,\mu) \in B_{\varepsilon}} |\exp(R_{T}(\theta,\mu))-1|\leq \sup_{(\theta,\mu) \in B_{\varepsilon}} \left(|R_{T}(\theta,\mu)|+|R_{T}(\theta,\mu)|^2\right),$$
which is due to fact that $|e^{x}-1-x-\frac{1}{2}x^2| = o(|x|^2)$ for sufficiently small $|x|$. 

\end{proof}

\subsubsection{Proof of \texorpdfstring{$r_T(\theta,\mu)$}{TEXT}.} \label{smallrT}
This section provides the intermediate results used in the proof of Lemma \ref{RT} 


\begin{lemma}\label{lemmart}
Under Assumptions \ref{1} to\ref{2},
\[
\sup_{\theta,\mu\in B_{\varepsilon}}\frac{\|{r}_{T}(\theta,\mu)\|}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|} \lesssim_{p} \frac{\sqrt{k}}{ {T}},
\]

\end{lemma}
\begin{proof} 
Let $\mathcal{M}_{m,T}(\theta,\mu)=\frac{M_{m,T}(\theta,\mu)}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|},$
which is a centered object by definition and satisfies the following,
$\E\left(\mathcal{M}_{m,T}(\theta,\mu)\right)=0$. We focus on its behaviors on $B_{\varepsilon}$.  
Assumption \ref{2} imposes differentiability conditions on $\E(\widehat{m}(\theta)) - \E(\widehat{m}(\theta(\nu(\mu)))$ concerning $\theta$, and thus, the residual terms $\mathcal{M}_{m,T}(\theta, \mu)$ shrinks to $0$ within $B_{\varepsilon}$ because, on $B_{\varepsilon}$, the higher-order terms related to $\|G(\theta(\nu(\mu)))(\theta - \theta(\nu(\mu)))\|$ also diminishes to $0$ following Assumption \ref{2}. We use $\mathcal{M}_{m,T}(\theta,\mu)$ to analyze $r_T(\theta,\mu)$.


By construction, we have that $\frac{r_{T}(\theta,\mu)}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|}- \mathcal{M}_{m,T}(\theta,\mu) =\frac{-h(\theta,\mu)+ \E(\widehat{m}(\theta))-\E(\widehat{m}(\theta(\nu(\mu))))}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|}.$  According to Assumption \ref{2}, on $B_{\varepsilon}$, $\|\frac{r_{T}(\theta,\mu)}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|}- \mathcal{M}_{m,T}(\theta,\mu)\|$ is bounded by 
\begin{align*}
\frac{\|-h(\theta,\mu) +(\sup_{\theta,\mu\in B_{\varepsilon}}\lambda_{\max}(\partial^2 \E(g(Z_t,\theta))/\partial \theta\partial \theta^{\top})) \|\theta-\theta(\nu(\mu))\|^2\|}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|} \lesssim \frac{ \sqrt{k}[\sqrt{k}\log(T)]^2}{T}.
\end{align*}
Assumption \ref{2} implies that $\frac{k\log(T)}{\sqrt{T}}\to 0$, and thus $\sup_{\theta,\mu\in B_{\varepsilon}}\|\frac{r_{T}(\theta,\mu)}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|}- \mathcal{M}_{m,T}(\theta,\mu)\| \ll  \frac{\sqrt{k}(\log T)}{\sqrt{T}}$ on $B_{\varepsilon}$. Then it suffices to examine $\mathcal{M}_{m,T}(\theta,\mu)$ for the rate of $\frac{r_{T}(\theta,\mu)}{{{\sqrt{k}\log T}}+\sqrt{T}\|h(\theta,\mu)\|}$. We then use Lemma \ref{bound} to analyze the term ${M}_{m,T}(\theta,\mu)$, where the variable $\mu$ in Theorem B.15 corresponds to $(\theta - \theta(\nu(\mu))) \in \mathbb{R}^{k}$ in our context. As a result, $\Upsilon_{\circ}(r)$ should represent a ball containing $B_{\varepsilon}$. 



We next analyze the terms, i.e., $A$ and $v_{0}r\mathfrak{z}_{\mathbb{H}}(\mathrm{x})$ in Theorem B.15 in \cite{spokoiny2017penalized}, where $v_{0}$ refers to variance, $r$ refers to radius and $\mathfrak{z}_{\mathbb{H}}(\mathrm{x})$ refers to entropy of $\Upsilon_{\circ}(r)$. By Assumption \ref{2}, we have ${r}\approx \frac{\sqrt{k}\log T}{\sqrt{T}}$. The $A$ therein is identity $I_{q}$, and $\mathfrak{z}_{\mathbb{H}}(\mathrm{x})\approx \sqrt{k}$, and due to the second differentiability assumption in Assumption \ref{1}, $v_{0} \lesssim 1/\sqrt{T}$.  

Then, we have $\sup_{\theta,\mu\in B_{\varepsilon}}M_{m,T}(\theta,\mu)\lesssim_p \frac{{k} \log T}{T}$ and $\sup_{\theta,\mu\in B_{\varepsilon}}\mathcal{M}_{m,T}(\theta,\mu)\lesssim_p \frac{\sqrt{k}}{T}$. 
\end{proof}


\subsubsection{Useful Lemmas}
Here, we list a few useful lemmas from \cite{spokoiny2017penalized} and \cite{spokoiny2019accuracy}.  
\begin{lemma}(Corollary A.3. from \cite{spokoiny2019accuracy}) Let $\gamma$ be a standard normal random vector in $\mathbb{R}^{k}$.
Then for any $\mathrm{x}>0$
\[
\begin{aligned}\mathbb{P}\left(\|\gamma\|^{2}\geq k+2\sqrt{k\mathrm{x}}+2\mathrm{x}\right) & \leq\mathrm{e}^{-\mathrm{x}},\\
\mathbb{P}(\|\gamma\|\geq\sqrt{k}+\sqrt{2\mathrm{x}}) & \leq\mathrm{e}^{-\mathrm{x}},\\
\mathbb{P}\left(\|\gamma\|^{2}\leq k-2\sqrt{k\mathrm{x}}\right) & \leq\mathrm{e}^{-\mathrm{x}}.
\end{aligned}
\]
\end{lemma}

\begin{lemma}(Theorem A.2. from \cite{spokoiny2019accuracy}) \label{tail}
Let $H$ be a positive definite matrix. Let $\boldsymbol{\xi}\sim {N}\left(0,H^{2}\right)$
be a mean-zero normal random vector in $\mathbb{R}^{k}$ and $B$ be a symmetric non-negative definite matrix
such that $A=H^{-1}BH$ is a {trace operator} in $\mathbb{R}^{k}$.
Then with $k=\operatorname{tr}(A)$, $\mathrm{v}^{2}=\operatorname{tr}\left(A^{2}\right)$,
and $\lambda=\|A\|$, it holds for each $\mathrm{x}\geq0,$
\[
\begin{aligned} & \mathbb{P}\left({\boldsymbol{\xi}}^{\top}B\boldsymbol{\xi}\geq z^{2}(A,\mathrm{x})\right)\leq\mathrm{e}^{-\mathrm{x}},\\
&\mbox{with} \quad z(A,\mathrm{x})\stackrel{\text{ def }}{=}\sqrt{\mathrm{k}+2\mathrm{vx}^{1/2}+2\lambda\mathrm{x}}.
\end{aligned}
\]
It also implies
\[
\mathbb{P}\left(\left\Vert B^{1/2}\boldsymbol{\xi}\right\Vert >\mathrm{k}^{1/2}+(2\lambda\mathrm{x})^{1/2}\right)\leq\mathrm{e}^{-\mathrm{x}}.
\]
If $B$ is symmetric but not necessarily positive, then
\[
\mathbb{P}\left(|\boldsymbol{\xi}^{\top}B\boldsymbol{\xi}-\mathrm{k}|>2\mathrm{v}\mathrm{x}^{1/2}+2\lambda\mathrm{x}\right)\leq2\mathrm{e}^{-\mathrm{x}}.
\]
\end{lemma}



\begin{lemma}(Theorem B.15. from \cite{spokoiny2017penalized})\label{bound}
Let $\mathcal{Y}(\boldsymbol{v})$ with $\boldsymbol{v}\in \Upsilon_0(r)=\{\boldsymbol{v}\in \Upsilon:  \| \boldsymbol{v}-\boldsymbol{v}^* \| \leq r\}$ and  $\Upsilon\subseteq\mathbb{R}^{k}$, be a
smooth centered random vector process with values in $\mathbb{R}^{q}$. Let also $\E[\mathcal{Y}(\boldsymbol{v}^{*})]=0$
for the center $\boldsymbol{v}^{*}\in \Upsilon_0(r)$. Without loss of generality, assume
$\boldsymbol{v}^{*}=0$. We aim to bound $\|\mathcal{Y}(\boldsymbol{v})\|$ uniformly over $\boldsymbol{v}$
over a vicinity  $\Upsilon_0(r)$ of $\boldsymbol{v}^{*}$. By $\nabla\mathcal{Y}(\boldsymbol{v})$
we denote the $k\times q$ matrix with entries $\nabla_{\boldsymbol{v}_{i}}\mathcal{Y}(\boldsymbol{v}),i\leq k,j\leq q$.
Suppose that $\mathcal{Y}(\boldsymbol{v})$ satisfies for each $\boldsymbol{\gamma}_{1}\in\mathbb{R}^{k}$
and $\boldsymbol{\gamma}_{2}\in\mathbb{R}^{q}$ with $\left\Vert \boldsymbol{\gamma}_{1}\right\Vert =\left\Vert \boldsymbol{\gamma}_{2}\right\Vert =1$, and there exists a positive constant $v_0$, 
\[
\sup_{\boldsymbol{v}\in\Upsilon} \log \E \exp\left\{ \lambda\boldsymbol{\gamma}_{1}^{\top}\nabla\mathcal{Y}(\boldsymbol{v})\boldsymbol{\gamma}_{2}\right\} \leq\frac{v_{0}^{2}\lambda^{2}}{2},\quad|\lambda|\leq g.
\] 
Let $A$ be a matrix fulfilling $1 / 2 \leq\left\|A A^{\top}\right\|\leq 1$. Then for each $r$, it holds
$$
\mathbb{P}\left\{\sup _{\boldsymbol{v} \in \Upsilon_0(r)}\|A \nabla\mathcal{Y}(\boldsymbol{v})\|>\sqrt{8} v_0 r \mathfrak{z}_{\mathbb{H}}(\mathrm{x})\right\} \leq \mathrm{e}^{-\mathrm{x}},
$$
where $\mathfrak{z}_{\mathbb{H}}(\mathrm{x})$ is given by the following  with $\mathbb{Q}_2={p}_A+\mathbb{Q}_2\left(\Upsilon_{\circ}(r)\right)$.
$$
\begin{aligned}
& \mathfrak{z}_{\mathbb{H}}(\mathrm{x})= \begin{cases}2 \sqrt{\mathbb{Q}_2+2 \mathrm{x}}, & \text { if } \mathbb{Q}_2+2 \mathrm{x} \leq \mathrm{g}^2, \\
2 \mathrm{~g}^{-1} \mathrm{x}+\mathrm{g}^{-1} \mathbb{Q}_2+\mathrm{g}, & \text { if } \mathbb{Q}_2+2 \mathrm{x}>\mathrm{g}^2.\end{cases}
\end{aligned}
$$
In the above,  $\mathbb{Q}_2$ relates to the entropy of the set $ \Upsilon_0(r)$, $p_A$ denotes a trace norm of a trace operator $A^{-2}$, and both can be calculated according to section B.4 in \cite{spokoiny2017penalized} as outlined below.

For each $k\leq 1$, by $\mathcal{M}_k$ we denote a $r_k$-net in $\Upsilon^{\circ}(r_0)$ with $r_k=r_02^{-k}$, so that $\Upsilon^{\circ}(r_0) \subseteq \bigcup_{\boldsymbol{v} \in \mathcal{M}_k}  \{\boldsymbol{v}'\in \Upsilon:  \| \boldsymbol{v}'-\boldsymbol{v} \| \leq r_k \} $, then $\mathbb{Q}_2\left(\Upsilon^{\circ}\right) \stackrel{\text { def }}{=} \sum_{k=1}^{\infty} 2^{-k+1} \log \left(2 \mathbb{N}_k\right)$ with $\mathbb{N}_k \stackrel{\text { def }}{=}\left|\mathcal{M}_k\right|$ being the cardinality of $\mathcal{M}_k$. For a positive self-adjoint operator in $\mathbb{R}^{\infty}$, denoted by $\mathbb{H}$, such that $\lambda_{\min}(\mathbb{H})=1$ and $\mathbb{H}^{-2}$ is a trace operator, then $\mathrm{p}_\mathbb{H} \stackrel{\text { def }}{=} \operatorname{tr}\left(\mathbb{H}^{-2}\right)=\sum_{j=1}^{\infty} h_j^{-2}<\infty,$
where $1=h_1 \leq h_2 \leq \cdots$ are the ordered eigenvalues of $H$.

\end{lemma}


\begin{lemma}(Theorem B.8. in \cite{spokoiny2017penalized})\label{covering}
Suppose that for some $\alpha>1$,
$
\mathrm{p}_{\mathbb{H}}(\alpha) \stackrel{\text { def }}{=} \sum_{j=1}^{\infty} h_j^{-2} \log ^\alpha\left(h_j^2\right)<\infty,
$
then
$
\mathbb{Q}_2(\Upsilon^{\circ}_{\mathbb{H}} (r)) \leq \mathrm{C} \sum_{j=1}^{\infty} h_j^{-1},
$ with $\Upsilon^{\circ}_{\mathbb{H}} (r) = \{\boldsymbol{v}'\in \Upsilon:  \| \mathbb{H}(\boldsymbol{v}'-\boldsymbol{v} )\| \leq r\} ,$ for a fixed center $\boldsymbol{v}$.
\end{lemma}
\begin{lemma} (Lemma A.17 from \cite{spokoiny2019accuracy})\label{Gaussintegral}
Let $\mathcal{T}$ be a linear operator in $\mathbb{R}^k$ with $\|\mathcal{T}\|_{\text {op }} \leq 1$. Let $\boldsymbol{z} \in \mathbb{R}^{k}$ be a unit norm vector: $\|\boldsymbol{z}\|=1$. Define $k=\operatorname{tr}\left(\mathcal{T}^{\top} \mathcal{T}\right)$. For any positive $\mathrm{C}_0, \mathrm{r}_0$ with $1 / 2<\mathrm{C}_0 \leq 1$ and $\mathrm{C}_0 \mathrm{r}_0>2 \sqrt{k+1}+\sqrt{\mathrm{x}}$,
$$
\begin{aligned}
& \mathbb{E}\left\{{|\langle \boldsymbol{z}, \gamma\rangle|^2 } \exp \left(-\mathrm{C}_0 \mathrm{r}_0\|\mathcal{T} \gamma\|+\frac{\mathrm{C}_0 \mathrm{r}_0^2}{2}+\frac{1}{2}\|\mathcal{T} \gamma\|^2\right) \mathbb{I}\left(\|\mathcal{T} \gamma\|>\mathrm{r}_0\right)\right\}  \leq \mathrm{Ce}^{-\left(k+\mathrm{x}\right) / 2}.
\end{aligned}
$$
\end{lemma}


