\section{Verification of Assumption \ref{Gaussian}.} 

We impose a high-level expansion assumption in Assumption \ref{Gaussian}. 
We extend the method of obtaining an expansion of a CUE estimator from \cite{newey2004higher} to our high-dimensional misspecified moment settings to verify that assumption. Corollary \ref{coro:Gaussian} delivers this expansion. 
\begin{corollary}\label{coro:Gaussian} 
Suppose that the following assumptions hold with $\xi>2$:
\begin{enumerate} 
\item Assumption \ref{a1}; 
\item  Assumption \ref{assum33};
\item $g(Z_t,\theta)$ is continuous in $\theta \in \Theta$ with probability one;
\item    for a given $\mu \in \mathcal{M}$, 
$\sup_{1\leq u \leq q, \theta\in\Theta}\mathbb{E}( \|e_u^\top (g(Z_t, \theta) -\mu)\|^{\xi}) <C $,  $\sup_{\theta\in\Theta}\mathbb{E}( \|(g(Z_t, \theta) -\mu)(g(Z_t, \theta) -\mu)^\top \|^{\xi})< Cq^{\xi/2}$ for some positive constant  $C$, where $e_u$ denotes a $q\times 1$ vector with the $u$th element of $e_u$ being one and the rest entries are zero;
\item Define $\|.\|_F$ as the Fubinius norm. 
For each given $\mu \in \Gamma$,  $\mathbb{E}\|(g(Z_t, \theta(\mu)) - \mu)(g(Z_t, \theta(\mu)) - \mu)^\top - \Omega(\theta(\mu),\mu) \|_F^2 = O(q)$, 
{$\mathbb{E}\|g(Z_t, \theta(\mu)) - \mu\|^\xi \lesssim q^{\xi/2} $},   
{$\mathbb{E}\|(g(Z_t, \theta(\mu)) - \mu)(g(Z_t, \theta(\mu)) - \mu)^\top - \Omega(\theta(\mu),\mu) \|_F^\xi \lesssim q^{\xi/2} $}; 
\item $g(Z_t,\theta)$ is  
continuously differentiable, and
$G_t(\theta)=\partial g_t(\theta) / \partial \theta$;
{          \item   there exists a neighborhood, $\mathcal{N}(\theta(\mu))$, of $\theta(\mu)$ such that for each {$\theta \in \mathcal{N}(\theta(\mu))$}: there exists a non-negative scalar random variable $b(Z_t)$ such that  $\| g(Z_t, \theta)-g(Z_t, \theta(\mu))  \|\leq b(Z_t) \|\theta -\theta(\mu)\|$,  $\|\partial (g(Z_t, \theta)-\mu) /\partial \theta -\partial (g(Z_t, \theta(\mu))-\mu) /\partial \theta \|\leq b(Z_t) \|\theta -\theta(\mu)\|$,  and $\mathbb{E}[ (b(Z_t))^2 ]<\infty$;  
} 
\item

$\|\sup_{\theta \in \Theta}(T^{-1}\sum_t \{G_t({\theta}) -\E G_t(\theta)\})\| = o_p(1)$, 
there exists $C>0$ such that 
$1/C\leq  \lambda_{\min}(\mathbb{E}[(\partial (g(Z_t, \theta)-\mu)/ \partial \theta^\top)]^\top 
\mathbb{E} [\partial (g(Z_t, \theta)-\mu)/ \partial \theta^\top ])  \leq \lambda_{\max}(\mathbb{E}(\partial (g(Z_t, \theta)-\mu)/ \partial \theta^\top)^\top \mathbb{E}\partial (g(Z_t, \theta)-\mu)/ \partial \theta^\top )  \leq C$;

\item   
\label{item-coro appendix: }
{There exits a constant $\xi_\lambda \in (\xi^{-1} , 2^{-1})$ such that $ \max \{q  T^{-\xi_\lambda + \xi^{-1}}, q T^{\xi_\lambda - 2^{-1}}\} \rightarrow 0$. }
\end{enumerate}
Then, the following expansion (\ref{eq:expansion}) holds for any fixed $\mu \in \Gamma$,
\begin{equation} \small 
\left\|\widehat{\theta}(\mu)-\theta(\mu)-(G(\theta(\mu))^{\top }\Omega(\theta(\mu),\mu)^{-1} G(\theta(\mu)) )^{-1}G(\theta(\mu))^{\top}\Omega(\theta(\mu),\mu)^{-1} \left(\widehat{m}\left(\theta(\mu)\right)-\mu\right)\right\|  =o_p( {q} T^{-1/2}),\label{eq:expansion}
\end{equation}
where we consider 
$\widehat{\theta}(\mu) =\argmin_{\theta \in \Theta} \{\widehat{m}(\theta)-\mu\}^{\top}{\widehat{\Omega}(\theta, \mu)^{-1}} \{\widehat{m}(\theta)-\mu\},$ 
{$\Omega(\theta(\mu), \mu)=\mathbb{E}[(g(Z_t, \theta(\mu)) - \mu )(g(Z_t, \theta(\mu))-\mu)^\top]$ and $\widehat{\Omega}(\theta(\mu), \mu)=T^{-1}\sum_{t=1}^T[(g(Z_t, \theta(\mu)) - \mu )(g(Z_t, \theta(\mu))-\mu)^\top]$}.
Thus, Assumption \ref{Gaussian} is satisfied for this case once the distributional property of $(\widehat{m}(\theta)-\mu)$ leads to the Gaussian limiting distribution, which hold under conditions indicated by, e.g., the central limit theorem proposed in \cite{francq2005central}. 
\end{corollary}
Before the discussion, we first claim several lemmas employed in proving Corollary \ref{coro:Gaussian}, which correspond to Lemmas A1-A3 in \cite{newey2004higher} and are adjusted to fit our conditions. Furthermore, we let $\rho(v)$ be a quadratic scalar function such that $\rho(v) = - v - \frac{1}{2} v^2$ and let $ \rho_j(v)=\partial^j \rho(v) / \partial v^j$, and we let $$\widehat{P}_\mu(\theta,\lambda)=\frac{1}{T}\sum_{t=1}^T \rho(\lambda^{\top} (g(Z_t, \theta) -\mu))= -\lambda^\top \frac{1}{T}\sum_{t=1}^T (g(Z_t, \theta) -\mu))  -\lambda^\top \frac{1}{T}\sum_{t=1}^T (g(Z_t, \theta) -\mu))(g(Z_t, \theta) -\mu))^\top \lambda.$$ 
The estimator for $\theta(\mu)$ for a given $\mu\in \Gamma$ then corresponds to a saddle point problem such that $$\widehat{\theta}(\mu) =\argmin_{\theta\in \Theta} \max_{\lambda \in {{\widehat{\Lambda}_{T,\mu}}}(\theta)  } \widehat{P}_\mu(\theta,\lambda),$$ with $ {{\widehat{\Lambda}_{T,\mu}}}(\theta)  = \{\lambda: \lambda^{\top} (g(Z_t, \theta)-\mu)\in \Lambda_g, 1\leq t\leq T \}$ and $\Lambda_g$ being an open interval containing zero. We use the following notations for a given $\mu \in \Gamma$. We denote  $g_t(\theta)=g(Z_t, \theta)$ and $\widehat{g}_{\mu, t}=g_t(\widehat{\theta}(\mu))$. 
Let ${\upsilon}_{\theta\lambda}$ be a augmented parameter vector such that ${\upsilon}_{\theta\lambda} = (\theta^\top, \lambda^\top)^\top$ and for a given $\mu \in \Gamma$, ${\upsilon}_{\theta(\mu)0} = (\theta(\mu)^\top, 0^\top)^\top$. Let $v_t(\mu, {\upsilon}_{\theta\lambda} )=\lambda^{\top} (g_t(\theta)-\mu)$ and $v_{t,1}(\mu, {\upsilon}_{\theta\lambda} )=\partial v_t(\mu, {\upsilon}_{\theta\lambda} ) / \partial {\upsilon}_{\theta\lambda} =\left(\lambda^{\top} G_t(\theta), (g_t(\theta)-\mu)^{\top}\right)^{\top}$.  
Denote $ m_\mu\left(Z_t, {\upsilon}_{\theta\lambda} \right)=\partial \rho\left(v_t(\mu, {\upsilon}_{\theta\lambda} )\right)/\partial {\upsilon}_{\theta\lambda}  =\rho_1\left(v_t(\mu, {\upsilon}_{\theta\lambda} )\right)v_{t,1}(\mu, {\upsilon}_{\theta\lambda} ),$ $m_{\mu,t}({\upsilon}_{\theta\lambda} )=m_\mu\left(Z_t, {\upsilon}_{\theta\lambda} \right)$, $M_\mu=\mathbb{E}\left[ \partial m_{\mu, t}\left( {\upsilon}_{\theta(\mu)0}\right) /\partial {\upsilon}_{\theta\lambda}^\top  \right]$, $\psi_\mu(Z_t)=-M_\mu^{-1} m_\mu\left(Z_t, {\upsilon}_{\theta\lambda}\right)$ and $\widehat{\psi}_\mu= \sum_{t=1}^{T} \psi_\mu(Z_t)/\sqrt{T}$. By construction, we have $M_\mu= -\left(\begin{matrix}
0 & G(\theta(\mu))^\top \\ G(\theta(\mu)) & \Omega(\theta(\mu),\mu)
\end{matrix} \right)$. 

\begin{lemma}(Generalised High dimensional Fuk-Nagaev Inequality)
\label{l2cont} 
Consider i.i.d. centered $X_1, ..., X_n$ in $\mathbb{R}^k$. Let $\Sigma := \E[X_1X_1^{\top}]$ and $\omega := \diag(\Sigma)$. Assume that $\E\lVert X_1\rVert^\xi < \infty$ for some $\xi > 2$, then we have for any $t > 0$,
\begin{equation}
\mathrm{P}\bigg\{\big\lVert\sum_{i=1}^n X_i\big\rVert \geq 2\sqrt{n|\omega|_1} + t\bigg\} \leq C_\xi\frac{n\mathrm{E}\lVert X_1\rVert^\xi}{t^\xi} + \exp\bigg(-\frac{t^2}{3n\lVert \omega\rVert}\bigg),
\end{equation}
where $C_\xi > 0$ is a constant only depending on $\xi$.
\end{lemma}
\begin{proof} See Theorem 3.1 in \cite{einmahl2008characterization}. We apply Theorem 3.1 therein with $(B,\|\cdot\|)=\left(\mathbb{R}^k,\|\cdot\|\right)$ where $\eta=\delta=1$.  The unit ball of the dual of $\left(\mathbb{R}^k,\|\cdot\|\right)$ is the set of linear functions $\left\{x=\left(x_1, \ldots, x_k\right)^T \mapsto \sum_{j=1}^k \lambda_j x_j: (\sum_{j=1}^k\left|\lambda_j\right|^2)^{1/2} \leq 1\right\}$, and for $\lambda_1, \ldots, \lambda_k$ with $(\sum_{j=1}^k\left|\lambda_j\right|^2)^{1/2} \leq 1$, with the following step,
$$
\begin{gathered}
\sum_{i=1}^n \mathbb{E}\left[\left(\sum_{j=1}^k \lambda_j X_{i j}\right)^2\right]= \sum_{i=1}^n \E\left[\lambda^{\top}X_iX_i^{\top}\lambda\right]
\leq n \|\lambda\| \lambda_{\max}(\Sigma)\leq n \|\omega\|.
\end{gathered}
$$
Hence in this case, $\Lambda_n^2$ in Theorem 3.1 \cite{einmahl2008characterization} is bounded by  $n  \|\omega\|$. Additionally, by Jensen's inequality, $\sqrt{n|\omega|_1} \geq \mathbb{E}\lVert\sum_{i=1}^n X_i\rVert$. Therefore, Lemma \ref{l2cont} is implied by Theorem 3.1 \cite{einmahl2008characterization}.
\end{proof}

\begin{lemma}\label{lemA1}
Under the assumptions of Corollary \ref{coro:Gaussian}, let $b_t=\sup_{\theta\in \Theta}\|g(Z_t, \theta) -\mu \|$ for a $\mu\in \Gamma$, then $\max_{1\leq t\leq T}b_t =O_p( {q}^{{1}/{2}} T^{{1}/{\xi}})$. 
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lemA1}]~\\
Denote $b_{tu}=\sup_{\theta\in\Theta} \|e_u^\top(g(Z_t, \theta) -\mu) \|$, and thus
$ b_t\leq  \max_{1\leq u\leq q}\sqrt{q} b_{tu}$. The assumption that $\max_{1\leq u\leq q}\mathbb{E}(b_{tu}^{\xi}) <C $ and the Markov inequality imply that $\max_{1\leq u\leq q}\max_{1\leq t\leq T} b_{tu}=O_p(T^{1/\xi})$, and thus the conclusion follows.
\end{proof}




