\begin{lemma}\label{lem15}
Under the assumptions of Corollary \ref{coro:Gaussian}, $\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\| =O_p(qT^{-1/2})$ for any $\mu \in \Gamma$.  
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem15}]
Since we have a saddle point problem, 
\begin{align*}
\widehat{P}_{\mu}(\widehat{\theta}(\mu), \widehat{\lambda}_g(\epsilon_T) )   \leq  \widehat{P}_{\mu}(\widehat{\theta}(\mu),\widehat{\lambda})  \leq   \max_{\lambda \in \Lambda_{T, q^{1/2}}}  \widehat{P}_{\mu}(\theta(\mu), {\lambda}),  
\end{align*}
where $\widehat{\lambda}_g(\epsilon_T)=-\epsilon_T (\widehat{m}(\widehat{\theta}(\mu))-\mu)$ and $\epsilon_T$ is a positive scalar. We have from Lemma \ref{lemA31} that  $\widehat{P}_{\mu}(\widehat{\theta}(\mu),\widehat{\lambda}) \leq   \max_{\lambda \in \Lambda_{T, q^{1/2}}}  \widehat{P}_{\mu}(\theta(\mu), {\lambda})  =  O_p(qT^{-1}).$ For the term $\widehat{P}_{\mu}(\widehat{\theta}(\mu), \widehat{\lambda}_g(\epsilon_T))$ we have that 
\begin{align*}
\widehat{P}_{\mu}(\widehat{\theta}(\mu),\widehat{\lambda}_g(\epsilon_T)) =\epsilon_T\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|^2 -1/2 (\widehat{\lambda}_g(\epsilon_T))^\top(\frac{1}{T} \sum_t { (g_t(\widehat{\theta}(\mu))-\mu)^\top} (g_t(\widehat{\theta}(\mu))-\mu) ) \widehat{\lambda}_g(\epsilon_T),
\end{align*}
and thus the fact that $$1/2 (\widehat{\lambda}_g(\epsilon_T))^\top(\frac{1}{T} \sum_t { (g_t(\widehat{\theta}(\mu))-\mu)^\top} (g_t(\widehat{\theta}(\mu))-\mu) ) \widehat{\lambda}_g(\epsilon_T)\leq q(\sum_{t=1} b_{t}^2/T)\| \widehat{\lambda}_g(\epsilon_T)\|^2 $$ implied by the proof of Lemma \ref{lemA1} leads to 
\begin{align*}
& \epsilon_T\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|^2 - O_p(q)\| \widehat{\lambda}_g(\epsilon_T)\|^2 = \epsilon_T\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|^2 - O_p(q) \epsilon_T^2\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|^2 
\leq     O_p(qT^{-1})
\end{align*} 
If we choose $\epsilon_T =T^{-\xi_\lambda}/\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|$ so that $\widehat{\lambda}_g(T^{-\xi_\lambda}/\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|)\in \Lambda_{T,q^{1/2}} \cap \widehat{\Lambda}_{T}(\widehat{\theta}(\mu))$ w.p.a.1., the above inequality implies that 
\begin{align*}
\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\| 
\leq  O_p(q)  O_p(T^{-\xi_\lambda}) +   O_p(qT^{\xi_\lambda-1}).
\end{align*}
Hence, $\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\| =  o_p(T^{-1/\xi})$ and from the assumption $q  T^{-\xi_\lambda + \xi^{-1}}\rightarrow 0$, we know that $\widehat{\lambda}_g(\epsilon_T)$ is an interior point in $\Lambda_{T,q^{1/2}}$ and in $\widehat{\Lambda}_{T}(\widehat{\theta}(\mu))$  w.p.a.1. as long as $\epsilon_T \rightarrow 0$. Now consider one arbitrary drifting to zero sequence $\epsilon_T$, $\epsilon_T\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|^2 - O_p(q)\epsilon_T^2\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|^2 =  O_p(qT^{-1})$ implies that  $\epsilon_T \|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|^2 =  O_p(qT^{-1})$ if $\epsilon_T=o_p(q^{-1})$, since this is true for all such sequences, we know $\|\widehat{m}(\widehat{\theta}(\mu)) -\mu\|=O_p(qT^{-1/2})$. 
\end{proof}

\begin{lemma}\label{lem16}
Under the assumptions of Corollary \ref{coro:Gaussian}, $\| \widehat{\theta}(\mu) -\theta(\mu)\| =O_p(qT^{-1/2})$. 
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem16}] 


The differentiability assumption implies that 
$$\widehat{m}(\widehat{\theta}(\mu)) -\widehat{m}({\theta}(\mu)) = T^{-1}\sum_t G_t(\overline{\theta}
(\mu))^{\top}(\widehat{\theta}(\mu) -{\theta}(\mu) ),$$
where $$\|\Bar{\theta}(\mu)-{\theta}(\mu)\|\leq \|\widehat{\theta}(\mu)-{\theta}(\mu)\|.$$ Denote $G(\theta) = \mathbb{E}G_t(\theta)$,  and the assumption  $
\|\sup_{\theta\in \Theta}(T^{-1}\sum_t G_t({\theta})^{\top}-\E G_t(\theta)^\top)\| =o_p(1)$ leads to
$\widehat{m}(\widehat{\theta}(\mu)) -\widehat{m}({\theta}(\mu)) = (G(\bar{\theta}
(\mu))+ o_p(1))^{\top}(\widehat{\theta}(\mu) -{\theta}(\mu) ),$ {where $o_p(1)$ is defined in terms of $|.|_2$ norm}.
Thus the assumption that $\lambda_{\min} (G(\bar{\theta}
(\mu))^{\top}G(\bar{\theta}
(\mu)))$ is bounded away from zero implies that
$$\|(\widehat{\theta}(\mu) -{\theta}(\mu) )\|\leq C\|\widehat{m}(\widehat{\theta}(\mu)) -\widehat{m}({\theta}(\mu))\|\leq C\{\|\widehat{m}(\widehat{\theta}(\mu))-\mu\| +\|\widehat{m}({\theta}(\mu))-\mu\|\},$$
then the rate follows as $\|\widehat{m}(\widehat{\theta}(\mu))-\mu\|=O_p(qT^{-1/2})$ indicated by Lemma \ref{lem15} and $\|\widehat{m}({\theta}(\mu))-\mu\|=O_p(q^{1/2}T^{-1/2})$ indicated by Lemma \ref{l2cont}. 
\end{proof}

Consider a first-order Taylor expansion of $\sum_t m(Z_t,{\upsilon}_{\theta\lambda} )/T$ for $\widehat{\upsilon}_{\theta\lambda} =\left(\widehat{\theta}(\mu)^{\top}, \widehat{\lambda}^{\top}\right)^{\top}$ and $ {\upsilon}_{\theta(\mu)0}=\left(\theta(\mu)^{\top}, 0^{\top}\right)^{\top}$, we have $0=\left(\begin{array}{c}
0 \\
{- \widehat{m}\left(\theta(\mu)\right)}
\end{array}\right)+ \bar{M}_\mu \left(\widehat{\upsilon}_{\theta\lambda} -{\upsilon}_{\theta(\mu)0}\right),$ where
\begin{align*} 
& \bar{M}_\mu=\left(\begin{array}{cc}
0 & \sum_{t=1}^T\rho_1\left(\bar{\lambda}^{\top} \widehat{g}_{\mu, t}\right) G_t(\bar{\theta}(\mu))^{\top} / T \\
\sum_{t=1}^T \rho_1\left(\bar{\lambda}^{\top} \widehat{g}_{\mu, t}\right) G_t(\bar{\theta}(\mu)) / T & \sum_{t=1}^T \rho_2\left(\bar{\lambda}^{\top} \widehat{g}_{\mu, t}\right) g_t(\bar{\theta}(\mu)) \widehat{g}_{\mu, t}^{\top} /T
\end{array}\right),  
\end{align*}
and $\bar{\theta}(\mu)$ and $\bar{\lambda}$ are mean values converging to $\theta(\mu)$ and $0$ that actually differ from row to row of the matrix $\bar{M}_\mu$. 


\begin{lemma}\label{lem17}
Under the assumptions of Corollary \ref{coro:Gaussian}, $\| \Bar{M}_\mu -M_\mu\|=o_p(1)$, for all $\mu$.
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem17}] 

We first show that
$\|\widehat{\Omega}(\theta(\mu), \mu)- \Omega(\theta(\mu), \mu) \| = o_p(1)$ with {$\widehat{\Omega}(\theta(\mu), \mu)= \frac{1}{T}\sum_{t} (\widehat{g}_{\mu, t}-\mu) (\widehat{g}_{\mu, t}-\mu)^{\top} $}. This comes 
directly from the fact that  
\begin{align*}
&    \|\widehat{\Omega}(\theta(\mu), \mu) - \Omega(\theta(\mu), \mu) \| =   \|\frac{1}{T}\sum_{t} (\widehat{g}_{\mu, t}-\mu)(\widehat{g}_{\mu, t}-\mu)^{\top} - \Omega(\theta(\mu), \mu) \|  
\\ \leq &   \left\|\frac{1}{T}\sum_t( \widehat{g}_{\mu, t} - {g}_t({\theta}(\mu)) ) (\widehat{g}_{\mu, t} -{g}_t({\theta}(\mu)))^\top \right\|+2\left\|\frac{1}{T}\sum_t({g}_t({\theta}(\mu)) -\mu ) (\widehat{g}_{\mu, t} -{g}_t({\theta}(\mu)))^\top  \right\|\\ 
&+  \left\|\frac{1}{{T}} \sum_t (g_t(\theta(\mu))-\mu)(g_t(\theta(\mu))-\mu)^\top  - \Omega(\theta(\mu), \mu) \right\|   ={ o_p(1) }
\end{align*} 
where  
\begin{enumerate}
\item $\left\|\frac{1}{T}\sum_t( \widehat{g}_{\mu, t} - {g}_t({\theta}(\mu)) ) (\widehat{g}_{\mu, t} -{g}_t({\theta}(\mu)))^\top \right\|=o_p(1)$ results from the fact that  $\| \widehat{g}_{\mu, t} - {g}_t({\theta}(\mu)) ) \| \leq b(Z_t) \|\widehat{\theta}(\mu)-{\theta}(\mu)\|$ and  
\begin{align*}
& \left\|\frac{1}{T}\sum_t( \widehat{g}_{\mu, t} - {g}_t({\theta}(\mu)) ) (\widehat{g}_{\mu, t} -{g}_t({\theta}(\mu)))^\top \right\| \leq 
\frac{1}{T}\sum_t (b(Z_t))^2 \|\widehat{\theta}(\mu)-{\theta}(\mu)\|^2.    
\end{align*}


\item $\left\|\frac{1}{T}\sum_t({g}_t({\theta}(\mu)) -\mu ) (\widehat{g}_{\mu, t} -{g}_t({\theta}(\mu)))^\top  \right\| = o_p(1)$ results from the fact that 
\begin{align*}
& \left\|\frac{1}{T}\sum_t({g}_t({\theta}(\mu)) -\mu ) (\widehat{g}_{\mu, t} -{g}_t({\theta}(\mu)))^\top  \right\|\\
= &{ \left\|\frac{1}{{T}}\sum_t({g}_t({\theta}(\mu)) -\mu )(\widehat{\theta}(\mu) -{\theta}(\mu)) )^\top  G_t(\bar{\theta}(\mu))^\top  \right\|} \\
\leq & \max_t b_t \| \widehat{\theta}(\mu) -{\theta}(\mu)) \|{ \left\|\frac{1}{{T}}\sum_t G_t(\bar{\theta}(\mu))^\top  \right\|} =O_p(q^{3/2}T^{1/\xi - 1/2})
\end{align*} 

\item  $ \left\|\frac{1}{{T}} \sum_t (g_t(\theta(\mu))-\mu)(g_t(\theta(\mu))-\mu)^\top  - \Omega(\theta(\mu),\mu) \right\| =O_p(q^{1/2}T^{-1/2})$ as in the proof of Lemma \ref{lemA31}.

\end{enumerate}
Next, $\| \frac{1}{T}\sum_t G_t(\widehat{\theta}(\mu)) - \mathbb{E} G_t(\theta(\mu))) \|=o_p(1)$  results from the triangular inequality and the facts that $$\|\frac{1}{T}\sum_t G_t(\widehat{\theta}(\mu)) -  G_t(\theta(\mu))) \|\leq \frac{\sum_t b(Z_t)}{T}\|\widehat{\theta}(\mu) -\theta(\mu)\|,$$ and that $\| \frac{1}{T}\sum_t G_t({\theta}(\mu)) - \mathbb{E} G_t(\theta(\mu))) \| $ is bounded by assumption. Since the above arguments also hold when we replace parts of $\widehat{\theta}(\mu)$ by $\bar{\theta}(\mu)$, the final conclusion is then indicated once we notice that $\|\bar{\lambda}^{\top}\widehat{g}_{\mu, t} \|=o_p(1)$, which is indicated by Lemma \ref{lem15} and the fact that $\|\widehat{\Omega} - \Omega(\theta(\mu), \mu) \| = o_p(1)$. 




\end{proof}




\begin{proof}[Proof of Corollary \ref{coro:Gaussian}] 
We now can establish the expansion \ref{eq:expansion}  to show the validity of Assumption \ref{Gaussian}. 
Note that by assumption $M_\mu$ is non-singular, and Lemma \ref{lem17}  implies that $\bar{M}_\mu$ is also non-singular w.p.a.1. such that  $\|\bar{M}_\mu^{-1} -M_\mu^{-1}\| \leq \|\bar{M}_\mu^{-1} \| \|\bar{M}_\mu  -M_\mu  \| \|M_\mu^{-1}\| =o_p(1)$, and thus $$\sqrt{T}\left(\widehat{\upsilon}_{\theta\lambda} -{\upsilon}_{\theta(\mu)0} \right)=-(M_\mu^{-1}+o_p(1))\left(0,-\sqrt{T} (\widehat{m}\left(\theta(\mu)\right)^{\top}-\mu^\top)\right)^{\top},$$ with 
\begin{align*} 
& {M}_\mu^{-1}=-\left(\begin{array}{cc}
F^{-1}_{\mu} & -F^{-1}_{\mu}G(\theta(\mu))^{\top}\Omega(\theta(\mu), \mu)^{-1} \\ -\Omega(\theta(\mu), \mu)^{-1}G(\theta(\mu))F^{-1}_{\mu} &\Omega(\theta(\mu), \mu)^{-1} + \Omega(\theta(\mu), \mu)^{-1}G(\theta(\mu))F^{-1}_{\mu}G(\theta(\mu))^{\top}\Omega(\theta(\mu), \mu)^{-1}  
\end{array}\right)
\end{align*}
and $F_{\mu}=- G(\theta(\mu))^{\top }\Omega(\theta(\mu), \mu)^{-1} G(\theta(\mu)).$ 
Therefore, $\|(\widehat{\theta}(\mu)-\theta(\mu)) -  F^{-1}_{\mu}G(\theta(\mu))^{\top}\Omega(\theta(\mu), \mu)^{-1}( \widehat{m}\left(\theta(\mu)\right)-\mu )\| = o_p(q{T}^{-1/2})$. The assumptions proposed in this analysis can be relaxed further if only for the validity of Assumption \ref{Gaussian}.  
\end{proof} 
\section{Link to optimal decision rule}
\label{appendix:optimalrule}


We argue in this section that, similar to the results established in \cite{andrews2022optimal}, under model misspecification, we can also establish that the quasi-posterior can be obtained as the limit of a sequence of posteriors under proper priors, and the resulting quasi-Bayes decision rule can correspond to the pointwise limit of the sequence of Bayes decision rules. 
To align with the setup in \cite{andrews2022optimal}, we do not work directly with $\mathbb{P}_{\mu}$ or focus solely on the parameter $\theta(\mu)$. Instead, We define a fixed coarse reference measurement $\mathbb{P}_0$ and consider the parameter pair $(\theta(\mu), \mu)$. While the construction in this subsection may appear tedious, it is primarily introduced to facilitate this match.




\begin{Assumption}(Measure in the limit) \label{assum:(Measure in the limit)} 
There exists $\tilde{Z}_t$, which is a maximal subset of $Z_t$ such that the distribution of $\tilde{Z}_t$ does not change with respect to any $(\theta(\mu),\mu) \in \Xi$.
There exists i.i.d. random sequence $\mu_t$ such that $\E_{\mathbb{P}_{\mu^*}}(\mu_t)= \mu^*$. The random variable $(g(Z_t,\theta(\mu)) - \mu_t, \tilde{Z}_t), t=1,\cdots, T$ follows $\mathbb{P}_0$ that is invariant for all plausible  pairs $(\theta(\mu),\mu)\in \Xi$.
\end{Assumption}

The specification of the $\mathbb{P}_0$ 
matches the nonparametric Bayesian idea from \cite{gallant2007statistical} such that we can treat $\mu_t$ as a latent variable capturing the misspecification, and $\mathbb{P}_0$ remains invariant with respect to the plausible characteristics. While $\mathbb{P}_\mu$ is a marginal measure over $Z_t$ given $\mu$, $\mathbb{P}_0$ can then be seen as a coarse joint measure concerning $(Z_t, \mu_t)$ and it may not be enough to deduce a marginal distribution for $Z_t$ or $\mu_t$, which is similar to the case discussed in \cite{gallant2007statistical}. 

Assumption \ref{assum:(Measure in the limit)} essentially assumes that the measure (in the limit) of the sample moment can be decomposed into two parts. The plausible term impacts one part, while the remaining part is a measure invariant to $(\theta(\mu),\mu)$. For example, in the plausible IV model from \cite{conley2012plausibly}, we may choose $\mu_t=  \gamma D_t^\top  D_t, \Tilde{Z}_t=(X_t^{\top}, W_t^{\top}, D_t^{\top})^{\top}$ and thus the distribution of $\sum_t [g(Z_t,\theta(\mu)) - \mu_t]$ does not depend on the plausible term $\mu$.  Additionally, it is reasonable to consider
the deviations from the measure of $((g(Z_t,\theta) - \mu_t)^\top, \Tilde{Z}_t^\top )^\top$, i.e., $\mathbb{P}_0$, and in the spirit of \cite{andrews2022optimal} and \cite{kitamura2013robustness} we consider perturbations in the probability measure in Assumption \ref{assum: Differentiability in quadratic mean}.
The subspace of score functions as 
\[
T_{\mu}\left(\mathbb{P}_{0}\right)=\left\{ f\in T\left(\mathbb{P}_{0}\right):\mathbb{E}_{\mathbb{P}_{0}}\left[f(Z_t) \left(g\left(Z_t, \theta(\mu)\right) - \mu_t\right) \right]=0\right\}.
\]
We define $\bar{m}(\mu,\theta)=\E_{\mathbb{P}_0}(f\left(g\left(Z_t, \theta\right) - \mu_t\right))$, then for $f\in T_{\mu}\left(\mathbb{P}_0\right)$, 
by design $\bar{m}(\mu,\theta(\mu))=0$. 

\begin{Assumption}(Differentiability in quadratic mean) \label{assum: Differentiability in quadratic mean}  $(g(Z_t,\theta) - \mu_t, \Tilde{Z}_t)$ of size $T$ follows distribution {$\mathbb{P}=\mathbb{P}_{T,f}$}, where the sequence
$\mathbb{P}_{T,f}$ converges to  $\mathbb{P}_{0}$, 
\[
\int\left[\sqrt{T}\left(d\mathbb{P}_{T,f}^{1/2}-d\mathbb{P}_0^{1/2}\right)-\frac{1}{2}fd\mathbb{P}_0^{1/2}\right]^{2}\rightarrow0.
\]
\end{Assumption}

While the score $f$ controls the data distribution, our interest
lies in the plausible pair $(\theta(\mu),\mu)$. Denote $\widehat{g}(\theta,\mu) = \frac{1}{\sqrt{T}}\sum_{t=1}^T [g(Z_t,\theta) -\mu]$. 


\begin{Assumption}(GP in the limit) \label{assum:(GP in the limit)} 
Assume that under $\mathbb{P}_{T,f}$, $\widehat{g}(\theta(\mu),\mu)$ weakly converges to a Gaussian process with mean function $\bar{m}(\cdot)$ and covariance function $\Sigma(\cdot)$, where the covariance function is continuous and nonsingular for all pairs $(\theta,\mu)$ and is consistently estimable. 
\end{Assumption}
Additionally, denote by $\tilde{g}(\cdot)$ the limiting Gaussian process of $\widehat{g}(\cdot)$ on $(\theta(\mu),\mu)$ pairs, $\mathcal{C}_\Xi$ the space of continuous functions from $\Xi$ to $\mathbb{R}^{q}$. Let $A$ be any linear functional $A: \mathcal{C}_\Xi \rightarrow \mathbb{R}^{q}$ such that $\operatorname{Cov}(A(\tilde{g}(\cdot)), \tilde{g}(\theta,\mu))$ is nonsingular for all $(\theta,\mu)$. Let $h_\perp(\cdot)=\tilde{g}(\cdot)-\operatorname{Cov}(\tilde{g}(\cdot), \xi_A) \operatorname{Var}(\xi_A)^{-1} \xi_A$ and $\mu_\perp(\cdot)=\bar{m}(\cdot)-\operatorname{Cov}(\tilde{g}(\cdot), \xi_A) \operatorname{Var}(\xi_A)^{-1} A(\tilde{g}(\cdot))$, where $\xi_A=A(\tilde{g}(\cdot))$.   

Analogue to arguments in Sections 3.1.2 from \cite{andrews2022optimal}, the likelihood function $\ell\left(\mu_\perp, \theta(\mu), \mu; \tilde{g}(\cdot)\right)$ based on the observed data $\tilde{g}(\cdot)$ factors as
$$
\ell\left(\mu_\perp, \theta(\mu), \mu; \tilde{g}(\cdot)\right)=\ell\left(\mu_\perp, \theta(\mu), \mu; \xi_A\right) \ell(\mu_\perp; h_\perp),
$$
and thus their equation (8) directly implies that a class of proportional priors over $\mu_\perp$ would give rise to quasi-Bayes as a limiting case. 



To establish that quasi-Bayes decision rules are pointwise limits of the corresponding Bayes decision rules, it suffices to verify the conditions of Theorem 8 in \cite{andrews2022optimal}. The non-singularity of the covariance function is ensured, for instance, by Assumption \ref{a3}.i). The remaining conditions of their Theorem 8 require a loss function $\ell(a, \theta, \mu)$ that is uniformly bounded, continuous, and strictly convex in $a$ for each $(\theta, \mu)$, along with a compact and convex action space $\mathcal{A}$. These requirements are met with appropriately chosen loss functions and action spaces.



