Let $X$ be in $\UBC$.

\begin{ddd}\label{okbepgrbkeprbegfdb}
A uniform scale on $X$ is a  cofinal family $(U_{n})_{n\in \nat}$ in the uniform structure of $X$.
\end{ddd}

Note that the existence of a uniform scale is a non-trivial condition on the uniform structure.



We say that a  second uniform  scale  $(V_{n})_{n\in \nat}$ dominates the first if
$U_{n}\subseteq V_{n}$ for all $n$ in $\nat$.
\begin{ex}\label{kohprethegtgtrge}
If the uniform structure of $X$ comes from a metric, then $X$ admits a uniform scale. One can take  
$(V_{n^{-1}})_{n\in \nat}$, where $V_{r}$ is the metric entourage of width $r$ and we interpret 
$V_{\infty}:=X\times X$.

Every uniform scale $(U_{n})_{n\in \nat}$ of $X$ is dominated by a uniform scale of the form
$(V_{r(n)})_{n\in \nat}$, where $r:\nat\to (0,\infty]$ is a function such that $\lim_{n\to \infty} r(n)=0$.
We can take $r(n):=\inf\{r\in (0,\infty]\mid U_{n}\subseteq V_{r}\}+1$.
\hB
\end{ex}




 Let $X$ be in $\Fun(BG,\UBC)$. 
 \begin{ddd}\label{kohpertgetrgeg1}
 A uniform scale $(V_{n})_{n\in \nat}$ is called a Lipschitz scale for the $G$-action  if for every $g$ in $G$ there exists  $k$ in $\nat$ (the Lipschitz constant of $g$) such that for every $n$ and $l$ in $\nat$  we have $gV^{l}_{n}\subseteq V_{n}^{lk}$.
 \end{ddd}

    \begin{ddd}\label{kohpertgetrgeg}
   The action of $G$ on $X$ is called Lipschitz if 
   every uniform scale   on $X$ is dominated by a Lipschitz scale. 

   \end{ddd}

  %We call the integer $k$ a  Lipschitz constant for $g$. %  $k$ may depend on $g$, but it must be the same for all entourages $V$.

\begin{ex}
If the uniform structure of $X$ comes from a metric   and $G$ acts by Lipschitz maps,
then the action of $G$ on $X$ is Lipschitz.  In order to construct a Lipschitz scale 
dominating a given uniform scale   use the second part of \cref{kohprethegtgtrge}.
\end{ex}





