\begin{rem}
There is no need to pass to homotopy categories. For every $X$ in $\Fun(BG,\UBC)$ we have an
   equivalence of symmetric monoidal  rig-space $R(X)\simeq \prod_{\Z} \Fin^{\simeq}\rtimes \Z$, see
  \cite{Gepner_2015}. 
Group-completing the right-hand side we get a ring spectrum  $\bA:=(\prod_{\Z} \Fin^{\simeq}\rtimes \Z)^{\grp} $. Then for every object $X$ in $\Fun(BG,\UBC)$ we  have a homomorphism of ring spectra
  $$\bA\to \End_{\CMctr}(\Yoctr(\Sq(X)//G))\ .$$
 Passing to $\pi_{0}$ we get $\pi_{0} \bA\cong \prod_{\Z}\Z\rtimes \Z$ and recover $a$.
 Using the Baratt-Priddy-Quillen equivalence $(\Fin^{\simeq})^{\grp}\simeq S$ we get a map
 $\bA\to  \prod_{\Z}S\rtimes \Z$ which we expect to be an equivalence. 
We have $ (\prod_{\Z} \Fin^{\simeq})^{\grp}\simeq  \prod_{\Z}S$ by \cite[Prop. 7.2.5]{unik},
but at the moment we have no reference for the fact that group completion commutes with
forming the crossed product.
 \hB
\end{rem}


The homomorphism $a$ induces a ring homomorphism
$$\bar a: \frac{\prod_{\nat}\Z}{\bigoplus_{\nat}\Z}\rtimes \Z \to \End_{\ho(\CMctr)}(\Yoctr( \Sq(X)//G,\Sq_{-}(X)//G))\ .$$





We end this section with an application to the construction of coarse homology classes on the cone $ \cO^{\infty}(X)//G$.
Let $E$ be a spectrum-valued  coarse homology theory with transfers and $x$ be in $\pi_{*}E(\Sq(X)//G,\Sq_{-}(X)//G)$.  Assume that $$t_{*}x= \phi \cdot x$$ for some
$\phi$ in $\frac{\prod_{\nat}\Z}{\bigoplus_{\nat}\Z} $.
Then 
we have
$$(1+t) (\psi \cdot x)=0 \ , \qquad x=(1+t) \kappa \cdot x\ ,$$ where
$\psi$ and $\kappa$ in $\frac{\prod_{\nat}\Z}{\bigoplus_{\nat}\Z}$ solve \begin{equation}\label{iojweorgwoerf}\psi+(t\psi) \cdot \phi=0 \ , \quad (\kappa-\bar 1)+ (t\kappa)\cdot \phi=0
\end{equation}
and $\bar 1$ in $ \frac{\prod_{\nat}\Z}{\bigoplus_{\nat}\Z}$ is the  unit.
The second equation are always solvable recursively.
This implies that  
$\iota^{\exp}_{*} x=0$ for $\iota^{\exp}$ as in \eqref{rewgerfewrfwe}. As a result we see that 
the class $x$ is not useful to produce interesting classes in $\pi_{*}E(\cO^{\infty}(X)//G)$ via $\iota^{\exp}$, see also \cref{hkepetgerhrthergrtg}.
A similar observation has already been made in \cite[Sec. 4.1]{Kitsios:2025aa}.


By solving the  first equality in \eqref{iojweorgwoerf} we can find   new classes
$\psi \cdot x$ in the kernel of $1+t$   and therefore in the image of $$\delta: \pi_{*+1}E( \cO^{\infty}(X)//G)\to
  \pi_{*}E(\Sq(X)//G ,\Sq_{-}(X)//G )$$ with $\delta$ as in 
\eqref{rewgerfewrfwe}.
  Such a  class is non-trivial provided $x$ is so and
  $\psi$ is invertible.  The recursive equation for $\psi$ is
  $\psi_{n}:=- \psi_{n-1} \phi_{n}$ which must hold for sufficiently large $n$. 
   Since $\phi_{n}$ is eventually non-zero, we see that eventually non-zero solutions for $\psi$ exist as well.

  If $t_{*}x=x$, then we can take  $\psi=[(\pm 1)]:=[((-1)^{n})_{n\in \nat}]$.
  Again, this possibility of construction classes on the cone has already been observed in  \cite[Sec 4.2]{Kitsios:2025aa}.
  Note that \cref{oijoegwerferfwref} can be used to produce classes $x$ with this property.


  \begin{ex}\label{hkepetgerhrthergrtg}
  In this example we recover the motivic analogue of  \cite[Thm. B]{Kitsios:2025aa} for the cone at $\infty$. The proof is essentially a version of 
   \cite[(4.1)]{Kitsios:2025aa}.
   We consider the quotient map
   $$\iota:\Sq(X)//G \to \cO^{\infty}(X)//G$$
   induced by the identity of underlying sets.
       % Let $F:=\lim_{\BZ}\Yoctr(\Sq(X)//G)$.
   Below we implicitly use the equivalence   $$\Yoctr(\cO^{\infty}(X)//G)\stackrel{\simeq}{\to}\Yoctr(\cO^{\infty}(X)//G, \cO_{-}^{\infty}(X)//G)$$ for the second map in \eqref{erwfwerferwfwf}.
   The map $c$  in \eqref{erwfwerferwfwf} is the canonical map.


   \begin{prop}\label{okheprthertgetrge}
   The map
  \begin{equation}\label{erwfwerferwfwf}
\lim_{B\Z}\Yoctr(\Sq(X)//G,\Sq_{-}(X)//G)\stackrel{c}{\to} \Yoctr(\Sq(X)//G,\Sq_{-}(X)//G)\stackrel{\Yoctr(\iota)}{\to} \Yoctr(\cO ^{\infty}(X)//G)
\end{equation}  is  trivial. \end{prop}
   \begin{proof}
One checks using a coarse homotopy that $$\Yoctr(\iota)\simeq \Yoctr( \iota^{\exp})\circ  \psi  :\Yoctr(\Sq(X)//G,\Sq_{-}(X)//G)\to\Yoctr(\cO ^{\infty}(X)//G)\ ,$$ where $\psi=[(\psi_{n})_{n\in \Z}]$ in $\frac{\prod_{\nat}\Z}{\bigoplus_{\nat} \Z}$ with $\psi_{n}= 2^{n-1} 
 $ for large $n$. 
  We can solve $(1+t) \phi = \psi$ for $\phi$ in $\frac{\prod_{\nat}\Z}{\bigoplus_{\nat} \Z}$.
  Then $(1+t)\phi c\simeq \psi c$ and therefore 
  $\Yoctr(\iota) c\simeq \Yoctr( \iota^{\exp}) \psi  c\simeq \Yoctr( \iota^{\exp}) (1+t) \phi  c\simeq 0$ by \eqref{rewgerfewrfwe}.
  \end{proof}   
  \end{ex}

  \begin{rem}
  The map $\iota$ restricts to a map
   $$\iota_{\ge 0}:\Sq_{\ge 0}(X)//G \to \cO_{\ge 0}^{\infty}(X)//G\ .$$
   Using an analogous argument as above  and the exponential Mayer-Vietoris decomposition 
of $\cO_{\ge 0}^{\infty}(X)//G$ one can show that 
   $$\lim_{B\Z}\Yoctr(\Sq(X)//G )\stackrel{c}{\to} \Yoctr(\Sq(X)//G )\stackrel{\Yoctr(\iota_{\ge 0})\circ \Yoctr(\pr_{\ge 0})}{\to}\Yoctr( \cO_{\ge 0}^{\infty}(X)//G)\ .$$ 
   Applied to the coarse homology theory with transfers $K\cX$
  and the class $[p]$ in $$\lim_{B\Z} K\cX(   \Sq(X)//G,\Sq_{-}(X)//G)$$ for $p$ as in \eqref{whtgwergergws} we precisely obtain 
     \cite[Thm. B]{Kitsios:2025aa} with the same argument as in    \cite[(4.1)]{Kitsios:2025aa}.
\hB
  \end{rem}











