 \section{Sequence spaces and the $L^{2}$-index theorem}\label{hkoeprttrgegertg1}

Let $Y$ be a bornological coarse space which decomposes as a coarsely disjoint union of subspaces $(Y_{n})_{n\in \nat}$. We consider the big family $Y_{-}:=(Y_{\le k})_{k\in \nat}$
with $Y_{\le k}:= \bigsqcup_{n\le k} Y_{n} $.   
We furthermore consider a branched coarse $G$-covering   $f:X\to Y$  with respect to $Y_{-}$ and set
 $X_{n}:=f^{-1}(Y_{n})$.   We define the big family $X_{-}:=f^{-1}(Y_{-})$ on $X$.
Using excision we obtain canonical maps
$$K\cX(Y )\to \prod_{n\in \nat} K\cX(Y_{n})\ , \quad K\cX^{G}(X )\to \prod_{n\in \nat} K\cX^{G}(X_{n})$$
which associate to a class $p$   its sequence of components $(p_{n})_{n}$.
We get induced maps 
$$K\cX(Y ,Y_{-})\to \frac{\prod_{n\in \nat} K\cX(Y_{n})}{ \bigoplus_{n\in \nat} K\cX(Y_{n})}\ , \quad K\cX^{G}(X,X_{-} )\to \frac{\prod_{n\in \nat} K\cX^{G}(X_{n})}{\bigoplus_{n\in \nat} K\cX^{G}(X_{n})}\ ,$$
which associate to a class $[p]$   the tail $[(p_{n})_{n\in \nat}]$ of the sequence of components. Note that   only the tail is well-defined, not the components $p_{n}$ separately.

We now assume  for every $n$ in $\nat$ that $Y_{n}$ is bornologically bounded  and that $X_{n}$ is bornologically $G$-bounded.
We then  
  have  traces $\tau:\pi_{0} K\cX(Y_{n})\to \Z$ and  $G$-traces $\tau^{G}:\pi_{0} K\cX^{G}(X_{n})\to \R$, see 
 \cite[Sec. 9]{Bunke:2025aa} for details.
%Applying these traces to the sequences of components we get  traces
%$\hat \tau:K\cX_{0}(Y)\to \prod_{\nat}\Z$ and $\hat \tau^{G}:K\cX^{G}_{0}(X)\to \prod_{\nat}\R$.
 Applying these traces to the tails of the sequences of components we get traces
$$\bar \tau:\pi_{0}K\cX (Y,Y_{-})\to\frac{\prod_{\nat}\Z}{\bigoplus_{\nat}\Z}\ , \quad \bar \tau^{G}:\pi_{0} K\cX^{G} (X,X_{-})\to\frac{\prod_{\nat}\R}{\bigoplus_{\nat}\R}\ .$$ 




We now assume in addition  that $X$ has finite asymptotic dimension. Then the transfer
$$f^{*}:K\cX(Y,Y_{-})\to K\cX^{G}(X,X_{-})$$ is defined by \cite[Cor. 8.8]{Bunke:2025aa}. Spezializing the coarse assembly map  \eqref{gewrferfwerfrefwref} to the motive $\Yo(Y,Y_{-})$ in $\CM$ we 
 get  the morphism of spectra
\begin{equation}\label{gwrefwerfwerfwref}
\mu:\Sigma^{-1}K\cX(\cO^{\infty,\strg}\bP(Y,Y_{-}))\to  K\cX(Y,Y_{-})\ .
\end{equation} We consider a class $[p]$ in $\pi_{0}K\cX (Y,Y_{-})$

Note that Assumption \ref{retgtrtbvgfdbgfd}.\ref{gkpwerferfwfref}.\ref{ijfioerfjowewfqwef}  together with 
  Assumption \ref{retgtrtbvgfdbgfd}.\ref{koperhtrtgetrgertg}  
  implies that   the terms in \eqref{grewfwerfrw34w} below are well-defined as explained above.  
The following  \cref{retgtrtbvgfdbgfd} is a version of 
 \cite[Lem. 6.5]{Willett_2012} in the context of the coarse assembly map $K\cX(\mu)$ with $\mu$ as in \eqref{okopgtrgegrtg}. 
 \begin{theorem}\label{retgtrtbvgfdbgfd}   
 We assume:  \begin{enumerate} 
 \item \label{koperhtrtgetrgertg} 
 The components $Y_{n}$ are bornologically bounded and  $X_{n}$ are bornologically $G$-bounded for all $n$.
  \item \label{hwrtwrgwrgrtgt} $Y_{n}$ is a finite union of  coarsely bounded coarse components for every $n$ in $\nat$.  \item \label{gkpwerferfwfref} For a cofinal subset of entourages $U$ of $X$ we have:
 \begin{enumerate}   \item  \label{gergewferfwerferw} The bornological coarse space  $Y_{f(U)}$ has bounded geometry. 
  \item \label{kpogwregrefwrf} 
  The bornological coarse space $X_{U}$ has finite asymptotic dimension. 
   \item \label{ijfioerfjowewfqwef} The bornological coarse space $X$ has finite asymptotic dimension. 
  \end{enumerate}
