Recall the notion of   finite uniform topological dimension \cite[Def. 4.5]{Bunke:2025aa}.
If $X$ has finite  uniform topological dimension   and finite (coarse) asymptotic dimension, then $\Sq(X)$ 
has finite asymptotic dimension by \cite[Cor. 4.9]{Bunke:2025aa}. In our present situation we need that 
$\Sq(X)_{V}$ has finite asymptotic dimension for every $G$-adapted entourage $V$. The coverings with Lebesgue entourage $V$ provided  by  \cite[Cor. 4.9]{Bunke:2025aa} are bounded in the coarse structure of $\Sq(X)$, but not necessarily bounded in the smaller coarse structure of $\Sq(X)_{V}$.  
 In order to ensure the latter condition this we need the following stronger finiteness condition.  


 Let $X$ be in $\UBC$.  
\begin{ddd}\label{asna} 
 A uniform scale $(V_{n})_{n\in \nat}$ has  finite Assouad-Nagata dimension 
 if there exists $d$ and $k$ in $\nat$ such that for every $l$ and $n$ in $\nat$ there exists
 a $V_{n}^{kl}$-bounded covering of multiplicity $d$ with Lebesgue entourage $V^{l}_{n}$.
    \end{ddd}

    \begin{rem}
    We use the term {\em Assouad-Nagata dimension}
   since we consider \cref{asna} as the natural generalization of the classical notion of finite 
Assouad-Nagata dimension from metric spaces to uniform spaces.
If the uniform scale is comes from a metric scale  $(V_{r(n)})_{n\in \nat}$ with $\lim_{n\to \infty} r(n)=0$, then
the condition boils down to the classical notion.
 \hB
\end{rem}
\begin{rem}
One could try to define finite Assouad-Nagata dimension as the condition that there exists
$d$ and $k$ in $\nat$ such that for every uniform entourage $V$ of $X$ there exists
a $V^{k}$-bounded covering with multiplicity bounded by $d$ and Lebesgue entourage $V$.
But this condition might be too strong even in the metric case since it must be satisfied also  for  entourages $V$ which are not contained
in any bounded metric entourage.  
 \hB
\end{rem}


For simplicity we assume that $X$ has the maximal coarse structure as required anyway by Assumption \ref{kopherthretge9}.\ref{lptgeertgetrg}. Recall that $V$ is a $G$-adapted symmetric  coarse entourage of $\Sq(X)$.
After enlarging $V$ further we can  assume that $V_{n}=X\times X$ for $n<0$.

 \begin{lem}\label{koptwehrtherthrteeg}
 If  the uniform scale $(V_{n})_{n\in \nat}$   has finite   Assouad-Nagata dimension,   then 
  $\Sq(X)_{V}//G$ has bounded geometry. 
  \end{lem}
  \begin{proof}
    We will first show under the assumption that $(V_{n})_{n\in \nat}$ is a uniform scale  with   finite Assouad-Nagata dimension that $\Sq(X)_{V}$ has bounded geometry. Then we use the Lipschitz condition in order to  conclude that
  $\Sq(X)_{V}//G$ has bounded geometry, too.



It suffices to show for any $V^{2}$-discrete subset $Z$ of $\Sq(X)_{V}$ that for every $l$ in $\nat$ we have  $\sup_{y\in \Sq(X)} |V^{l}[y]\cap Z|<\infty$.

If $y\in \Sq_{<0}(X)$, then $  |V^{l}[y]\cap Z| \le 1$.  It therefore  remains to consider $y$ in $\Sq_{\ge 0}(X)$.
      Let $k$ and $d$  be as in   \cref{asna}. 
   For every $n$ in $\nat$ we choose  a $V^{k}_{n}$-bounded covering of $X$ with Lebesgue entourage $V_{n}$ and multiplicity bounded by $d$.
   These coverings together provide a $V^{k}$-bounded covering $\cW=(W_{i})_{i\in  I}$  of $\Sq_{\ge 0}(X)$ with multiplicity bounded by $d$ and   with Lebesgue entourage $ V$.
Therefore  $|\{i\in I\mid Y\cap W_{i}\not=\emptyset\}|\le d^{2l}$  for every $V^{2l}$-bounded subset $Y$ of $\Sq_{\ge 0}(X)$.  Note that $V^{l}[y]$ is $V^{2l}$-bounded for every $y$ in $\Sq_{\ge 0}(X)$.
   By $V^{2}$-discreteness of $Z$   for every $i$ in $I$ we have $|W_{i}\cap Z|\le 1$. We conclude that   
   \begin{equation}\label{wercfvsvdfv}\sup_{y\in \Sq_{\ge 0}(X)} |V^{l}[y]\cap Z|\le \sup_{y\in \Sq_{\ge 0}(X)} |\{i\in I\mid V^{l}[y]\cap W_{i}\not=\emptyset\}| \le d^{2l}<\infty \ .
\end{equation}
 This finishes the proof of bounded geometry for $\Sq(X)_{V}$.

Let $F$ be a finite subset of $G$ and set \begin{equation}\label{oerwigjregvweorgwergwr}W_{F}:=\{(gy,y)\mid f\in F, y\in \Sq(X)\}\ .
\end{equation} Since $V$ is $G$-adapted (see \cref{herjtogitrjgoetrgrtegetrg}), the uniform scale $(V_{n})_{n\in \nat}$ is a Lipschitz scale for the $G$-action. Therefore 
  the entourages $W_{F}\circ V^{l}$ for all finite subsets $F$ of $G$ and $l$ in $\nat$ are cofinal in the coarse structure of
$\Sq(X)_{V}//G$. We have $W_{F}[V^{l}[y]]=\bigcup_{g\in F} g V^{l}[y]$. Let $r$ in $\nat$ be a bound on the Lipschitz constants (see \cref{kohpertgetrgeg1})
of the elements $g$ in $F$.  Then  $W_{F}[V^{l}[z]]\subseteq \bigcup_{g\in F}  V^{rl}[gy]$.   It follows that
$ \sup_{y\in \Sq(X)}|W_{F}[V^{l}[y]]\cap Z|\le |F| \sup_{y\in \Sq(X)} |V^{rl}[y]\cap Z|<\infty$.


     \end{proof}




 For simplicity we again assume that $X$ has the maximal coarse structure.  \begin{lem}\label{pltherthtergegrtg} Under the same assumptions as \cref{koptwehrtherthrteeg} the bornological coarse space
  $\Sq(X)_{V}$ has finite asymptotic dimension.
\end{lem}
\begin{proof} Let $d$ and $k$ be as in \cref{asna}.
We  fix $l$ in $\nat$. For every $n$ in $\Z$ we choose a $V_{n}^{kl}$-bounded covering of $X$ with multiplicity bounded by $d$  and with Lebesgue entourage $V_{n}^{l}$. Thereby for $n<0$ we take the one-member covering $(X)$.



Putting these coverings together we 
get a $V^{kl}$-bounded covering of $\Sq(X)$ with multiplicity bounded by $d$ and Lebesgue entourage $V^{l}$.
\end{proof}






