The identity map of underlying sets is a morphism $\Sq(X_{\disc})//G\to \Sq(X)//G$ of bornological coarse spaces. In the following 
 we  turn $\hat H$ into a $\Sq(X)//G$-controlled Hilbert space determined on points with locally finite support, see  \cite{buen} for these notions. By \cref{kopherthretge9}.\ref{hpkprhtrgrtegerg} we can choose a coarse entourage $V$ of $\Sq(X)$ such that all the components $V_{n}$ are uniform entourages of $X$.  Using the further assumptions on $X$   we can choose  (see \cref{gkowperweferf} below for details) a measurable  $V^{2}$-bounded partition $(B_{j})_{j\in I}$ of a subset of full measure  of  $\Z\times X$   with $\hat \nu(B_{i})>0$ for all $i$ in $I$ and a locally 
 finite $V^{5}$-dense family $(b_{i})_{i\in I}$ of base points with $b_{i}\in B_{i}$. 
 We define the finitely additive projection-valued measure on $\hat H$ by 
$$\hat\mu(Y):=\sum_{i\in I } \hat \nu(B_{i})\delta_{b_{i}}\ .$$ 


 \begin{construction}\label{gkowperweferf}{\em 
 We start from a maximal $V$-separated family $(x_{j})_{j\in J}$ on $\Z\times X$. By  Assumption \ref{kopherthretge9}.\ref{hpkprhtrgrtegerg1}
each component $\{n\}\times X$ contains finitely many of them.
 Then $(V^{2}[x_{j}])_{j\in J }$ is a countable covering of $\Z\times X$.
 We can now choose inductively subsets $B_{j}\subseteq V^{2}[x_{j}]$ for every $j$ in $J$
 such that $(B_{j})_{j\in J}$ is a (necessarily $V^{2}$-bounded) measurable partition of $\Z\times X$.
 We set $I:=\{j\in J\mid \nu(B_{j})>0\}$. For every $i$ in $I$ we choose a point $b_{i}$ in the necessarily non-empty set $B_{i}$. Then $(b_{i})_{i\in I}$ is $V^{3}$-dense.
 Indeed, otherwise there exists a point $x$ in $\Z\times X$ such that
 $V[x]\cap B_{i}=\emptyset$ for all $i$ in $I$.
This implies $\nu(V[x])=0$ which contradicts the assumption that $\supp(\nu)=X$. 
 \hB



 }
 \end{construction}


    We  have the Roe algebra  $C(\Sq(X)//G,\hat H,\hat \mu)$ defined as the subalgebra of $B(\hat H)$
 generated by locally finite and controlled operators \cite{buen}.
 The following  observation  was made e.g. in  
  \cite{dsa}, \cite{Li_2023}, \cite{Kitsios:2025aa}.
 Recall our standing Assumption  \ref{kopherthretge9}.\ref{kpbgbrgebgrbgrb}.
 \begin{lem}\label{koprherhertgertgtr} We have\begin{equation}\label{fgdbfgbdfgberth}\hat P\in  C (\Sq(X)//G,\hat H,\hat\mu)\ .
\end{equation}  \end{lem}
\begin{proof} We first consider  the apriori larger Roe type algebra $C_{fp\cap lc}(\Sq(X)//G,\hat H,\hat\mu)$ of locally compact operators which can be approximated by  controlled operators.   The proof of  
  \cite[Thm. 6.20]{mvi} applies to the current situation and ensures the equality 
\begin{equation}\label{werfwerfwerf}C(\hat X//G,\hat H,\hat\mu)=C_{fp\cap lc}(\hat X//G,\hat H,\hat\mu)\ .
\end{equation}
Note that the operators $\hat \rho(g)$ considered on $(\hat H,\hat \mu)$ are no longer $U_{\{g\}}$-controlled (see \cref{gkopretgertfert}), but they are still
$V^{2}\circ U_{\{g\}}\circ V^{2}$-controlled. Consequently, these and $\hat M_{S}$ are controlled on $(\hat H,\hat \mu)$  for the coarse structure of $\Sq(X)//G$. As $\hat P$ is clearly locally compact  we have  $\hat P\in 
 C_{fp\cap lc}(\Sq(X)//G,\hat H,\hat\mu)$, and therefore by 
 \eqref{werfwerfwerf} we get \eqref{fgdbfgbdfgberth}.
 \end{proof}


\begin{rem}\label{erwg9upwerg}
We use the Assumption \ref{kopherthretge9}.\ref{kpbgbrgebgrbgrb} of a spectral gap for convenience
since then \cref{koprherhertgertgtr} has the class-room presentable proof given above.
But  the assertion of \cref{koprherhertgertgtr} holds under the more general assumption that the action of
$G$ on $(X,\nu)$ is strongly ergodic  \cite[Def. 2.10]{Li_2021}\footnote{We thank F. Vigolo for pointing this out.}
. In this case it follows from \cite[Cor. 4.4]{Li_2023}
and the equivalence of strong ergodicity and asymptotic expansion  \cite[Lem. 3.16]{Li_2021}. \hB
\end{rem}


