In the following we use the version of the definition \cite[Def. 8.10]{Bunke:2025aa} of a ghost operator, a notion originally introduced by G.Yu.
We consider $\hat P^{s}$ on $\Sq(X)//G$ with the big family $\Sq_{-}(X)//G$.
\begin{lem} \label{hpopethrtgertgtg} $\hat P^{s}$ is a ghost operator. \end{lem}
\begin{proof} Any coarse entourage of $\Sq(X)//G$ is contained in an entourage  
$U:=W_{F}\circ V$ for some $G$-adapted coarse entourage $V$ of $\Sq(X)$ and $W_{F}$ as in \eqref{oerwigjregvweorgwergwr}.
 We let
$U_{n}$ denote its restriction to the $n$-component which we consider as a copy of $X$.
We must show that
\begin{equation}\label{gerfwefewrfwer}\lim_{n_{0}\to \infty} \sup_{n\ge n_{0}}\sup_{x,x'\in X} \|\nu(U_{n}[x])P\nu(U _{n}[x'])\|=0\ .\end{equation}
We have $$ \|\nu(U_{n}[x])P\nu(U_{n}[x'])\|\le \sqrt{\nu(U_{n}[x])\nu(U_{n}[x'])}\ .$$
 By $G$-invariance of $\nu$ we furthermore have 
$ \nu(U_{n}[x])\le |F|\sup_{x\in X}\nu(V_{n}[x])$.
We now use that $(V_{n})_{n\in \nat}$ is a uniform scale. 
Since $\nu$ is non-atomic we can conclude (the argument in \cite[Lem. 6.3]{drno}, \cite[Lem. 5.4]{Li_2023} also works in the context of uniform spaces) that
$\lim_{n_{0}\to \infty}  \sup_{n\ge n_{0}}\sup_{x\in X}\nu(V_{n}[x])=0$. This implies \eqref{gerfwefewrfwer}.
 %\uli{here we need that $\nu(\bigcap_{n\in \nat} U_{n})=\lim_{n\to \infty} \nu(U_{n})$ for a decreasing sequence of opens. This is a regularity assumption on $\nu$}
 \end{proof}



