\section{Introduction}
\label{section::intro}

%================================================================================
\subsection{Problem set up}

Link prediction \citep{janicik2005social,clauset2008hierarchical,kim2011network,mohan2013graphical,mohan2021graphical} is a fundamental problem in network data analysis, with applications across sociology, econometrics, and biology, where real-world networks are often only partially observed.
While early work focused on developing accurate prediction of individual links, the growing demand for simultaneous prediction of multiple links has brought concerns about reproducibility and statistical validity to the forefront. By formulating this task as a multiple hypothesis testing problem, false discovery rate (FDR) control has become a widely adopted tool. However, FDR control for link prediction in networks presents unique challenges owing to complex network edge dependencies and unknown, heterogeneous patterns of missingness. To address these challenges, which remain inadequately resolved in the literature, we introduce a new method called conformal link prediction ({\tt clp}). Our approach enables multiple link prediction with provably valid false discovery rate control.

Let $A \in \mathbb{R}^{n\times n}$ denote the adjacency matrix of a directed network with $n$ nodes and no self-loops. Missingness in $A$ is described by a binary matrix $M\in \{0,1\}^{n\times n}$, where its entry $M_{i,j}=1$ if $A_{i,j}$ is missing, and $M_{i,j}$'s are independent Bernoulli$(q_{i,j})$ random variables with unknown and potentially heterogeneous missing probabilities $q_{i,j}\in[0,1]$. Define $M^c=1-M$. Throughout, we adopt the following standard assumption \citep{shao2023distribution}.
\begin{assumption}
    \label{assumption::rm}
    The  missing pattern $M$  is independent of the network $A$.
\end{assumption}
We define the test set as the collection of unobserved links:
\begin{align}
    \Dtest:=\{(i,j): i,j \in [n]=\{1,\ldots, n\}, M_{i,j}=1\},
    \label{def::test-set}
\end{align}
where $\Dtest$ is random as $M$ is random. For simplicity of presentation, we focus on predicting all links in $\Dtest$, while our method can be applied to any subset. 
Following \citet{jin2022selection}, we formulate link prediction as a multiple testing problem with random hypotheses:
\begin{align} 
    H_{i,j}: A_{i,j} \leq c_{i,j}~ 
    \text{for } (i,j) \in \Dtest,
    \label{def::hypothesis-testing}
\end{align} where $c_{i,j}$'s are user-specified. For example, in the international trade flow network \citep{helpman2008estimating}, if the goal is to determine whether any trading activity exists between two countries, $c_{i,j}$ can be set to zero. Alternatively, if the focus is on detecting higher volumes of bilateral trade, $c_{i,j}$ can be set to an appropriate positive value. 

For the rejection set $\cR:=\{{(i,j) \in \Dtest}: \textrm{Reject }H_{i,j}\}$, the false discovery proportion (FDP) is defined as $\textrm{FDP}=
(|\cR| \vee 1)^{-1} \sum_{(i,j)\in \cR} \mathbbm{1}_{[A_{i,j}\leq c_{i,j}]}$. Our objective is to control $\textrm{FDR}=E(\textrm{FDP})$ at a pre-specified significance level, based on given $\{c_{i,j}\}_{(i,j) \in \Dtest}$ and observed data $\big\{A\circ M^c, M\big\}$, where ``$\circ$'' denotes the element-wise product. A major challenge for FDR control in classical link prediction methods is that the unknown and potentially non-uniform missing rates $\{q_{i,j}\}$ lead to non-exchangeable observations $A\circ M^c$, which hinders uncertainty quantification. Moreover, complex dependencies among predicted links further render most traditional FDR control procedures inapplicable. 





%================================================================================
\subsection{Related literature}


Link prediction has been extensively studied over recent decades \citep{liben2003link,hasan2011survey, zhang2017estimating,zhu2021neural}.
Alternatively, by viewing network data as a random matrix or a realisation of an unobservable graphon, link prediction has also been approached via matrix estimation or completion \citep{candes2010matrix,candes2011robust,koltchinskii2011nuclear,davenport20141} and graphon estimation \citep{gao2015rate,xu2018rates}. 
However, most existing studies either lack uncertainty quantification or rely on strong modelling assumptions. 
To achieve our goal of distribution-free uncertainty quantification, we bridge two key ingredients.
The first is conformal prediction \citep{vovk2005algorithmic,shafer2008tutorial}, a powerful model-agnostic framework that enables flexible applications. In particular, it has been adapted to multiple testing problems through the construction of conformal p-values, namely, p-values derived from conformal procedures \citep{lei2021conformal, jin2022selection, bates2023testing}.
The second ingredient, which addresses the issue that conformal p-values are typically mutually dependent, is the e-BH procedure \citep{wang2022false}, which ensures valid FDR control under such dependence. Based on e-values \citep{vovk2021values}, the e-BH procedure has gained attention due to its convenience in handling complex dependencies. Recent examples include the derandomised knockoff procedure \citep{ren2024derandomised} and the use of e-values in conformal prediction \citep{bashari2024derandomized,ignatiadis2024values}.


Conformal prediction for matrix data was pioneered by \cite{gui2023conformalized} and \citet{shao2023distribution}. 
\cite{gui2023conformalized} considered random missingness and is therefore more closely related to our setting, whereas \citet{shao2023distribution} examined arbitrary and potentially adversarial missing patterns.
However, neither study addresses the task of predicting multiple links. Recently, \citet{marandon2024conformal} introduced conformal link prediction with FDR control. However, their method is limited to unweighted networks and assumes a ``double-standard'' sampling scheme, in which missing rates are required to be uniform across all links. Under this sampling assumption, subsequent work by \cite{blanchard2024fdr} sought to provide theoretical justification for \citet{marandon2024conformal}.
This assumption effectively imposes the exchangeability on all links with values exceeding $c_{i,j}$, which reduces technical difficulty but limits practical applicability.
\citet{liang2024structured} proposed a structured splitting scheme for simultaneous prediction of a small number of links, without addressing the multiple testing problem. To date, valid FDR control for multiple link prediction in general network settings remains an open challenge.



\subsection{Our contributions}

We develop a new conformal inference framework for multiple network link prediction with provable FDR control.
Unlike prior work, our method is designed to address the complex structure of partially observed networks, where missingness is heterogeneous and the dependencies among predictions are intricate. 
The approach combines novel conformal calibration schemes with a principled global aggregation strategy. 
Our main contributions are threefold.

First, we introduce a conformal inference method tailored to row-wise link prediction.
A key innovation is a carefully constructed multi-splitting scheme that partitions each row's test set and adaptively allocates calibration sets. 
This enables the construction of exchangeable nonconformity scores and valid conformal p-values, even under unknown and nonuniform missingness. 
The method achieves FDR control for any node sizes $n$ through a nontrivial adaptation of the Benjamini–Hochberg (BH) procedure \citep{benjamini1995controlling}, applied in a row-wise fashion.



Second, we propose a novel aggregation technique that transforms the row-wise decisions, obtained via the BH procedure, into valid e-values, and applies the e-BH procedure for FDR control. 
This step requires careful design to accommodate unknown yet arbitrary dependence across predicted network links, a challenge not addressed by standard conformal or e-value methods. We further introduce a derandomisation step to enhance stability, along with an e-value inflation strategy to improve power, both tailored to the unique demands for predicting multiple network links.

Third, our method is broadly applicable: it extends naturally to unweighted, undirected, and bipartite networks. 
It operates without knowledge of the missingness mechanism and provides finite-sample guarantees. 
Our framework thus advances the scope of conformal inference in network analysis, extending beyond existing approaches such as \citet{tibshirani2019conformal} and \citet{gui2023conformalized}. 
Numerical studies confirm the practical effectiveness of the proposed method.




%================================================================================
\section{Conformal link prediction with FDR control}
\label{section::cap-with-fdr-control}


%================================================================================
\subsection{Link prediction under unknown missing probabilities}
\label{section::2-1}

We adopt the general weighted graphon model \citep{gao2016optimal} as the base for our method for its generality and flexibility. 
For the adjacency matrix $A$, we assume that
\begin{align}
    A_{i,j} 
    \sim
    f(\xi_i,\xi_j), \text{ ~for~ } i\neq j \in [n],
    ~~
    \text{where }\{\xi_i\}_{1\leq i\leq n} \stackrel{\rm i.i.d.} \sim \mathrm{Uniform}[0,1].
    \label{def::exch-model}
\end{align}
Here, $A_{i,j}$ is generated according to some distribution parameterised by $f(\xi_i,\xi_j)$, such as Bernoulli and Gaussian. Intuitively, \eqref{def::exch-model} first generates an independent and identically distributed sample of nodes from a hyper-population of ``all kinds of nodes" and then generate links based on function $f$.
This framework covers a broad family of network models, such as in the social relations model \citep{kenny1984srm,Gill2001srm}, conditionally independent dyad model \citep{chandrasekhar2016cid,graham2020cid}, and random-effects model \citep{gelman2006ref,aronow2015cluster}. Under model \eqref{def::exch-model}, for any permutation $\pi(\cdot)$ of node labels, we have 
\begin{align}
    \{A_{i,j}\}_{i\neq j \in [n]}
    \overset{d}{=}
    \{A_{\pi(i),\pi(j)}\}_{i\neq j \in [n]}.
    \label{def::exch-property}
\end{align}
This is referred to as the exchangeability property of $A$. Importantly, the exchangeability in \eqref{def::exch-property} pertains to the not-fully-observable complete $A$, not the observed $A\circ M^c$.
Note that our notion of exchangeability in \eqref{def::exch-property} differs from that used in prior work. 
Previous studies \citep{tibshirani2019conformal,gui2023conformalized} rely on  exchangeability induced by $M$, and therefore require either uniform missing rates ${q_{i,j}}$ or their accurate estimations under the ``weighted exchangeability" framework.
In contrast, we model $A$ as a random graph with an inherent exchangeability as defined in \eqref{def::exch-property}. 
With the mild additional assumption of exchangeability of the complete $A$, we waive the need for prior knowledge of the potentially non-uniform missing rates ${q_{i,j}}$'s, a key restrictive assumption in earlier works.

To address the challenge of unknown ${q_{i,j}}$'s, we propose a divide-and-conquer approach to break the problem into sub-tasks.
First, for each row $i_0$, we construct ``local tests'' where exchangeability holds within a row-wise subset of observations, which leads to valid ``local'' FDR controls. 
Then, the local test decisions are aggregated into e-values to construct a global test of the hypotheses in \eqref{def::hypothesis-testing} for all unobserved links, with valid FDR control.


%================================================================================
\subsection{Step 1: breaking down global test into smaller local tests}
\label{section::2-2}


Our first step is to design a local test within row $i_0$ by constructing exchangeable conformal p-values \citep{jin2022selection}. 
Let $\Itesti=\{(i_0,j): j\in [n], M_{i_0,j}=1\}$ denote the column indices of missing entries in row $i_0$, corresponding to missing links for node $i_0$.
Then, the corresponding set of local hypotheses is
\begin{align}
    H_{i_0,j}: A_{i_0,j} \leq c_{i_0,j},
    ~~
    \text{for }j \in \Itesti.
    \label{def::hypothesis-testing-local}
\end{align}
We randomly split the observed entries in row $i_0$, that is, those in $(\Itesti)^c$, into
a training set $\{A_{i_0,j} : j \in \Itraini \}$ and a calibration set $\{A_{i_0,j} : j \in \Icalibi \}$, as illustrated in Figure \ref{fig::row-illus-ex}.

\begin{figure}[h]
    \centering
    \includegraphics[width=\textwidth]{row-illus-ex3.0.jpg}
    \vspace{-2em}
    \caption{
    Illustration of $\Itesti$, $\Itraini$, and $\Icalibi$ within row $i_0$.
    }
    \label{fig::row-illus-ex}
\end{figure}

Under the random missing mechanism in Assumption \ref{assumption::rm}, the observed entries in the same row can be viewed as a randomly selected subset of exchangeable random variables.
It turns out that, as a consequence of
the exchangeability of latent factors $\{\xi_i\}_{1\leq i\leq n}$, the entries in $\{A_{i_0,j}\}_{j \in \Icalibi \cup \Itesti}$ are exchangeable, as established in the following proposition.
\begin{proposition}
\label{prop::withinrow-exch}
Under Assumption \ref{assumption::rm} and model  \eqref{def::exch-model}, given $M$, for any $i_0 \in [n]$ and any permutation $\widetilde\pi(\cdot)$ of index set $\Icalibi \cup \Itesti$, we have
    $$
        \{A_{i_0,j}: j \in \Icalibi \cup \Itesti\}\overset{d}{=}\{A_{i_0,\widetilde\pi(j)}: j \in \Icalibi \cup \Itesti\}.
    $$
\end{proposition}

For each $j \in \Icalibi \cup \Itesti $, we select data from observed links using a carefully designed strategy, detailed later in Section \ref{sec23}, to construct a link prediction $\wh A_{i_0,j}$ such that
\begin{align}
    \{\wh A_{i_0,j}\} \text{ are exchangeable for } j\in \Icalibi \cup\Itesti.
  \label{eq:est-cond}
\end{align}
Based on \eqref{eq:est-cond}, we construct the nonconformity scores \citep{jin2022selection} as follows
\begin{align*}
    S(\wh A_{i_0,j}; z) := z - \wh A_{i_0,j}, ~ \text{for }j \in \Icalibi \cup \Itesti,
\end{align*}
where $S(\wh A_{i_0,j}; z)$ is monotone with respect to the second argument by definition. Intuitively, $S(\wh A_{i_0,j}; z)$ quantifies how well the value $z$ conforms to the predictions. Using the nonconformity scores, we define p-values for entries $\{(i_0,j_1):j_1 \in \Itesti\}$ as
\begin{align}
    \wh{\mathfrak p}_{i_0,j_1}
    :=&~
    \dfrac
        {
            1 +
            \sum_{j' \in \Icalibi}
            \mathbbm{1}\{ S(\wh A_{i_0,j'}; A_{i_0,j'}) < S(\wh A_{i_0,j_1}; c_{i_0,j_1}) \} 
        }
        {
            1 + |\Icalibi|
        }
        , ~ 
        \text{for each }j_1 \in \Itesti.
    \label{eqn-def::hat-p-value}
\end{align}
We then apply the BH procedure to  
$\big\{\wh{\mathfrak p}_{i_0,j}: j \in \Itesti \big\}$ as follows. Let $\wh{\mathfrak p}_{(\ell)}^{i_0}$ denote the $\ell$th smallest element of the sorted values of 
$\big\{\wh{\mathfrak p}_{i_0,j}: j \in \Itesti
\big\}$. Given any $\alphaBH>0$, define
\begin{align}
    \wh\ell
    :=
    \max\big\{
        \ell:
        \wh{\mathfrak p}_{(\ell)}^{i_0}
        \leq
        \alphaBH \cdot \ell / |\Itesti|
    \big\}.
    \label{equation::BH-threshold-l}
\end{align}
We reject $H_{i_0,j}$ for all $j$ such that $\wh{\mathfrak p}_{i_0,j} < \wh{\mathfrak p}_{(\wh\ell)}^{i_0}$, and denote the rejection set by $\cR_{\rm BH}^{i_0}(\alphaBH)$. The following result establishes FDR control for this local testing procedure.  
\begin{theorem}[Oracle FDR control for the local test with conformal p-values]
\label{thm::FDR-rowwise}
    For network $A$ generated from \eqref{def::exch-model}, suppose the prediction $\hat A$ satisfies \eqref{eq:est-cond}.
    Assume that the random variables $\{A_{i_0,j} - \wh A_{i_0,j}\}_{j \in \Icalibi} \cup \{c_{i_0,j} - \wh A_{i_0,j}\}_{j \in \Itesti}$ have no ties almost surely. 
    Then, for any $\alphaBH \in (0,1)$, the rejection set $\cR_{\rm BH}^{i_0}(\alphaBH)$ for testing local hypotheses in \eqref{def::hypothesis-testing-local} satisfies FDR $\leq \alphaBH$.
\end{theorem}  

\begin{remark}
In presence of ties, one can simply apply a random tie-breaking trick as that in \citet{lei2018distribution,tibshirani2019conformal}.
\end{remark}



\subsection{Construction of $\hat A$ and local tests with FDR control}
\label{sec23}
To build an operational method, we construct $\hat A$ that satisfies \eqref{eq:est-cond} for implementing the local test in Section~\ref{section::2-1}. 
Due to the unknown and non-uniform missingness, directly applying popular existing link prediction methods, such as matrix factorization or node similarity-based tools, would not satisfy the required
exchangeabililty condition in \eqref{eq:est-cond}.
To better illustrate our strategy, we start with an ``oracle method''.
Consider a weighed link estimation:
\begin{equation}
\label{eq:weighted-est}
    \wh  A_{i_0,j_1} =  \sum\nolimits_{j_2 \in \Itraini} w(j_1,j_2)
    A_{i_0,j_2},\quad  \text{for}~{j_1\in \Icalibi \cup\Itesti },
\end{equation}
where the weight $w(j_1,j_2)$ may be data-dependent. 
Inspired by \cite{zhang2017estimating}, for any $j_1 \in \Itesti \cup \Icalibi$ and $j_2 \in \Itraini$, we set
\begin{align}
    w(j_1,j_2)
    =
    K\big(d_{j_1,j_2}\big)
    \Big\{
        \sum\nolimits_{j_2' \in \Itraini} K\big(d_{j_1,j_2'}\big) \Big\}^{-1},
    \label{method::A-estimate-oracle}
\end{align}
where $K(\cdot)$ is a smooth and Lipschitz kernel function, and
$$
    {d}(j_1,j_2)    := \int_0^1 \Big|\int_0^1 \big\{f(u,\xi_{j_1})-f(u,\xi_{j_2})\big\} f(u,v) \td u \Big| \td v
$$
measures the dissimilarity of graphon slices $f(\cdot, \xi_{j_1})$ and $f(\cdot, \xi_{j_2})$.
Since the oracle weights do not depend on $M$, the non-uniform missing pattern will not break the exchangeability of entries in $\{A_{i_0,j} - \hat A_{i_0,j}: j \in \Icalibi \cup \Itesti\}$.
Consequently, the validity of FDR control for the local test, based on the downstream BH procedure, follows from Theorem~\ref{thm::FDR-rowwise}.


To make \eqref{eq:weighted-est} operational in practice, we replace the oracle dissimilarity $d$ in \eqref{method::A-estimate-oracle} with a computable $\hat d$.
Noted by \citet{shao2023distribution}, for each $j$, we can view $A_{i_0,j}$ as the response and $A_{(-i_0),j}$, the remainder of column $j$, as the predictor. The challenge, however, lies in constructing a suitable surrogate for the unobservable graphon slices $f(\cdot, \xi_j)$'s in \eqref{method::A-estimate-oracle}, such that $\hat d$ would not break exchangeability -- for instance, simply filling the unobserved entries with 0 and plug in Equation (9) of \citet{zhang2017estimating} will not work.

Our key idea is to select a carefully chosen subset of $[A\circ M^c]_{(-i_0),j}$'s that maintains exchangeability.
This is another layer of divide-and-conquer approach.
Rather than using the entire calibration set $\Icalibi$ to test all hypotheses in $\Itesti$, we divide $\Icalibi$ into $|\Itesti|$ smaller subsets, and randomly assign one subset $\Icalibi(j_0)$ to each $j_0\in\Itesti$. 
However, if $|\Itesti|$ is not small relative to $|\Icalibi|$, there may be insufficient calibration samples. In such nontrivial cases, we partition $\Itesti$ into disjoint subsets $\{\Itesti(1), \Itesti(2), \ldots, \Itesti(k)\}$ and reuse the same calibration set $\Icalibi$ across each subset $\Itesti(k_0)$, for $k_0 \in [k]$. The results are then aggregated using the e-BH procedure to form a global test, as detailed in Section \ref{section::2-3}. For the remainder of this paper, we focus on the nontrivial case where $|\Itesti|$ is not small compared to $|\Icalibi|$. We therefore test hypotheses within a partition $\Itesti(k_0)$: 
\begin{align}
    H_{i_0,j}: A_{i_0,j} \leq c_{i_0,j},
    ~~
    \text{where }j \in \Itesti(k_0).
    \label{def::hypothesis-testing-local-sampleV}
\end{align}
Let $r_0$ denote the minimum size of calibration split $|\Icalibi(j_0)|$, so that $|\Itesti(k_0)|\leq r_1:= \lfloor \abs{\Icalibi}/r_0 \rfloor$, and the number of partitions required is $\lceil|\Itesti|/r_1\rceil$. 

\begin{figure}[h]
    \centering
    \includegraphics[width=\textwidth]{clp-alg-illus-ex6.0.jpg}
    \vspace{-1.5em}
    \caption{
    Construction of $\hat A_{j_0,j_1}$. 
    (a) Splitting row $i_0$ into training and calibration sets.
    (b) Construction of $\Omega_{j_0}$. 
    (c) Dissimilarity measures. 
    }
    \label{fig::clp-alg-illus-ex}
\end{figure}

With this setup in place, we are now ready to illustrate the core of our method in Figure \ref{fig::clp-alg-illus-ex} and walk readers through it.
Recall that row $i_0$ is partitioned into training, calibration and, test sets, as shown in Figure \ref{fig::clp-alg-illus-ex}-(a).
Figure \ref{fig::clp-alg-illus-ex}-(b) illustrates a simplified example, where the calibration set comprises only two elements, $\Icalibi(j_0)=\{5,6\}$, and the test set contains a single entry $\{j_0\}:=\{7\}$.
When $|\Icalibi(j_0) \cup \{j_0\}|$ is small, with high probability, we can identify multiple rows $i\in \Itraini$, collectively denoted as $\Omega_{j_0}$, for which the submatrix $A_{\Omega_{j_0}\times (\Icalibi(j_0) \cup \{j_0\})}$ contains no missing entries, highlighted as dark yellow cells in Figure \ref{fig::clp-alg-illus-ex}-(b).

Note that the construction of $\Omega_{j_0}$ depends on the missing pattern. Importantly, the proposition below guarantees that, under the mild condition on missing rates $q_{i,j}\le c_0<1$, there exists a sufficiently large number of fully observed rows for constructing $A_{\Omega_{j_0}\times (\Icalibi(j_0) \cup \{j_0\})}$.

\begin{proposition}[Number of fully observed rows in columns $\Icalibi(j_0) \cup \{j_0\}$]\label{prop:num-match-rows}
  Suppose the missing probabilities $q_{i,j}\le c_0<1$ for $i,j \in [n]$, and there exists a constant $C_1>0$ such that $\abs{\Itraini} = C_1 n$, and $\abs{\Icalibi(j_0)}= r_0$. Then we have $\abs{\Omega_{j_0}}\ge {C_1}(1-c_0)^{r_0+1} n/2$ with probability at least $1-\exp\{-n C_1 (1-c_0)^{2r_0+2}/16\}$.
\end{proposition}

Next, we construct $\hat A_{i_0, j_1}$ for all $j_1\in \Icalibi(j_0) \cup \{j_0\}$ and explain why they are exchangeable.
Recall that we use a weighted average of $A_{i_0,j_2}$'s to estimate $A_{i_0,j_1}$ in \eqref{eq:weighted-est},  where $j_2\in \Itraini$ and the weight depends on a dissimilarity measure $\hat d_{j_1,j_2}$. 
Now let us specify $\hat d_{j_1,j_2}$ formally. 
For each $j\in \Itraini\backslash\{j_2\}$, define $\Omega_{j_1,j_2,j}$ to be the maximum subset of $[n]$ satisfying: (1) $\Omega_{j_1,j_2,j}\subseteq \Omega_{j_0}$; and (2) the submatrix $A_{\Omega_{j_1,j_2,j}\times \{j_1,j_2,j\}}$ contains no missing link.
Denote by $\langle\cdot,\cdot\rangle$ the inner product of two vectors, we define $\hat d_{j_1,j_2,j}$ and use it to construct $\hat d_{j_1,j_2}$, as follows:
\allowdisplaybreaks
\begin{align}
    \hat d_{j_1,j_2,j}
    :=&~
   \frac{\big|
        \langle
            A_{\Omega_{j_1,j_2,j}, j_1} - A_{\Omega_{j_1,j_2,j}, j_2},
            A_{\Omega_{j_1,j_2,j}, j}
        \rangle
    \big|}{|\Omega_{j_1,j_2,j}|},
    \label{def::d_{j_1,j_2,j}}
    \\
    \text{and}\quad
    \hat d_{j_1,j_2}
    :=&~
    \sum\nolimits_{j \in \Itraini \backslash \{j_2\}} \frac{\hat d_{j_1,j_2,j}}{|\Itraini| - 1}.
    \label{def::d_{j_1,j_2}}
\end{align}
Then similar to \eqref{method::A-estimate-oracle}, we can construct
\begin{equation}    \label{method::A-estimate} 
\wh A_{i_0,j_1}:=
\Big\{\sum\nolimits_{j_2' \in \Itraini} K\big(\wh d_{j_1,j_2'}\big)\Big\}^{-1} \sum\nolimits_{j_2' \in \Itraini} K\big(\wh d_{j_1,j_2'}\big) A_{i_0,j_2'}    ~~\text{for}~~ 
  j_1\in \Icalibi(j_0)\cup\{j_0\}.
\end{equation}

Let us explain why the $\hat A_{i_0,j_1}$'s constructed in such a way are exchangeable.
By Proposition \ref{prop::withinrow-exch}, it suffices to show that the dissimilarities $\hat d_{j_1,j_2}$'s are exchangeable for all $j_1\in \Icalibi(j_0) \cup \{j_0\}$, which 
in turn follows from the exchangeability of the underlying $\hat d_{j_1,j_2,j}$'s for these $j_1$'s.
Now we make a crucial observation that by construction, for each fixed pair $(j_2, j)$, all indices $j_1\in \Icalibi(j_0) \cup \{j_0\}$ share a common $\Omega_{j_1,j_2,j}$.
For clarity, this observation is illustrated by comparing the three vertically stacked panels in Figure \ref{fig::clp-alg-illus-ex}-(c), where dark orange cells highlight the rows corresponding to $\Omega_{j_1,j_2,j}$. By Assumption \ref{assumption::rm} and model \eqref{def::exch-model}, conditional on $M$ and $\{\xi_{j'}: j'\in \Itraini\}$, $\xi_{j_1}$'s are independent and identically distributed for $j_1\in \Icalibi(j_0) \cup \{j_0\}$. This immediately implies the exchangeability of $\hat d_{j_1,j_2,j}$'s, and hence that of $\hat A_{i_0,j_1}$'s, for all $j_1\in \Icalibi(j_0) \cup \{j_0\}$.
Consequently, the nonconformity scores $S(\wh A_{i_0,j'}; A_{i_0,j'})$ for $j'\in \Icalibi(j_0)\cup\{j_0\}$ are also exchangeable. Therefore,
\begin{equation}\label{eqn-def::emp-p-value}
    \begin{aligned}
        \wh{\mathfrak p}_{i_0,j_0}
        :=&~
        \dfrac
            {
                1 +
                \sum_{j' \in \Icalibi(j_0)}
                \mathbbm{1}\{ S(\wh A_{i_0,j'}; A_{i_0,j'}) < S(\wh A_{i_0,j_0}; c_{i_0,j_0})\}
            }
            {
                1 + |\Icalibi(j_0)|
            }
            ~~ \text{for}~~
            j_0 \in \Itesti(k_0),
    \end{aligned}
\end{equation}
are valid conformal p-values \citep{jin2022selection,bates2023testing}. Moreover, these p-values are conditionally independent by Proposition \ref{prop:emp-cond-ind} below, thus suitable for the BH procedure. 


\begin{proposition}[Conditional independence of empirical p-values]\label{prop:emp-cond-ind}
For network $A$ generated from \eqref{def::exch-model}, under Assumption \ref{assumption::rm}, conditional on $\{\xi_j:j\in\Itraini\}$, $\{A_{i,j}:i,j\in\Itraini\}$ and the missing pattern $M$, the p-values in \eqref{eqn-def::emp-p-value} are independent within $\Itesti(k_0)$. 
\end{proposition}

Building on the above property of $\wh{\mathfrak p}_{i_0,j_0}$'s, we apply the BH procedure in \eqref{equation::BH-threshold-l} to obtain a rejection set $\cR_{\rm BH}^{i_0,k_0}(\alphaBH)$, as summarised in Algorithm \ref{algorithm::sample-local-test}. We conclude this section with the FDR control guarantee for Algorithm \ref{algorithm::sample-local-test} in Theorem \ref{thm:local-FDR-split}.

\begin{algorithm}
\caption{Local test for \eqref{def::hypothesis-testing-local-sampleV} with FDR control
}
\label{algorithm::sample-local-test}

    \KwIn{Targeting row index $i_0$, set 
    $\Itesti(k_0)$, $\Icalibi$, $\Itraini$, and
    calibration size $r_0 \ge C/\alphaBH $.}

        Partition $\Icalibi$ into disjoint $\abs{\Itesti(k_0)}$ subsets randomly, which are $\{\Icalibi(j_0): j_0\in \Itesti(k_0)\}$\;

       \For{$j_0\in \Itesti(k_0)$ }{
        Find the fully observed rows in the block $\{A(i,j)\}$, for $i\in \Itraini$ and $j\in \Icalibi(j_0)\cup\{j_0\}$, denoted by $\Omega_{j_0}$\;

        Calculate $\wh A_{i_0,j}$ for $j \in\Icalibi(j_0)\cup\{j_0\}$ using \eqref{def::d_{j_1,j_2,j}}--\eqref{method::A-estimate}\;

        Compute p-value for $j_0$ using \eqref{eqn-def::emp-p-value}\;
       }
       Apply the BH procedure in \eqref{equation::BH-threshold-l} to p-values in $\Itesti(k_0)$ and obtain $\cR_{\rm BH}^{i_0,k_0}(\alphaBH)$\; 

    \KwOut{Rejection set $\cR_{\rm BH}^{i_0,k_0}(\alphaBH)$.} 

\end{algorithm}


\begin{theorem}[FDR control for the local test with empirical p-values by splitting] 
\label{thm:local-FDR-split}
Assume the network $A$ is generated from \eqref{def::exch-model}. Under Assumption \ref{assumption::rm}, for any $\alphaBH \in (0,1)$, given $M$, the output $\cR_{\rm BH}^{i_0,k_0}(\alphaBH)$ of Algorithm \ref{algorithm::sample-local-test} for testing \eqref{def::hypothesis-testing-local-sampleV} satisfies FDR $\leq \alphaBH$ for testing \eqref{def::hypothesis-testing-local-sampleV}.
\end{theorem}







