\section{FDR control for undirected and bipartite networks}
\label{supp-section::bipartitie-and-undirected}

In this section, we extend the proposed {\tt clp} framework to accommodate undirected and bipartite networks, elaborating on the modified version of Algorithm \ref{algorithm::sample-local-test}. Notice that once Algorithm \ref{algorithm::sample-local-test} and its properties are still valid to control the FDR for the local test as defined in Theorem \ref{thm:local-FDR-split}, we can directly incorporate it into Algorithm \ref{algorithm::BH-EBH-framework} and establish the FDR control across all missing links by applying the proof of Theorem \ref{thm:emp-fdr-global}. 

We start with the undirected networks.
Due to symmetry, we consider that information on the network and missing patterns is incorporated in the upper triangular part, \ie, $\{A_{i,j}\}$, $\{M_{i,j}\}$, for { $i<j$}. 
To facilitate the analysis, we write the extended version of $A$, $M$ as $A'$, $M'$, where
\begin{equation}
\label{eq:A-M-extend}
    A_{i,j}'=\left\{\begin{array}{cc}
       A_{i,j}  & \text{ if } { i<j} \\
        A_{j,i}  & \text{ if }  { i>j}
    \end{array}\right. ~~; \quad  M_{i,j}'=\left\{\begin{array}{cc}
       M_{i,j}  & \text{ if } { i<j} \\
        M_{j,i}  & \text{ if }  { i>j}
    \end{array}\right. .
\end{equation}
We now describe the FDR control for the local test in undirected networks in Alogrihtm \ref{algorithm::sample-local-test-und}.
\begin{algorithm}
\caption{Local test with FDR control for undirected network 
}
\label{algorithm::sample-local-test-und}

    \KwIn{Targeting row index $i_0$, set $\Itesti(k_0)$ where $j_0>i_0$ for each $j_0\in \Itesti(k_0)$.}
        Extend the $A$ and $M$ to $A'$ and $M'$ according to \eqref{eq:A-M-extend}; 

        Split the observed entries in row $i_0$ of $A'$ as $\Itraini$ ,$\Icalibi$ by missingness $M'$;

        Run Algorithm \ref{algorithm::sample-local-test} on $A'$, $M'$ for row $i_0$, set $\Itesti(k_0)$, given $\Itraini$ and $\Icalibi$;

    \KwOut{Rejection set $\cR_{\rm BH}^{i_0,k_0}(\alphaBH)$.}
\end{algorithm}

\begin{proposition}[Conditional independence in undirected networks]\label{prop:emp-cond-ind-undirected} Suppose we run Algorithm \ref{algorithm::sample-local-test} on $A'$ and $M'$, with the test set $\Dtest$ in the upper triangular matrix.
Then, conditional on $\{\xi_j:j\in\Itraini\}$, $\{A_{i,j}:i,j\in\Itraini, { i<j}\}$ and the missing pattern $M$, the p-values in \eqref{eqn-def::emp-p-value} from  $A'$ and $M'$ are valid and independent within $\Itesti(k_0)$. 
\end{proposition}


\begin{figure}[h]
    \centering
    % \vspace{1em}
    \includegraphics[width=\textwidth]{clp-undirected-illus-v3.jpg}
    \vspace{-1.5em}
    \caption{
    Illustration of the splitting procedure in {\tt clp} under undirected network. 
    (a) Construction of $\Itraini$ and $\Icalibi$ for each $\Itesti(k_0)$.
    (b) Construction of $\Omega_{j_0}$. 
    }
    \label{fig::clp-undirected-illus}
\end{figure}

Figure \ref{fig::clp-undirected-illus} provides an illustrative example of the splitting procedure in {\tt clp} for an undirected network. 
It is seen that the construction follows the same procedure as described in Section \ref{section::2-2} for directed networks.
Based on Proposition \ref{prop:emp-cond-ind-undirected}, the FDR control results below follows directly by the proof of Theorems \ref{thm:local-FDR-split}--\ref{thm:emp-fdr-global}.


\begin{theorem}[FDR control results for undirected networks] \label{thm:FDR-undirected}
Under the conditions of Proposition \ref{prop:emp-cond-ind-undirected}, in each local test set within row $i_0$: $\{H_{i_0,j_0}: j_0 \in \Itesti(k_0)\}$, the BH procedure using  $\wh{\mathfrak p}_{i_0,j_0},j_0 \in \Itesti(k_0)$ will lead to a valid FDR control: $\text{FDR}\le \alphaBH$ on this local test set. 
Moreover, the rejection set of {\tt clp} as the output of Algorithm \ref{algorithm::BH-EBH-framework} satisfies $\text{FDR} \leq \alphaeBH$ on the whole test set $\{H_{i,j}: i < j\in [n], M_{i,j}=1\}$, for any $\alphaBH, \alphaeBH \in (0,1)$.
\end{theorem}


We then turn to the bipartite networks, where $A, M\in \mathbb{R}^{n \times m}$ and the bipartite network $A$ follows the decomposition:
\begin{align}
    A_{i,j}\sim f(\xi_i,\zeta_j), \text{ ~for~ } i \in [n], \ j\in[m],
    \label{def::exch-model-bipartite}
\end{align}
where $\{\xi_i\}_{1\leq i\leq n}, \{\zeta_j\}_{1\leq j\leq m}\stackrel{\rm i.i.d.} \sim \mathrm{Uniform}[0,1]$. Notice that, the bipartite networks can be viewed as a $n\times m$ sub-network of the directed network \eqref{def::exch-model} in $\mathbb{R}^{ (n+m) \times (n+m)}$. Suppose that $A^{\text{full}}\in\mathbb{R}^{ (n+m) \times (n+m)}$ is a directed network generated by
$\big\{\{\xi_i\}_{1\leq i\leq n}, \{\zeta_j\}_{1\leq j\leq m}\big\}\stackrel{\rm i.i.d.} \sim \mathrm{Uniform}[0,1]$ following \eqref{def::exch-model}. Then, it is seen that $A=A^{\text{full}}[1:n,n+1:n+m]$ is a submatrix of the exchangeable $A^{\text{full}}$. Following this observation, we can show the exchangeablity of bipartite networks below.

\begin{lemma}[Exchangeablity in bipartite network]\label{lemma:exch-bipartite}
   Suppose $A\in \mathbb{R}^{n \times m}$ follows \eqref{def::exch-model-bipartite}, then for any permutation $\pi_1$ on $[n]$ and $\pi_2$ on $[m]$, we have 
   \begin{equation*}
       \{A_{i,j}\}_{i\in[n],j\in[m]}  \overset{d}{=}
    \{A_{\pi_1(i),\pi_2(j)}\}_{i\in[n],j\in[m]}.
   \end{equation*}
\end{lemma}
The poof of Lemma \ref{lemma:exch-bipartite} follows the property \eqref{def::exch-property} by noticing that any $\pi_1$ on $[n]$ and $\pi_2$ on $[m]$ can be combined as a unique $ \pi_{\text{full}}$ acting on $[n+m]$ with 
        \begin{equation*}
           \pi_{\text{full}}(i)=  \left\{ \begin{array}{cl}
             \pi_1(i) & \text{when } i\in [n], \\
            \pi_2(i-n)+n & \text{when } i \in[n+m] \backslash [n]. \\
                    \end{array}\right. 
        \end{equation*}
We now modify our Algorithm \ref{algorithm::sample-local-test} to the following version by substituting $\Itraini$ in step 3 by $[n]{\backslash \{i_0\}}$ in Algorithm \ref{algorithm::sample-local-test-bipartite}.


\begin{algorithm}
\caption{Local test with FDR control for bipartite network 
}
\label{algorithm::sample-local-test-bipartite}

    \KwIn{Targeting row index $i_0$, set $\Itesti(k_0)$, $\Icalibi$, $\Itesti$ and
    calibration size $r_0 \ge C/\alphaBH $.}

        Split $\Icalibi$ into $\abs{\Itesti(k_0)}$ parts evenly, \textit{i.e.}, $\{\Icalibi(j_0)\}_{j_0}$, for each $j_0\in \Itesti(k_0)$\;

       \For{$j_0\in \Itesti(k_0)$ }{

        Find the fully observed rows in the block $\{A(i,j)\}$, for $i\in [n]{\backslash \{i_0\}}$ and $j\in \Icalibi(j_0)\cup\{j_0\}$, which we denote by $\Omega_{j_0}$\;

        Calculate $\wh A_{i_0,j}$ for $j \in\Icalibi(j_0)\cup\{j_0\}$ using \eqref{def::d_{j_1,j_2,j}}--\eqref{method::A-estimate}\;
        Compute p-value for $j_0$ using \eqref{eqn-def::emp-p-value}\;
       }
       Run BH procedure for p-values in $\Itesti(k_0)$ and record the rejection results $\cR_{\rm BH}^{i_0,k_0}(\alphaBH)$\; 

    \KwOut{Rejection set $\cR_{\rm BH}^{i_0,k_0}(\alphaBH)$.} 
\end{algorithm}

By the construction of $\Omega_{j_0}$, the submatrix $[A\circ M^c]_{\Omega_{j_0},\Icalibi(j_0)\cup\{j_0\} }$ is always fully observed. 
According to Lemma \ref{lemma:exch-bipartite}, we can show the following exchangeability property within the submatrix.

\begin{proposition} 
\label{prop::col-index-exch-v2}
    Conditional on the missing pattern $M$ and $\{\xi_i\}_{i\in\Omega_{j_0}}$, $\{\zeta_j\}_{j\in \Itraini}$, the submatrix $ [A\circ M^c]_{\Omega_{j_0},\Icalibi(j_0)\cup\{j_0\} }$ is exchangeable with respect to the columns indices, \ie,
        \begin{equation*}
        \{[A\circ M^c]_{i,j}\}_{i\in \Omega_{j_0}, j\in \Icalibi(j_0)\cup\{j_0\}} \overset{d}{=} \{[A\circ M^c]_{i,\pi(j)} \}_{i\in \Omega_{j_0}, j\in \Icalibi(j_0)\cup\{j_0\}} 
    \end{equation*}
    where  $\pi(\cdot)$ is any permutation of the index set $\Icalibi(j_0)\cup\{j_0\}$.
\end{proposition}


An example illustrating the splitting procedure in {\tt clp} for bipartite networks is shown in Figure \ref{fig::clp-bipartite-illus}.

\begin{figure}[h]
    \centering
    \includegraphics[width=\textwidth]{clp-bipartite-illus-v2.jpg}
    \vspace{-3.5em}
    \caption{
    Illustration of the splitting procedure in {\tt clp} under bipartite network. 
    (a) Construction of $\Itraini$ and $\Icalibi$ for each $\Itesti(k_0)$. 
    (b) Construction of $\Omega_{j_0}$. 
    }
    \label{fig::clp-bipartite-illus}
\end{figure}

Now we are ready to construct the conformal p-values.
We can analogously define $\Omega_{j_1,j_2,j}$ as in the main paper.
By construction, for every given $(j_2, j)$,  where $j_2 \in \Itraini$, all $j_1\in \Icalibi(j_0) \cup \{j_0\}$ share a common $\Omega_{j_1,j_2,j}$.
By Proposition \ref{prop::col-index-exch-v2}, conditional on the training data $\{\xi_i\}_{i\in\Omega_{j_0}}$, $\{\zeta_j\}_{j\in\Itraini}$, training block $\{A_{i,j}\}_{i\in\Omega_{j_0},j\in\Itraini}$ and missing pattern $M$, it is seen that for each $j_2\in \Itraini$, we have 
\allowdisplaybreaks
\begin{equation*}
    \begin{aligned}
           \wh{d}(\pi(j_1),j_2)
    =&~
    \sum_{j \in \Itraini \backslash \{j_2\}} 
        \frac{
            |\langle A_{\Omega_{\pi(j_1),j_2,j},\pi(j_1)} - A_{\Omega_{\pi(j_1),j_2,j},j_2}, A_{\Omega_{\pi(j_1),j_2,j},j} \rangle|
        }
        {
            \big( |\Itraini| - 1 \big) |\Omega_{\pi(j_1),j_2,j}|
        } \\
         \overset{d}{=} & \sum_{j \in \Itraini \backslash \{j_2\}} 
        \frac{
            |\langle A_{\Omega_{j_1,j_2,j},j_1} - A_{\Omega_{j_1,j_2,j},j_2}, A_{\Omega_{j_1,j_2,j},j} \rangle|
        }
        {
            \big( |\Itraini| - 1 \big) |\Omega_{j_1,j_2,j}|
        } = \wh{d}(j_1,j_2).\\
    \end{aligned}
\end{equation*}
The second equality above is due to the the definition of inner product and Proposition \ref{prop::col-index-exch-v2}. This directly gives the following proposition, which can be justified by applying the proof of Proposition \ref{prop:emp-cond-ind}. 

\begin{proposition}[Conditional independence between empirical p-values]\label{prop:emp-cond-ind-bipartite}
Conditional on the training data $\{\xi_i\}_{i\in\Omega_{j_0}}$, $\{\zeta_j\}_{j\in\Itraini}$, training block $\{A_{i,j}\}_{i\in\Omega_{j_0},j\in\Itraini}$ and missing pattern $M$, the p-values in \eqref{eqn-def::emp-p-value} are valid and independent within $\Itesti(k_0)$. 
\end{proposition}

Analogous to Theorem \ref{thm:FDR-undirected}, according to Proposition \ref{prop:emp-cond-ind-bipartite}, we obtain the following FDR control results.

\begin{theorem}[FDR control results for bipartite networks]
\label{thm:FDR-bipartite}
Under the conditions of Proposition \ref{prop:emp-cond-ind-bipartite}, in each local test set within row $i_0$: $\{H_{i_0,j_0}: j_0 \in \Itesti(k_0)\}$, the BH procedure using $\wh{\mathfrak p}_{i_0,j_0},j_0 \in \Itesti(k_0)$ leads to a valid FDR control: $\text{FDR}\le \alphaBH$ on this local test set.
Moreover, the rejection set of {\tt clp} by inserting Algorithm \ref{algorithm::sample-local-test-bipartite} to Algorithm \ref{algorithm::BH-EBH-framework} satisfies $\text{FDR} \leq \alphaeBH$ on the test set $\{H_{i,j}: i \in [n], j\in [m], M_{i,j}=1\}$, for any $\alphaBH, \alphaeBH \in (0,1)$.
\end{theorem}









